local downloadFile: (path: string) -> string = function(path: string): string
	if not isfile(path) then
		local source: string = game:HttpGet('https://raw.githubusercontent.com/Copiums/Velocity/'..readfile('velo/profiles/commit.txt')..'/'..select(1, path:gsub('velo/', '')), true);
		if source == '404: Not Found' then
			error('Velocity could not download '..path);
		end;
		writefile(path, '--This watermark is used to delete the file if its cached, remove it to make the file persist after velocity updates.\n'..source);
	end;
	return readfile(path);
end;

