	local PlaceSpeed: table;
	local stockPlaceCps: number = bedwars.SharedConstants.BLOCK_PLACE_CPS;
	bedwars.DefaultPlaceCPS = stockPlaceCps;

	local reapply: () -> () = function(): ()
		if NoClickDelay["Enabled"] then
			NoClickDelay:Toggle();
			NoClickDelay:Toggle();
		end;
	end;

	NoClickDelay = vape.Categories.Combat:CreateModule({
		["Name"] = 'NoClickDelay',
		["Function"] = function(callback: boolean): ()
			if not callback then
				return;
			end;
			local sword: table = bedwars.SwordController;
			if RemoveDelay["Enabled"] then
				local oldTooFast: (...any) -> ...any = sword.isClickingTooFast;
				sword.isClickingTooFast = function(self: table): boolean
					self.lastSwing = tick();
					return false;
				end;
				NoClickDelay:Clean(function(): ()
					sword.isClickingTooFast = oldTooFast;
				end);

				if SwingLock["Enabled"] then
					local oldDisabled: (...any) -> ...any = sword.getSwordSwingDisabled;
					sword.getSwordSwingDisabled = function(): boolean
						return false;
					end;
					NoClickDelay:Clean(function(): ()
						sword.getSwordSwingDisabled = oldDisabled;
					end);
				end;

				local drill: table? = bedwars.DrillTabletController;
				if Drill["Enabled"] and drill then
					local oldDrill: (...any) -> ...any = drill.isClickingTooFast;
					drill.isClickingTooFast = function(): boolean
						return false;
					end;
					NoClickDelay:Clean(function(): ()
						drill.isClickingTooFast = oldDrill;
					end);
				end;
			end;

			if FastPlace["Enabled"] then
				bedwars.SharedConstants.BLOCK_PLACE_CPS = PlaceSpeed["Value"];
				NoClickDelay:Clean(function(): ()
					bedwars.SharedConstants.BLOCK_PLACE_CPS = bedwars.DefaultPlaceCPS;
				end);
			end;

			if Hitreg["Enabled"] then
				local hitBudget: number = 60 / (store.remoteLimits.SwordHit or config.RemoteLimit);
				local lastSwing: number, gap: number, natural: number = 0, 0.3, 0.3;
				local gamepadKey: Enum.KeyCode? = nil;
				local adjust: table = bedwars.SyncEvents.SwordSwing:setPriority(150):connect(function(event: table): ()
					natural = event.attackSpeed;
					local fury: number = bedwars.StatusEffectUtil:isActive(lplr.Character, 'fury_potion') and 2 - bedwars.BlackMarketeerBalance.FURY_POTION_ATTACK_SPEED_MULTIPLIER or 1;
					local base: number = natural / fury;
					local meta: table? = bedwars.ItemMeta[event.swordType];
					local stock: number? = meta and meta.sword and meta.sword.attackSpeed;
					if stock and math.abs(base - stock) < 1e-6 then
						base = stock;
					end;
					local spacing: number, _: number, _: number, cooldown: number = swordtiming.Calculate(base, fury, HitregRate["Value"] >= 35, hitBudget, HitregRate["Value"]);
					event.attackSpeed = math.max(spacing, cooldown);
					gap = event.attackSpeed;
				end);
				local restore: table = bedwars.SyncEvents.SwordSwing:setPriority(300):connect(function(event: table): ()
					event.attackSpeed = natural;
				end);
				local stamp: table = bedwars.SyncEvents.SwordSwing:setPriority(500):connect(function(event: table): ()
					if not event:isCancelled() then
						lastSwing = os.clock();
					end;
				end);
				local holdDisabled: boolean = sword:isHoldAutoSwingDisabled();
				sword:disableHoldAutoSwing();
				NoClickDelay:Clean(function(): ()
					adjust:Destroy();
					restore:Destroy();
