						sword:enableHoldAutoSwing();
					end;
				end);

				local holdSwing: () -> () = function(): ()
					if gamepadKey and os.clock() - lastSwing >= gap and store.hand.toolType == 'sword' and not sword.disableSwingState then
						sword:swingSwordAtMouse();
					end;
				end;
				NoClickDelay:Clean(inputService.InputBegan:Connect(function(input: InputObject): ()
					local controller: table? = bedwars.KeybindLoadController;
					local binds: table? = controller and type(controller.getKeybinds) == 'function' and controller:getKeybinds();
					local attack: any = binds and binds.gamepad and binds.gamepad.controlActions.Attack;
					if input.UserInputType == Enum.UserInputType.Gamepad1 and input.KeyCode == (typeof(attack) == 'EnumItem' and attack or Enum.KeyCode.ButtonR2) then
						gamepadKey = input.KeyCode;
						holdSwing();
					end;
				end));
				NoClickDelay:Clean(inputService.InputEnded:Connect(function(input: InputObject): ()
					if input.KeyCode == gamepadKey then
						gamepadKey = nil;
					end;
				end));
				NoClickDelay:Clean(runService.Heartbeat:Connect(holdSwing));
			end;
		end,
		["Tooltip"] = 'Removes the 9 clicks a second cap the client puts on swinging'
	});
	RemoveDelay = NoClickDelay:CreateToggle({
		["Name"] = 'Remove click delay',
		["Default"] = true,
		["Function"] = function(callback: boolean): ()
			if Drill then
				SwingLock.Object.Visible = callback;
				Drill.Object.Visible = callback;
			end;
			reapply();
		end,
		["Tooltip"] = 'The click cap removal itself; turn off to use only Hitreg adjust or Fast place'
	});
	SwingLock = NoClickDelay:CreateToggle({
		["Name"] = 'Swing lock',
		["Function"] = reapply,
		["Tooltip"] = 'Also lets you swing while a kit ability has swinging turned off, like sigrid on her elk'
	});
	Drill = NoClickDelay:CreateToggle({
		["Name"] = 'Drill',
		["Default"] = true,
		["Function"] = reapply,
		["Tooltip"] = 'Removes the same cap on the drill tablet'
	});
	Hitreg = NoClickDelay:CreateToggle({
		["Name"] = 'Hitreg adjust',
		["Function"] = function(callback: boolean): ()
			if HitregRate then
				HitregRate.Object.Visible = callback;
			end;
			reapply();
		end,
		["Tooltip"] = 'Swaps the games attack cooldown for a hit count of your own'
	});
	HitregRate = NoClickDelay:CreateSlider({
		["Name"] = 'Hitreg',
		["Min"] = 1,
		["Max"] = 36,
		["Default"] = 35,
		["Darker"] = true,
		["Visible"] = false,
		["Suffix"] = function(value: number): string
			return value == 1 and 'hit / 10s' or 'hits / 10s';
		end,
		["Tooltip"] = '35 matches killaura spacing, fury potions still speed it up'
	});
	FastPlace = NoClickDelay:CreateToggle({
		["Name"] = 'Fast place',
		["Function"] = function(callback: boolean): ()
			if PlaceSpeed then
				PlaceSpeed.Object.Visible = callback;
			end;
			reapply();
		end,
		["Tooltip"] = 'Changes the block place delay. Block-In and BedProtector keep the normal speed'
	});
	PlaceSpeed = NoClickDelay:CreateSlider({
		["Name"] = 'Place CPS',
		["Min"] = 1,
		["Max"] = 100,
		["Default"] = 13,
		["Darker"] = true,
		["Visible"] = false,
		["Function"] = function(value: number): ()
			if NoClickDelay["Enabled"] and FastPlace["Enabled"] then
				bedwars.SharedConstants.BLOCK_PLACE_CPS = value;
			end;
		end
	});
	NoClickDelay:CreateButton({
		["Name"] = 'Reset to bedwars cps',
		["Function"] = function(): ()
			PlaceSpeed:SetValue(bedwars.DefaultPlaceCPS);
		end
	});
end);

velo.run(function(): ()
	local Reach: table;
	local SwordReach: table;
	local SwordRange: table;
	local AirChance: table;
	local PlaceReach: table;
	local PlaceRange: table;
	local BreakReach: table;
	local BreakRange: table;
	local placeDefault: number = 24;
	local breakDefault: number = 18;
	local hitboxPadding: number = 2;
	local rng: Random = Random.new();

	local applySwordRange: () -> () = function(): ()
		bedwars.CombatConstant.RAYCAST_SWORD_CHARACTER_DISTANCE = Reach["Enabled"] and SwordReach["Enabled"] and SwordRange["Value"] + hitboxPadding or store.swordDistance;
	end;
	local studs: (value: number) -> string = function(value: number): string
		return value <= 1 and 'stud' or 'studs';
	end;

	Reach = vape.Categories.Combat:CreateModule({
		["Name"] = 'Reach',
		["Function"] = function(callback: boolean): ()
			applySwordRange();
			if not callback then
				return;
			end;
			local selector: table = bedwars.BlockSelector;
			local oldMouseInfo: (...any) -> ...any = selector.getMouseInfo;
			selector.getMouseInfo = function(self: table, mode: number, arguments: table?): ...any
				arguments = arguments or {};
				if mode == 0 then
					arguments.range = PlaceReach["Enabled"] and PlaceRange["Value"] or placeDefault;
				elseif mode == 1 then
					arguments.range = BreakReach["Enabled"] and BreakRange["Value"] or breakDefault;
				end;
				return oldMouseInfo(self, mode, arguments);
			end;

			local sword: table = bedwars.SwordController;
			local oldSend: (...any) -> ...any = sword.sendServerRequest;
			sword.sendServerRequest = function(self: table, target: any, ...: any): ...any
				local character: Model? = target and target:getInstance();
				local root: BasePart? = character and character.PrimaryPart;
				if root and entitylib.isAlive then
					local humanoid: Humanoid? = character:FindFirstChildWhichIsA('Humanoid');
					local airborne: boolean = humanoid and humanoid.FloorMaterial == Enum.Material.Air or math.abs(root.AssemblyLinearVelocity.Y) > 0.01;
					local handItem: table? = self:getHandItem();
					if (root.Position - entitylib.character.RootPart.Position).Magnitude > getReach(handItem and handItem.tool) and airborne and rng:NextNumber(0, 100) > AirChance:GetRandomValue() then
						return nil;
					end;
				end;
				return oldSend(self, target, ...);
			end;

			Reach:Clean(function(): ()
				selector.getMouseInfo = oldMouseInfo;
				sword.sendServerRequest = oldSend;
			end);
		end,
		["Tooltip"] = 'Allows you to place, attack, and break further'
	});
	SwordReach = Reach:CreateToggle({
		["Name"] = 'Sword Reach',
		["Default"] = true,
		["Function"] = function(callback: boolean): ()
			if AirChance then
				SwordRange.Object.Visible = callback;
				AirChance.Object.Visible = callback;
				applySwordRange();
			end;
		end
	});
	SwordRange = Reach:CreateSlider({
		["Name"] = 'Range',
		["Min"] = 1,
		["Max"] = 18,
		["Default"] = 18,
		["Decimal"] = 5,
		["Darker"] = true,
		["Suffix"] = studs,
		["Function"] = function(value: number): ()
			-- catsix writes the raw slider value here (no hitbox padding) until the next toggle re-applies value + 2.
			bedwars.CombatConstant.RAYCAST_SWORD_CHARACTER_DISTANCE = Reach["Enabled"] and SwordReach["Enabled"] and value or store.swordDistance;
		end
	});
	AirChance = Reach:CreateTwoSlider({
		["Name"] = 'Air reach hit chance',
		["Min"] = 0,
		["Max"] = 100,
		["DefaultMin"] = 100,
		["DefaultMax"] = 100,
		["Darker"] = true,
		["Tooltip"] = 'Chance for a hit past normal reach to land while the target is airborne, rolled every swing'
	});
	PlaceReach = Reach:CreateToggle({
		["Name"] = 'Placement Reach',
		["Function"] = function(callback: boolean): ()
			if PlaceRange then
				PlaceRange.Object.Visible = callback;
			end;
		end
	});
	PlaceRange = Reach:CreateSlider({
		["Name"] = 'Placement Range',
		["Min"] = 1,
		["Max"] = 60,
		["Default"] = 18,
		["Darker"] = true,
		["Visible"] = false,
		["Suffix"] = studs
	});
	BreakReach = Reach:CreateToggle({
		["Name"] = 'Break Reach',
		["Function"] = function(callback: boolean): ()
			if BreakRange then
				BreakRange.Object.Visible = callback;
			end;
		end
	});
	BreakRange = Reach:CreateSlider({
		["Name"] = 'Break Range',
		["Min"] = 1,
		["Max"] = 30,
		["Default"] = 30,
		["Decimal"] = 5,
		["Darker"] = true,
		["Visible"] = false,
		["Suffix"] = studs
	});
	Reach:CreateButton({
		["Name"] = 'Reset to default reach',
		["Function"] = function(): ()
			BreakRange:SetValue(breakDefault);
			PlaceRange:SetValue(placeDefault);
			SwordRange:SetValue(store.swordDistance - hitboxPadding);
		end,
		["Tooltip"] = 'Resets every range back to default'
	});
end);

velo.run(function(): ()
	local Sprint: table;
	local AutoSprint: table;
	local KeepSprint: table;
	local keepConstant: number = 5;

	local setKeepSprint: (enabled: boolean) -> () = function(enabled: boolean): ()
		local start: (...any) -> ...any = bedwars.SprintController.startSprinting;
		local current: any = debug.getconstant(start, keepConstant);
		if current ~= 'blockSprint' and current ~= 'blockSprinting' then
			notif('Sprint', 'Keep sprint is unavailable in this BedWars version', 5, 'warning');
			return;
		end;
		debug.setconstant(start, keepConstant, enabled and 'blockSprinting' or 'blockSprint');
	end;

	local reapply: () -> () = function(): ()
		if Sprint["Enabled"] then
			Sprint:Toggle();
			Sprint:Toggle();
		end;
	end;

	Sprint = vape.Categories.Combat:CreateModule({
		["Name"] = 'Sprint',
		["Function"] = function(callback: boolean): ()
			local controller: table = bedwars.SprintController;
			local mobileUi: Instance? = inputService.TouchEnabled and lplr.PlayerGui:FindFirstChild('MobileUI') or nil;
			local sprintButton: Instance? = mobileUi and mobileUi:FindFirstChild('4');
			if sprintButton and sprintButton:IsA('GuiObject') then
				sprintButton.Visible = not (callback and AutoSprint["Enabled"]);
			end;
			if callback then
				if AutoSprint["Enabled"] then
					local oldStop: (...any) -> ...any = controller.stopSprinting;
					controller.stopSprinting = function(...: any): any
						local result: any = oldStop(...);
						controller:startSprinting();
						return result;
					end;
					Sprint:Clean(function(): ()
						controller.stopSprinting = oldStop;
					end);
					Sprint:Clean(entitylib.Events.LocalAdded:Connect(function(): ()
						task.delay(0.1, function(): ()
							controller:stopSprinting();
						end);
					end));
				end;
				if KeepSprint["Enabled"] then
					setKeepSprint(true);
					Sprint:Clean(function(): ()
						setKeepSprint(false);
					end);
				end;
			end;
			controller:stopSprinting();
		end,
		["Tooltip"] = 'Sets your sprinting to true.'
	});
	AutoSprint = Sprint:CreateToggle({
		["Name"] = 'Auto sprint',
		["Default"] = true,
		["Function"] = reapply,
		["Tooltip"] = 'The sprint itself; turn off to use only Keep sprint'
	});
	KeepSprint = Sprint:CreateToggle({
		["Name"] = 'Keep sprint',
		["Function"] = reapply,
		["Tooltip"] = 'Lets you sprint with a speed potion.'
	});
end);

velo.run(function(): ()
	local TriggerBot: table;
	local Targets: table;
	local Range: table;
