	local ClickSpeed: table;
	local LimitItems: table;
	local RegionCheck: table;
	local ContinueKill: table;
	local ContinueTime: table;
	local RequireMouse: table;
	local AfkCheck: table;
	local GuiCheck: table;
	local ShowTarget: table;
	local BoxAnimation: table;
	local BoxSpeed: table;
	local BoxColor: table;
	local mouseRange: number = 200;
	local killGrace: number = 1;
	local idleDelay: number = 0.016;
	local boxSize: Vector3 = Vector3.new(4, 6, 4);
	local rayParams: RaycastParams = RaycastParams.new();
	local box: BoxHandleAdornment?, sizeTween: Tween?, sizeGoal: Vector3? = nil, nil, nil;

	local playersFirst: (a: table, b: table) -> boolean = function(a: table, b: table): boolean
		if (a.Entity.Player ~= nil) ~= (b.Entity.Player ~= nil) then
			return a.Entity.Player ~= nil;
		end;
		return a.Magnitude < b.Magnitude;
	end;

	local findTarget: (origin: Vector3, range: number) -> table? = function(origin: Vector3, range: number): table?
		if Angle["Value"] > 0 then
			local view: CFrame = gameCamera.CFrame;
			local limit: number = math.cos(math.rad(math.min(Angle["Value"], 360)) / 2);
			for _: number, ent: table in entitylib.AllPosition({
				["Part"] = 'RootPart',
				["Range"] = range,
				["Origin"] = origin,
				["Players"] = Targets.Players["Enabled"],
				["NPCs"] = Targets.NPCs["Enabled"],
				["Wallcheck"] = Targets.Walls["Enabled"] or nil,
				["Sort"] = playersFirst
			}) do
				local delta: Vector3 = ent.RootPart.Position - view.Position;
				if delta.Magnitude < 0.001 or view.LookVector:Dot(delta.Unit) >= limit then
					return ent;
				end;
			end;
			return nil;
		end;
		local ray: Ray = lplr:GetMouse().UnitRay;
		rayParams.FilterDescendantsInstances = {lplr.Character};
		local hit: RaycastResult? = bedwars.QueryUtil:raycast(ray.Origin, ray.Direction * mouseRange, rayParams);
		for _: number, ent: table in (hit and entitylib.List or {}) do
			local allowed: boolean = ent.Player and Targets.Players["Enabled"] or not ent.Player and Targets.NPCs["Enabled"];
			if allowed and ent.Targetable and hit.Instance:IsDescendantOf(ent.Character) and (origin - ent.RootPart.Position).Magnitude <= range and not (Targets.Walls["Enabled"] and entitylib.Wallcheck(origin, ent.RootPart.Position, nil, ent)) then
				return ent;
			end;
		end;
		return nil;
	end;

	TriggerBot = vape.Categories.Combat:CreateModule({
		["Name"] = 'TriggerBot',
		["Function"] = function(callback: boolean): ()
			if not callback then
				return;
			end;
			local lastTarget: table?, lastSwing: number, killUntil: number, nextCheck: number = nil, 0, 0, 0;
			local triggerStep: () -> () = function(): ()
				local now: number = tick();
				if now < nextCheck then
					return;
				end;
				if vape.ThreadFix then
					setthreadidentity(8);
				end;
				local ent: table?, attack: boolean = nil, false;
				local ready: boolean = entitylib.isAlive
					and not (GuiCheck["Enabled"] and bedwars.AppController:isLayerOpen(bedwars.UILayers.MAIN))
					and (not RequireMouse["Enabled"] or inputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1))
					and not (AfkCheck["Enabled"] and isAfk())
					and (not LimitItems["Enabled"] or store.hand.toolType == 'sword')
					and (not bedwars.DaoController or bedwars.DaoController.chargingMaid == nil);
				if ready then
					local range: number = math.clamp(Range["Value"], 0, getReach(store.hand.tool) * 2);
					ent = findTarget(entitylib.character.RootPart.Position, range);
					if lastTarget and lastTarget.Health <= 0 then
						if now - lastSwing <= killGrace then
							killUntil = now + ContinueTime["Value"];
						end;
						lastTarget = nil;
					end;
					attack = ent ~= nil
						or (RegionCheck["Enabled"] and bedwars.SwordController:getTargetInRegion(range, 0) ~= nil)
						or (ContinueKill["Enabled"] and now < killUntil);
					if ent then
						lastTarget = ent;
						targetinfo.Targets[ent] = now + 1;
					end;
					if attack and canSwing() then
						lastSwing = ent and now or lastSwing;
						bedwars.SwordController:swingSwordAtMouse();
					end;
				end;
				if box then
					box.Adornee = ent and ent.RootPart or nil;
					local goal: Vector3 = ent and boxSize or Vector3.zero;
					if goal ~= sizeGoal or not sizeTween or sizeTween.PlaybackState ~= Enum.PlaybackState.Completed then
						sizeTween = tweenService:Create(box, TweenInfo.new(BoxSpeed["Value"], Enum.EasingStyle[BoxAnimation["Value"]]), {["Size"] = goal});
						sizeTween:Play();
						sizeGoal = goal;
					end;
					if ent then
						box.Color3 = Color3.fromHSV(BoxColor["Hue"], BoxColor["Sat"], BoxColor["Value"]);
						box.Transparency = 1 - BoxColor["Opacity"];
					end;
				end;
				nextCheck = now + (attack and 1 / ClickSpeed:GetRandomValue() or idleDelay);
			end;
			TriggerBot:Clean(task.spawn(function(): ()
				repeat
					if vape.ThreadFix then
						setthreadidentity(8);
					end;
					triggerStep();
					task.wait();
				until false;
			end));
		end,
		["Tooltip"] = 'Automatically swings when hovering over a entity'
	});
	Targets = TriggerBot:CreateTargets({
		["Players"] = true,
		["NPCs"] = true,
		["Walls"] = true
	});
	Range = TriggerBot:CreateSlider({
		["Name"] = 'Range',
		["Min"] = 1,
		["Max"] = 18,
		["Default"] = 18,
		["Decimal"] = 10,
		["Suffix"] = function(value: number): string
			return value <= 1 and 'stud' or 'studs';
		end,
		["Tooltip"] = 'Clamped by the reach of what you are holding'
	});
	Angle = TriggerBot:CreateSlider({
		["Name"] = 'Angle',
		["Min"] = 0,
		["Max"] = 360,
		["Default"] = 0,
		["Suffix"] = 'degrees',
		["Tooltip"] = 'Swings at anything inside this cone of your view instead of only under the cursor, 360 includes behind you'
	});
	ClickSpeed = TriggerBot:CreateTwoSlider({
		["Name"] = 'CPS',
		["Min"] = 1,
		["Max"] = 9,
		["DefaultMin"] = 7,
		["DefaultMax"] = 7
	});
	LimitItems = TriggerBot:CreateToggle({
		["Name"] = 'Limit to items',
		["Default"] = true,
		["Tooltip"] = 'Only swings while holding a sword'
	});
	RegionCheck = TriggerBot:CreateToggle({
		["Name"] = 'Region check',
		["Default"] = true,
		["Tooltip"] = 'Also swings when the game reports a target inside your sword region'
	});
	ContinueKill = TriggerBot:CreateToggle({
		["Name"] = 'Continue after kill',
		["Function"] = function(callback: boolean): ()
			if ContinueTime then
				ContinueTime.Object.Visible = callback;
			end;
		end,
		["Tooltip"] = 'Keeps swinging briefly after your target dies so the next one gets hit right away'
	});
	ContinueTime = TriggerBot:CreateSlider({
		["Name"] = 'Continue time',
		["Min"] = 0.05,
		["Max"] = 2,
		["Default"] = 0.4,
		["Decimal"] = 100,
		["Darker"] = true,
		["Visible"] = false,
		["Suffix"] = 'seconds'
	});
	RequireMouse = TriggerBot:CreateToggle({["Name"] = 'Require mouse down'});
	AfkCheck = TriggerBot:CreateToggle({
		["Name"] = 'AFK check',
		["Tooltip"] = 'Stops after 30 seconds without input'
	});
	GuiCheck = TriggerBot:CreateToggle({["Name"] = 'GUI check'});
	ShowTarget = TriggerBot:CreateToggle({
		["Name"] = 'Show target',
		["Function"] = function(callback: boolean): ()
			if BoxColor then
				BoxAnimation.Object.Visible = callback;
				BoxSpeed.Object.Visible = callback;
				BoxColor.Object.Visible = callback;
			end;
			if callback then
				local adornment: BoxHandleAdornment = Instance.new('BoxHandleAdornment');
				adornment.Adornee = nil;
				adornment.AlwaysOnTop = true;
				adornment.Size = Vector3.zero;
				adornment.CFrame = CFrame.new(0, -0.5, 0);
				adornment.ZIndex = 0;
				if vape.ThreadFix then
					setthreadidentity(8);
				end;
				adornment.Parent = vape.gui;
				box, sizeTween = adornment, nil;
			elseif box then
				box:Destroy();
				box = nil;
			end;
		end
	});
	local easings: {string} = {'Bounce'};
	for _: number, style: EnumItem in Enum.EasingStyle:GetEnumItems() do
		if not table.find(easings, style.Name) then
			table.insert(easings, style.Name);
		end;
	end;
	BoxAnimation = TriggerBot:CreateDropdown({
		["Name"] = 'Box Animation',
		["List"] = easings,
		["Darker"] = true,
		["Visible"] = false
	});
	BoxSpeed = TriggerBot:CreateSlider({
		["Name"] = 'Animation Speed',
		["Min"] = 0,
		["Max"] = 10,
		["Default"] = 0.9,
		["Decimal"] = 30,
		["Darker"] = true,
		["Visible"] = false
	});
	BoxColor = TriggerBot:CreateColorSlider({
		["Name"] = 'Target Color',
		["DefaultHue"] = 0.6,
		["DefaultOpacity"] = 0.5,
		["Darker"] = true,
		["Visible"] = false
	});
end);

velo.run(function(): ()
	local Velocity: table;
	local Horizontal: table;
	local Vertical: table;
	local Chance: table;
	local TargetCheck: table;
	local AfkCheck: table;
	local AfkTime: table;
	local Delay: table;
	local DelayChance: table;
	local VerticalDelay: table;
	local HorizontalDelay: table;
	local DelayTarget: table;
	local targetRange: number = 50;
	local rng: Random = Random.new();
	local lastInput: number = 0;

	local playerNearby: () -> boolean = function(): boolean
		return entitylib.EntityPosition({["Range"] = targetRange, ["Part"] = 'RootPart', ["Players"] = true}) ~= nil;
	end;

	Velocity = vape.Categories.Combat:CreateModule({
		["Name"] = 'Velocity',
		["Function"] = function(callback: boolean): ()
			if not callback then
				return;
			end;
			lastInput = tick();
			Velocity:Clean(inputService.InputBegan:Connect(function(): ()
				lastInput = tick();
			end));
			local util: table = bedwars.KnockbackUtil;
			local oldApply: (...any) -> ...any = util.applyKnockback;
			util.applyKnockback = function(root: any, mass: any, direction: any, knockback: table?, ...: any): ...any
				local skipped: boolean = rng:NextNumber(0, 100) > Chance:GetRandomValue()
					or AfkCheck["Enabled"] and tick() - lastInput >= AfkTime["Value"] and entitylib.isAlive and entitylib.character.Humanoid.MoveDirection.Magnitude == 0;
				if not skipped and (not TargetCheck["Enabled"] or playerNearby()) then
					knockback = knockback or {};
					if Horizontal["Value"] == 0 and Vertical["Value"] == 0 then
						return nil;
					end;
					knockback.horizontal = (knockback.horizontal or 1) * (Horizontal["Value"] / 100);
					knockback.vertical = (knockback.vertical or 1) * (Vertical["Value"] / 100);
				end;
				if Delay["Enabled"] and rng:NextNumber(0, 100) <= DelayChance["Value"] and (not DelayTarget["Enabled"] or playerNearby()) then
					local extra: table = table.pack(...);
					for _: number, split: table in {{'horizontal', VerticalDelay}, {'vertical', HorizontalDelay}} do
						local part: table = knockback and table.clone(knockback) or {};
						part[split[1]] = 0;
						task.delay(split[2]:GetRandomValue() / 1000, oldApply, root, mass, direction, part, table.unpack(extra, 1, extra.n));
					end;
					return nil;
				end;
				return oldApply(root, mass, direction, knockback, ...);
			end;
			Velocity:Clean(function(): ()
				util.applyKnockback = oldApply;
			end);
		end,
		["Tooltip"] = 'Reduces knockback taken'
	});
	Horizontal = Velocity:CreateSlider({
		["Name"] = 'Horizontal',
		["Min"] = 0,
		["Max"] = 100,
		["Default"] = 0,
		["Suffix"] = '%'
	});
	Vertical = Velocity:CreateSlider({
		["Name"] = 'Vertical',
		["Min"] = 0,
		["Max"] = 100,
		["Default"] = 0,
		["Suffix"] = '%'
	});
	Chance = Velocity:CreateTwoSlider({
		["Name"] = 'Chance range',
		["Min"] = 0,
		["Max"] = 100,
		["DefaultMin"] = 100,
		["DefaultMax"] = 100,
		["Tooltip"] = 'Chance in % for each knockback to be reduced, rolled between the two values every hit'
	});
	TargetCheck = Velocity:CreateToggle({
		["Name"] = 'Only when targeting',
		["Tooltip"] = 'Only reduces knockback while a player is within 50 studs'
	});
	AfkCheck = Velocity:CreateToggle({
		["Name"] = 'AFK check',
		["Function"] = function(callback: boolean): ()
			if AfkTime then
				AfkTime.Object.Visible = callback;
			end;
		end,
		["Tooltip"] = 'Takes full knockback while you stand still and have not pressed anything for the AFK time'
	});
	AfkTime = Velocity:CreateSlider({
		["Name"] = 'AFK time',
		["Min"] = 1,
		["Max"] = 60,
		["Default"] = 10,
		["Darker"] = true,
		["Visible"] = false,
		["Suffix"] = function(value: number): string
			return value == 1 and 'second' or 'seconds';
		end
	});
	Delay = Velocity:CreateToggle({
		["Name"] = 'Delay knockback',
		["Function"] = function(callback: boolean): ()
			if DelayTarget then
				DelayChance.Object.Visible = callback;
				VerticalDelay.Object.Visible = callback;
				HorizontalDelay.Object.Visible = callback;
				DelayTarget.Object.Visible = callback;
			end;
		end,
		["Tooltip"] = 'Delays incoming knockback packets (catsix KnockbackDelay); set Chance range to 0 to only delay'
	});
	DelayChance = Velocity:CreateSlider({
		["Name"] = 'Delay chance',
		["Min"] = 1,
		["Max"] = 100,
		["Default"] = 40,
		["Darker"] = true,
		["Visible"] = false,
		["Suffix"] = '%'
	});
	VerticalDelay = Velocity:CreateTwoSlider({
		["Name"] = 'Vertical delay',
		["Min"] = 0,
		["Max"] = 500,
		["DefaultMin"] = 50,
		["DefaultMax"] = 200,
		["Darker"] = true,
		["Visible"] = false,
		["Tooltip"] = 'catsix Air delay: milliseconds before the vertical part is applied'
	});
	HorizontalDelay = Velocity:CreateTwoSlider({
		["Name"] = 'Horizontal delay',
		["Min"] = 0,
		["Max"] = 500,
		["DefaultMin"] = 50,
		["DefaultMax"] = 200,
		["Darker"] = true,
		["Visible"] = false,
		["Tooltip"] = 'catsix Ground delay: milliseconds before the horizontal part is applied'
	});
	DelayTarget = Velocity:CreateToggle({
		["Name"] = 'Delay target check',
		["Darker"] = true,
		["Visible"] = false,
		["Tooltip"] = 'Only delays knockback while a player is within 50 studs'
	});
end);

