			local steps: number = math.clamp(math.ceil(math.max(t * 60, (arc.Magnitude * t + gravity * t * t * 0.5) / 6)), 12, 240);
			for step: number = 1, steps do
				local elapsed: number = t * step / steps;
				local point: Vector3 = origin + arc * elapsed - Vector3.new(0, gravity * elapsed * elapsed * 0.5, 0);
