velo.run(function(): ()
	local AutoCharge: table = {["Enabled"] = false};
	local ChargeTime: table;
	local multiHitConstant: string, damageConstant: string = 'multiHitCheckDurationSec', 'damage';

	AutoCharge = vape.Categories.Combat:CreateModule({
		["Name"] = 'AutoCharge',
		["Function"] = function(callback: boolean): ()
			if not callback then
				return;
			end;
			local sword: table = bedwars.SwordController;
			local constantIndex: number? = nil;
			for index: number, value: any in debug.getconstants(sword.attackEntity) do
				if value == multiHitConstant then
					constantIndex = index;
					break;
				end;
			end;
			if constantIndex then
				debug.setconstant(sword.attackEntity, constantIndex, damageConstant);
			else
				notif('AutoCharge', 'Multi-hit check not found in this version, only swing pacing is active', 6, 'warning');
			end;
			local lastCharge: number, effectReady: boolean = 0, false;
			local oldRequest: (...any) -> ...any = sword.sendServerRequest;
			local oldEffect: (...any) -> ...any = sword.playSwordEffect;
			local requestHook: (...any) -> ...any = function(self: table, ...: any): ...any
				if os.clock() - lastCharge < ChargeTime["Value"] then
					return nil;
				end;
				self.lastSwingServerTimeDelta = 0.5;
				lastCharge, effectReady = os.clock(), true;
				local item: table? = self:getHandItem();
				if item and item.tool then
					self:playSwordEffect(bedwars.ItemMeta[item.tool.Name], false);
				end;
				return oldRequest(self, ...);
			end;
			local effectHook: (...any) -> ...any = function(...: any): ...any
				if not effectReady then
					return nil;
				end;
				effectReady = false;
				return oldEffect(...);
			end;
			sword.sendServerRequest = requestHook;
			sword.playSwordEffect = effectHook;
			AutoCharge:Clean(function(): ()
				if constantIndex then
					debug.setconstant(sword.attackEntity, constantIndex, multiHitConstant);
				end;
				if sword.sendServerRequest == requestHook then
					sword.sendServerRequest = oldRequest;
				end;
				if sword.playSwordEffect == effectHook then
					sword.playSwordEffect = oldEffect;
				end;
			end);
		end,
		["Tooltip"] = 'Allows you to get charged hits while spam clicking.'
	});
	ChargeTime = AutoCharge:CreateSlider({
		["Name"] = 'Charge Time',
		["Min"] = 0,
		["Max"] = 0.5,
		["Default"] = 0.4,
		["Decimal"] = 100
	});
end);

velo.run(function(): ()
	local BedESP: table = {["Enabled"] = false};
	local Mode: table = {["Value"] = '2D'};
	local BedColor: table = {["Hue"] = 0.44, ["Sat"] = 1, ["Value"] = 1};
	local TeamColor: table = {["Enabled"] = true};
	local BoundingBox: table = {["Enabled"] = true};
	local Filled: table = {["Enabled"] = false};
	local HealthBar: table = {["Enabled"] = false};
	local ShowName: table = {["Enabled"] = false};
	local Background: table = {["Enabled"] = false};
	local HideOwn: table = {["Enabled"] = true};
	local DistanceCheck: table = {["Enabled"] = false};
	local DistanceRange: table = {["ValueMin"] = 0, ["ValueMax"] = 256};
	local legColor: Color3 = Color3.fromRGB(167, 112, 64);
	local cornerSigns: {Vector3} = {
		Vector3.new(1, 1, 1), Vector3.new(1, -1, 1), Vector3.new(-1, 1, 1), Vector3.new(-1, -1, 1),
		Vector3.new(1, 1, -1), Vector3.new(1, -1, -1), Vector3.new(-1, 1, -1), Vector3.new(-1, -1, -1)
	};
	local edges: {{number}} = {{1, 2}, {3, 4}, {5, 6}, {7, 8}, {1, 3}, {1, 5}, {5, 7}, {7, 3}, {2, 4}, {2, 6}, {6, 8}, {8, 4}};
	local tracked: {[Instance]: table} = {};
	local folder: Folder = Instance.new('Folder');
	folder.Parent = vape.gui;

	local tintOf: (bed: Instance, part: BasePart?) -> Color3 = function(bed: Instance, part: BasePart?): Color3
		local custom: Color3 = Color3.fromHSV(BedColor["Hue"], BedColor["Sat"], BedColor["Value"]);
		if not TeamColor["Enabled"] then
			return custom;
		end;
		if part then
			return part.Name == 'Legs' and legColor or part.Color;
		end;
		local sheet: Instance? = bed:FindFirstChild('Bed');
		return sheet and sheet:IsA('BasePart') and sheet.Color or custom;
	end;

	local newDrawing: (entry: table, kind: string, properties: table, tinted: boolean) -> any = function(entry: table, kind: string, properties: table, tinted: boolean): any
		local object: any = Drawing.new(kind);
		for property: string, value: any in properties do
			object[property] = value;
		end;
		if tinted then
			object.Color = tintOf(entry.Bed);
			entry.Tinted[object] = true;
		end;
		table.insert(entry.Objects, object);
		return object;
	end;

	local recolor: () -> () = function(): ()
		for bed: Instance, entry: table in tracked do
			for _: number, object: any in entry.Objects do
				if typeof(object) == 'Instance' then
					object.Color3 = tintOf(bed, object.Adornee);
				elseif entry.Tinted[object] then
					object.Color = tintOf(bed);
				end;
			end;
		end;
	end;

	local release: (bed: Instance) -> () = function(bed: Instance): ()
		local entry: table? = tracked[bed];
		if not entry then
			return;
		end;
		if vape.ThreadFix then
			setthreadidentity(8);
		end;
		tracked[bed] = nil;
		for _: number, object: any in entry.Objects do
			if typeof(object) == 'Instance' then
				object:Destroy();
			else
				object:Remove();
			end;
		end;
	end;

	local track: (bed: Instance) -> () = function(bed: Instance): ()
		if not BedESP["Enabled"] or not bed.Parent or not bed:IsA('BasePart') then
			return;
		end;
		if vape.ThreadFix then
			setthreadidentity(8);
		end;
		release(bed);
		local origin: CFrame = bed.CFrame;
		local low: Vector3, high: Vector3 = Vector3.one * math.huge, Vector3.one * -math.huge;
		local parts: {BasePart} = {};
		for _: number, part: Instance in bed:GetChildren() do
			if part:IsA('BasePart') and part.Name ~= 'Blanket' then
				table.insert(parts, part);
				local offset: CFrame, half: Vector3 = origin:ToObjectSpace(part.CFrame), part.Size / 2;
				if part.Name == 'Legs' then
					offset, half = offset * CFrame.new(0, -0.4, 0), half - Vector3.new(0, 0.5, 0);
				end;
				for _: number, sign: Vector3 in cornerSigns do
					local point: Vector3 = offset * (half * sign);
					low, high = low:Min(point), high:Max(point);
				end;
			end;
		end;
		if low.X == math.huge then
			low, high = -bed.Size / 2, bed.Size / 2;
		end;
		local center: Vector3, extents: Vector3 = (low + high) / 2, (high - low) / 2;
		local entry: table = {
			["Bed"] = bed,
			["Center"] = origin * center,
			["Corners"] = {},
			["Team"] = tonumber(bed:GetAttribute('TeamId')),
			["Cell"] = bedwars.BlockController:getBlockPosition(bed.Position),
			["Objects"] = {},
			["Tinted"] = {},
			["Adornments"] = Mode["Value"] == 'Adornment'
		};
		for index: number, sign: Vector3 in cornerSigns do
			entry.Corners[index] = origin * (center + extents * sign);
		end;

		if entry.Adornments then
			for _: number, part: BasePart in parts do
				local legs: boolean = part.Name == 'Legs';
				local box: BoxHandleAdornment = Instance.new('BoxHandleAdornment');
				box.Size = part.Size + Vector3.new(0.01, legs and -1 or 0.01, 0.01);
				box.CFrame = legs and CFrame.new(0, -0.4, 0) or CFrame.identity;
				box.AlwaysOnTop = true;
				box.ZIndex = legs and 0 or 2;
				box.Visible = false;
				box.Adornee = part;
				box.Color3 = tintOf(bed, part);
				box.Parent = folder;
				table.insert(entry.Objects, box);
			end;
		elseif Mode["Value"] == '2D' then
			entry.Box = newDrawing(entry, 'Square', {["Thickness"] = 1, ["Filled"] = false, ["ZIndex"] = 2, ["Transparency"] = BoundingBox["Enabled"] and 1 or 0}, true);
			if BoundingBox["Enabled"] then
				entry.Outer = newDrawing(entry, 'Square', {["Thickness"] = 1, ["Filled"] = false, ["ZIndex"] = 1, ["Transparency"] = 0.35, ["Color"] = Color3.new()}, false);
				entry.Inner = newDrawing(entry, 'Square', {["Thickness"] = 1, ["Filled"] = Filled["Enabled"], ["ZIndex"] = 1, ["Transparency"] = 0.35, ["Color"] = Color3.new()}, false);
			end;
			if HealthBar["Enabled"] then
				entry.HealthBack = newDrawing(entry, 'Line', {["Thickness"] = 3, ["ZIndex"] = 1, ["Transparency"] = 0.35, ["Color"] = Color3.new()}, false);
				entry.Health = newDrawing(entry, 'Line', {["Thickness"] = 1, ["ZIndex"] = 2}, false);
			end;
			if ShowName["Enabled"] then
				local queue: table? = bedwars.QueueMeta[store.queueType];
				local team: table? = queue and entry.Team and queue.teams[entry.Team];
				local title: string = (team and team.displayName or 'Team '..tostring(entry.Team or '?'))..' Bed';
				if Background["Enabled"] then
					entry.TextBack = newDrawing(entry, 'Square', {["Thickness"] = 1, ["Filled"] = true, ["ZIndex"] = 0, ["Transparency"] = 0.35, ["Color"] = Color3.new()}, false);
				end;
				entry.Shadow = newDrawing(entry, 'Text', {["Text"] = title, ["Size"] = 20, ["Center"] = true, ["ZIndex"] = 1, ["Color"] = Color3.new()}, false);
				entry.Text = newDrawing(entry, 'Text', {["Text"] = title, ["Size"] = 20, ["Center"] = true, ["ZIndex"] = 2}, true);
			end;
		else
			entry.Lines = {};
			for index: number = 1, #edges do
				entry.Lines[index] = newDrawing(entry, 'Line', {["Thickness"] = 1}, true);
			end;
		end;
		tracked[bed] = entry;
	end;

	local render: () -> () = function(): ()
		if vape.ThreadFix then
			setthreadidentity(8);
		end;
		local origin: Vector3? = entitylib.isAlive and entitylib.character.RootPart.Position or nil;
		local ownTeam: number? = tonumber(lplr:GetAttribute('Team'));
		for bed: Instance, entry: table in tracked do
			local _: Vector3, onScreen: boolean = gameCamera:WorldToViewportPoint(entry.Center);
			local distance: number = origin and (origin - entry.Center).Magnitude or math.huge;
			local shown: boolean = (onScreen or entry.Adornments == true)
				and not (HideOwn["Enabled"] and entry.Team == ownTeam)
				and not (DistanceCheck["Enabled"] and (distance < DistanceRange["ValueMin"] or distance > DistanceRange["ValueMax"]));
			if entry.Shown ~= shown then
				entry.Shown = shown;
				for _: number, object: any in entry.Objects do
					object.Visible = shown;
				end;
			end;
			if not shown or entry.Adornments then
				continue;
			end;
			local points: {Vector2} = {};
			for index: number, corner: Vector3 in entry.Corners do
				local point: Vector3 = gameCamera:WorldToViewportPoint(corner);
				points[index] = Vector2.new(point.X, point.Y);
			end;
			if entry.Lines then
				for index: number, edge: {number} in edges do
					entry.Lines[index].From = points[edge[1]];
					entry.Lines[index].To = points[edge[2]];
				end;
				continue;
			end;
			local low: Vector2, high: Vector2 = points[1], points[1];
			for _: number, point: Vector2 in points do
				low, high = low:Min(point), high:Max(point);
			end;
			local size: Vector2 = high - low;
			entry.Box.Position = low // 1;
			entry.Box.Size = size // 1;
			if entry.Outer then
				entry.Outer.Position = (low - Vector2.one) // 1;
				entry.Outer.Size = (size + Vector2.one * 2) // 1;
				entry.Inner.Position = (low + Vector2.one) // 1;
				entry.Inner.Size = (size - Vector2.one * 2) // 1;
			end;
			if entry.Health then
				local data: Instance? = bedwars.BlockController:getStore():getBlockData(entry.Cell);
				local health: number = math.clamp((data and (data:GetAttribute('1') or data:GetAttribute('Health')) or bed:GetAttribute('Health') or 1) / (bed:GetAttribute('MaxHealth') or 1), 0, 1);
				entry.Health.Color = Color3.fromHSV(health / 2.5, 0.89, 0.75);
				entry.Health.From = Vector2.new(low.X - 6, high.Y) // 1;
				entry.Health.To = Vector2.new(low.X - 6, high.Y - size.Y * health) // 1;
				entry.HealthBack.From = Vector2.new(low.X - 6, high.Y + 1) // 1;
				entry.HealthBack.To = Vector2.new(low.X - 6, low.Y - 1) // 1;
			end;
			if entry.Text then
				local anchor: Vector2 = Vector2.new(low.X + size.X / 2, low.Y - 28) // 1;
				entry.Text.Position = anchor;
				entry.Shadow.Position = anchor + Vector2.one;
				if entry.TextBack then
					local bounds: Vector2 = entry.Text.TextBounds;
					entry.TextBack.Size = bounds + Vector2.new(8, 4);
					entry.TextBack.Position = anchor - Vector2.new(4 + bounds.X / 2, 0);
				end;
			end;
		end;
	end;

	local rebuild: () -> () = function(): ()
		if BedESP["Enabled"] then
			BedESP:Toggle();
			BedESP:Toggle();
		end;
	end;

	local syncOptions: () -> () = function(): ()
		local flat: boolean = Mode["Value"] == '2D';
		for _: number, option: table in {BoundingBox, Filled, HealthBar, ShowName} do
			if option.Object then
				option.Object.Visible = flat;
			end;
		end;
		if Background.Object then
			Background.Object.Visible = flat and ShowName["Enabled"];
		end;
		if DistanceRange.Object then
			DistanceRange.Object.Visible = DistanceCheck["Enabled"];
		end;
	end;

	BedESP = vape.Categories.Render:CreateModule({
		["Name"] = 'BedESP',
		["Function"] = function(callback: boolean): ()
			if callback then
				BedESP:Clean(collectionService:GetInstanceAddedSignal('bed'):Connect(function(bed: Instance): ()
					task.delay(0.2, track, bed);
				end));
				BedESP:Clean(collectionService:GetInstanceRemovedSignal('bed'):Connect(release));
				BedESP:Clean(runService.RenderStepped:Connect(render));
				for _: number, bed: Instance in collectionService:GetTagged('bed') do
					track(bed);
				end;
			else
				for bed: Instance in tracked do
					release(bed);
				end;
			end;
		end,
		["Tooltip"] = 'Render beds through walls'
	});
	Mode = BedESP:CreateDropdown({
		["Name"] = 'Mode',
		["List"] = {'2D', '3D', 'Adornment'},
		["Function"] = function(value: string): ()
			rebuild();
			syncOptions();
		end,
		["Tooltip"] = '2D - screen box with optional health and name\n3D - outlined bounding box\nAdornment - highlights every bed part'
	});
	BedColor = BedESP:CreateColorSlider({
		["Name"] = 'Bed Color',
		["Function"] = recolor
	});
	TeamColor = BedESP:CreateToggle({
		["Name"] = 'Use Team Color',
		["Default"] = true,
		["Darker"] = true,
		["Function"] = recolor
	});
	BoundingBox = BedESP:CreateToggle({
		["Name"] = 'Bounding Box',
		["Default"] = true,
		["Darker"] = true,
		["Function"] = rebuild
	});
	Filled = BedESP:CreateToggle({
		["Name"] = 'Filled',
		["Darker"] = true,
		["Function"] = rebuild
	});
	HealthBar = BedESP:CreateToggle({
		["Name"] = 'Health Bar',
		["Darker"] = true,
		["Function"] = rebuild
	});
	ShowName = BedESP:CreateToggle({
		["Name"] = 'Name',
		["Darker"] = true,
		["Function"] = function(callback: boolean): ()
			rebuild();
			syncOptions();
		end
	});
	Background = BedESP:CreateToggle({
		["Name"] = 'Show Background',
		["Darker"] = true,
		["Function"] = rebuild
	});
	HideOwn = BedESP:CreateToggle({
		["Name"] = 'Hide Own Bed',
		["Default"] = true,
		["Tooltip"] = "Hides your own team's bed"
	});
	DistanceCheck = BedESP:CreateToggle({
		["Name"] = 'Distance Check',
		["Function"] = syncOptions
	});
	DistanceRange = BedESP:CreateTwoSlider({
		["Name"] = 'Bed Distance',
		["Min"] = 0,
		["Max"] = 512,
		["DefaultMin"] = 0,
		["DefaultMax"] = 256,
		["Darker"] = true,
		["Visible"] = false
	});
	syncOptions();
end);

velo.run(function(): ()
	local ObjectESP: table = {["Enabled"] = false};
	local ShowDistance: table = {["Enabled"] = true};
	local Scale: table = {["Value"] = 1};
	local Transparency: table = {["Value"] = 0.5};
	local TextColor: table = {["Hue"] = 0.44, ["Sat"] = 1, ["Value"] = 1};
	local ItemDistance: table = {["Enabled"] = false};
	local YourTraps: table = {["Enabled"] = true};
	local TrapColor: table = {["Hue"] = 0, ["Sat"] = 0.75, ["Value"] = 1};
	local PotBackground: table = {["Enabled"] = true};
	local PotColor: table = {["Hue"] = 0, ["Sat"] = 0, ["Value"] = 0, ["Opacity"] = 0.5};
	local textSize: number = 14;
	local panelTextSize: number = 16;
	local panelRefresh: number = 0.25;
	local panelRows: number = 8;
	local voidHeight: number = -200;
	local hoardRadius: number = 6;
	local timers: {[Instance]: Instance?} = {};
	local potTemplate: (MeshPart | boolean)? = nil;
	local panel: table? = nil;
	local expanded: boolean = false;
	local folder: Folder = Instance.new('Folder');
	if vape.ThreadFix then
		setthreadidentity(8);
	end;
	folder.Parent = vape.gui;

	local generatorKinds: {[string]: table} = {
		["iron"] = {["Name"] = 'Iron', ["Color"] = 'rgb(255,255,255)', ["Toggle"] = {["Enabled"] = true}, ["Tooltip"] = "Shows your team's iron generator"},
		["diamond"] = {["Name"] = 'Diamond', ["Color"] = 'rgb(85,170,255)', ["Toggle"] = {["Enabled"] = true}, ["Tooltip"] = 'Shows diamond generators, in blue'},
		["emerald"] = {["Name"] = 'Emerald', ["Color"] = 'rgb(85,255,85)', ["Toggle"] = {["Enabled"] = false}, ["Tooltip"] = 'Shows emerald generators, in green'}
	};
	local generatorOrder: {string} = {'iron', 'diamond', 'emerald'};

	local withDistance: (entry: table, point: Vector3, origin: Vector3?) -> string = function(entry: table, point: Vector3, origin: Vector3?): string
		if ShowDistance["Enabled"] and origin then
			return entry.Name..' | '..math.floor((origin - point).Magnitude)..'m';
		end;
		return entry.Name;
	end;

	local categories: {table} = {
		{
			["Name"] = 'Beehives',
			["Tags"] = {["beehive"] = 'Beehive'},
			["Height"] = 1,
			["Arial"] = true,
			["Async"] = true,
			["Label"] = function(object: Instance): string
				local placer: number? = object:GetAttribute('PlacedByUserId');
				local owner: Player? = placer and playersService:GetPlayerByUserId(placer) or nil;
				if owner then
					return owner.Name;
				end;
				if placer then
					local success: boolean, result: any = pcall(playersService.GetNameFromUserIdAsync, playersService, placer);
					if success and result then
						return result;
					end;
				end;
				return 'Unknown';
			end,
			["Text"] = function(entry: table): string?
				local level: number = entry.Object:GetAttribute('Level') or 0;
				return entry.Name.."'s beehive | "..level..' Bee'..(level >= 2 and 's' or '');
			end
		},
		{
			["Name"] = 'Collectables',
			["Tags"] = {
				["alchemist_ingedients"] = 'Ingredient', ["alchemy_crystal"] = 'Crystal', ["crystalheart_seed"] = 'Crystalheart',
				["forest_environment_plant"] = 'Plant', ["ghost"] = 'Ghost', ["hidden-metal"] = 'Metal', ["jailor_soul"] = 'Soul',
				["murder_coin"] = 'Coin', ["shadow_coin"] = 'Shadow Coin', ["soulvine_seed"] = 'Soulvine', ["spirit_gardener_energy"] = 'Energy',
				["spirit_gardener_seeds"] = 'Seed', ["stars"] = 'Star', ["tearbloom_seed"] = 'Tearbloom'
			},
			["Height"] = 2,
			["ListName"] = 'Collectable List',
			["Defaults"] = {'Coin', 'Crystal', 'Crystalheart', 'Energy', 'Ghost', 'Ingredient', 'Metal', 'Plant', 'Seed', 'Shadow Coin', 'Soul', 'Soulvine', 'Star', 'Tearbloom'},
			["Text"] = withDistance
		},
		{
			["Name"] = 'Crates',
			["Tags"] = {
				["CrateAltar"] = 'Crate Altar', ["GlitchedLuckyBlock"] = 'Lucky Block', ["GrowingHalloweenLuckyBlock"] = 'Lucky Block',
				["HalloweenLuckyBlock"] = 'Lucky Block', ["MagicalHeroLuckyBlock"] = 'Lucky Block', ["NewYearsLuckyBlock"] = 'Lucky Block',
				["RewardCrate"] = 'Reward Crate', ["brewing_cauldron"] = 'Cauldron', ["cauldron"] = 'Cauldron', ["chest"] = 'Chest',
				["crate"] = 'Crate', ["infected-crate"] = 'Crate', ["juggernaut-crate"] = 'Juggernaut Crate', ["launch-pad"] = 'Launch Pad',
				["personal-chest"] = 'Personal Chest', ["smelter-block"] = 'Smelter', ["squad-launcher"] = 'Squad Launcher', ["team-crate"] = 'Team Crate'
			},
			["Height"] = 2,
			["Deep"] = true,
			["ListName"] = 'Crate List',
			["Defaults"] = {'Cauldron', 'Chest', 'Crate', 'Crate Altar', 'Juggernaut Crate', 'Launch Pad', 'Lucky Block', 'Personal Chest', 'Reward Crate', 'Smelter', 'Squad Launcher', 'Team Crate'},
			["Text"] = withDistance
		},
		{
			["Name"] = 'Crops',
			["Tags"] = {["HarvestableCrop"] = 'Crop'},
			["Height"] = 1,
			["Arial"] = true,
			["Pivot"] = true,
			["Label"] = function(object: Instance): string
				local meta: table? = bedwars.ItemMeta[object.Name];
				return meta and meta.displayName or 'Crop';
			end,
			["Text"] = function(entry: table): string?
				return entry.Name;
			end
		},
		{
			["Name"] = 'Generators',
			["Tags"] = {},
			["Panel"] = true
		},
		{
			["Name"] = 'Items',
			["Tags"] = {["ItemDrop"] = 'Item'},
			["Height"] = 1,
			["Arial"] = true,
			["White"] = true,
			["Loose"] = true,
			["ListName"] = 'Item List',
			["Defaults"] = {},
			["Label"] = function(object: Instance): string
				local meta: table? = bedwars.ItemMeta[object.Name];
				return meta and meta.displayName or object.Name;
			end,
			["Text"] = function(entry: table, point: Vector3, origin: Vector3?): string?
				if point.Y <= voidHeight then
					return nil;
				end;
				local amount: number = entry.Object:GetAttribute('Amount') or 1;
				local text: string = entry.Name..(amount >= 2 and ' x'..amount or '');
				if ItemDistance["Enabled"] then
					text = '<font color="rgb(85, 255, 85)">[</font><font color="rgb(255, 255, 255)">'..(origin and math.floor((origin - point).Magnitude) or 0)..'</font><font color="rgb(85, 255, 85)">]</font> '..text;
				end;
				return text;
			end
		},
		{
			["Name"] = 'Pots',
			["Tags"] = {["block"] = 'Desert Pot'},
			["Blocks"] = {["desert_pot"] = 'Desert Pot'}
		},
		{
			["Name"] = 'Traps',
			["Tags"] = {["block"] = 'Trap'},
			["Blocks"] = {
				["glue_trap"] = 'Gloop', ["grave_trap"] = 'Grave', ["grave_trap_block"] = 'Grave', ["invisible_landmine"] = 'Landmine',
				["lucky_block_trap"] = 'Lucky Trap', ["snap_trap"] = 'Snap Trap', ["spike_trap"] = 'Spikes', ["tesla_trap"] = 'Tesla'
			},
			["Height"] = 2,
			["Solid"] = true,
			["ListName"] = 'Trap List',
			["Defaults"] = {'Gloop', 'Grave', 'Landmine', 'Lucky Trap', 'Snap Trap', 'Spikes', 'Tesla'},
			["Text"] = function(entry: table, point: Vector3, origin: Vector3?): string?
				if not YourTraps["Enabled"] then
					local placer: number? = entry.Object:GetAttribute('PlacedByUserId');
					if placer and placer ~= 0 then
						local owner: Player? = playersService:GetPlayerByUserId(placer);
						if placer == lplr.UserId or (owner ~= nil and owner:GetAttribute('Team') == lplr:GetAttribute('Team')) then
							return nil;
						end;
					end;
				end;
				return withDistance(entry, point, origin);
			end
		}
	};
	for _: number, category: table in categories do
		category.Tracked = {};
	end;

	local colorOf: (category: table) -> Color3 = function(category: table): Color3
		local option: table? = category.Color;
		return option and Color3.fromHSV(option["Hue"], option["Sat"], option["Value"]) or Color3.new(1, 1, 1);
	end;

	local paintPot: (entry: table) -> () = function(entry: table): ()
		entry.Viewport.BackgroundColor3 = Color3.fromHSV(PotColor["Hue"], PotColor["Sat"], PotColor["Value"]);
		entry.Viewport.BackgroundTransparency = 1 - (PotBackground["Enabled"] and PotColor["Opacity"] or 0);
		entry.Blur.Visible = PotBackground["Enabled"];
	end;

	local untrack: (category: table, object: Instance) -> () = function(category: table, object: Instance): ()
		local entry: table? = category.Tracked[object];
		if entry then
			category.Tracked[object] = nil;
			entry.Label:Destroy();
		end;
	end;

	local track: (category: table, object: Instance, tag: string) -> () = function(category: table, object: Instance, tag: string): ()
		if category.Tracked[object] then
			return;
		end;
		local name: string?;
		if category.Blocks then
			name = (not category.Solid or object:IsA('BasePart')) and category.Blocks[object.Name] or nil;
		elseif category.Label then
			name = category.Label(object);
			if not ObjectESP["Enabled"] or category.Tracked[object] then
				return;
			end;
		else
			name = category.Tags[tag];
		end;
		if not name then
			return;
		end;
		if category.List then
			local filter: {string} = category.List.ListEnabled;
			local allowed: boolean = false;
			if category.Loose then
				allowed = #filter == 0;
				for _: number, wanted: string in filter do
					allowed = allowed or wanted:lower() == object.Name:lower() or wanted:lower() == name:lower();
				end;
			else
				allowed = table.find(filter, name) ~= nil;
			end;
			if not allowed then
				return;
			end;
		end;
		if vape.ThreadFix then
			setthreadidentity(8);
		end;
		if not category.Text then
			local billboard: BillboardGui = Instance.new('BillboardGui');
			billboard.Parent = folder;
			billboard.Name = object.Name;
			billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0);
			billboard.Size = UDim2.fromOffset(36, 36);
			billboard.AlwaysOnTop = true;
			billboard.ClipsDescendants = false;
			billboard.Adornee = object;
			local entry: table = {["Label"] = billboard, ["Blur"] = addBlur(billboard)};
			entry.Viewport = Instance.new('ViewportFrame');
			entry.Viewport.Size = UDim2.fromOffset(36, 36);
			entry.Viewport.Position = UDim2.fromScale(0.5, 0.5);
			entry.Viewport.AnchorPoint = Vector2.new(0.5, 0.5);
			entry.Viewport.BorderSizePixel = 0;
			entry.Viewport.Ambient = Color3.new(1, 1, 1);
			entry.Viewport.LightColor = Color3.new(1, 1, 1);
			entry.Viewport.Parent = billboard;
			paintPot(entry);
			local corner: UICorner = Instance.new('UICorner');
			corner.CornerRadius = UDim.new(0, 4);
			corner.Parent = entry.Viewport;
			if potTemplate == nil then
				local assets: Instance? = replicatedStorage:FindFirstChild('Assets');
				local blocks: Instance? = assets and assets:FindFirstChild('Blocks');
				local model: Instance? = blocks and blocks:FindFirstChild('desert_pot');
				potTemplate = model and model:FindFirstChildWhichIsA('MeshPart', true) or false;
			end;
			if potTemplate then
				local mesh: MeshPart = potTemplate:Clone();
				mesh.CFrame = CFrame.Angles(0, math.rad(25), 0);
				mesh.Parent = entry.Viewport;
				local camera: Camera = Instance.new('Camera');
				camera.CFrame = CFrame.lookAt(Vector3.new(0, 0.75, 3.9), Vector3.new(0, 0.05, 0));
				camera.Parent = entry.Viewport;
				entry.Viewport.CurrentCamera = camera;
			end;
			category.Tracked[object] = entry;
			return;
		end;
		local label: TextLabel = Instance.new('TextLabel');
		label.Name = name;
		label.Text = name;
		label.AnchorPoint = Vector2.new(0.5, 1);
		label.AutomaticSize = Enum.AutomaticSize.XY;
		label.Size = UDim2.new();
		label.BackgroundColor3 = Color3.new();
		label.BackgroundTransparency = Transparency["Value"];
		label.BorderSizePixel = 0;
		if category.Arial then
			label.Font = Enum.Font.Arial;
		else
			label.FontFace = uipallet.Font;
		end;
		label.TextSize = textSize * Scale["Value"];
		label.TextColor3 = colorOf(category);
		label.RichText = true;
		label.Visible = false;
		local padding: UIPadding = Instance.new('UIPadding');
		padding.PaddingLeft = UDim.new(0, 4);
		padding.PaddingRight = UDim.new(0, 4);
		padding.PaddingTop = UDim.new(0, 3);
		padding.PaddingBottom = UDim.new(0, 4);
		padding.Parent = label;
		label.Parent = folder;
		category.Tracked[object] = {["Label"] = label, ["Name"] = name, ["Object"] = object};
	end;

	local pointOf: (category: table, entry: table) -> Vector3? = function(category: table, entry: table): Vector3?
		local object: Instance = entry.Object;
		if category.Pivot and object:IsA('Model') then
			return object:GetPivot().Position;
		end;
		local part: BasePart? = entry.Part;
		if not part then
			part = object:IsA('Model') and object.PrimaryPart or (object:IsA('BasePart') and object or nil);
			if category.Deep then
				part = part or object:FindFirstChildWhichIsA('BasePart');
				entry.Part = part;
			end;
		end;
		return part and part.Position or nil;
	end;

	local render: () -> () = function(): ()
		local origin: Vector3? = entitylib.isAlive and entitylib.character.RootPart.Position or nil;
		for _: number, category: table in categories do
			if not category.Text then
				continue;
			end;
			for object: Instance, entry: table in category.Tracked do
				local point: Vector3? = object.Parent and pointOf(category, entry) or nil;
				if not point then
					untrack(category, object);
					continue;
				end;
				local screen: Vector3, onScreen: boolean = gameCamera:WorldToViewportPoint(point + Vector3.new(0, category.Height, 0));
				local text: string? = onScreen and category.Text(entry, point, origin) or nil;
				entry.Label.Visible = text ~= nil;
				if text then
					if entry.Label.Text ~= text then
						entry.Label.Text = text;
					end;
					entry.Label.Position = UDim2.fromOffset(screen.X, screen.Y);
				end;
			end;
		end;
	end;

	local refreshPanel: () -> () = function(): ()
		if not panel then
			return;
		end;
		local origin: Vector3 = entitylib.isAlive and entitylib.character.RootPart.Position or gameCamera.CFrame.Position;
		local drops: {Instance} = collectionService:GetTagged('ItemDrop');
		local entries: {table} = {};
		for _: number, generator: Instance in collectionService:GetTagged('Generator') do
			local resource: string? = nil;
			if generator:IsA('BasePart') then
				local id: string = generator:GetAttribute('Id') or '';
				local team: string? = id:match('^(.-)_generator$');
				if team then
					resource = team == tostring(lplr:GetAttribute('Team')) and 'iron' or nil;
				else
					resource = id:match('^(diamond)_') or id:match('^(emerald)_');
				end;
			end;
			local kind: table? = resource and generatorKinds[resource];
			if kind and kind.Toggle["Enabled"] then
				local timer: Instance? = timers[generator];
				if not timer or not timer.Parent then
					local app: Instance? = generator:FindFirstChild('RoactTree');
					app = app and app:FindFirstChild('TeamOreGeneratorApp');
					timer = app and (app:FindFirstChild('Countdown', true) or app:FindFirstChild('Timer', true));
					timers[generator] = timer;
				end;
				local seconds: number? = timer and timer:IsA('TextLabel') and tonumber(timer.Text:match('%[([%d%.]+)%]') or timer.Text:match('([%d%.]+)')) or nil;
				local stored: number = 0;
				for _: number, drop: Instance in drops do
					if drop.Name == resource and drop:IsA('BasePart') then
						local offset: Vector3 = drop.Position - generator.Position;
						if Vector2.new(offset.X, offset.Z).Magnitude <= hoardRadius and offset.Y >= -12 and offset.Y <= 4 then
							stored += drop:GetAttribute('Amount') or 1;
						end;
					end;
				end;
				table.insert(entries, {
					["Resource"] = resource,
					["Kind"] = kind,
					["Level"] = generator:GetAttribute('GeneratorLevel') or 0,
					["Countdown"] = seconds and math.ceil(seconds),
					["Stored"] = stored,
					["Distance"] = (generator.Position - origin).Magnitude
				});
			end;
		end;
		table.sort(entries, function(first: table, second: table): boolean
			return first.Distance < second.Distance;
		end);
		local describe: (entry: table, distance: boolean) -> string = function(entry: table, distance: boolean): string
			local parts: {string} = {entry.Kind.Name..' T'..entry.Level};
			if entry.Countdown then
				table.insert(parts, entry.Countdown..'s');
			end;
			table.insert(parts, entry.Stored..' stored');
			if distance then
				table.insert(parts, math.floor(entry.Distance)..' studs');
			end;
			return '<font color="'..entry.Kind.Color..'">'..table.concat(parts, ' | ')..'</font>';
		end;
		local lines: {string} = {'<b>GeneratorESP</b>', '<font size="4"> </font>'};
		for _: number, resource: string in generatorOrder do
			for _: number, entry: table in entries do
				if entry.Resource == resource then
					table.insert(lines, describe(entry, false));
					break;
				end;
			end;
		end;
		if #entries == 0 then
			table.insert(lines, 'No generators');
		end;
		local showList: boolean = expanded and #entries > 0;
		if showList then
			table.insert(lines, '<font size="4"> </font>');
			for index: number, entry: table in entries do
				if index > panelRows then
					break;
				end;
				table.insert(lines, describe(entry, true));
			end;
		end;
		local info: TextLabel = panel.Info;
		info.Text = table.concat(lines, '\n');
		local bounds: Vector2 = getfontsize(removeTags(info.Text), info.TextSize, info.FontFace);
		local title: Vector2 = getfontsize('GeneratorESP', info.TextSize, Font.new(info.FontFace.Family, Enum.FontWeight.Bold));
		panel.Window.Size = UDim2.fromOffset(math.max(bounds.X, title.X) + 16, bounds.Y + (showList and -8 or 4));
	end;

	local buildPanel: () -> () = function(): ()
		if vape.ThreadFix then
			setthreadidentity(8);
		end;
		local window: TextButton = Instance.new('TextButton');
		window.Name = 'GeneratorViewer';
		window.Position = UDim2.fromOffset(12, 330);
		window.BackgroundColor3 = Color3.new();
		window.BackgroundTransparency = Transparency["Value"];
		window.Text = '';
		window.AutoButtonColor = false;
		window.Visible = false;
		window.Parent = vape.gui.ScaledGui;
		addBlur(window);
		local corner: UICorner = Instance.new('UICorner');
		corner.CornerRadius = UDim.new(0, 5);
		corner.Parent = window;
		local info: TextLabel = Instance.new('TextLabel');
		info.Size = UDim2.new(1, -16, 1, -16);
		info.Position = UDim2.fromOffset(8, 8);
		info.BackgroundTransparency = 1;
		info.TextXAlignment = Enum.TextXAlignment.Left;
		info.TextYAlignment = Enum.TextYAlignment.Top;
		info.TextSize = panelTextSize * Scale["Value"];
		info.TextColor3 = Color3.new(1, 1, 1);
		info.TextStrokeColor3 = Color3.new();
		info.TextStrokeTransparency = 0.8;
		info.Font = Enum.Font.Arial;
		info.RichText = true;
		info.Parent = window;
		local pressed: UDim2? = nil;
		window.InputBegan:Connect(function(input: InputObject): ()
			if vape.ThreadFix then
				setthreadidentity(8);
			end;
			local mouse: boolean = input.UserInputType == Enum.UserInputType.MouseButton1;
			if not (vape.gui.ScaledGui.ClickGui.Visible or vape.Legit.Window.Visible) or not (mouse or input.UserInputType == Enum.UserInputType.Touch) then
				return;
			end;
			local offset: Vector2 = Vector2.new(window.AbsolutePosition.X - input.Position.X, window.AbsolutePosition.Y - input.Position.Y + guiService:GetGuiInset().Y) / vape.guiscale.Scale;
			local moving: RBXScriptConnection = inputService.InputChanged:Connect(function(changed: InputObject): ()
				if changed.UserInputType == (mouse and Enum.UserInputType.MouseMovement or Enum.UserInputType.Touch) then
					local position: Vector3 = changed.Position;
					if inputService:IsKeyDown(Enum.KeyCode.LeftShift) then
						offset, position = (offset // 3) * 3, (position // 3) * 3;
					end;
					window.Position = UDim2.fromOffset(position.X / vape.guiscale.Scale + offset.X, position.Y / vape.guiscale.Scale + offset.Y);
				end;
			end);
			local released: RBXScriptConnection;
			released = input.Changed:Connect(function(): ()
				if input.UserInputState == Enum.UserInputState.End then
					moving:Disconnect();
					released:Disconnect();
				end;
			end);
		end);
		window.MouseButton1Down:Connect(function(): ()
			pressed = window.Position;
		end);
		window.MouseButton1Click:Connect(function(): ()
			if pressed == window.Position then
				expanded = not expanded;
				refreshPanel();
			end;
		end);
		vape:Clean(window);
		panel = {["Window"] = window, ["Info"] = info};
	end;

	local restyle: () -> () = function(): ()
		for _: number, category: table in categories do
			if not category.Text then
				continue;
			end;
			for _: Instance, entry: table in category.Tracked do
				entry.Label.TextSize = textSize * Scale["Value"];
				entry.Label.BackgroundTransparency = Transparency["Value"];
				entry.Label.TextColor3 = colorOf(category);
			end;
		end;
		if panel then
			panel.Window.BackgroundTransparency = Transparency["Value"];
			panel.Info.TextSize = panelTextSize * Scale["Value"];
			task.spawn(refreshPanel);
		end;
	end;

	local syncOptions: () -> () = function(): ()
		for _: number, category: table in categories do
			for _: number, option: table in category.Options or {} do
				if option.Object then
					option.Object.Visible = category.Toggle["Enabled"];
				end;
			end;
		end;
		if PotColor.Object then
			PotColor.Object.Visible = PotColor.Object.Visible and PotBackground["Enabled"];
		end;
	end;

	local rebuild: () -> () = function(): ()
		syncOptions();
		if ObjectESP["Enabled"] then
			ObjectESP:Toggle();
			ObjectESP:Toggle();
		end;
	end;

	ObjectESP = vape.Categories.Render:CreateModule({
		["Name"] = 'ObjectESP',
		["Function"] = function(callback: boolean): ()
			if not callback then
				for _: number, category: table in categories do
					for object: Instance in category.Tracked do
						untrack(category, object);
					end;
				end;
				table.clear(timers);
				if panel then
					panel.Window.Visible = false;
				end;
				return;
			end;
			for _: number, category: table in categories do
				if not category.Toggle["Enabled"] then
					continue;
				end;
				if category.Panel then
					if not panel then
						buildPanel();
					end;
					panel.Window.Visible = true;
					ObjectESP:Clean(task.spawn(function(): ()
						repeat
							refreshPanel();
							task.wait(panelRefresh);
						until not ObjectESP["Enabled"];
					end));
					continue;
				end;
				for tag: string in category.Tags do
					ObjectESP:Clean(collectionService:GetInstanceAddedSignal(tag):Connect(function(object: Instance): ()
						track(category, object, tag);
					end));
					ObjectESP:Clean(collectionService:GetInstanceRemovedSignal(tag):Connect(function(object: Instance): ()
						untrack(category, object);
					end));
					for _: number, object: Instance in collectionService:GetTagged(tag) do
						if category.Async then
							ObjectESP:Clean(task.spawn(track, category, object, tag));
						else
							track(category, object, tag);
						end;
					end;
				end;
			end;
			ObjectESP:Clean(runService.PreRender:Connect(render));
		end,
		["Tooltip"] = 'Labels world objects through walls: beehives, kit collectables, crates & lucky blocks, crops, a generator panel, dropped items, desert pots and traps'
	});
	ShowDistance = ObjectESP:CreateToggle({
		["Name"] = 'Distance',
		["Default"] = true,
		["Tooltip"] = 'Distance suffix on collectables, crates and traps'
	});
	Scale = ObjectESP:CreateSlider({
		["Name"] = 'Scale',
		["Min"] = 0.1,
		["Max"] = 3,
		["Default"] = 1,
		["Decimal"] = 10,
		["Function"] = restyle
	});
	Transparency = ObjectESP:CreateSlider({
		["Name"] = 'Transparency',
		["Min"] = 0,
		["Max"] = 1,
		["Default"] = 0.5,
		["Decimal"] = 100,
		["Function"] = restyle
	});
	TextColor = ObjectESP:CreateColorSlider({
		["Name"] = 'Text Color',
		["Function"] = restyle,
		["Darker"] = true
	});
	for _: number, category: table in categories do
		category.Toggle = ObjectESP:CreateToggle({
			["Name"] = category.Name,
			["Default"] = true,
			["Function"] = rebuild
		});
		category.Options = {};
		category.Color = not category.White and TextColor or nil;
		if category.ListName then
			category.List = ObjectESP:CreateTextList({
				["Name"] = category.ListName,
				["Default"] = category.Defaults,
				["Darker"] = true,
				["Function"] = rebuild,
				["Tooltip"] = category.Loose and 'Only shows the items in this list, by name or item id.\nLeave it empty to show every item' or nil
			});
			table.insert(category.Options, category.List);
		end;
		if category.Name == 'Generators' then
			for _: number, resource: string in generatorOrder do
				local kind: table = generatorKinds[resource];
				kind.Toggle = ObjectESP:CreateToggle({
					["Name"] = kind.Name..' Generator',
					["Default"] = kind.Toggle["Enabled"],
					["Darker"] = true,
					["Function"] = function(): ()
						if panel then
							task.spawn(refreshPanel);
						end;
					end,
					["Tooltip"] = kind.Tooltip
				});
				table.insert(category.Options, kind.Toggle);
			end;
		elseif category.Name == 'Items' then
			ItemDistance = ObjectESP:CreateToggle({
				["Name"] = 'Item Distance',
				["Darker"] = true,
				["Tooltip"] = 'Shows the distance of the item'
			});
			table.insert(category.Options, ItemDistance);
		elseif category.Name == 'Pots' then
			PotBackground = ObjectESP:CreateToggle({
				["Name"] = 'Pot Background',
				["Default"] = true,
				["Darker"] = true,
				["Function"] = function(): ()
					syncOptions();
					for _: Instance, entry: table in category.Tracked do
						paintPot(entry);
					end;
				end
			});
			PotColor = ObjectESP:CreateColorSlider({
				["Name"] = 'Pot Background Color',
				["DefaultValue"] = 0,
				["DefaultOpacity"] = 0.5,
				["Darker"] = true,
				["Function"] = function(): ()
					for _: Instance, entry: table in category.Tracked do
						paintPot(entry);
					end;
				end
			});
			table.insert(category.Options, PotBackground);
			table.insert(category.Options, PotColor);
		elseif category.Name == 'Traps' then
			YourTraps = ObjectESP:CreateToggle({
				["Name"] = 'Your traps',
				["Default"] = true,
				["Darker"] = true,
				["Tooltip"] = 'Also shows the ones your own team placed'
			});
			TrapColor = ObjectESP:CreateColorSlider({
				["Name"] = 'Trap Text Color',
				["DefaultHue"] = 0,
				["DefaultSat"] = 0.75,
				["Darker"] = true,
				["Function"] = restyle
			});
			category.Color = TrapColor;
			table.insert(category.Options, YourTraps);
			table.insert(category.Options, TrapColor);
		end;
	end;
	syncOptions();
end);

velo.run(function(): ()
	local StorageESP: table = {["Enabled"] = false};
	local Items: table = {["ListEnabled"] = {}};
	local ShowAmount: table = {["Enabled"] = false};
	local Background: table = {["Enabled"] = true};
	local BackgroundColor: table = {["Hue"] = 0, ["Sat"] = 0, ["Value"] = 0, ["Opacity"] = 0.5};
	local tracked: {[Instance]: table} = {};
	local folder: Folder = Instance.new('Folder');
	folder.Parent = vape.gui;

	local paint: (entry: table) -> () = function(entry: table): ()
		entry.Frame.BackgroundColor3 = Color3.fromHSV(BackgroundColor["Hue"], BackgroundColor["Sat"], BackgroundColor["Value"]);
		entry.Frame.BackgroundTransparency = 1 - (Background["Enabled"] and BackgroundColor["Opacity"] or 0);
		entry.Blur.Visible = Background["Enabled"];
	end;

	local refresh: (entry: table) -> ();
	refresh = function(entry: table): ()
		for _: number, connection: RBXScriptConnection in entry.Watches do
			connection:Disconnect();
		end;
		table.clear(entry.Watches);
		for _: number, child: Instance in entry.Frame:GetChildren() do
			if child:IsA('ImageLabel') then
				child:Destroy();
			end;
		end;
		local amounts: {[string]: number} = {};
		local order: {string} = {};
		for _: number, item: Instance in entry.Chest:GetChildren() do
			local wanted: boolean = false;
			for _: number, filter: string in Items.ListEnabled do
				wanted = wanted or item.Name:find(filter, 1, true) ~= nil;
			end;
			if wanted then
				if not amounts[item.Name] then
					table.insert(order, item.Name);
				end;
				amounts[item.Name] = (amounts[item.Name] or 0) + (item:GetAttribute('Amount') or 0);
				if ShowAmount["Enabled"] then
					table.insert(entry.Watches, item:GetAttributeChangedSignal('Amount'):Connect(function(): ()
						refresh(entry);
					end));
				end;
			end;
		end;
		for _: number, itemType: string in order do
			local icon: ImageLabel = Instance.new('ImageLabel');
			icon.Size = UDim2.fromOffset(32, 32);
			icon.BackgroundTransparency = 1;
			icon.Image = bedwars.getIcon({["itemType"] = itemType}, true);
			icon.Parent = entry.Frame;
			if ShowAmount["Enabled"] and amounts[itemType] > 1 then
				local amount: TextLabel = Instance.new('TextLabel');
				amount.Name = 'Amount';
				amount.Size = UDim2.fromOffset(31, 14);
				amount.Position = UDim2.fromOffset(0, 18);
				amount.BackgroundTransparency = 1;
				amount.Text = tostring(amounts[itemType]);
				amount.TextXAlignment = Enum.TextXAlignment.Right;
				amount.TextSize = 14;
				amount.TextColor3 = uipallet.Text;
				amount.TextStrokeColor3 = Color3.new();
				amount.TextStrokeTransparency = 0.4;
				amount.FontFace = uipallet.Font;
				amount.Parent = icon;
			end;
		end;
		entry.Billboard.Enabled = #order > 0;
	end;

	local forget: (part: Instance) -> () = function(part: Instance): ()
		local entry: table? = tracked[part];
		if not entry then
			return;
		end;
		tracked[part] = nil;
		for _: number, connection: RBXScriptConnection in entry.Watches do
			connection:Disconnect();
		end;
		entry.Billboard:Destroy();
	end;

	local attach: (part: Instance) -> () = function(part: Instance): ()
		local value: any = part:WaitForChild('ChestFolderValue', 3);
		local chest: Instance? = value and value.Value;
		if not chest or not StorageESP["Enabled"] or tracked[part] then
			return;
		end;
		if vape.ThreadFix then
			setthreadidentity(8);
		end;
		local billboard: BillboardGui = Instance.new('BillboardGui');
		billboard.Name = 'chest';
		billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0);
		billboard.Size = UDim2.fromOffset(36, 36);
		billboard.AlwaysOnTop = true;
		billboard.ClipsDescendants = false;
		billboard.Adornee = part;
		billboard.Parent = folder;
		local blur: ImageLabel = addBlur(billboard);
		local frame: Frame = Instance.new('Frame');
		frame.Size = UDim2.fromScale(1, 1);
		frame.Parent = billboard;
		local layout: UIListLayout = Instance.new('UIListLayout');
		layout.FillDirection = Enum.FillDirection.Horizontal;
		layout.Padding = UDim.new(0, 4);
		layout.VerticalAlignment = Enum.VerticalAlignment.Center;
		layout.HorizontalAlignment = Enum.HorizontalAlignment.Center;
		layout:GetPropertyChangedSignal('AbsoluteContentSize'):Connect(function(): ()
			billboard.Size = UDim2.fromOffset(math.max(layout.AbsoluteContentSize.X + 4, 36), 36);
		end);
		layout.Parent = frame;
		local corner: UICorner = Instance.new('UICorner');
		corner.CornerRadius = UDim.new(0, 4);
		corner.Parent = frame;
		local entry: table = {["Billboard"] = billboard, ["Frame"] = frame, ["Blur"] = blur, ["Chest"] = chest, ["Watches"] = {}};
		tracked[part] = entry;
		paint(entry);
		StorageESP:Clean(chest.ChildAdded:Connect(function(): ()
			refresh(entry);
		end));
		StorageESP:Clean(chest.ChildRemoved:Connect(function(): ()
			refresh(entry);
		end));
		refresh(entry);
	end;

	local refreshAll: () -> () = function(): ()
		for _: Instance, entry: table in tracked do
			refresh(entry);
		end;
	end;

	StorageESP = vape.Categories.Render:CreateModule({
		["Name"] = 'StorageESP',
		["Function"] = function(callback: boolean): ()
			if callback then
				StorageESP:Clean(collectionService:GetInstanceAddedSignal('chest'):Connect(function(part: Instance): ()
					StorageESP:Clean(task.spawn(attach, part));
				end));
				StorageESP:Clean(collectionService:GetInstanceRemovedSignal('chest'):Connect(forget));
				for _: number, part: Instance in collectionService:GetTagged('chest') do
					StorageESP:Clean(task.spawn(attach, part));
				end;
			else
				for part: Instance in tracked do
					forget(part);
				end;
			end;
		end,
		["Tooltip"] = 'Displays items in chests'
	});
	Items = StorageESP:CreateTextList({
		["Name"] = 'Item',
		["Function"] = refreshAll
	});
	ShowAmount = StorageESP:CreateToggle({
		["Name"] = 'Show Amount',
		["Function"] = refreshAll,
		["Tooltip"] = 'Displays how much of each item the chest holds'
	});
	Background = StorageESP:CreateToggle({
		["Name"] = 'Background',
		["Default"] = true,
		["Function"] = function(callback: boolean): ()
			if BackgroundColor.Object then
				BackgroundColor.Object.Visible = callback;
			end;
			for _: Instance, entry: table in tracked do
				paint(entry);
			end;
		end
	});
	BackgroundColor = StorageESP:CreateColorSlider({
		["Name"] = 'Background Color',
		["DefaultValue"] = 0,
		["DefaultOpacity"] = 0.5,
		["Darker"] = true,
		["Function"] = function(hue: number, sat: number, value: number, opacity: number): ()
			for _: Instance, entry: table in tracked do
				paint(entry);
			end;
		end
	});
end);

velo.run(function(): ()
	local NameTags: table = {["Enabled"] = false};
	local Targets: table;
	local FontOption: table;
	local TagColor: table;
	local Scale: table;
	local Transparency: table;
	local Health: table;
	local Distance: table;
	local Equipment: table;
	local Inventory: table;
	local InventoryItems: table;
	local Enchant: table;
	local Rank: table;
	local DisplayName: table;
	local PriorityOnly: table;
	local DrawingMode: table;
	local DistanceCheck: table;
	local DistanceLimit: table;
	local inventoryRefresh: number = 0.5;
	local iconSize: number = 30;
	local equipmentSlots: {string} = {'Hand', 'Helmet', 'Chestplate', 'Boots', 'Kit'};
	local tags: {[table]: table} = {};
	local rankCache: {[Player]: string} = {};
	local folder: Folder = Instance.new('Folder');
	folder.Name = 'NameTags';
	if vape.ThreadFix then
		setthreadidentity(8);
	end;
	folder.Parent = vape.gui;
	vape:Clean(folder);
	vape:Clean(playersService.PlayerRemoving:Connect(function(plr: Player): ()
		rankCache[plr] = nil;
	end));

	local restart: () -> () = function(): ()
		if NameTags["Enabled"] then
			NameTags:Toggle();
			NameTags:Toggle();
		end;
	end;

	local tagColor: (ent: table) -> Color3 = function(ent: table): Color3
		return entitylib.getEntityColor(ent) or Color3.fromHSV(TagColor["Hue"], TagColor["Sat"], TagColor["Value"]);
	end;

	local template: (ent: table) -> string = function(ent: table): string
		local rich: boolean = not DrawingMode["Enabled"];
		local text: string = ent.Player and whitelist:tag(ent.Player, true, rich)..(DisplayName["Enabled"] and ent.Player.DisplayName or ent.Player.Name) or ent.Character.Name;
		if Health["Enabled"] then
			local health: number = math.round(ent.Health);
			local shade: Color3 = Color3.fromHSV(math.clamp(ent.Health / ent.MaxHealth, 0, 1) / 2.5, 0.89, 0.75);
			text ..= rich and ' <font color="rgb('..math.floor(shade.R * 255)..','..math.floor(shade.G * 255)..','..math.floor(shade.B * 255)..')">'..health..'</font>' or ' '..health;
		end;
		if Distance["Enabled"] then
			text = (rich and '<font color="rgb(85,255,85)">[</font><font color="rgb(255,255,255)">%s</font><font color="rgb(85,255,85)">]</font> ' or '[%s] ')..(text:gsub('%%', '%%%%'));
		end;
		return text;
	end;

	local showText: (tag: table, distance: number) -> () = function(tag: table, distance: number): ()
		local text: string = Distance["Enabled"] and string.format(tag.Template, distance) or tag.Template;
		local label: TextLabel? = tag.Label;
		if label then
			label.Text = text;
			task.spawn(function(): ()
				local bounds: Vector2 = getfontsize(removeTags(text), label.TextSize, label.FontFace);
				if label.Text == text then
					label.Size = UDim2.fromOffset(bounds.X + 8, bounds.Y + 7);
				end;
			end);
			return;
		end;
		tag.Text.Text = text;
		tag.Square.Size = tag.Text.TextBounds + Vector2.new(8, 7);
	end;

	local newIcon: (parent: Instance, name: string, position: UDim2, size: number) -> ImageLabel = function(parent: Instance, name: string, position: UDim2, size: number): ImageLabel
		local icon: ImageLabel = Instance.new('ImageLabel');
		icon.Name = name;
		icon.Size = UDim2.fromOffset(size, size);
		icon.Position = position;
		icon.BackgroundTransparency = 1;
		icon.Image = '';
		icon.Parent = parent;
		return icon;
	end;

	local enchantImage: (character: Model) -> string = function(character: Model): string
		for attribute: string in character:GetAttributes() do
			if attribute:find('StatusEffect_', 1, true) and not attribute:find('_stacks', 1, true) then
				local effect: any = bedwars.StatusEffectMeta[bedwars.StatusEffectMeta[(attribute:gsub('StatusEffect_', ''))]];
				local enchant: table? = type(effect) == 'string' and bedwars.EnchantMeta[(effect:gsub('_[123]', ''))];
				if enchant then
					return enchant.image;
				end;
			end;
		end;
		return '';
	end;

	local fillInventory: (ent: table, tag: table) -> () = function(ent: table, tag: table): ()
		local inventory: table? = store.inventories[ent.Player];
		if not inventory then
			return;
		end;
		local shown: number = 0;
		for _: number, item: table in inventory.items or {} do
			if #InventoryItems.ListEnabled > 0 and not table.find(InventoryItems.ListEnabled, item.itemType) then
				continue;
			end;
			shown += 1;
			local icon: ImageLabel = tag.Holder:FindFirstChild(tostring(shown));
			if not icon then
				icon = newIcon(tag.Holder, tostring(shown), UDim2.new(), 24);
				local amount: TextLabel = Instance.new('TextLabel');
				amount.Name = 'Amount';
				amount.Size = UDim2.fromOffset(23, 11);
				amount.Position = UDim2.fromOffset(0, 13);
				amount.BackgroundTransparency = 1;
				amount.FontFace = tag.Label.FontFace;
				amount.TextSize = 11;
				amount.TextColor3 = Color3.new(1, 1, 1);
				amount.TextStrokeTransparency = 0.4;
				amount.TextXAlignment = Enum.TextXAlignment.Right;
				amount.Parent = icon;
			end;
			icon.LayoutOrder = shown;
			icon.Visible = true;
			icon.Image = bedwars.getIcon(item, true);
			icon.Amount.Text = (item.amount or 1) > 1 and tostring(item.amount) or '';
		end;
		for _: number, icon: Instance in tag.Holder:GetChildren() do
			if icon:IsA('ImageLabel') and tonumber(icon.Name) > shown then
				icon.Visible = false;
			end;
		end;
	end;

	local refresh: (ent: table) -> () = function(ent: table): ()
		local tag: table? = tags[ent];
		if not tag then
			return;
		end;
		tag.Template = template(ent);
		tag.Shown = nil;
		showText(tag, entitylib.isAlive and math.floor((entitylib.character.RootPart.Position - ent.RootPart.Position).Magnitude) or 0);
		local inventory: table? = ent.Player and store.inventories[ent.Player];
		if tag.Hand and inventory then
			local armor: {[number]: table} = {};
			for _: any, item: any in inventory.armor or {} do
				local meta: table? = type(item) == 'table' and bedwars.ItemMeta[item.itemType];
				if meta and meta.armor then
					armor[meta.armor.slot] = item;
				end;
			end;
			local kitMeta: table? = bedwars.BedwarsKitMeta[string.split(ent.Player:GetAttribute('PlayingAsKits') or 'none', ',')[1]];
			tag.Hand.Image = bedwars.getIcon(inventory.hand or {["itemType"] = ''}, true);
			tag.Helmet.Image = bedwars.getIcon(armor[0] or {["itemType"] = ''}, true);
			tag.Chestplate.Image = bedwars.getIcon(armor[1] or {["itemType"] = ''}, true);
			tag.Boots.Image = bedwars.getIcon(armor[2] or {["itemType"] = ''}, true);
			tag.Kit.Image = kitMeta and kitMeta.renderImage or '';
		end;
		if tag.Holder then
			fillInventory(ent, tag);
		end;
		if tag.EnchantIcon then
			tag.EnchantIcon.Image = enchantImage(ent.Character);
		end;
		if tag.Text then
			tag.Text.Color = tagColor(ent);
		end;
	end;

	local remove: (ent: table) -> () = function(ent: table): ()
		local tag: table? = tags[ent];
		tags[ent] = nil;
		if not tag then
			return;
		end;
		if tag.Label then
			tag.Label:Destroy();
		else
			tag.Text:Remove();
			tag.Square:Remove();
		end;
	end;

	local build: (ent: table) -> () = function(ent: table): ()
		if vape.ThreadFix then
			setthreadidentity(8);
		end;
		remove(ent);
		if (ent.Player and not Targets.Players["Enabled"]) or (ent.NPC and not Targets.NPCs["Enabled"]) or (PriorityOnly["Enabled"] and not ent.Targetable and not ent.Friend) then
			return;
		end;
		local tag: table = {["Refresh"] = 0};
		tags[ent] = tag;
		if DrawingMode["Enabled"] then
			tag.Square = Drawing.new('Square');
			tag.Square.Filled = true;
			tag.Square.Transparency = 1 - Transparency["Value"];
			tag.Square.Color = Color3.new();
			tag.Square.ZIndex = 1;
			tag.Text = Drawing.new('Text');
			tag.Text.Size = 15 * Scale["Value"];
			tag.Text.Font = 0;
			tag.Text.ZIndex = 2;
			tag.Text.Color = tagColor(ent);
			refresh(ent);
			return;
		end;
		local label: TextLabel = Instance.new('TextLabel');
		label.Name = ent.Player and ent.Player.Name or ent.Character.Name;
		label.AnchorPoint = Vector2.new(0.5, 1);
		label.BackgroundColor3 = Color3.new();
		label.BackgroundTransparency = Transparency["Value"];
		label.BorderSizePixel = 0;
		label.FontFace = FontOption["Value"];
		label.TextSize = 14;
		label.RichText = true;
		label.TextColor3 = tagColor(ent);
		label.Visible = false;
		local scaler: UIScale = Instance.new('UIScale');
		scaler.Scale = Scale["Value"];
		scaler.Parent = label;
		tag.Label = label;
		if Equipment["Enabled"] then
			for index: number, slot: string in equipmentSlots do
				tag[slot] = newIcon(label, slot, UDim2.fromOffset(-60 + index * iconSize, -iconSize), iconSize);
			end;
		end;
		if Inventory["Enabled"] and ent.Player then
			local holder: Frame = Instance.new('Frame');
			holder.Name = 'Inventory';
			holder.AnchorPoint = Vector2.new(0.5, 0);
			holder.AutomaticSize = Enum.AutomaticSize.X;
			holder.BackgroundTransparency = 1;
			holder.Position = UDim2.new(0.5, 0, 1, 2);
			holder.Size = UDim2.fromOffset(0, 24);
			holder.Parent = label;
			local layout: UIListLayout = Instance.new('UIListLayout');
			layout.FillDirection = Enum.FillDirection.Horizontal;
			layout.HorizontalAlignment = Enum.HorizontalAlignment.Center;
			layout.Padding = UDim.new(0, 2);
			layout.SortOrder = Enum.SortOrder.LayoutOrder;
			layout.Parent = holder;
			tag.Holder = holder;
		end;
		if Enchant["Enabled"] and ent.Player then
			tag.EnchantIcon = newIcon(label, 'EnchantIcon', UDim2.fromOffset(-iconSize, -4), iconSize);
		end;
		if Rank["Enabled"] and ent.Player then
			local plr: Player = ent.Player;
			local icon: ImageLabel = newIcon(label, 'RankIcon', UDim2.fromOffset(0, -4), iconSize);
			local first: string = removeTags(template(ent));
			tag.RankIcon = icon;
			task.spawn(function(): ()
				icon.Position = UDim2.fromOffset(getfontsize(first, label.TextSize, label.FontFace).X + 10, -4);
				local rank: string? = rankCache[plr];
				if not rank then
					local ranks: any = fire('FetchRanks', 'CallServer', {plr.UserId});
					rank = type(ranks) == 'table' and type(ranks[1]) == 'table' and ranks[1].rankDivision or nil;
					rankCache[plr] = rank;
				end;
				icon.Image = rank and bedwars.RankMeta[rank] and bedwars.RankMeta[rank].image or '';
			end);
		end;
		label.Parent = folder;
		refresh(ent);
	end;

	local render: () -> () = function(): ()
		if vape.ThreadFix then
			setthreadidentity(8);
		end;
		local origin: Vector3? = entitylib.isAlive and entitylib.character.RootPart.Position or nil;
		local now: number = tick();
		for ent: table, tag: table in tags do
			local root: Vector3 = ent.RootPart.Position;
			local distance: number = origin and (origin - root).Magnitude or math.huge;
			local point: Vector3, visible: boolean = gameCamera:WorldToViewportPoint(root + Vector3.new(0, ent.HipHeight + 1, 0));
			visible = visible and (not DistanceCheck["Enabled"] or (distance >= DistanceLimit["ValueMin"] and distance <= DistanceLimit["ValueMax"]));
			if tag.Label then
				tag.Label.Visible = visible;
			else
				tag.Text.Visible = visible;
				tag.Square.Visible = visible;
			end;
			if not visible then
				continue;
			end;
			local rounded: number = origin and math.floor(distance) or 0;
			if Distance["Enabled"] and tag.Shown ~= rounded then
				tag.Shown = rounded;
				showText(tag, rounded);
			end;
			if tag.Holder and now >= tag.Refresh then
				tag.Refresh = now + inventoryRefresh;
				store.inventories[ent.Player] = bedwars.getInventory(ent.Player);
				fillInventory(ent, tag);
			end;
			if tag.Label then
				tag.Label.Position = UDim2.fromOffset(point.X, point.Y);
			else
				local size: Vector2 = tag.Square.Size;
				tag.Square.Position = Vector2.new(point.X - size.X / 2, point.Y - size.Y);
				tag.Text.Position = tag.Square.Position + Vector2.new(4, 3);
			end;
		end;
	end;

	NameTags = vape.Categories.Render:CreateModule({
		["Name"] = 'NameTags',
		["Function"] = function(callback: boolean): ()
			if callback then
				for _: number, ent: table in entitylib.List do
					build(ent);
				end;
				NameTags:Clean(entitylib.Events.EntityAdded:Connect(build));
				NameTags:Clean(entitylib.Events.EntityRemoved:Connect(remove));
				NameTags:Clean(entitylib.Events.EntityUpdated:Connect(refresh));
				NameTags:Clean(vape.Categories.Friends.ColorUpdate.Event:Connect(function(): ()
					for ent: table, tag: table in tags do
						if tag.Label then
							tag.Label.TextColor3 = tagColor(ent);
						else
							tag.Text.Color = tagColor(ent);
						end;
					end;
				end));
				NameTags:Clean(runService.RenderStepped:Connect(render));
			else
				for ent: table in tags do
					remove(ent);
				end;
			end;
		end,
		["Tooltip"] = 'Renders nametags on entities through walls.'
	});
	Targets = NameTags:CreateTargets({
		["Players"] = true,
		["Function"] = restart
	});
	FontOption = NameTags:CreateFont({
		["Name"] = 'Font',
		["Blacklist"] = 'Arial',
		["Function"] = restart
	});
	TagColor = NameTags:CreateColorSlider({
		["Name"] = 'Player Color',
		["Function"] = function(hue: number, sat: number, value: number): ()
			for ent: table, tag: table in tags do
				local shade: Color3 = entitylib.getEntityColor(ent) or Color3.fromHSV(hue, sat, value);
				if tag.Label then
					tag.Label.TextColor3 = shade;
				else
					tag.Text.Color = shade;
				end;
			end;
		end
	});
	Scale = NameTags:CreateSlider({
		["Name"] = 'Scale',
		["Function"] = restart,
		["Default"] = 1,
		["Min"] = 0.1,
		["Max"] = 1.5,
		["Decimal"] = 10
	});
	Transparency = NameTags:CreateSlider({
		["Name"] = 'Transparency',
		["Function"] = restart,
		["Default"] = 0.5,
		["Min"] = 0,
		["Max"] = 1,
		["Decimal"] = 10
	});
	Health = NameTags:CreateToggle({
		["Name"] = 'Health',
		["Function"] = restart
	});
	Distance = NameTags:CreateToggle({
		["Name"] = 'Distance',
		["Function"] = restart
	});
	Equipment = NameTags:CreateToggle({
		["Name"] = 'Equipment',
		["Function"] = restart,
		["Tooltip"] = 'Shows the held item, armor and kit above the tag.'
	});
	Inventory = NameTags:CreateToggle({
		["Name"] = 'Inventory',
		["Function"] = function(callback: boolean): ()
			if InventoryItems then
				InventoryItems.Object.Visible = callback;
			end;
			restart();
		end,
		["Tooltip"] = 'Shows how many of each listed item they are carrying.'
	});
	InventoryItems = NameTags:CreateTextList({
		["Name"] = 'Inventory Items',
		["Default"] = {'fireball', 'glue_projectile', 'telepearl', 'tnt'},
		["Darker"] = true,
		["Visible"] = false,
		["Tooltip"] = 'Item types to count, empty shows everything they hold.'
	});
	Enchant = NameTags:CreateToggle({
		["Name"] = 'Show Enchant',
		["Function"] = restart
	});
	Rank = NameTags:CreateToggle({
		["Name"] = 'Show Rank',
		["Function"] = restart
	});
	DisplayName = NameTags:CreateToggle({
		["Name"] = 'Use Displayname',
		["Function"] = restart,
		["Default"] = true
	});
	PriorityOnly = NameTags:CreateToggle({
		["Name"] = 'Priority Only',
		["Function"] = restart,
		["Default"] = true,
		["Tooltip"] = 'Only tag enemies and friends.'
	});
	DrawingMode = NameTags:CreateToggle({
		["Name"] = 'Drawing',
		["Function"] = restart
	});
	DistanceCheck = NameTags:CreateToggle({
		["Name"] = 'Distance Check',
		["Function"] = function(callback: boolean): ()
			DistanceLimit.Object.Visible = callback;
		end
	});
	DistanceLimit = NameTags:CreateTwoSlider({
		["Name"] = 'Player Distance',
		["Min"] = 0,
		["Max"] = 256,
		["DefaultMin"] = 0,
		["DefaultMax"] = 64,
		["Darker"] = true,
		["Visible"] = false
	});
end);

velo.run(function(): ()
	local KitESP: table = {["Enabled"] = false};
	local Icons: table;
	local Background: table;
	local BackgroundColor: table;
	local IconScale: table;
	local Spy: table;
	local Viewer: table;
	local SpyNotify: table;
	local IgnoreTeam: table;
	local IgnoreSelf: table;
	local SpyRange: table;
	local SpyWindow: table;
	local SpyDelay: table;
	local DigItems: table;
	local Collectables: table;
	local Draft: table;
	local DraftHistory: table;
	local spyToggles: {[string]: table} = {};
	local iconSize: number = 36;
	local historyLength: number = 8;
	local historyWait: number = 15;
	local spyTick: number = 0.2;
	local iconPoll: number = 1;
	local partWait: number = 10;
	local partPoll: number = 0.25;
	local draftDelay: number = 0.3;
	local draftPoll: number = 0.1;
	local columnWait: number = 10;
	local draftTween: TweenInfo = TweenInfo.new(0.2, Enum.EasingStyle.Cubic, Enum.EasingDirection.Out);

	local iconKits: {[string]: {string}} = {
		["alchemist"] = {'alchemist_ingedients', 'wild_flower'},
		["beekeeper"] = {'bee', 'bee'},
		["bigman"] = {'treeOrb', 'natures_essence_1'},
		["ghost_catcher"] = {'ghost', 'ghost_orb'},
		["metal_detector"] = {'hidden-metal', 'iron'},
		["sheep_herder"] = {'SheepModel', 'purple_hay_bale'},
		["sorcerer"] = {'alchemy_crystal', 'wild_flower'},
		["star_collector"] = {'stars', 'crit_star'}
	};
	local spyKits: {[string]: table} = {
		["beekeeper"] = {["Tags"] = {'bee'}, ["Label"] = 'bee', ["Item"] = 'bee'},
		["bigman"] = {["Tags"] = {'treeOrb'}, ["Label"] = 'tree orb'},
		["bounty_hunter"] = {["Bounty"] = true},
		["farmer_cletus"] = {["Tags"] = {'HarvestableCrop'}, ["Label"] = 'crop'},
		["fisherman"] = {["Fishing"] = true},
		["jailor"] = {["Tags"] = {'jailor_soul'}, ["Label"] = 'soul'},
		["metal_detector"] = {["Tags"] = {'hidden-metal'}, ["Label"] = 'metal', ["Digging"] = true},
		["spirit_assassin"] = {["Tags"] = {'EvelynnSoul'}, ["Label"] = 'spirit'},
		["star_collector"] = {["Tags"] = {'stars'}, ["Label"] = 'star'}
	};
	local extraLabels: {[string]: string} = {
		["alchemist_ingedients"] = 'ingredient',
		["alchemy_crystal"] = 'crystal',
		["crystalheart_seed"] = 'crystalheart seed',
		["forest_environment_plant"] = 'plant',
		["ghost"] = 'ghost',
		["murder_coin"] = 'coin',
		["shadow_coin"] = 'shadow coin',
		["soulvine_seed"] = 'soulvine seed',
		["spirit_gardener_energy"] = 'energy',
		["spirit_gardener_seeds"] = 'seed',
		["tearbloom_seed"] = 'tearbloom seed'
	};

	local totals: {[Player]: {[string]: number}} = {};
	local histories: {[number]: {string}} = {};
	local fetching: {[number]: boolean} = {};
	local expanded: boolean = false;
	local folder: Folder = Instance.new('Folder');
	folder.Name = 'KitESP';
	if vape.ThreadFix then
		setthreadidentity(8);
	end;
	folder.Parent = vape.gui;
	vape:Clean(folder);

	local panel: TextButton = Instance.new('TextButton');
	panel.Name = 'KitSpyViewer';
	panel.Position = UDim2.fromOffset(12, 260);
	panel.AutomaticSize = Enum.AutomaticSize.XY;
	panel.BackgroundColor3 = Color3.new();
	panel.BackgroundTransparency = 0.5;
	panel.AutoButtonColor = false;
	panel.Text = '';
	panel.Visible = false;
	panel.Parent = vape.gui.ScaledGui;
	vape:Clean(panel);
	addBlur(panel);
	local panelCorner: UICorner = Instance.new('UICorner');
	panelCorner.CornerRadius = UDim.new(0, 5);
	panelCorner.Parent = panel;
	local panelPadding: UIPadding = Instance.new('UIPadding');
	for _: number, side: string in {'PaddingLeft', 'PaddingRight', 'PaddingTop', 'PaddingBottom'} do
		panelPadding[side] = UDim.new(0, 8);
	end;
	panelPadding.Parent = panel;
	local panelText: TextLabel = Instance.new('TextLabel');
	panelText.AutomaticSize = Enum.AutomaticSize.XY;
	panelText.BackgroundTransparency = 1;
	panelText.TextXAlignment = Enum.TextXAlignment.Left;
	panelText.TextYAlignment = Enum.TextYAlignment.Top;
	panelText.TextSize = 16;
	panelText.TextColor3 = Color3.new(1, 1, 1);
	panelText.TextStrokeTransparency = 0.8;
	panelText.Font = Enum.Font.Arial;
	panelText.RichText = true;
	panelText.Parent = panel;

	local playerLabel: (plr: Player?) -> string = function(plr: Player?): string
		return plr and plr.DisplayName or 'someone';
	end;

	local plural: (amount: number, label: string) -> string = function(amount: number, label: string): string
		return amount..' '..label..(amount == 1 and '' or 's');
	end;

	local ignored: (plr: Player) -> boolean = function(plr: Player): boolean
		if plr == lplr then
			return IgnoreSelf["Enabled"];
		end;
		return IgnoreTeam["Enabled"] and plr.Team == lplr.Team;
	end;

	local drawViewer: () -> () = function(): ()
		local rows: {table} = {};
		for plr: Player, kinds: {[string]: number} in totals do
			local count: number, parts: {string} = 0, {};
			for label: string, amount: number in kinds do
				count += amount;
				table.insert(parts, plural(amount, label));
			end;
			table.sort(parts);
			table.insert(rows, {["Count"] = count, ["Text"] = playerLabel(plr)..': '..table.concat(parts, ', ')});
		end;
		table.sort(rows, function(a: table, b: table): boolean
			return a.Count > b.Count;
		end);
		local lines: {string} = {'<b>KitSpy</b>'};
		for index: number, row: table in rows do
			if not expanded and index > 5 then
				table.insert(lines, '+'..(#rows - 5)..' more');
				break;
			end;
			table.insert(lines, row.Text);
		end;
		if #rows == 0 then
			table.insert(lines, 'Nothing spotted yet');
		end;
		panelText.Text = table.concat(lines, '\n');
		panel.Visible = KitESP["Enabled"] and Spy["Enabled"] and Viewer["Enabled"];
	end;
	vape:Clean(panel.MouseButton1Click:Connect(function(): ()
		expanded = not expanded;
		drawViewer();
	end));

	local credit: (plr: Player, label: string, amount: number, quiet: boolean?) -> number = function(plr: Player, label: string, amount: number, quiet: boolean?): number
		local kinds: {[string]: number} = totals[plr] or {};
		kinds[label] = (kinds[label] or 0) + amount;
		totals[plr] = kinds;
		drawViewer();
		if not quiet and SpyNotify["Enabled"] then
			notif('KitSpy', playerLabel(plr)..' picked up '..plural(amount, label)..' ('..kinds[label]..' total)', 5, 'info');
		end;
		return kinds[label];
	end;

	local reportLoot: (plr: Player, verb: string, filtered: boolean) -> () = function(plr: Player, verb: string, filtered: boolean): ()
		local now: number, found: {string} = workspace:GetServerTimeNow(), {};
		for _: number, item: table in (store.inventories[plr] or {["items"] = {}}).items do
			local fresh: boolean = now - (item.addedToBackpackTime or 0) <= SpyWindow["Value"];
			if fresh and (not filtered or #DigItems.ListEnabled == 0 or table.find(DigItems.ListEnabled, item.itemType)) then
				local meta: table? = bedwars.ItemMeta[item.itemType];
				table.insert(found, ((item.amount or 1) > 1 and item.amount..'x ' or '')..(meta and meta.displayName or item.itemType));
			end;
		end;
		if #found > 0 then
			notif('KitSpy', playerLabel(plr)..' '..verb..' '..table.concat(found, ', '), 8, 'info');
		end;
	end;

	local partOf: (object: Instance) -> BasePart? = function(object: Instance): BasePart?
		if object:IsA('BasePart') then
			return object;
		end;
		return object:IsA('Model') and (object.PrimaryPart or object:FindFirstChild('Root') or object:FindFirstChildWhichIsA('BasePart', true)) or object:FindFirstChildWhichIsA('BasePart', true);
	end;

	local startIcons: () -> () = function(): ()
		local billboards: {[Instance]: BillboardGui} = {};
		local connections: {RBXScriptConnection} = {};
		local addIcon: (object: Instance, icon: string) -> ();
		addIcon = function(object: Instance, icon: string): ()
			if billboards[object] then
				return;
			end;
			local part: BasePart? = partOf(object);
			if not part then
				KitESP:Clean(task.spawn(function(): ()
					local deadline: number = os.clock() + partWait;
					repeat
						task.wait(partPoll);
						part = partOf(object);
					until part or not object.Parent or os.clock() > deadline or not KitESP["Enabled"];
					if part and object.Parent and KitESP["Enabled"] and not billboards[object] then
						addIcon(object, icon);
					end;
				end));
				return;
			end;
			if vape.ThreadFix then
				setthreadidentity(8);
			end;
			local scale: number = IconScale["Value"];
			local billboard: BillboardGui = Instance.new('BillboardGui');
			billboard.Name = icon;
			billboard.StudsOffsetWorldSpace = Vector3.new(0, 3, 0);
			billboard.Size = UDim2.fromOffset(iconSize * scale, iconSize * scale);
			billboard.AlwaysOnTop = true;
			billboard.ClipsDescendants = false;
			billboard.Adornee = part;
			billboard.Parent = folder;
			local blur: ImageLabel = addBlur(billboard);
			blur.Size = UDim2.new(1, 89 * scale, 1, 52 * scale);
			blur.Position = UDim2.fromOffset(-48 * scale, -31 * scale);
			blur.Visible = Background["Enabled"];
			local image: ImageLabel = Instance.new('ImageLabel');
			image.Size = UDim2.fromOffset(iconSize * scale, iconSize * scale);
			image.Position = UDim2.fromScale(0.5, 0.5);
			image.AnchorPoint = Vector2.new(0.5, 0.5);
			image.BackgroundColor3 = Color3.fromHSV(BackgroundColor["Hue"], BackgroundColor["Sat"], BackgroundColor["Value"]);
			image.BackgroundTransparency = 1 - (Background["Enabled"] and BackgroundColor["Opacity"] or 0);
			image.BorderSizePixel = 0;
			image.Image = bedwars.getIcon({["itemType"] = icon}, true);
			image.Parent = billboard;
			local corner: UICorner = Instance.new('UICorner');
			corner.CornerRadius = UDim.new(0, 4);
			corner.Parent = image;
			billboards[object] = billboard;
		end;
		local clear: () -> () = function(): ()
			for _: number, connection: RBXScriptConnection in connections do
				connection:Disconnect();
			end;
			table.clear(connections);
			table.clear(billboards);
			folder:ClearAllChildren();
		end;
		KitESP:Clean(clear);
		KitESP:Clean(task.spawn(function(): ()
			local current: string? = nil;
			repeat
				local kits: {string} = store.equippedKits or {};
				local key: string = table.concat(kits, ',');
				if key ~= current then
					current = key;
					clear();
					for _: number, kit: string in kits do
						local watch: {string}? = iconKits[kit];
						if watch then
							table.insert(connections, collectionService:GetInstanceAddedSignal(watch[1]):Connect(function(object: Instance): ()
								addIcon(object, watch[2]);
							end));
							table.insert(connections, collectionService:GetInstanceRemovedSignal(watch[1]):Connect(function(object: Instance): ()
								local billboard: BillboardGui? = billboards[object];
								if billboard then
									billboard:Destroy();
									billboards[object] = nil;
								end;
							end));
							for _: number, object: Instance in collectionService:GetTagged(watch[1]) do
								addIcon(object, watch[2]);
							end;
						end;
					end;
				end;
				task.wait(iconPoll);
			until not KitESP["Enabled"];
		end));
	end;

	local startSpy: () -> () = function(): ()
		local watched: {[Instance]: table} = {};
		local pending: {table} = {};
		local counts: {[Player]: {[string]: number}} = {};
		local animators: {[Animator]: boolean} = {};
		local spyPart: (object: Instance) -> BasePart? = function(object: Instance): BasePart?
			if object:IsA('Model') then
				return object.PrimaryPart or object:FindFirstChildWhichIsA('BasePart', true);
			end;
			return object:IsA('BasePart') and object or nil;
		end;
		local itemCount: (plr: Player, itemType: string) -> number = function(plr: Player, itemType: string): number
			local amount: number = 0;
			for _: number, item: table in (store.inventories[plr] or {["items"] = {}}).items do
				amount += item.itemType == itemType and (item.amount or 1) or 0;
			end;
			return amount;
		end;
		local nearest: (position: Vector3) -> Player? = function(position: Vector3): Player?
			local closest: Player?, best: number = nil, SpyRange["Value"];
			for _: number, ent: table in entitylib.List do
				if ent.Player and not ignored(ent.Player) and (ent.RootPart.Position - position).Magnitude <= best then
					closest, best = ent.Player, (ent.RootPart.Position - position).Magnitude;
				end;
			end;
			return closest;
		end;
		local track: (tags: {string}, label: string?, item: string?) -> () = function(tags: {string}, label: string?, item: string?): ()
			collection(tags, KitESP, function(list: table, object: Instance, tag: string): ()
				local part: BasePart? = spyPart(object);
				watched[object] = {["Label"] = label or extraLabels[tag] or 'collectable', ["Item"] = item, ["Position"] = part and part.Position};
			end, function(list: table, object: Instance, tag: string): ()
				local entry: table? = watched[object];
				watched[object] = nil;
				if not entry or not entry.Position then
					return;
				end;
				if entry.Item then
					table.insert(pending, {["Position"] = entry.Position, ["Time"] = tick(), ["Label"] = entry.Label, ["Item"] = entry.Item});
					return;
				end;
				local taker: Player? = nearest(entry.Position);
				if taker then
					credit(taker, entry.Label, 1);
				end;
			end);
		end;

		local items: {[string]: boolean} = {};
		for kit: string, spec: table in spyKits do
			if not spyToggles[kit]["Enabled"] then
				continue;
			end;
			if spec.Tags then
				track(spec.Tags, spec.Label, spec.Item);
				if spec.Item then
					items[spec.Item] = true;
					for _: number, ent: table in entitylib.List do
						if ent.Player then
							counts[ent.Player] = counts[ent.Player] or {};
							counts[ent.Player][spec.Item] = itemCount(ent.Player, spec.Item);
						end;
					end;
				end;
			end;
			if spec.Digging then
				local digAnimation: string = bedwars.GameAnimationUtil:getAssetId(bedwars.AnimationType.SHOVEL_DIG);
				local watchDigs: (ent: table) -> () = function(ent: table): ()
					local animator: Animator? = ent.Player and not ignored(ent.Player) and ent.Humanoid:FindFirstChildOfClass('Animator') or nil;
					if not animator or animators[animator] then
						return;
					end;
					animators[animator] = true;
					KitESP:Clean(animator.AnimationPlayed:Connect(function(played: AnimationTrack): ()
						if played.Animation.AnimationId == digAnimation then
							task.delay(SpyDelay["Value"], reportLoot, ent.Player, 'dug up', true);
						end;
					end));
				end;
				KitESP:Clean(entitylib.Events.EntityAdded:Connect(watchDigs));
				for _: number, ent: table in entitylib.List do
					watchDigs(ent);
				end;
			end;
			if spec.Bounty then
				local hunters: {[Player]: Player} = {};
				KitESP:Clean(bedwars.Client:Get('BountyHunterTargetChanged'):Connect(function(data: any): ()
					local hunter: any = type(data) == 'table' and data.hunter;
					if typeof(hunter) ~= 'Instance' or not hunter:IsA('Player') then
						return;
					end;
					local target: Player? = data.newTargetUserId ~= 0 and playersService:GetPlayerByUserId(data.newTargetUserId) or nil;
					hunters[hunter] = target;
					if target and SpyNotify["Enabled"] and not ignored(hunter) then
						notif('KitSpy', playerLabel(hunter)..' is now hunting '..playerLabel(target), 12, 'info');
					end;
				end));
				KitESP:Clean(vapeEvents.EntityDeathEvent.Event:Connect(function(deathTable: table): ()
					local victim: Player? = playersService:GetPlayerFromCharacter(deathTable.entityInstance);
					local killer: Player? = playersService:GetPlayerFromCharacter(deathTable.fromEntity);
					if not victim or not killer or hunters[killer] ~= victim then
						return;
					end;
					hunters[killer] = nil;
					if not ignored(killer) then
						credit(killer, 'bounty', 1, true);
						notif('KitSpy', playerLabel(killer)..' claimed their bounty on '..playerLabel(victim), 20, 'alert');
						task.delay(SpyDelay["Value"], reportLoot, killer, 'looted', false);
					end;
				end));
				KitESP:Clean(playersService.PlayerRemoving:Connect(function(plr: Player): ()
					hunters[plr] = nil;
					for hunter: Player, target: Player in hunters do
						if target == plr then
							hunters[hunter] = nil;
						end;
					end;
				end));
			end;
			if spec.Fishing then
				KitESP:Clean(bedwars.Client:Get('FishCaught'):Connect(function(data: any): ()
					local plr: any = type(data) == 'table' and data.catchingPlayer;
					local drops: any = plr and data.dropData and data.dropData.drops;
					if not drops or ignored(plr) or #drops == 0 then
						return;
					end;
					local caught: {string} = {};
					for _: number, drop: table in drops do
						local meta: table? = bedwars.ItemMeta[drop.itemType];
						table.insert(caught, plural(drop.amount, (meta and meta.displayName or drop.itemType):lower()));
					end;
					credit(plr, 'catch', 1, true);
					if SpyNotify["Enabled"] then
						notif('KitSpy', playerLabel(plr)..' caught '..table.concat(caught, ', '), 20, 'info');
					end;
				end));
			end;
		end;
		if #Collectables.ListEnabled > 0 then
			track(Collectables.ListEnabled, nil, nil);
		end;

		local nextScan: number = 0;
		KitESP:Clean(runService.Heartbeat:Connect(function(): ()
			local now: number = tick();
			if now < nextScan then
				return;
			end;
			nextScan = now + spyTick;
			for object: Instance, entry: table in watched do
				local part: BasePart? = spyPart(object);
				entry.Position = part and part.Position or entry.Position;
			end;
			for index: number = #pending, 1, -1 do
				if now - pending[index].Time > SpyWindow["Value"] then
					table.remove(pending, index);
				end;
			end;
			if not next(items) then
				return;
			end;
			for _: number, ent: table in entitylib.List do
				local plr: Player? = ent.Player;
				if not plr or ignored(plr) then
					continue;
				end;
				local previous: {[string]: number} = counts[plr] or {};
				counts[plr] = previous;
				for itemType: string in items do
					local amount: number = itemCount(plr, itemType);
					local gained: number = previous[itemType] and amount - previous[itemType] or 0;
					previous[itemType] = amount;
					for index: number = #pending, 1, -1 do
						local pickup: table = pending[index];
						if gained > 0 and pickup.Item == itemType and (ent.RootPart.Position - pickup.Position).Magnitude <= SpyRange["Value"] then
							table.remove(pending, index);
							credit(plr, pickup.Label, gained);
							break;
						end;
					end;
				end;
			end;
		end));
		drawViewer();
		KitESP:Clean(function(): ()
			table.clear(animators);
			panel.Visible = false;
		end);
	end;

	local kitImage: (kit: string?) -> string = function(kit: string?): string
		local meta: table? = bedwars.BedwarsKitMeta[string.split(kit or 'none', ',')[1]] or bedwars.BedwarsKitMeta.none;
		return meta and meta.renderImage or '';
	end;

	local resolvePlayer: (entry: Instance, name: string) -> Player? = function(entry: Instance, name: string): Player?
		for _: number, plr: Player in playersService:GetPlayers() do
			if plr.Name == name or plr.DisplayName == name or plr:GetAttribute('DisguiseDisplayName') == name then
				return plr;
			end;
		end;
		local streamer: table? = bedwars.StreamerModeController;
		if streamer and type(streamer.getDisplayName) == 'function' then
			for _: number, plr: Player in playersService:GetPlayers() do
				local success: boolean, shown: any = pcall(streamer.getDisplayName, streamer, plr);
				if success and shown == name then
					return plr;
				end;
			end;
		end;
		local render: Instance? = entry:FindFirstChild('PlayerRender', true);
		local userId: string? = render and render:IsA('ImageLabel') and render.Image:match('id=(%d+)') or nil;
		local rendered: Player? = userId and playersService:GetPlayerByUserId(tonumber(userId)) or nil;
		if rendered then
			return rendered;
		end;
		if name == entry:GetAttribute('KitDisplayOriginalName') then
			return playersService:GetPlayerByUserId(entry:GetAttribute('KitDisplayUserId') or 0);
		end;
		return nil;
	end;

	local previousKits: (plr: Player) -> {string} = function(plr: Player): {string}
		local userId: number = plr.UserId;
		if histories[userId] then
			return histories[userId];
		end;
		local deadline: number = os.clock() + historyWait;
		while fetching[userId] do
			if not KitESP["Enabled"] or os.clock() >= deadline then
				return {};
			end;
			task.wait();
		end;
		if histories[userId] then
			return histories[userId];
		end;
		fetching[userId] = true;
		local success: boolean, kits: any = pcall(function(): {string}?
			local data: any = fire('RequestMatchHistory', 'CallServer', plr.Name);
			if type(data) ~= 'table' or type(data.matchHistory) ~= 'table' then
				return nil;
			end;
			table.sort(data.matchHistory, function(a: table, b: table): boolean
				return (tonumber(a.matchStartTime) or 0) > (tonumber(b.matchStartTime) or 0);
			end);
			local found: {string} = {};
			for index: number, match: table in data.matchHistory do
				if index > historyLength then
					break;
				end;
				local kit: string = 'none';
				for _: number, member: table in match.players or {} do
					if member.playerInfo and member.playerInfo.userId == userId then
						kit = member.bedwars and member.bedwars.kit or 'none';
						break;
					end;
				end;
				table.insert(found, kit);
			end;
			return found;
		end);
		fetching[userId] = nil;
		if success and type(kits) == 'table' then
			histories[userId] = kits;
			return kits;
		end;
		return {};
	end;

	local drawHistory: (card: Instance, plr: Player) -> () = function(card: Instance, plr: Player): ()
		local old: Instance? = card:FindFirstChild('PreviousKits');
		if old then
			old:Destroy();
		end;
		if not DraftHistory["Enabled"] then
			return;
		end;
		local holder: Frame = Instance.new('Frame');
		holder.Name = 'PreviousKits';
		holder.AnchorPoint = Vector2.new(0.5, 0);
		holder.Position = UDim2.fromScale(0.5, 0.03);
		holder.Size = UDim2.fromScale(0.86, 0.24);
		holder.BackgroundColor3 = Color3.new();
		holder.BackgroundTransparency = 1;
		holder.BorderSizePixel = 0;
		holder.ClipsDescendants = true;
		holder.ZIndex = 3;
		holder.Parent = card;
		KitESP:Clean(holder);
		local corner: UICorner = Instance.new('UICorner');
		corner.CornerRadius = UDim.new(0, 4);
		corner.Parent = holder;
		local padding: UIPadding = Instance.new('UIPadding');
		padding.PaddingLeft = UDim.new(0, 3);
		padding.PaddingRight = UDim.new(0, 3);
		padding.Parent = holder;
		local layout: UIListLayout = Instance.new('UIListLayout');
		layout.FillDirection = Enum.FillDirection.Horizontal;
		layout.HorizontalAlignment = Enum.HorizontalAlignment.Center;
		layout.VerticalAlignment = Enum.VerticalAlignment.Center;
		layout.Padding = UDim.new(0, 2);
		layout.SortOrder = Enum.SortOrder.LayoutOrder;
		layout.Parent = holder;
		local kits: {string} = previousKits(plr);
		if not KitESP["Enabled"] or not DraftHistory["Enabled"] or not holder.Parent then
			return;
		end;
		if #kits == 0 then
			holder:Destroy();
			return;
		end;
		for index: number, kit: string in kits do
			local icon: ImageLabel = Instance.new('ImageLabel');
			icon.Name = 'Kit'..index;
			icon.LayoutOrder = index;
			icon.Size = UDim2.fromScale(1, 1);
			icon.SizeConstraint = Enum.SizeConstraint.RelativeYY;
			icon.BackgroundTransparency = 1;
			icon.Image = kitImage(kit);
			icon.ScaleType = Enum.ScaleType.Fit;
			icon.ZIndex = 4;
			icon.Parent = holder;
			local order: TextLabel = Instance.new('TextLabel');
			order.Name = 'Order';
			order.Position = UDim2.fromOffset(1, 1);
			order.Size = UDim2.fromOffset(13, 13);
			order.BackgroundColor3 = Color3.new();
			order.BackgroundTransparency = 1;
			order.BorderSizePixel = 0;
			order.FontFace = Font.new(uipallet.Font.Family, Enum.FontWeight.Bold);
			order.Text = tostring(index);
			order.TextColor3 = Color3.new(1, 1, 1);
			order.TextSize = 9;
			order.ZIndex = 5;
			order.Parent = icon;
			local orderCorner: UICorner = Instance.new('UICorner');
			orderCorner.CornerRadius = UDim.new(0, 4);
			orderCorner.Parent = order;
		end;
	end;

	local startDraft: () -> () = function(): ()
		local entryConnections: {[Instance]: {RBXScriptConnection}} = {};
		local active: () -> boolean = function(): boolean
			return KitESP["Enabled"] and Draft["Enabled"];
		end;
		local drawEntry: (entry: Instance) -> ();
		drawEntry = function(entry: Instance): ()
			task.wait(draftDelay);
			if not active() or not entry.Parent then
				return;
			end;
			local nameLabel: Instance? = entry:FindFirstChild('PlayerName', true);
			if not nameLabel then
				return;
			end;
			local originalName: string = nameLabel:GetAttribute('NickHiderOriginalText') or nameLabel.Text;
			local plr: Player? = resolvePlayer(entry, originalName);
			if not active() or not entry.Parent or not plr then
				return;
			end;
			local frame: Instance? = entry:FindFirstChild('1');
			local card: Instance? = frame and frame:FindFirstChild('MatchDraftPlayerCard');
			if not card then
				return;
			end;
			for _: number, connection: RBXScriptConnection in entryConnections[entry] or {} do
				connection:Disconnect();
			end;
			local image: ImageLabel? = card:FindFirstChild('KitImage');
			if not image then
				image = Instance.new('ImageLabel');
				image.BackgroundTransparency = 1;
				image.AnchorPoint = Vector2.new(1, 0.5);
				image.Position = UDim2.fromScale(1.05, 0);
				image.Name = 'KitImage';
				image.Size = UDim2.fromScale(1.5, 1.5);
				image.ZIndex = 1;
				image.ImageTransparency = 0.4;
				image.SliceCenter = Rect.new(0, 0, 0, 0);
				image.SliceScale = 1;
				image.ScaleType = Enum.ScaleType.Crop;
				image.Parent = card;
				KitESP:Clean(image);
				local ratio: UIAspectRatioConstraint = Instance.new('UIAspectRatioConstraint');
				ratio.Name = '1';
				ratio.AspectRatio = 1;
				ratio.AspectType = Enum.AspectType.FitWithinMaxSize;
				ratio.DominantAxis = Enum.DominantAxis.Width;
				ratio.Parent = image;
			end;
			local showKit: () -> () = function(): ()
				image.Image = kitImage(plr:GetAttribute('PlayingAsKits'));
				image.Position = UDim2.fromScale(1.05, 0);
				tweenService:Create(image, draftTween, {["Position"] = UDim2.fromScale(1.05, 0.5)}):Play();
			end;
			showKit();
			task.spawn(drawHistory, card, plr);
			entry:SetAttribute('KitDisplayUserId', plr.UserId);
			entry:SetAttribute('KitDisplayOriginalName', originalName);
			local kitWatch: RBXScriptConnection = plr:GetAttributeChangedSignal('PlayingAsKits'):Connect(function(): ()
				if active() and image.Parent then
					showKit();
				end;
			end);
			local nameWatch: RBXScriptConnection = nameLabel:GetPropertyChangedSignal('Text'):Once(function(): ()
				kitWatch:Disconnect();
				drawEntry(entry);
			end);
			entryConnections[entry] = {kitWatch, nameWatch};
			KitESP:Clean(nameWatch);
			KitESP:Clean(kitWatch);
		end;
		KitESP:Clean(task.spawn(function(): ()
			local body: Instance? = nil;
			repeat
				local app: Instance? = lplr.PlayerGui:FindFirstChild('MatchDraftApp');
				local background: Instance? = app and app:FindFirstChild('DraftAppBackground');
				local frame: Instance? = background and background:FindFirstChild('1');
				body = frame and frame:FindFirstChild('BodyContainer');
				if not body then
					task.wait(draftPoll);
				end;
			until body or not active();
			if not body or not active() then
				return;
			end;
			for team: number = 1, 2 do
				if not active() then
					break;
				end;
				local column: Instance? = nil;
				local deadline: number = tick() + columnWait;
				repeat
					column = body:FindFirstChild('Team'..team..'Column');
					if not column then
						task.wait(draftPoll);
					end;
				until column or not active() or tick() >= deadline;
				if column then
					KitESP:Clean(column.ChildAdded:Connect(drawEntry));
					for _: number, entry: Instance in column:GetChildren() do
						task.spawn(drawEntry, entry);
					end;
				end;
			end;
		end));
		KitESP:Clean(function(): ()
			table.clear(entryConnections);
		end);
	end;

	local restart: () -> () = function(): ()
		if KitESP["Enabled"] then
			KitESP:Toggle();
			KitESP:Toggle();
		end;
	end;

	KitESP = vape.Categories.Render:CreateModule({
		["Name"] = 'KitESP',
		["Function"] = function(callback: boolean): ()
			if not callback then
				return;
			end;
			if Icons["Enabled"] then
				startIcons();
			end;
			if Spy["Enabled"] then
				startSpy();
			end;
			if Draft["Enabled"] then
				startDraft();
			end;
		end,
		["Tooltip"] = 'Kit intel: icons over your kit objects, a spy on what enemies do with their kits, and enemy kits in the match draft.'
	});

	local section: (shown: boolean, members: {table}) -> () = function(shown: boolean, members: {table}): ()
		for _: number, member: table in members do
			member.Object.Visible = shown;
		end;
	end;
	local iconOptions: {table} = {};
	local spyOptions: {table} = {};
	local draftOptions: {table} = {};

	Icons = KitESP:CreateToggle({
		["Name"] = 'Kit Icons',
		["Default"] = true,
		["Function"] = function(callback: boolean): ()
			section(callback, iconOptions);
			restart();
		end,
		["Tooltip"] = 'ESP for kit objects of every kit you are playing (both kits in Kit Fusion).'
	});
	Background = KitESP:CreateToggle({
		["Name"] = 'Background',
		["Default"] = true,
		["Darker"] = true,
		["Function"] = function(callback: boolean): ()
			if BackgroundColor then
				BackgroundColor.Object.Visible = callback and Icons["Enabled"];
			end;
			for _: number, billboard: Instance in folder:GetChildren() do
				billboard.ImageLabel.BackgroundTransparency = 1 - (callback and BackgroundColor["Opacity"] or 0);
				billboard.Blur.Visible = callback;
			end;
		end
	});
	BackgroundColor = KitESP:CreateColorSlider({
		["Name"] = 'Background Color',
		["DefaultValue"] = 0,
		["DefaultOpacity"] = 0.5,
		["Darker"] = true,
		["Function"] = function(hue: number, sat: number, value: number, opacity: number): ()
			for _: number, billboard: Instance in folder:GetChildren() do
				billboard.ImageLabel.BackgroundColor3 = Color3.fromHSV(hue, sat, value);
				billboard.ImageLabel.BackgroundTransparency = 1 - (Background["Enabled"] and opacity or 0);
			end;
		end
	});
	IconScale = KitESP:CreateSlider({
		["Name"] = 'Scale',
		["Min"] = 0.1,
		["Max"] = 1.5,
		["Default"] = 1,
		["Decimal"] = 10,
		["Darker"] = true,
		["Function"] = function(value: number): ()
			for _: number, billboard: Instance in folder:GetChildren() do
				billboard.Size = UDim2.fromOffset(iconSize * value, iconSize * value);
				billboard.ImageLabel.Size = UDim2.fromOffset(iconSize * value, iconSize * value);
				billboard.Blur.Size = UDim2.new(1, 89 * value, 1, 52 * value);
				billboard.Blur.Position = UDim2.fromOffset(-48 * value, -31 * value);
			end;
		end
	});
	iconOptions = {Background, BackgroundColor, IconScale};

	Spy = KitESP:CreateToggle({
		["Name"] = 'Kit Spy',
		["Function"] = function(callback: boolean): ()
			section(callback, spyOptions);
			restart();
		end,
		["Tooltip"] = 'Reports what other players do with their kit, from bee pickups to bounty claims.'
	});
	Viewer = KitESP:CreateToggle({
		["Name"] = 'Viewer',
		["Default"] = true,
		["Darker"] = true,
		["Function"] = drawViewer,
		["Tooltip"] = 'Panel with everything each player has picked up, click it to expand.'
	});
	SpyNotify = KitESP:CreateToggle({
		["Name"] = 'Notifications',
		["Default"] = true,
		["Darker"] = true,
		["Tooltip"] = 'Notify every time someone is caught using their kit.'
	});
	IgnoreTeam = KitESP:CreateToggle({
		["Name"] = 'Ignore teammates',
		["Default"] = true,
		["Darker"] = true
	});
	IgnoreSelf = KitESP:CreateToggle({
		["Name"] = 'Ignore yourself',
		["Default"] = true,
		["Darker"] = true
	});
	SpyRange = KitESP:CreateSlider({
		["Name"] = 'Range',
		["Min"] = 1,
		["Max"] = 40,
		["Default"] = 25,
		["Darker"] = true,
		["Suffix"] = function(value: number): string
			return value <= 1 and 'stud' or 'studs';
		end,
		["Tooltip"] = 'How close a player must be to a pickup to be blamed for it.'
	});
	SpyWindow = KitESP:CreateSlider({
		["Name"] = 'Window',
		["Min"] = 1,
		["Max"] = 10,
		["Default"] = 3,
		["Darker"] = true,
		["Suffix"] = function(value: number): string
			return value > 1 and 'secs' or 'sec';
		end,
		["Tooltip"] = 'How recently something must have happened to still count.'
	});
	SpyDelay = KitESP:CreateSlider({
		["Name"] = 'Delay',
		["Min"] = 0,
		["Max"] = 2,
		["Default"] = 0.5,
		["Decimal"] = 100,
		["Darker"] = true,
		["Suffix"] = function(value: number): string
			return value == 1 and 'sec' or 'secs';
		end,
		["Tooltip"] = 'Wait before reading their inventory after a dig or a bounty kill.'
	});
	DigItems = KitESP:CreateTextList({
		["Name"] = 'Items',
		["Placeholder"] = 'item type (iron_ingot)',
		["Darker"] = true,
		["Tooltip"] = 'Only report these item types when someone digs, empty reports everything.'
	});
	Collectables = KitESP:CreateTextList({
		["Name"] = 'Collectables',
		["Default"] = {'alchemist_ingedients', 'alchemy_crystal', 'crystalheart_seed', 'ghost', 'murder_coin', 'shadow_coin', 'soulvine_seed', 'spirit_gardener_energy', 'spirit_gardener_seeds', 'tearbloom_seed'},
		["Darker"] = true,
		["Tooltip"] = 'Extra collectable tags to watch, credited to whoever was closest when they vanished.'
	});
	KitESP:CreateButton({
		["Name"] = 'Reset totals',
		["Function"] = function(): ()
			table.clear(totals);
			drawViewer();
		end
	});
	spyOptions = {Viewer, SpyNotify, IgnoreTeam, IgnoreSelf, SpyRange, SpyWindow, SpyDelay, DigItems, Collectables};
	local kitName: (kit: string) -> string = function(kit: string): string
		local meta: table? = bedwars.BedwarsKitMeta[kit];
		return meta and meta.name or kit;
	end;
	local spyNames: {string} = {};
	for kit: string in spyKits do
		table.insert(spyNames, kit);
	end;
	table.sort(spyNames, function(a: string, b: string): boolean
		return kitName(a) < kitName(b);
	end);
	for _: number, kit: string in spyNames do
		spyToggles[kit] = KitESP:CreateToggle({
			["Name"] = 'Spy '..kitName(kit),
			["Default"] = true,
			["Darker"] = true,
			["Function"] = restart
		});
		table.insert(spyOptions, spyToggles[kit]);
	end;

	Draft = KitESP:CreateToggle({
		["Name"] = 'Draft Display',
		["Function"] = function(callback: boolean): ()
			section(callback, draftOptions);
			restart();
		end,
		["Tooltip"] = 'Shows every player\'s kit on the match draft screen.'
	});
	DraftHistory = KitESP:CreateToggle({
		["Name"] = 'Show previous kits',
		["Default"] = true,
		["Darker"] = true,
		["Function"] = restart,
		["Tooltip"] = 'Shows the kits each player used in their last 8 games, newest first.'
	});
	draftOptions = {DraftHistory};
	section(Icons["Enabled"], iconOptions);
	section(Spy["Enabled"], spyOptions);
	section(Draft["Enabled"], draftOptions);
end);

velo.run(function(): ()
	local ProjectileTracers: table = {["Enabled"] = false};
	local TracerMaterial: table;
	local TracerColor: table;
	local Thickness: table;
	local Curve: table;
	local Opacity: table;
	local Lifetime: table;
	local Fade: table;
	local rayLength: number = 2000;
	local rayParams: RaycastParams = RaycastParams.new();
	rayParams.FilterType = Enum.RaycastFilterType.Exclude;

	local drawArc: (projectile: Instance) -> () = function(projectile: Instance): ()
		local filter: {Instance} = {projectile};
		if lplr.Character then
			table.insert(filter, lplr.Character);
		end;
		rayParams.FilterDescendantsInstances = filter;
		local root: BasePart? = projectile:IsA('BasePart') and projectile or projectile:IsA('Model') and projectile.PrimaryPart or nil;
		local meta: table? = bedwars.ProjectileMeta[projectile.Name];
		if not root or not meta then
			return;
		end;
		local origin: Vector3, velocity: Vector3 = root.Position, root.AssemblyLinearVelocity;
		local speed: number = velocity.Magnitude;
		if speed <= 0 then
			return;
		end;
		local direction: Vector3 = velocity / speed;
		local gravity: Vector3 = Vector3.new(0, -(meta.gravitationalAcceleration or workspace.Gravity), 0);
		local hit: RaycastResult? = workspace:Raycast(origin, direction * rayLength, rayParams);
		local endpoint: Vector3 = hit and hit.Position or origin + direction * rayLength;
		local steps: number = Curve["Value"];
		local stepTime: number = (endpoint - origin).Magnitude / speed / steps;
		local material: Enum.Material = Enum.Material[TracerMaterial["Value"]];
		local arc: Model = Instance.new('Model');
		if material == Enum.Material.Glass then
			local highlight: Highlight = Instance.new('Highlight');
			highlight.Enabled = false;
			highlight.Parent = arc;
		end;
		local from: Vector3 = origin;
		for step: number = 1, steps do
			local t: number = step * stepTime;
			local to: Vector3 = origin + velocity * t + 0.5 * gravity * t * t;
			local length: number = (to - from).Magnitude;
			if length >= 0.01 then
				local segment: Part = Instance.new('Part');
				segment.Anchored = true;
				segment.CanCollide = false;
				segment.CanQuery = false;
				segment.CanTouch = false;
				segment.CastShadow = false;
				segment.Color = Color3.fromHSV(TracerColor["Hue"], TracerColor["Sat"], TracerColor["Value"]);
				segment.Size = Vector3.new(Thickness["Value"], Thickness["Value"], length);
				segment.CFrame = CFrame.lookAt(from, to) * CFrame.new(0, 0, -length / 2);
				segment.Material = material;
				segment.Transparency = Opacity["Value"];
				if Fade["Enabled"] then
					tweenService:Create(segment, TweenInfo.new(Lifetime["Value"]), {["Transparency"] = 1}):Play();
				end;
				segment.Parent = arc;
			end;
			from = to;
		end;
		arc.Parent = workspace.Terrain;
		task.delay(Lifetime["Value"], arc.Destroy, arc);
	end;

	ProjectileTracers = vape.Categories.Render:CreateModule({
		["Name"] = 'ProjectileTracers',
		["Function"] = function(callback: boolean): ()
			if callback then
				ProjectileTracers:Clean(workspace.ChildAdded:Connect(function(projectile: Instance): ()
					task.delay(0, function(): ()
						if ProjectileTracers["Enabled"] and projectile.Parent and projectile:GetAttribute('ProjectileShooter') == lplr.UserId then
							drawArc(projectile);
						end;
					end);
				end));
			end;
		end,
		["Tooltip"] = 'Replacement tracers for projectiles'
	});
	local materials: {string} = {'SmoothPlastic'};
	for _: number, material: EnumItem in Enum.Material:GetEnumItems() do
		if material.Name ~= 'SmoothPlastic' then
			table.insert(materials, material.Name);
		end;
	end;
	TracerMaterial = ProjectileTracers:CreateDropdown({
		["Name"] = 'Material',
		["List"] = materials
	});
	TracerColor = ProjectileTracers:CreateColorSlider({
		["Name"] = 'Tracer Color',
		["DefaultOpacity"] = 0.5
	});
	Thickness = ProjectileTracers:CreateSlider({
		["Name"] = 'Thickness',
		["Min"] = 0.01,
		["Max"] = 1,
		["Default"] = 0.1,
		["Decimal"] = 100
	});
	Curve = ProjectileTracers:CreateSlider({
		["Name"] = 'Curveness',
		["Min"] = 1,
		["Max"] = 100,
		["Default"] = 40,
		["Tooltip"] = 'How curve the projectile is gonna be\n(More curve = more lag)'
	});
	Opacity = ProjectileTracers:CreateSlider({
		["Name"] = 'Opacity',
		["Min"] = 0,
		["Max"] = 1,
		["Default"] = 0,
		["Decimal"] = 100
	});
	Lifetime = ProjectileTracers:CreateSlider({
		["Name"] = 'Lifetime',
		["Min"] = 0,
		["Max"] = 5,
		["Default"] = 2,
		["Decimal"] = 100,
		["Suffix"] = 'secs'
	});
	Fade = ProjectileTracers:CreateToggle({
		["Name"] = 'Fade',
		["Default"] = true
	});
end);

velo.run(function(): ()
	local SkinChanger: table = {["Enabled"] = false};
	local tierPrefixes: {[string]: boolean} = {["leather"] = true, ["chainmail"] = true, ["wood"] = true, ["stone"] = true, ["gold"] = true, ["iron"] = true, ["diamond"] = true, ["emerald"] = true};
	local kitPrefixes: {[string]: boolean} = {["tactical"] = true, ["flower"] = true, ["falconer"] = true, ["life"] = true, ["feather"] = true};
	local clawModels: {string} = {'lobby_kaida_claw', 'bear_claws', 'summoner_claw_1', 'summoner_claw_2', 'summoner_claw_3', 'summoner_claw_4'};
	local respawnPasses: number = 10;
	local respawnGap: number = 0.4;
	local skinsByItem: {[string]: {[string]: string}} = {};
	local familyOf: {[string]: string} = {};
	local familyMembers: {[string]: {string}} = {};
	local familySkins: {[string]: {[string]: string}} = {};
	local familyOptions: {[string]: table} = {};
	local claws: {[string]: string} = {};
	local originalSkins: {[Instance]: table} = {};
	local swapped: {[Instance]: table} = {};
	local swordSounds: {[string]: table} = {};
	local lastHand: string?;
	local queued: boolean = false;
	local accessoryWatch: RBXScriptConnection?;

	local titleCase: (text: string) -> string = function(text: string): string
		return (text:gsub('_', ' '):gsub('%a+', function(word: string): string
			return word:sub(1, 1):upper()..word:sub(2);
		end));
	end;

	for _: any, skinId: string in bedwars.ItemSkinType do
		local meta: table? = bedwars.getItemSkinMeta(skinId);
		local item: table? = meta and meta.itemType and bedwars.ItemMeta[meta.itemType];
		if item and not (item.block and not item.image) then
			local label: string = '_'..skinId..'_';
			for segment: string in meta.itemType:gmatch('[^_]+') do
				label = label:gsub('_'..segment..'_', '_');
			end;
			label = label:gsub('^_+', ''):gsub('_+$', '');
			skinsByItem[meta.itemType] = skinsByItem[meta.itemType] or {};
			skinsByItem[meta.itemType][titleCase(label ~= '' and label or skinId)] = skinId;
		end;
	end;

	for itemType: string in skinsByItem do
		local family: string = itemType:gsub('_%d+$', '');
		for _: number, prefixes: {[string]: boolean} in {tierPrefixes, kitPrefixes} do
			local prefix: string?, rest: string? = family:match('^([^_]+)_(.+)$');
			family = prefix and prefixes[prefix] and rest or family;
		end;
		family = family:gsub('_left$', ''):gsub('_helmet$', '_armor'):gsub('_chestplate$', '_armor'):gsub('_leggings$', '_armor'):gsub('_boots$', '_armor');
		familyOf[itemType] = family;
		familyMembers[family] = familyMembers[family] or {};
		table.insert(familyMembers[family], itemType);
	end;

	for _: number, model: string in clawModels do
		if replicatedStorage.Items:FindFirstChild(model) then
			claws[titleCase((model:gsub('^lobby_', '')))] = model;
		end;
	end;

	local resolve: (itemType: string) -> (string?, string?) = function(itemType: string): (string?, string?)
		local family: string? = familyOf[itemType];
		local option: table? = SkinChanger["Enabled"] and family and familyOptions[family] or nil;
		local label: string? = option and option["Value"];
		if not label or label == 'None' then
			return nil, nil;
		end;
		if claws[label] then
			return nil, claws[label];
		end;
		local skin: string? = skinsByItem[itemType][label] or familySkins[family][label];
		return skin, skin;
	end;

	local applySounds: () -> () = function(): ()
		for itemType: string in skinsByItem do
			local sword: table? = bedwars.ItemMeta[itemType].sword;
			if sword then
				local skin: string? = resolve(itemType);
				local skinSword: table? = skin and bedwars.getItemSkinMeta(skin).sword;
				if skinSword and (skinSword.swingSounds or skinSword.hitSounds) then
					swordSounds[itemType] = swordSounds[itemType] or {["Swing"] = sword.swingSounds, ["Hit"] = sword.hitSounds};
					sword.swingSounds = skinSword.swingSounds or swordSounds[itemType].Swing;
					sword.hitSounds = skinSword.hitSounds or swordSounds[itemType].Hit;
				elseif swordSounds[itemType] then
					sword.swingSounds = swordSounds[itemType].Swing;
					sword.hitSounds = swordSounds[itemType].Hit;
					swordSounds[itemType] = nil;
				end;
			end;
		end;
	end;

	local applyModel: (accessory: Instance) -> () = function(accessory: Instance): ()
		local model: string? = select(2, resolve(accessory.Name));
		local handle: Instance? = accessory:FindFirstChild('Handle');
		local template: Instance? = model and replicatedStorage.Items:FindFirstChild(model);
		if not handle or not template or swapped[accessory] then
			return;
		end;
		local templateHandle: BasePart = template.Handle;
		local grip: Attachment? = handle:FindFirstChild('RightGripAttachment');
		local templateGrip: Attachment? = templateHandle:FindFirstChild('RightGripAttachment');
		local record: table = {["Model"] = model, ["Parts"] = {}, ["Size"] = handle.Size, ["Grip"] = grip and grip.CFrame};
		swapped[accessory] = record;
		accessory.Destroying:Once(function(): ()
			swapped[accessory] = nil;
		end);
		for _: number, child: Instance in handle:GetChildren() do
			if child:IsA('BasePart') and child:GetAttribute('SkinHidden') == nil then
				child:SetAttribute('SkinHidden', child.Transparency);
				child.Transparency = 1;
			end;
		end;
		if handle:IsA('MeshPart') and templateHandle:IsA('MeshPart') then
			handle:ApplyMesh(templateHandle);
		end;
		handle.Size = templateHandle.Size;
		if grip and templateGrip then
			grip.CFrame = templateGrip.CFrame;
		end;
		for _: number, piece: Instance in templateHandle:GetChildren() do
			if piece:IsA('BasePart') then
				local part: BasePart = piece:Clone();
				part.CanCollide = false;
				part.CanTouch = false;
				part.CanQuery = false;
				part.Massless = true;
				part.CFrame = handle.CFrame * (templateHandle.CFrame:Inverse() * piece.CFrame);
				part.Parent = handle;
				local weld: WeldConstraint = Instance.new('WeldConstraint');
				weld.Part0 = handle;
				weld.Part1 = part;
				weld.Parent = part;
				table.insert(record.Parts, part);
			end;
		end;
	end;

	local setToolSkin: (tool: any, skin: string?) -> () = function(tool: any, skin: string?): ()
		if typeof(tool) ~= 'Instance' then
			return;
		end;
		if skin then
			if not originalSkins[tool] then
				originalSkins[tool] = {["Value"] = tool:GetAttribute('ItemSkin')};
				tool.Destroying:Once(function(): ()
					originalSkins[tool] = nil;
				end);
			end;
			if tool:GetAttribute('ItemSkin') ~= skin then
				tool:SetAttribute('ItemSkin', skin);
			end;
		elseif originalSkins[tool] then
			local original: any = originalSkins[tool].Value;
			originalSkins[tool] = nil;
			tool:SetAttribute('ItemSkin', original);
		end;
	end;

	local applySkins: () -> () = function(): ()
		local inventory: table = store.inventory.inventory;
		local handSkin: string = inventory.hand and inventory.hand.itemSkin or '';
		local changed: boolean = false;
		for _: number, item: table in inventory.items do
			local skin: string? = resolve(item.itemType);
			setToolSkin(item.tool, skin);
			if (item.itemSkin or '') ~= (skin or '') then
				item.itemSkin = skin;
				changed = true;
			end;
		end;
		if inventory.hand then
			local skin: string? = resolve(inventory.hand.itemType);
			setToolSkin(inventory.hand.tool, skin);
			if (inventory.hand.itemSkin or '') ~= (skin or '') then
				inventory.hand.itemSkin = skin or '';
				changed = true;
			end;
		end;
		local hand: string? = inventory.hand and inventory.hand.itemType;
		if not changed and hand == lastHand then
			return;
		end;
		if hand ~= lastHand or (inventory.hand and inventory.hand.itemSkin or '') ~= handSkin then
			bedwars.InventoryViewmodelController:handleStore(bedwars.Store:getState());
		end;
		lastHand = hand;
		for _: number, accessory: Instance in (lplr.Character and lplr.Character:GetChildren() or {}) do
			local record: table? = accessory:IsA('Accessory') and swapped[accessory] or nil;
			if record and record.Model ~= select(2, resolve(accessory.Name)) then
				local handle: Instance? = accessory:FindFirstChild('Handle');
				local template: Instance? = replicatedStorage.Items:FindFirstChild(accessory.Name);
				for _: number, part: BasePart in record.Parts do
					part:Destroy();
				end;
				for _: number, child: Instance in (handle and handle:GetChildren() or {}) do
					local transparency: number? = child:GetAttribute('SkinHidden');
					if transparency then
						child.Transparency = transparency;
						child:SetAttribute('SkinHidden', nil);
					end;
				end;
				if handle then
					if template and handle:IsA('MeshPart') and template.Handle:IsA('MeshPart') then
						handle:ApplyMesh(template.Handle);
					end;
					handle.Size = record.Size;
					local grip: Attachment? = handle:FindFirstChild('RightGripAttachment');
					if grip and record.Grip then
						grip.CFrame = record.Grip;
					end;
				end;
				swapped[accessory] = nil;
			end;
			if accessory:IsA('Accessory') then
				applyModel(accessory);
			end;
		end;
	end;

	local queueSkins: () -> () = function(): ()
		if queued then
			return;
		end;
		queued = true;
		task.defer(function(): ()
			queued = false;
			applySkins();
		end);
	end;

	local watchAccessories: (character: Model) -> () = function(character: Model): ()
		if accessoryWatch then
			accessoryWatch:Disconnect();
		end;
		accessoryWatch = character.ChildAdded:Connect(function(child: Instance): ()
			if child:IsA('Accessory') and child:WaitForChild('Handle', 3) and SkinChanger["Enabled"] then
				applyModel(child);
			end;
		end);
	end;

	SkinChanger = vape.Categories.Render:CreateModule({
		["Name"] = 'SkinChanger',
		["Function"] = function(callback: boolean): ()
			if callback then
				SkinChanger:Clean(vapeEvents.InventoryChanged.Event:Connect(queueSkins));
				SkinChanger:Clean(vapeEvents.InventoryAmountChanged.Event:Connect(queueSkins));
				SkinChanger:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damage: table): ()
					if damage.fromEntity ~= lplr.Character or damage.damageType ~= 0 then
						return;
					end;
					local held: table? = store.hand.toolType == 'sword' and store.hand or store.tools.sword;
					local tool: Instance? = held and held.tool;
					local skin: string? = tool and originalSkins[tool] and tool:GetAttribute('ItemSkin');
					local meta: table? = skin and bedwars.getItemSkinMeta(skin);
					local sounds: {string}? = meta and meta.sword and meta.sword.hitSounds;
					if sounds and #sounds > 0 then
						local root: BasePart? = damage.entityInstance and damage.entityInstance.PrimaryPart;
						bedwars.AudioManager:playAudio(sounds[math.random(1, #sounds)], {["position"] = root and root.Position});
					end;
				end));
				SkinChanger:Clean(lplr.CharacterAdded:Connect(function(character: Model): ()
					lastHand = nil;
					watchAccessories(character);
					task.spawn(function(): ()
						for _: number = 1, respawnPasses do
							task.wait(respawnGap);
							if not SkinChanger["Enabled"] then
								return;
							end;
							applySkins();
						end;
					end);
				end));
				SkinChanger:Clean(function(): ()
					if accessoryWatch then
						accessoryWatch:Disconnect();
						accessoryWatch = nil;
					end;
				end);
				if lplr.Character then
					watchAccessories(lplr.Character);
				end;
			end;
			applySounds();
			applySkins();
			if not callback then
				table.clear(originalSkins);
				table.clear(swapped);
			end;
		end,
		["Tooltip"] = 'Reskins the items you hold, including their sounds. Only you can see it.'
	});

	local familyOrder: {string} = {};
	local familyNames: {[string]: string} = {};
	local familyLabels: {[string]: {string}} = {};
	for family: string, members: {string} in familyMembers do
		table.sort(members);
		familySkins[family] = {};
		familyNames[family] = titleCase(#members > 1 and family or members[1]);
		local labels: {string}, melee: boolean = {}, false;
		for _: number, itemType: string in members do
			melee = melee or bedwars.ItemMeta[itemType].sword ~= nil;
			for label: string, skin: string in skinsByItem[itemType] do
				if not familySkins[family][label] then
					familySkins[family][label] = skin;
					table.insert(labels, label);
				end;
			end;
		end;
		for label: string in (melee and claws or {}) do
			table.insert(labels, label);
		end;
		table.sort(labels);
		table.insert(labels, 1, 'None');
		familyLabels[family] = labels;
		table.insert(familyOrder, family);
	end;
	table.sort(familyOrder, function(a: string, b: string): boolean
		return familyNames[a] < familyNames[b];
	end);
	for _: number, family: string in familyOrder do
		familyOptions[family] = SkinChanger:CreateDropdown({
			["Name"] = familyNames[family],
			["List"] = familyLabels[family],
			["Function"] = function(): ()
				if SkinChanger["Enabled"] then
					applySounds();
					applySkins();
				end;
			end
		});
	end;
end);

velo.run(function(): ()
	local CustomArmour: table = {["Enabled"] = false};
	local Color: table;
	local Transparency: table;
	local Boots: table;
	local Helmet: table;
	local Chestplate: table;
	local highlights: {[Instance]: Highlight} = {};

	local paint: (accessory: Instance) -> () = function(accessory: Instance): ()
		local wanted: boolean = false;
		for piece: string, option: table in {["boot"] = Boots, ["helmet"] = Helmet, ["chestplate"] = Chestplate} do
			wanted = wanted or (accessory.Name:find(piece) ~= nil and option["Enabled"]);
		end;
		local handle: Instance? = accessory:FindFirstChild('Handle');
		local highlight: Highlight? = highlights[accessory];
		if not CustomArmour["Enabled"] or not wanted or not handle or accessory:GetAttribute('VeloTrim') then
			if highlight then
				highlight:Destroy();
				highlights[accessory] = nil;
			end;
			return;
		end;
		if not highlight then
			highlight = Instance.new('Highlight');
			highlight.DepthMode = Enum.HighlightDepthMode.Occluded;
			highlight.OutlineTransparency = 1;
			highlight.Adornee = handle;
			highlight.Parent = accessory;
			highlights[accessory] = highlight;
			highlight.Destroying:Once(function(): ()
				if highlights[accessory] == highlight then
					highlights[accessory] = nil;
				end;
			end);
		end;
		highlight.FillColor = Color3.fromHSV(Color["Hue"], Color["Sat"], Color["Value"]);
		highlight.FillTransparency = Transparency["Value"] / 100;
	end;

	local paintAll: () -> () = function(): ()
		for accessory: Instance in highlights do
			paint(accessory);
		end;
		for _: number, child: Instance in (lplr.Character and lplr.Character:GetChildren() or {}) do
			if child:IsA('Accessory') then
				paint(child);
			end;
		end;
	end;

	local watchCharacter: (character: Model) -> () = function(character: Model): ()
		CustomArmour:Clean(character.ChildAdded:Connect(function(child: Instance): ()
			if child:IsA('Accessory') and child:WaitForChild('Handle', 3) then
				paint(child);
			end;
		end));
	end;

	CustomArmour = vape.Categories.Velocity:CreateModule({
		["Name"] = 'CustomArmour',
		["Function"] = function(callback: boolean): ()
			if callback then
				CustomArmour:Clean(lplr.CharacterAdded:Connect(watchCharacter));
				CustomArmour:Clean(function(): ()
					for _: Instance, highlight: Highlight in highlights do
						highlight:Destroy();
					end;
					table.clear(highlights);
				end);
				if lplr.Character then
					watchCharacter(lplr.Character);
				end;
				paintAll();
			end;
		end,
		["Tooltip"] = 'Recolors your armour. Only you can see it.'
	});
	Color = CustomArmour:CreateColorSlider({
		["Name"] = 'Color',
		["Function"] = paintAll
	});
	Transparency = CustomArmour:CreateSlider({
		["Name"] = 'Transparency',
		["Min"] = 0,
		["Max"] = 100,
		["Default"] = 0,
		["Function"] = paintAll,
		["Tooltip"] = 'Transparency of the color.'
	});
	Boots = CustomArmour:CreateToggle({
		["Name"] = 'Boots',
		["Default"] = true,
		["Function"] = paintAll,
		["Tooltip"] = 'Colors the boots.'
	});
	Helmet = CustomArmour:CreateToggle({
		["Name"] = 'Helmet',
		["Default"] = true,
		["Function"] = paintAll,
		["Tooltip"] = 'Colors the helmet.'
	});
	Chestplate = CustomArmour:CreateToggle({
		["Name"] = 'Chestplate',
		["Default"] = true,
		["Function"] = paintAll,
		["Tooltip"] = 'Colors the chestplate.'
	});
end);

velo.run(function(): ()
	if not bedwars.ArmorTrimType then
		return;
	end;
	local ArmorChanger: table = {["Enabled"] = false};
	local Trim: table;
	local Color: table;
	local Effect: table;
	local Tier: table;
	local slotNames: {[number]: string} = {[0] = 'helmet', [1] = 'chestplate', [2] = 'boots'};
	local labels: {[string]: {string}} = {["Trim"] = {}, ["Color"] = {}, ["Effect"] = {}};
	local values: {[string]: {[string]: any}} = {["Trim"] = {}, ["Color"] = {}, ["Effect"] = {}};
	local added: {Instance} = {};

	local prettify: (text: string) -> string = function(text: string): string
		return (text:gsub('_', ' '):gsub('%a+', function(word: string): string
			return word:sub(1, 1):upper()..word:sub(2):lower();
		end));
	end;

	for _: number, source: table in {
		{["Into"] = 'Trim', ["Enum"] = bedwars.ArmorTrimType, ["Meta"] = bedwars.ArmorTrimMeta},
		{["Into"] = 'Color', ["Enum"] = bedwars.ArmorTrimColor},
		{["Into"] = 'Effect', ["Enum"] = bedwars.ArmorTrimEffectType, ["Meta"] = bedwars.ArmorTrimEffectMeta}
	} do
		for key: any, value: any in source.Enum do
			local meta: table? = source.Meta and source.Meta[value];
			local label: string = meta and meta.name or prettify(tostring(source.Meta and value or key));
			if values[source.Into][label] == nil then
				values[source.Into][label] = value;
				table.insert(labels[source.Into], label);
			end;
		end;
		table.sort(labels[source.Into]);
	end;

	local clearAdded: () -> () = function(): ()
		for _: number, object: Instance in added do
			if object.Parent then
				object:Destroy();
			end;
		end;
		table.clear(added);
	end;

	local applyTrim: () -> () = function(): ()
		clearAdded();
		local character: Model? = lplr.Character;
		if not ArmorChanger["Enabled"] or not character then
			return;
		end;
		local trimType: any = values.Trim[Trim["Value"]];
		local trimColor: any = values.Color[Color["Value"]];
		local effectType: any = values.Effect[Effect["Value"]];
		if not trimType or not trimColor or not effectType then
			return;
		end;
		local before: {[Instance]: boolean} = {};
		for _: number, object: Instance in character:GetDescendants() do
			before[object] = true;
		end;
		bedwars.ArmorTrimController:attachArmorTrimEffects(character, trimType, trimColor, Tier["Value"] - 1, effectType);
		local colorMeta: table? = bedwars.ArmorTrimColorMeta[trimColor];
		local worn: {[string]: boolean} = {};
		for _: any, item: any in store.inventory.inventory.armor or {} do
			local meta: table? = typeof(item) == 'table' and bedwars.ItemMeta[item.itemType] or nil;
			if meta and meta.armor and slotNames[meta.armor.slot] then
				worn[slotNames[meta.armor.slot]] = true;
			end;
		end;
		for _: number, piece: Instance in bedwars.ArmorTrimUtil.createArmorTrims(trimType, colorMeta and colorMeta.color or Color3.new(1, 1, 1), Tier["Value"] - 1) do
			local slot: string? = nil;
			for name: string in worn do
				if table.find(piece.Name:split('_'), name) then
					slot = name;
					break;
				end;
			end;
			if slot then
				piece:SetAttribute('VeloTrim', true);
				bedwars.AccessoryUtil:addAccessory(character, piece);
			else
				piece:Destroy();
			end;
		end;
		bedwars.WeldTable:weldCharacterAccessories(character);
		for _: number, object: Instance in character:GetDescendants() do
			if not before[object] then
				table.insert(added, object);
			end;
		end;
	end;

	local refresh: () -> () = function(): ()
		if ArmorChanger["Enabled"] then
			applyTrim();
		end;
	end;

	ArmorChanger = vape.Categories.Render:CreateModule({
		["Name"] = 'ArmorChanger',
		["Function"] = function(callback: boolean): ()
			if callback then
				ArmorChanger:Clean(lplr.CharacterAdded:Connect(function(): ()
					task.wait(1);
					applyTrim();
				end));
				ArmorChanger:Clean(clearAdded);
			end;
			applyTrim();
		end,
		["Tooltip"] = 'Puts an armor trim on yourself, only you can see it.'
	});
	Trim = ArmorChanger:CreateDropdown({
		["Name"] = 'Trim',
		["List"] = labels.Trim,
		["Function"] = refresh
	});
	Color = ArmorChanger:CreateDropdown({
		["Name"] = 'Color',
		["List"] = labels.Color,
		["Function"] = refresh
	});
	Effect = ArmorChanger:CreateDropdown({
		["Name"] = 'Effect',
		["List"] = labels.Effect,
		["Function"] = refresh
	});
	Tier = ArmorChanger:CreateSlider({
		["Name"] = 'Tier',
		["Min"] = 1,
		["Max"] = 7,
		["Default"] = 7,
		["Function"] = refresh,
		["Suffix"] = function(value: number): string
			local rank: table? = bedwars.ArmorTrimEffectRankMeta[value - 1];
			return rank and rank.tier and prettify(tostring(rank.tier)) or '';
		end,
		["Tooltip"] = 'Higher tiers use the fancier version of the effect.'
	});
end);

velo.run(function(): ()
	local Clouds: table = {["Enabled"] = false};
	local Scale: table;
	local CloudColor: table;
	local folder: Instance?;
	local folderWatch: RBXScriptConnection?;
	local reference: {[Instance]: table} = {};

	local restyle: (part: Instance) -> () = function(part: Instance): ()
		if not part:IsA('BasePart') then
			return;
		end;
		reference[part] = reference[part] or {["Size"] = part.Size, ["Color"] = part.Color, ["Transparency"] = part.Transparency};
		part.Size = reference[part].Size * (Scale["Value"] / 100);
		part.Color = Color3.fromHSV(CloudColor["Hue"], CloudColor["Sat"], CloudColor["Value"]);
		part.Transparency = 1 - CloudColor["Opacity"];
	end;

	local applyAll: () -> () = function(): ()
		if not Clouds["Enabled"] or not folder then
			return;
		end;
		for _: number, part: Instance in folder:GetChildren() do
			restyle(part);
		end;
	end;

	local bindFolder: (found: Instance?) -> () = function(found: Instance?): ()
		if folderWatch then
			folderWatch:Disconnect();
			folderWatch = nil;
		end;
		folder = found;
		if not found then
			return;
		end;
		folderWatch = found.ChildAdded:Connect(function(part: Instance): ()
			task.defer(function(): ()
				if Clouds["Enabled"] then
					restyle(part);
				end;
			end);
		end);
		applyAll();
	end;

	Clouds = vape.Categories.Render:CreateModule({
		["Name"] = 'Clouds',
		["Function"] = function(callback: boolean): ()
			if callback then
				Clouds:Clean(workspace.ChildAdded:Connect(function(child: Instance): ()
					if child.Name == 'Clouds' then
						bindFolder(child);
					end;
				end));
				bindFolder(workspace:FindFirstChild('Clouds'));
			else
				bindFolder(nil);
				for part: Instance, saved: table in reference do
					if part.Parent then
						part.Size = saved.Size;
						part.Color = saved.Color;
						part.Transparency = saved.Transparency;
					end;
				end;
				table.clear(reference);
			end;
		end,
		["Tooltip"] = 'Restyles the clouds around the map.'
	});
	Scale = Clouds:CreateSlider({
		["Name"] = 'Size',
		["Min"] = 5,
		["Max"] = 300,
		["Default"] = 100,
		["Suffix"] = '%',
		["Function"] = applyAll
	});
	CloudColor = Clouds:CreateColorSlider({
		["Name"] = 'Color',
		["DefaultSat"] = 0,
		["Darker"] = true,
		["Function"] = applyAll
	});
end);

velo.run(function(): ()
	local CustomClouds: table = {["Enabled"] = false};
	local Size: table;
	local Color: table;
	local Transparency: table;
	local Material: table;
	local original: {[BasePart]: table} = {};
	local materials: {string} = {};
	for _: number, material: EnumItem in Enum.Material:GetEnumItems() do
		table.insert(materials, material.Name);
	end;

	local style: (part: Instance) -> () = function(part: Instance): ()
		if not CustomClouds["Enabled"] or not part:IsA('BasePart') then
			return;
		end;
		original[part] = original[part] or {["Size"] = part.Size, ["Color"] = part.Color, ["Transparency"] = part.Transparency, ["Material"] = part.Material};
		part.Size = original[part].Size * (Size["Value"] / 100);
		part.Color = Color3.fromHSV(Color["Hue"], Color["Sat"], Color["Value"]);
		part.Transparency = Transparency["Value"] / 100;
		part.Material = Enum.Material[Material["Value"]];
	end;

	local styleAll: () -> () = function(): ()
		local folder: Instance? = workspace:FindFirstChild('Clouds');
		for _: number, part: Instance in (folder and folder:GetChildren() or {}) do
			style(part);
		end;
	end;

	local bindFolder: (folder: Instance) -> () = function(folder: Instance): ()
		CustomClouds:Clean(folder.ChildAdded:Connect(function(part: Instance): ()
			task.defer(style, part);
		end));
		styleAll();
	end;

	CustomClouds = vape.Categories.Velocity:CreateModule({
		["Name"] = 'CustomClouds',
		["Function"] = function(callback: boolean): ()
