			if options.Cosmetics["Enabled"] or options.Accessories["Enabled"] then
				FPSBoost:Clean(entitylib.Events.EntityAdded:Connect(added));
				FPSBoost:Clean(entitylib.Events.EntityRemoved:Connect(function(ent: table): ()
