end);

velo.run(function(): ()
	local NoTextures: table = {["Enabled"] = false};
	local Materials: table;
	local Decals: table;
	local Meshes: table;
	local scanBatch: number = 500;
	local reference: {[Instance]: {[string]: any}} = {};

	local remember: (object: Instance, property: string) -> () = function(object: Instance, property: string): ()
		local properties: {[string]: any} = reference[object] or {};
		reference[object] = properties;
		if properties[property] == nil then
			properties[property] = object[property];
		end;
	end;

	local strip: (object: Instance) -> () = function(object: Instance): ()
		if Decals["Enabled"] and object:IsA('Decal') then
			local parent: Instance? = object.Parent;
			if parent and parent:IsA('BasePart') and parent.Transparency > 0.5 then
				return;
			end;
			remember(object, 'Transparency');
			object.Transparency = 1;
		elseif Decals["Enabled"] and object:IsA('SurfaceAppearance') then
			remember(object, 'Parent');
			object.Parent = nil;
		elseif Meshes["Enabled"] and object:IsA('SpecialMesh') then
			remember(object, 'TextureId');
			object.TextureId = '';
		elseif object:IsA('BasePart') then
			if Meshes["Enabled"] and object:IsA('MeshPart') then
				remember(object, 'TextureID');
				object.TextureID = '';
			end;
			if Materials["Enabled"] then
				remember(object, 'Material');
				object.Material = Enum.Material.SmoothPlastic;
			end;
		end;
	end;

	local scan: () -> () = function(): ()
		for index: number, object: Instance in store.map:GetDescendants() do
			if not NoTextures["Enabled"] then
				return;
			end;
			strip(object);
			if index % scanBatch == 0 then
				task.wait();
			end;
		end;
	end;

	local restoreAll: () -> () = function(): ()
		for object: Instance, properties: {[string]: any} in reference do
			pcall(function(): ()
				for property: string, value: any in properties do
					object[property] = value;
				end;
			end);
		end;
		table.clear(reference);
	end;

	local refresh: () -> () = function(): ()
		if not NoTextures["Enabled"] then
			return;
		end;
		restoreAll();
		scan();
	end;

	NoTextures = vape.Categories.Render:CreateModule({
		["Name"] = 'NoTextures',
		["Function"] = function(callback: boolean): ()
			if not callback then
				restoreAll();
				return;
			end;
			repeat
				task.wait();
			until store.map or not NoTextures["Enabled"];
			if not NoTextures["Enabled"] then
				return;
			end;
			NoTextures:Clean(store.map.DescendantAdded:Connect(function(object: Instance): ()
				task.defer(strip, object);
			end));
			scan();
		end,
		["Tooltip"] = 'Removes textures and materials from the map.'
	});
	Materials = NoTextures:CreateToggle({
		["Name"] = 'Materials',
		["Default"] = true,
		["Function"] = refresh,
		["Tooltip"] = 'Flattens every part to smooth plastic.'
	});
	Decals = NoTextures:CreateToggle({
		["Name"] = 'Decals',
		["Default"] = true,
		["Function"] = refresh,
		["Tooltip"] = 'Hides decals, textures and PBR surfaces, but keeps the textures of see-through blocks.'
	});
	Meshes = NoTextures:CreateToggle({
		["Name"] = 'Meshes',
		["Default"] = true,
		["Function"] = refresh,
		["Tooltip"] = 'Clears textures off meshes.'
	});
end);

velo.run(function(): ()
	local unlockedCap: number = 9999;
	local cap: number? = getfpscap and getfpscap() or nil;
	vape.Legit:CreateModule({
		["Name"] = 'FPSUnlocker',
		["Function"] = function(callback: boolean): ()
			if cap then
				setfpscap(callback and unlockedCap or cap);
			elseif callback then
				setfpscap(unlockedCap);
				notif('FPSUnlocker', 'You have to restart ur game inorder to disable this.', 8, 'info');
			end;
		end
	});
end);


velo.run(function(): ()
	local BedAlarm: table = {["Enabled"] = false};
	local Highlight: table;
	local Pearls: table;
	local Range: table;
	local Volume: table;
	local pearlTypes: {string} = {'telepearl', 'boba_pearl', 'teleport_hat'};
	local alarmCooldown: number = 3.05;
	local scanInterval: number = 0.1;
	local nearDistance: number = 30;
	local flightStep: number = 0.05;
	local flightSteps: number = 100;
	local landingParams: RaycastParams = RaycastParams.new();
	landingParams.RespectCanCollide = true;

	local findBed: () -> BasePart? = function(): BasePart?
		for _: number, bed: BasePart in collectionService:GetTagged('bed') do
			if tonumber(bed:GetAttribute('TeamId')) == tonumber(lplr:GetAttribute('Team')) then
				return bed;
			end;
		end;
		return nil;
	end;

	BedAlarm = vape.Legit:CreateModule({
		["Name"] = 'BedAlarm',
		["Function"] = function(callback: boolean): ()
			if not callback then
				return;
			end;
			local highlighted: {[Model]: boolean} = {};
			BedAlarm:Clean(entitylib.Events.EntityRemoved:Connect(function(ent: table): ()
				highlighted[ent.Character] = nil;
			end));
			local quietUntil: number = 0;
			local nextScan: number = 0;
			local alarm: (bed: BasePart, intruders: {table}, message: string) -> () = function(bed: BasePart, intruders: {table}, message: string): ()
				quietUntil = os.clock() + alarmCooldown;
				for _: number, ent: table in (Highlight["Enabled"] and intruders or {}) do
					if ent.Player and not highlighted[ent.Character] then
						highlighted[ent.Character] = true;
						bedwars.BedAlarmController:addIntruderPlayerHighlight(ent.Player);
					end;
				end;
				bedwars.NotificationController:sendInfoNotification({["message"] = message});
				local near: boolean = (entitylib.character.RootPart.Position - bed.Position).Magnitude < nearDistance;
				bedwars.AudioManager:playAudio(near and bedwars.SoundList.BED_ALARM or bedwars.SoundList.BED_ALARM_TRIGGERED_FAR, {
					["volumeMultiplier"] = Volume["Value"],
					["position"] = near and bed.Position or nil,
					["rollOffMaxDistance"] = 100
				});
			end;

			local launched: table = bedwars.SyncEvents.ProjectileLaunched:connect(function(event: table): ()
				if not Pearls["Enabled"] or not table.find(pearlTypes, event.projectileType) or typeof(event.origin) ~= 'Vector3' or typeof(event.launchVelocity) ~= 'Vector3' then
					return;
				end;
				local thrower: table? = entitylib.getEntity(event.shooter);
				local bed: BasePart? = thrower and thrower.Targetable and entitylib.isAlive and findBed() or nil;
				if not bed or os.clock() < quietUntil then
					return;
				end;
				local meta: table? = bedwars.ProjectileMeta[event.projectileType];
				local gravity: number = meta and meta.gravitationalAcceleration or config.Gravity;
				local ignore: {Instance} = {event.shooter};
				for _: number, ent: table in entitylib.List do
					table.insert(ignore, ent.Character);
				end;
				landingParams.FilterDescendantsInstances = ignore;
				local landing: Vector3 = event.origin;
				for step: number = 1, flightSteps do
					local t: number = step * flightStep;
					local point: Vector3 = event.origin + event.launchVelocity * t + Vector3.new(0, -0.5 * gravity * t * t, 0);
					local hit: RaycastResult? = workspace:Raycast(landing, point - landing, landingParams);
					landing = hit and hit.Position or point;
					if hit then
						break;
					end;
				end;
				if (landing - bed.Position).Magnitude <= Range["Value"] then
					alarm(bed, {thrower}, '[Bed Alarm]: An intruder pearled to your bed!');
				end;
			end);
			BedAlarm:Clean(function(): ()
				launched:Destroy();
			end);

			BedAlarm:Clean(runService.Heartbeat:Connect(function(): ()
				local now: number = os.clock();
				if now < nextScan or now < quietUntil then
					return;
				end;
				nextScan = now + scanInterval;
				if vape.ThreadFix then
					setthreadidentity(8);
				end;
				local bed: BasePart? = entitylib.isAlive and findBed() or nil;
				if not bed then
					return;
				end;
				local intruders: {table} = entitylib.AllPosition({
					["Origin"] = bed.Position,
					["Range"] = Range["Value"],
					["Part"] = 'RootPart',
					["Players"] = true
				});
