				if attachment then
					attachment:Destroy();
				end;
			end;
			local velocities: {[string]: Vector3} = {};
			for _: number, part: Instance in character:GetDescendants() do
				if part:IsA('BasePart') then
					velocities[part.Name] = part.AssemblyLinearVelocity;
				end;
			end;
			character.Archivable = true;
			local ragdoll: Model = character:Clone();
			local humanoid: Humanoid? = ragdoll:FindFirstChildOfClass('Humanoid');
			if humanoid then
				humanoid.Health = 100;
			end;
			ragdoll.Parent = workspace;
			debrisService:AddItem(ragdoll, 30);
			character:Destroy();
			task.delay(0.01, function(): ()
				if humanoid then
					humanoid:ChangeState(Enum.HumanoidStateType.Dead);
				end;
				ragdoll:BreakJoints();
				task.delay(0.01, function(): ()
					for _: number, part: Instance in ragdoll:GetDescendants() do
						if part:IsA('BasePart') then
							local float: BodyForce = Instance.new('BodyForce');
							float.Force = Vector3.new(0, (workspace.Gravity - 10) * part:GetMass(), 0);
							float.Parent = part;
							part.CanCollide = true;
							part.AssemblyLinearVelocity = velocities[part.Name] or Vector3.zero;
						end;
					end;
