			if glow then
				glow:Destroy();
			end;
			local ground: Vector3 = character.PrimaryPart.Position - Vector3.new(0, 8, 0);
			local from: Vector3 = Vector3.new((math.random(1, 10) - 5) * 2, boltHeight, (math.random(1, 10) - 5) * 2);
			for height: number = boltHeight - boltStep, 0, -boltStep do
				local to: Vector3 = height == 0 and Vector3.zero or Vector3.new((math.random(1, 10) - 5) * 2, height, (math.random(1, 10) - 5) * 2);
				for _: number, layer: table in boltLayers do
					local segment: Part = Instance.new('Part');
					segment.Size = layer.Size;
					segment.Material = layer.Material;
					segment.Color = layer.Color or segment.Color;
					segment.Transparency = layer.Transparency or 0;
					segment.Anchored = true;
					segment.CanCollide = false;
