			local emitter: Part = Instance.new('Part');
			emitter.Transparency = 1;
			emitter.Anchored = true;
			emitter.Size = Vector3.zero;
			emitter.Position = ground;
			emitter.Parent = workspace;
			bedwars.QueryUtil:setQueryIgnored(emitter, true);
			local thunder: Sound = Instance.new('Sound');
			thunder.SoundId = 'rbxassetid://6993372814';
			thunder.Volume = 2;
			thunder.Pitch = 0.5 + math.random(1, 3) / 10;
			thunder.Parent = emitter;
			thunder.Ended:Once(function(): ()
				emitter:Destroy();
			end);
			thunder:Play();
		end,
		["Delete"] = function(_: any, _: any, character: Model): ()
			character:Destroy();
		end
	};

	local applied: boolean = false;

	local applyKillEffect: () -> () = function(): ()
		if Mode["Value"] ~= 'None' then
			applied = true;
			lplr:SetAttribute('KillEffectType', Mode["Value"] == 'Bedwars' and effectIds.Kill[List["Value"]] or 'Custom'..Mode["Value"]);
		elseif applied then
			applied = false;
			lplr:SetAttribute('KillEffectType', 'default');
		end;
	end;

	local dropUnsupported: () -> () = function(): ()
		if not KillEffect["Enabled"] then
			return;
		end;
		if BedBreak["Enabled"] and not firesignal then
			notif('Bed Break Effect', 'This executor can\'t trigger the game\'s bed break effect', 5);
			BedBreak:Toggle();
		end;
		if Win["Enabled"] and not getconnections then
			notif('WinEffect', 'This executor cannot trigger the game\'s win effect callbacks', 5);
			Win:Toggle();
		end;
	end;

	KillEffect = vape.Legit:CreateModule({
		["Name"] = 'Kill Effect',
		["Function"] = function(callback: boolean): ()
