				for name: string in customEffects do
					bedwars.KillEffectController.killEffects['Custom'..name] = nil;
				end;
				if applied then
					applied = false;
					lplr:SetAttribute('KillEffectType', 'default');
				end;
				return;
			end;
			for name: string, effect: (...any) -> () in customEffects do
				bedwars.KillEffectController.killEffects['Custom'..name] = {
					["new"] = function(): table
						return {
							["onKill"] = effect,
							["isPlayDefaultKillEffect"] = function(): boolean
								return false;
							end
						};
					end
				};
			end;
			KillEffect:Clean(lplr:GetAttributeChangedSignal('KillEffectType'):Connect(applyKillEffect));
			applyKillEffect();

			KillEffect:Clean(vapeEvents.BedwarsBedBreak.Event:Connect(function(data: table): ()
