					["player"] = data.player,
					["cframe"] = CFrame.new(data.bedBlockPosition * 3),
					["effectType"] = effectIds.BedBreak[BedBreakList["Value"]],
					["teamId"] = data.brokenBedTeam.id,
					["centerBedPosition"] = data.bedBlockPosition * 3
				});
			end));

			KillEffect:Clean(vapeEvents.MatchEndEvent.Event:Connect(function(): ()
				if not Win["Enabled"] or not getconnections then
					return;
				end;
				for _: number, connection: table in getconnections(bedwars.Client:Get('WinEffectTriggered').instance.OnClientEvent) do
					if connection.Function then
						connection.Function({["winEffectType"] = effectIds.Win[WinList["Value"]], ["winningPlayer"] = lplr});
					end;
				end;
			end));
			dropUnsupported();
		end,
		["Tooltip"] = 'Custom final kill, bed break and win effects'
	});

	local namesOf: (meta: table, ids: {[string]: string}) -> {string} = function(meta: table, ids: {[string]: string}): {string}
		local names: {string} = {};
		for id: string, entry: table in meta do
			table.insert(names, entry.name);
			ids[entry.name] = id;
		end;
		table.sort(names);
		return names;
	end;

	Mode = KillEffect:CreateDropdown({
		["Name"] = 'Mode',
		["List"] = {'Bedwars', 'Gravity', 'Lightning', 'Delete', 'None'},
		["Function"] = function(value: string): ()
			if List then
				List.Object.Visible = value == 'Bedwars';
			end;
			if KillEffect["Enabled"] then
				applyKillEffect();
			end;
		end
	});
	List = KillEffect:CreateDropdown({
		["Name"] = 'Bedwars',
		["List"] = namesOf(bedwars.KillEffectMeta, effectIds.Kill),
		["Function"] = function(): ()
			if KillEffect["Enabled"] then
				applyKillEffect();
			end;
		end,
		["Darker"] = true
	});
	BedBreak = KillEffect:CreateToggle({
		["Name"] = 'Bed Break Effect',
		["Function"] = function(callback: boolean): ()
			if BedBreakList then
				BedBreakList.Object.Visible = callback;
			end;
			if callback then
				dropUnsupported();
			end;
		end,
		["Tooltip"] = 'Plays the chosen bed break effect on every bed break'
	});
	BedBreakList = KillEffect:CreateDropdown({
		["Name"] = 'Bed Break',
		["List"] = namesOf(bedwars.BedBreakEffectMeta, effectIds.BedBreak),
		["Darker"] = true
	});
	BedBreakList.Object.Visible = BedBreak["Enabled"];
	Win = KillEffect:CreateToggle({
		["Name"] = 'Win Effect',
		["Function"] = function(callback: boolean): ()
			if WinList then
				WinList.Object.Visible = callback;
			end;
			if callback then
				dropUnsupported();
			end;
		end,
		["Tooltip"] = 'Plays the chosen clientside win effect when the match ends'
	});
	WinList = KillEffect:CreateDropdown({
		["Name"] = 'Win',
		["List"] = namesOf(bedwars.WinEffectMeta, effectIds.Win),
		["Darker"] = true
	});
	WinList.Object.Visible = Win["Enabled"];
end);

velo.run(function(): ()
	local CleanKit: table = {["Enabled"] = false};
	local oldSpawnOrb: ((...any) -> ...any)?;

	CleanKit = vape.Legit:CreateModule({
		["Name"] = 'Clean Kit',
		["Function"] = function(callback: boolean): ()
			if not callback then
				bedwars.WindWalkerController.spawnOrb = oldSpawnOrb;
				return;
			end;
			oldSpawnOrb = bedwars.WindWalkerController.spawnOrb;
			bedwars.WindWalkerController.spawnOrb = function(): () end;
			local effect: Instance? = lplr.PlayerGui:FindFirstChild('WindWalkerEffect', true);
			if effect then
				effect.Visible = false;
				return;
			end;
			local watcher: RBXScriptConnection;
			watcher = lplr.PlayerGui.DescendantAdded:Connect(function(object: Instance): ()
				if object.Name == 'WindWalkerEffect' then
					if vape.ThreadFix then
						setthreadidentity(8);
					end;
					watcher:Disconnect();
					object.Visible = false;
				end;
			end);
			CleanKit:Clean(watcher);
		end,
		["Tooltip"] = 'Removes zephyr status indicator'
	});
end);

velo.run(function(): ()
	local Crosshair: table = {["Enabled"] = false};
	local Preset: table;
	local Image: table;
	local BlockOverlay: table;
	local FillColor: table;
	local OutlineColor: table;
	local Thickness: table;
	local Animate: table;
	local AnimationTime: table;
	local overlayOptions: {table} = {};
	local images: table = bedwars.Images and bedwars.Images.ui;
	local originalImages: {string}?;
	local presets: {[string]: string} = images and {
		["PC"] = images.hud.viewmodel_crosshair,
		["Mobile"] = images.mobile_controls.mobile_crosshairs,
		["Turret"] = images.common.turret_crosshair,
		["Mouse lock"] = 'rbxasset://textures/MouseLockedCursor.png'
	} or {};
	local overlay: Part?;
	local overlayBox: SelectionBox?;
	local overlayTween: Tween?;
	local selected: BasePart?;

	local refreshCrosshair: () -> () = function(): ()
		if not images then
			return;
		end;
		local custom: boolean = Crosshair["Enabled"] and Preset["Value"] ~= 'Default';
		if custom and not originalImages then
			originalImages = {images.hud.viewmodel_crosshair, images.mobile_controls.mobile_crosshairs};
		end;
		if custom then
			local image: string = presets[Preset["Value"]] or (tonumber(Image["Value"]) and 'rbxassetid://'..Image["Value"] or Image["Value"]);
			images.hud.viewmodel_crosshair = image;
			images.mobile_controls.mobile_crosshairs = image;
		elseif originalImages then
			images.hud.viewmodel_crosshair = originalImages[1];
			images.mobile_controls.mobile_crosshairs = originalImages[2];
			originalImages = nil;
		end;
		if bedwars.ViewmodelController.crosshair then
			bedwars.ViewmodelController:hideCrosshair();
			bedwars.ViewmodelController:showCrosshair();
		end;
	end;

	local followSelection: (part: Instance) -> () = function(part: Instance): ()
		local box: SelectionBox? = overlay and part:IsA('BasePart') and part.Anchored and part.Transparency == 1 and part:FindFirstChildOfClass('SelectionBox');
		if not box then
			return;
		end;
		box.Visible = false;
		selected = part;
		if overlayTween then
			overlayTween:Cancel();
			overlayTween = nil;
		end;
		if Animate["Enabled"] and overlay.Parent == gameCamera then
			overlayTween = tweenService:Create(overlay, TweenInfo.new(AnimationTime["Value"], Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {["CFrame"] = part.CFrame, ["Size"] = part.Size});
			overlayTween:Play();
			return;
		end;
		overlay.CFrame = part.CFrame;
		overlay.Size = part.Size;
		overlay.Parent = gameCamera;
	end;

	local paintOverlay: () -> () = function(): ()
		if overlayBox then
			overlayBox.LineThickness = Thickness["Value"];
			overlayBox.Color3 = Color3.fromHSV(OutlineColor["Hue"], OutlineColor["Sat"], OutlineColor["Value"]);
			overlayBox.Transparency = 1 - OutlineColor["Opacity"];
			overlayBox.SurfaceColor3 = Color3.fromHSV(FillColor["Hue"], FillColor["Sat"], FillColor["Value"]);
			overlayBox.SurfaceTransparency = 1 - FillColor["Opacity"];
		end;
	end;

	Crosshair = vape.Legit:CreateModule({
		["Name"] = 'Crosshair',
		["Function"] = function(callback: boolean): ()
			refreshCrosshair();
			if callback and BlockOverlay["Enabled"] then
				overlay = Instance.new('Part');
				overlay.Size = Vector3.one * 3;
				overlay.Anchored = true;
				overlay.CanCollide = false;
				overlay.CanQuery = false;
				overlay.CanTouch = false;
				overlay.CastShadow = false;
				overlay.Transparency = 1;
				overlayBox = Instance.new('SelectionBox');
				overlayBox.Adornee = overlay;
				overlayBox.Parent = overlay;
				paintOverlay();
				bedwars.QueryUtil:setQueryIgnored(overlay, true);
				for _: number, child: Instance in workspace:GetChildren() do
					followSelection(child);
				end;
				Crosshair:Clean(workspace.ChildAdded:Connect(function(child: Instance): ()
					task.defer(followSelection, child);
				end));
				Crosshair:Clean(workspace.ChildRemoved:Connect(function(child: Instance): ()
					if child ~= selected then
						return;
					end;
					selected = nil;
					task.delay(0.06, function(): ()
						if selected or not overlay then
							return;
						end;
						if overlayTween then
							overlayTween:Cancel();
							overlayTween = nil;
						end;
						overlay.Parent = nil;
					end);
				end));
			elseif not callback then
				local box: SelectionBox? = selected and selected:FindFirstChildOfClass('SelectionBox');
				if box then
					box.Visible = true;
				end;
				selected = nil;
				if overlayTween then
					overlayTween:Cancel();
					overlayTween = nil;
				end;
				if overlay then
					overlay:Destroy();
					overlay, overlayBox = nil, nil;
				end;
			end;
		end,
		["Tooltip"] = 'Custom first person crosshair and block selection overlay.'
	});
	Preset = Crosshair:CreateDropdown({
		["Name"] = 'Preset',
		["List"] = {'Custom', 'PC', 'Mobile', 'Turret', 'Mouse lock', 'Default'},
		["Function"] = function(value: string): ()
			if Image then
				Image.Object.Visible = value == 'Custom';
			end;
			if Crosshair["Enabled"] then
				refreshCrosshair();
			end;
		end,
		["Tooltip"] = 'Pick one of the games own crosshairs, Custom uses the image id below, Default keeps the game crosshair'
	});
	Image = Crosshair:CreateTextBox({
		["Name"] = 'Image',
		["Placeholder"] = 'image id (roblox)',
		["Function"] = function(enter: boolean): ()
			if enter and Crosshair["Enabled"] then
				refreshCrosshair();
			end;
		end
	});
	BlockOverlay = Crosshair:CreateToggle({
		["Name"] = 'Block Overlay',
		["Function"] = function(callback: boolean): ()
			for _: number, option: table in overlayOptions do
				option.Object.Visible = callback;
			end;
			if Crosshair["Enabled"] then
				Crosshair:Toggle();
				Crosshair:Toggle();
			end;
		end,
		["Tooltip"] = 'Restyles the outline on the block you are aiming at'
	});
	FillColor = Crosshair:CreateColorSlider({
		["Name"] = 'Fill Color',
		["DefaultSat"] = 0,
		["DefaultOpacity"] = 0.25,
		["Darker"] = true,
		["Function"] = paintOverlay
	});
	OutlineColor = Crosshair:CreateColorSlider({
		["Name"] = 'Outline Color',
		["DefaultSat"] = 0,
		["Darker"] = true,
		["Function"] = paintOverlay
	});
	Thickness = Crosshair:CreateSlider({
		["Name"] = 'Thickness',
		["Min"] = 0.01,
		["Max"] = 0.2,
		["Default"] = 0.04,
		["Decimal"] = 100,
		["Darker"] = true,
		["Function"] = paintOverlay
	});
	Animate = Crosshair:CreateToggle({
		["Name"] = 'Animate',
		["Default"] = true,
		["Darker"] = true,
		["Tooltip"] = 'Glides the overlay onto the next block instead of snapping to it'
	});
	AnimationTime = Crosshair:CreateSlider({
		["Name"] = 'Animation time',
		["Min"] = 0.01,
		["Max"] = 0.5,
		["Default"] = 0.08,
		["Decimal"] = 100,
		["Suffix"] = 's',
		["Darker"] = true
	});
	overlayOptions = {FillColor, OutlineColor, Thickness, Animate, AnimationTime};
	for _: number, option: table in overlayOptions do
		option.Object.Visible = false;
	end;
end);

velo.run(function(): ()
	local DamageIndicator: table = {["Enabled"] = false};
	local FontOption: table;
	local ColorMode: table;
	local TextColor: table;
	local Size: table;
	local Anchor: table;
	local Stroke: table;
	local TextMode: table;
	local Messages: table;
	local spawnIndicator: (...any) -> ...any = bedwars.DamageIndicator;
	local indicatorSettings: any = debug.getupvalues(spawnIndicator)[2];
	indicatorSettings = type(indicatorSettings) == 'table' and indicatorSettings or {};
	local savedSettings: table = {};
	local savedFont: EnumItem?;
	local fontIndex: number?;
	for index: number, constant: any in debug.getconstants(spawnIndicator) do
		if typeof(constant) == 'EnumItem' and constant.EnumType == Enum.Font then
			fontIndex = index;
			break;
		end;
	end;
	local phrases: {string} = {'Pow!', 'Pop!', 'Hit!', 'Smack!', 'Bang!', 'Boom!', 'Whoop!', 'Damage!', '-9e9!', 'Whack!', 'Crash!', 'Slam!', 'Zap!', 'Snap!', 'Thump!'};
	local palette: {Color3} = {
		Color3.fromRGB(255, 0, 0), Color3.fromRGB(255, 127, 0), Color3.fromRGB(255, 255, 0), Color3.fromRGB(0, 255, 0),
		Color3.fromRGB(0, 0, 255), Color3.fromRGB(75, 0, 130), Color3.fromRGB(148, 0, 211)
	};
	local velocityColor: Color3 = Color3.fromRGB(127, 0, 255);
	local rainbowPeriod: number = 5;

	local applySettings: () -> () = function(): ()
		if not DamageIndicator["Enabled"] then
			return;
		end;
		indicatorSettings.strokeThickness = Stroke["Enabled"] and 1 or 0;
		indicatorSettings.textSize = Size["Value"];
		indicatorSettings.blowUpSize = Size["Value"];
		indicatorSettings.blowUpDuration = 0;
		indicatorSettings.blowUpCompleteDuration = 0;
		indicatorSettings.anchoredDuration = Anchor["Value"];
		indicatorSettings.baseColor = Color3.fromHSV(TextColor["Hue"], TextColor["Sat"], TextColor["Value"]);
		if fontIndex then
			debug.setconstant(spawnIndicator, fontIndex, Enum.Font[FontOption["Value"]]);
		end;
	end;

	DamageIndicator = vape.Legit:CreateModule({
		["Name"] = 'DamageIndicator',
		["Function"] = function(callback: boolean): ()
			if not callback then
				for key: string, value: any in savedSettings do
					indicatorSettings[key] = value;
				end;
				if fontIndex and savedFont then
					debug.setconstant(spawnIndicator, fontIndex, savedFont);
				end;
				return;
			end;
			savedSettings = table.clone(indicatorSettings);
			savedFont = fontIndex and debug.getconstant(spawnIndicator, fontIndex) or nil;
			applySettings();
			if ColorMode["Value"] == 'Custom' and TextMode["Value"] == 'Default' then
				return;
			end;
			local cycling: {[TextLabel]: number} = {};
			local spawned: number = 0;
			DamageIndicator:Clean(workspace.DescendantAdded:Connect(function(object: Instance): ()
				if object.Name ~= 'DamageIndicatorPart' then
					return;
				end;
				local label: TextLabel? = object:FindFirstChildWhichIsA('TextLabel', true);
				if not label then
					return;
				end;
				spawned += 1;
				if ColorMode["Value"] == 'Rainbow' then
					label.TextColor3 = Color3.fromHSV(tick() % rainbowPeriod / rainbowPeriod, 1, 1);
				elseif ColorMode["Value"] == 'Palette' then
					cycling[label] = spawned;
				elseif ColorMode["Value"] == 'Velocity' then
					label.TextColor3 = velocityColor;
				end;
				local pool: {string} = TextMode["Value"] == 'Custom' and Messages["ListEnabled"] or TextMode["Value"] == 'Phrases' and phrases or {};
				if TextMode["Value"] == 'Velocity' then
					label.Text = 'Velocity on top!';
				elseif #pool > 0 then
					label.Text = pool[math.random(1, #pool)];
				end;
			end));
			if ColorMode["Value"] == 'Palette' then
				DamageIndicator:Clean(runService.Heartbeat:Connect(function(): ()
					for label: TextLabel, index: number in cycling do
						if not label.Parent then
							cycling[label] = nil;
							continue;
						end;
						cycling[label] = index % #palette + 1;
						label.TextColor3 = palette[cycling[label]];
					end;
				end));
			end;
		end,
		["Tooltip"] = 'Customize the damage indicator'
	});

	local restart: () -> () = function(): ()
		if DamageIndicator["Enabled"] then
			DamageIndicator:Toggle();
			DamageIndicator:Toggle();
		end;
	end;

	local fonts: {string} = {'GothamBlack'};
	for _: number, font: EnumItem in Enum.Font:GetEnumItems() do
