		end;
	end;

	local attach: (model: Model) -> () = function(model: Model): ()
		if rig.Model == model then
			return;
		end;
		model:ScaleTo(1);
		local torso: Instance? = model:FindFirstChild('LowerTorso');
		local accessory: Accessory? = model:FindFirstChildWhichIsA('Accessory');
		local reference: BasePart? = accessory and accessory:FindFirstChild('Handle') or model:FindFirstChild('RightHand');
		rig.Model = model;
		rig.Wrist = model.RightHand.RightWrist.C1;
		rig.Offset = reference and model.HumanoidRootPart.CFrame:PointToObjectSpace(reference.Position);
