		{["Name"] = 'Depth', ["Min"] = 0, ["Max"] = 2, ["Default"] = 0.8},
		{["Name"] = 'Horizontal', ["Min"] = 0, ["Max"] = 2, ["Default"] = 0.8},
		{["Name"] = 'Vertical', ["Min"] = -0.2, ["Max"] = 2, ["Default"] = -0.2}
	} do
		slider.Decimal = 10;
		slider.Function = function(): ()
			if Viewmodel["Enabled"] then
				applyOffsets(true);
			end;
		end;
		local created: table = Viewmodel:CreateSlider(slider);
		if slider.Name == 'Depth' then
			Depth = created;
		elseif slider.Name == 'Horizontal' then
			Horizontal = created;
		else
			Vertical = created;
		end;
	end;
	Size = Viewmodel:CreateSlider({
		["Name"] = 'Size',
		["Min"] = 0.1,
		["Max"] = 2,
		["Default"] = 1,
		["Decimal"] = 10,
		["Function"] = resize
	});
	for _: number, axis: string in {'X', 'Y', 'Z'} do
		table.insert(Rotations, Viewmodel:CreateSlider({
			["Name"] = 'Rotation '..axis,
			["Min"] = 0,
			["Max"] = 360,
			["Function"] = resize
		}));
	end;
	NoBob = Viewmodel:CreateToggle({
		["Name"] = 'No Bobbing',
		["Default"] = true,
		["Function"] = function(): ()
			if Viewmodel["Enabled"] then
				Viewmodel:Toggle();
				Viewmodel:Toggle();
			end;
		end
	});
	ColorMode = Viewmodel:CreateDropdown({
		["Name"] = 'Color Mode',
		["List"] = {'None', 'Highlight', 'Normal', 'Classic'},
		["Function"] = function(mode: string): ()
			if FillColor and OutlineColor and Material then
				FillColor.Object.Visible = mode ~= 'None';
				OutlineColor.Object.Visible = mode == 'Highlight' or mode == 'Normal';
				Material.Object.Visible = mode == 'Normal' or mode == 'Classic';
