		end,
		["Tooltip"] = 'Highlight: outlines the held item\nNormal: highlights the whole viewmodel\nClassic: recolors the viewmodel parts'
	});
	FillColor = Viewmodel:CreateColorSlider({
		["Name"] = 'Color',
		["DefaultSat"] = 0,
		["DefaultOpacity"] = 0.5,
		["Darker"] = true,
		["Visible"] = false,
		["Function"] = repaint
	});
	OutlineColor = Viewmodel:CreateColorSlider({
		["Name"] = 'Outline Color',
		["DefaultValue"] = 0,
		["DefaultOpacity"] = 0,
		["Darker"] = true,
		["Visible"] = false,
		["Function"] = repaint
	});
	local materials: {string} = {};
	for _: number, material: EnumItem in Enum.Material:GetEnumItems() do
		table.insert(materials, material.Name);
	end;
	Material = Viewmodel:CreateDropdown({
		["Name"] = 'Material',
		["List"] = materials,
		["Default"] = 'Neon',
