					local seconds: number = math.floor(remaining);
					if seconds <= 0 then
						entry.Frame:Destroy();
						shown[effect] = nil;
						continue;
					end;
					local percent: number = remaining / entry.Duration;
					local ringColor: Color3 = percent > 0.5 and accentColor or percent > 0.25 and warnColor or dangerColor;
					local theta: number = math.min(percent, 1) * 360;
					entry.Arcs.Left.Gradient.Rotation = math.clamp(theta, 180, 360);
					entry.Arcs.Right.Gradient.Rotation = math.clamp(theta, 0, 180);
					if ringColor ~= entry.Color then
						entry.Color = ringColor;
						entry.Arcs.Left.Stroke.Color = ringColor;
						entry.Arcs.Right.Stroke.Color = ringColor;
						entry.Time.TextColor3 = ringColor;
					end;
					if seconds ~= entry.Seconds then
						entry.Seconds = seconds;
						entry.Time.Text = string.format('%02d:%02d', seconds // 60, seconds % 60);
						entry.TimeShadow.Text = entry.Time.Text;
					end;
				end;
			end));
			PotionStatus:Clean(function(): ()
				for _: string, entry: table in shown do
					entry.Frame:Destroy();
				end;
