velo.run(function(): ()
	local Shaders: table = {["Enabled"] = false};
	local Mode: table = {["Value"] = 'Realistic'};
	local Lighting: table = {["Enabled"] = true};
	local Terrain: table = {["Enabled"] = true};
	local presets: {[string]: table} = {
		["Realistic"] = {["Brightness"] = 1, ["EnvironmentDiffuseScale"] = 0.2, ["EnvironmentSpecularScale"] = 0.82, ["Blur"] = 3.921, ["Saturation"] = 0.092, ["Cover"] = 0.4, ["Effects"] = true},
		["Clean"] = {["Brightness"] = 1, ["EnvironmentDiffuseScale"] = 0.2, ["EnvironmentSpecularScale"] = 0.8, ["Cover"] = 0.4, ["Effects"] = false}
	};
	local changed: {table} = {};

	local assign: (object: Instance, property: string, value: any) -> () = function(object: Instance, property: string, value: any): ()
		table.insert(changed, {["Object"] = object, ["Property"] = property, ["Original"] = object[property], ["Applied"] = value});
		object[property] = value;
	end;

	local reapply: () -> () = function(): ()
		if Shaders["Enabled"] then
			Shaders:Toggle();
			Shaders:Toggle();
		end;
	end;

	Shaders = vape.Categories.Velocity:CreateModule({
		["Name"] = 'Shaders',
		["Function"] = function(callback: boolean): ()
			if not callback then
				for index: number = #changed, 1, -1 do
					local entry: table = changed[index];
					if entry.Object[entry.Property] == entry.Applied then
						entry.Object[entry.Property] = entry.Original;
					end;
				end;
				table.clear(changed);
				return;
			end;
			local preset: table = presets[Mode["Value"]];
			if Lighting["Enabled"] then
				for _: number, object: Instance in lightingService:GetChildren() do
					if object:IsA('PostEffect') then
						assign(object, 'Enabled', false);
					elseif object:IsA('Sky') or object:IsA('Atmosphere') then
						assign(object, 'Parent', nil);
					end;
				end;
				local gameClouds: Clouds? = workspace.Terrain:FindFirstChildOfClass('Clouds');
				if gameClouds then
					assign(gameClouds, 'Parent', nil);
				end;
				for _: number, property: string in {'Brightness', 'EnvironmentDiffuseScale', 'EnvironmentSpecularScale'} do
					assign(lightingService, property, preset[property]);
				end;
				if preset.Effects then
					local blur: BlurEffect = Instance.new('BlurEffect');
					blur.Size = preset.Blur;
					local colorCorrection: ColorCorrectionEffect = Instance.new('ColorCorrectionEffect');
					colorCorrection.Saturation = preset.Saturation;
					for _: number, effect: Instance in {blur, colorCorrection, Instance.new('SunRaysEffect'), Instance.new('Sky'), Instance.new('Atmosphere')} do
						effect.Parent = lightingService;
						Shaders:Clean(effect);
					end;
				end;
				local clouds: Clouds = Instance.new('Clouds');
				clouds.Cover = preset.Cover;
				clouds.Parent = workspace.Terrain;
				Shaders:Clean(clouds);
			end;
			if Terrain["Enabled"] then
				assign(workspace.Terrain, 'WaterTransparency', 1);
				assign(workspace.Terrain, 'WaterReflectance', 1);
			end;
		end,
		["ExtraText"] = function(): string
			return Mode["Value"];
		end,
		["Tooltip"] = 'Makes the game\'s shaders better.'
	});
	Mode = Shaders:CreateDropdown({
		["Name"] = 'Mode',
		["List"] = {'Realistic', 'Clean'},
		["Default"] = 'Realistic',
		["Function"] = reapply,
		["Tooltip"] = 'Mode to render the shaders.'
	});
	Lighting = Shaders:CreateToggle({
		["Name"] = 'Lighting',
		["Default"] = true,
		["Function"] = reapply,
		["Tooltip"] = 'Applies changes to the lighting.'
	});
	Terrain = Shaders:CreateToggle({
		["Name"] = 'Terrain',
		["Default"] = true,
		["Function"] = reapply,
		["Tooltip"] = 'Applies changes to the terrain.'
	});
end);

