		end;
		watcher = character.DescendantAdded:Connect(function(object: Instance): ()
			if object.Name == 'Nametag' and object.Parent and object.Parent.Name == 'Head' then
				task.defer(object.Destroy, object);
			end;
		end);
	end;

	NoNameTag = vape.Categories.Velocity:CreateModule({
		["Name"] = 'NoNameTag',
		["Function"] = function(callback: boolean): ()
			if not callback then
				return;
			end;
			if lplr.Character then
				strip(lplr.Character);
			end;
			NoNameTag:Clean(lplr.CharacterAdded:Connect(strip));
			NoNameTag:Clean(function(): ()
				if watcher then
					watcher:Disconnect();
					watcher = nil;
				end;
			end);
		end,
		["Tooltip"] = 'Removes your NameTag.'
	});
end);

