		local timer: Instance? = matchBar and matchBar:FindFirstChild('5');
		if not (timer and timer:IsA('TextLabel')) then
			timer, matchBar = nil, nil;
			for _: number, object: Instance in (topBarApp and topBarApp:GetDescendants() or {}) do
