		create('UICorner', {["Parent"] = header});
		create('TextLabel', {["BackgroundTransparency"] = 1, ["Position"] = UDim2.fromScale(0.199, 0.356), ["Size"] = UDim2.fromOffset(139, 13), ["Font"] = Enum.Font.GothamBlack, ["Text"] = 'Velocity', ["TextColor3"] = Color3.new(1, 1, 1), ["TextScaled"] = true, ["TextXAlignment"] = Enum.TextXAlignment.Left, ["Parent"] = header});
		create('ImageLabel', {["BackgroundTransparency"] = 1, ["Position"] = UDim2.fromScale(0.0625, 0.267), ["Size"] = UDim2.fromOffset(20, 20), ["Image"] = 'rbxassetid://14314898887', ["Parent"] = header});
		local headerGlass: Frame = create('Frame', {["BackgroundTransparency"] = 1, ["Position"] = UDim2.fromScale(0.03125, 0.133), ["Size"] = UDim2.fromOffset(240, 33), ["Parent"] = header});

