			create('TextLabel', {["BackgroundTransparency"] = 1, ["Position"] = UDim2.fromScale(entry[1] > 0.2 and 0.111 or 0.0625, entry[1]), ["Size"] = UDim2.fromOffset(186, entry[2]), ["Font"] = entry[3], ["Text"] = entry[4], ["TextColor3"] = entry[5], ["TextScaled"] = true, ["TextXAlignment"] = Enum.TextXAlignment.Left, ["Parent"] = info});
		end;
		for _: number, dot: table in {{0.498, Color3.fromRGB(0, 255, 140)}, {0.815, Color3.fromRGB(255, 33, 33)}} do
			local marker: Frame = create('Frame', {["BackgroundColor3"] = dot[2], ["Position"] = UDim2.new(0, 17, dot[1], 0), ["Size"] = UDim2.fromOffset(5, 5), ["Parent"] = info});
			create('UICorner', {["CornerRadius"] = UDim.new(1, 0), ["Parent"] = marker});
		end;
		local timeLabel: TextLabel = create('TextLabel', {["BackgroundTransparency"] = 1, ["Position"] = UDim2.fromScale(0.0625, 0.329), ["Size"] = UDim2.fromOffset(186, 19), ["Font"] = Enum.Font.GothamBlack, ["Text"] = timer and timer.ContentText or '', ["TextColor3"] = Color3.new(1, 1, 1), ["TextScaled"] = true, ["TextXAlignment"] = Enum.TextXAlignment.Left, ["Parent"] = info});
		local deathLabel: TextLabel = create('TextLabel', {["BackgroundTransparency"] = 1, ["Position"] = UDim2.fromScale(0.0625, 0.646), ["Size"] = UDim2.fromOffset(186, 19), ["Font"] = Enum.Font.GothamBlack, ["Text"] = '0', ["TextColor3"] = Color3.new(1, 1, 1), ["TextScaled"] = true, ["TextXAlignment"] = Enum.TextXAlignment.Left, ["Parent"] = info});
		local infoGlass: Frame = create('Frame', {["BackgroundTransparency"] = 1, ["Position"] = UDim2.fromScale(0.03125, 0.045), ["Size"] = UDim2.fromOffset(241, 120), ["Parent"] = info});

		if timer then
			Stats:Clean(timer:GetPropertyChangedSignal('Text'):Connect(function(): ()
				timeLabel.Text = timer.ContentText;
			end));
		else
			Stats:Clean(runService.Heartbeat:Connect(function(): ()
				local elapsed: number = math.floor(tick() - started);
				local text: string = string.format('%d:%02d', elapsed // 60, elapsed % 60);
				if timeLabel.Text ~= text then
					timeLabel.Text = text;
