		for _: number, frame: Frame in {headerGlass, infoGlass} do
			table.insert(panels, {["Frame"] = frame, ["Part"] = create('Part', {["Anchored"] = true, ["CanCollide"] = false, ["CanQuery"] = false, ["CanTouch"] = false, ["CastShadow"] = false, ["Material"] = Enum.Material.Glass, ["Transparency"] = 0.98, ["BrickColor"] = glassColor, ["Parent"] = glassFolder})});
		end;
		Stats:Clean(runService.RenderStepped:Connect(function(): ()
			for _: number, panel: table in panels do
				local frame: GuiObject = panel.Frame;
				local depth: number = 1 - 0.05 * frame.ZIndex;
				local middle: Vector2 = frame.AbsolutePosition + frame.AbsoluteSize / 2;
				local center: Vector3 = gameCamera:ScreenPointToRay(middle.X, middle.Y, depth).Origin;
				if center.X ~= center.X then
					continue;
				end;
				local right: Vector3 = gameCamera:ScreenPointToRay(middle.X + frame.AbsoluteSize.X / 2, middle.Y, depth).Origin - center;
				local down: Vector3 = gameCamera:ScreenPointToRay(middle.X, middle.Y + frame.AbsoluteSize.Y / 2, depth).Origin - center;
				local rotation: number = 0;
				local ancestor: Instance? = frame;
				while ancestor and ancestor:IsA('GuiObject') do
					rotation += ancestor.Rotation;
					ancestor = ancestor.Parent;
				end;
				panel.Part.Size = Vector3.new(right.Magnitude * 2, down.Magnitude * 2, 0.001);
				panel.Part.CFrame = CFrame.fromMatrix(center, right.Unit, -down.Unit) * CFrame.Angles(0, 0, -math.rad(rotation));
			end;
		end));
	end;

	Stats = vape.Categories.Velocity:CreateModule({
		["Name"] = 'Stats',
		["Function"] = function(callback: boolean): ()
			if not callback then
				return;
			end;
			if store.matchState ~= 0 then
				show();
				return;
			end;
			notif('Velocity', 'Waiting for the game to load.', 5, 'warning');
