	for _: number, name: string in {'FatCat', 'Simply', 'VioletsDreams', 'Enlightened', 'Onyx', 'Fury', 'Wichtiger', 'Makima', 'Marin-Kitsawaba', 'Prime', 'Vile', 'Devourer', 'Acidic', 'Moon4Real', 'Nebula'} do
