	end;
	local imports: {[number]: Instance} = {};
	local activePack: table = packs.Velocity;
	local activeLookup: {[string]: table} = {};
	local changed: {table} = {};
	local created: {Instance} = {};

	local conceal: (root: Instance, keep: Instance?) -> () = function(root: Instance, keep: Instance?): ()
		for _: number, part: Instance in root:GetDescendants() do
			if part:IsA('BasePart') and part ~= keep then
				table.insert(changed, {["Object"] = part, ["Property"] = 'Transparency', ["Original"] = part.Transparency});
				part.Transparency = 1;
			end;
		end;
	end;

	local attach: (source: BasePart, handle: BasePart, placement: CFrame) -> () = function(source: BasePart, handle: BasePart, placement: CFrame): ()
		local model: BasePart = source:Clone();
		model.Anchored = false;
		model.CanCollide = false;
		model.CFrame = handle.CFrame * placement;
		model.Parent = handle.Parent;
		local weld: WeldConstraint = Instance.new('WeldConstraint');
		weld.Part0 = model;
		weld.Part1 = handle;
		weld.Parent = model;
		table.insert(created, model);
	end;

	local dressModel: (tool: Instance) -> () = function(tool: Instance): ()
		local pack: table = activePack;
		local item: table? = activeLookup[tool.Name];
		local handle: Instance? = item and tool:IsA('Accessory') and tool:WaitForChild('Handle', 5);
		if not handle or not TexturePack["Enabled"] then
			return;
		end;
		local cut: CFrame = CFrame.Angles(math.rad(item.Cut[1]), math.rad(item.Cut[2]), math.rad(item.Cut[3]));
		conceal(tool, nil);
		attach(item.Model, handle, cut * CFrame.Angles(0, math.rad(pack.Turn), 0));
		local held: Instance? = lplr.Character and lplr.Character:WaitForChild(tool.Name, 5);
		local heldHandle: Instance? = held and held:FindFirstChild('Handle');
		if not heldHandle or not TexturePack["Enabled"] then
			return;
		end;
		if pack.KeepHandle then
			conceal(held, heldHandle);
			return;
		end;
		conceal(held, nil);
		attach(item.Model, heldHandle, cut * CFrame.Angles(0, math.rad(pack.CharacterTurn), 0) * CFrame.new(item.Shift or pack.Shift or Vector3.zero));
	end;

	local dressAnimated: (tool: Instance) -> () = function(tool: Instance): ()
		local handle: Instance? = tool:IsA('Accessory') and tool.Name:lower():find('sword') and tool:FindFirstChild('Handle');
		if not handle then
			return;
		end;
		for property: string, value: any in {["Material"] = Enum.Material.ForceField, ["MeshId"] = 'rbxassetid://13471207377', ["BrickColor"] = BrickColor.new('Hot pink')} do
			table.insert(changed, {["Object"] = handle, ["Property"] = property, ["Original"] = handle[property]});
			handle[property] = value;
		end;
		for _: number, fill: Color3 in {Color3.fromRGB(221, 193, 255), Color3.fromHSV(AnimatedColor["Hue"], AnimatedColor["Sat"], AnimatedColor["Value"])} do
			local glow: Highlight = Instance.new('Highlight');
			glow.Adornee = handle;
			glow.FillTransparency = 0.5;
			glow.FillColor = fill;
			glow.OutlineTransparency = 0.2;
			glow.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop;
			glow.Parent = handle;
			table.insert(created, glow);
		end;
	end;

	local reapply: () -> () = function(): ()
		if TexturePack["Enabled"] then
			TexturePack:Toggle();
			TexturePack:Toggle();
		end;
	end;

	TexturePack = vape.Categories.Velocity:CreateModule({
		["Name"] = 'TexturePack',
		["Function"] = function(callback: boolean): ()
			if not callback then
				for index: number = #changed, 1, -1 do
					local entry: table = changed[index];
					if entry.Object.Parent then
						entry.Object[entry.Property] = entry.Original;
					end;
				end;
				for _: number, object: Instance in created do
					object:Destroy();
				end;
				table.clear(changed);
				table.clear(created);
				return;
			end;
			local url: string? = scriptPacks[Mode["Value"]];
			TexturePack:Clean(task.spawn(function(): ()
				if url then
					local source: string = game:HttpGet(url, true);
					for asset: string in source:gmatch('GetObjects%(%s*["\']rbxassetid://(%d+)') do
						if #game:GetObjects('rbxassetid://'..asset) == 0 then
							notif('TexturePack', Mode["Value"]..' uses asset '..asset..' which is no longer available.', 10, 'alert');
							return;
						end;
					end;
					local chunk: (() -> ())?, problem: string? = loadstring(source);
					if not chunk then
						notif('TexturePack', 'Failed to load '..Mode["Value"]..': '..tostring(problem), 10, 'alert');
						return;
					end;
					chunk();
					return;
				end;
				local viewmodel: Instance? = gameCamera:WaitForChild('Viewmodel', 10);
				if not viewmodel then
					return;
				end;
				local pack: table? = packs[Mode["Value"]];
				if pack then
					local import: Instance? = imports[pack.Asset] or game:GetObjects('rbxassetid://'..pack.Asset)[1];
					if not import then
						notif('TexturePack', 'Could not download the '..Mode["Value"]..' pack.', 10, 'alert');
						return;
					end;
					imports[pack.Asset] = import;
					activePack = pack;
					table.clear(activeLookup);
					for _: number, child: Instance in (pack.FromChildren and import:GetChildren() or {}) do
						activeLookup[child.Name] = {["Model"] = child, ["Cut"] = pack.FromChildren};
					end;
					for _: number, entry: table in pack.Items do
						local model: Instance? = import:FindFirstChild(entry[2]);
						if model then
							activeLookup[entry[1]] = {["Model"] = model, ["Cut"] = entry[3], ["Shift"] = entry[4]};
						end;
					end;
				end;
				local dress: (tool: Instance) -> () = pack and dressModel or dressAnimated;
				TexturePack:Clean(viewmodel.ChildAdded:Connect(dress));
				for _: number, tool: Instance in viewmodel:GetChildren() do
					task.spawn(dress, tool);
				end;
			end));
		end,
		["ExtraText"] = function(): string
			return Mode["Value"];
		end,
		["Tooltip"] = 'Customizes the texture pack. Script packs (Snoopy/qwertyui) stay applied until you rejoin.'
	});
	Mode = TexturePack:CreateDropdown({
		["Name"] = 'Mode',
		["List"] = {'Velocity', 'FirstPack', 'SecondPack', 'ThirdPack', 'FourthPack', 'FifthPack', 'SixthPack', 'SeventhPack', 'EighthPack', 'EgirlPack', 'CottonCandy', 'Pack512x', 'Pack1056x', 'PrivatePack', 'Aquarium', 'Ocean', 'Animated', 'DemonSlayer', 'Glizzy', 'FatCat', 'Simply', 'VioletsDreams', 'Enlightened', 'Onyx', 'Fury', 'Wichtiger', 'Makima', 'Marin-Kitsawaba', 'Prime', 'Vile', 'Devourer', 'Acidic', 'Moon4Real', 'Nebula', 'Lunar'},
		["Default"] = 'Velocity',
		["Function"] = reapply,
		["Tooltip"] = 'Mode to render the texture pack, credits to Snoopy and CatVape.'
	});
	AnimatedColor = TexturePack:CreateColorSlider({
		["Name"] = 'Animated Color',
		["Function"] = function(): ()
			if Mode["Value"] == 'Animated' then
				reapply();
			end;
		end,
		["Tooltip"] = 'Color of the Animated texture pack.'
	});
end);

velo.run(function(): ()
	local BedDefense: table;
	local BedMode: table = {["Value"] = 'Nearest'};
	local View: table = {["Value"] = 'All'};
	local MaxLayers: table = {["Value"] = 6};
	local ShowBed: table = {["Enabled"] = true};
	local AutoRotate: table = {["Enabled"] = true};
	local RotateSpeed: table = {["Value"] = 20, ["Object"] = {}};
	local Transparency: table;
	local loopRate: number = 0.1;
	local rescanRate: number = 0.5;
	local nearRange: number = 30;
	local zoomRange: Vector2 = Vector2.new(0.35, 3);
	local layerFolders: {Folder} = {};
	local layerButtons: {[string]: TextButton} = {};
	local tracked: {[Instance]: number} = {};
	local orbit: table = {["Yaw"] = 0, ["Pitch"] = math.rad(28), ["Radius"] = 12, ["Center"] = Vector3.zero, ["Zoom"] = 1};
	local drag: table = {["Input"] = nil, ["Last"] = Vector3.zero, ["Touches"] = {}, ["Pinch"] = nil};
	local current: BasePart?, picked: BasePart?, bedClone: Instance?;
	local pending: boolean, layerCount: number, accent: Color3? = false, 0, nil;

	local holder: Frame = Instance.new('Frame');
	holder.BackgroundColor3 = color.Dark(uipallet.Main, 0.1);
	holder.ClipsDescendants = true;
	holder.Size = UDim2.fromOffset(240, 246);
	Instance.new('UICorner').Parent = holder;
	local bedLabel: TextLabel = Instance.new('TextLabel');
	bedLabel.BackgroundTransparency = 1;
	bedLabel.FontFace = uipallet.Font;
	bedLabel.Position = UDim2.fromOffset(32, 0);
	bedLabel.Size = UDim2.new(1, -64, 0, 32);
	bedLabel.TextSize = 13;
	bedLabel.TextStrokeTransparency = 0.7;
	bedLabel.TextTruncate = Enum.TextTruncate.AtEnd;
	bedLabel.Parent = holder;
	local viewport: ViewportFrame = Instance.new('ViewportFrame');
	viewport.Ambient = Color3.fromRGB(170, 170, 170);
	viewport.BackgroundTransparency = 1;
	viewport.LightColor = Color3.new(1, 1, 1);
	viewport.LightDirection = Vector3.new(-0.4, -1, -0.3);
	viewport.Position = UDim2.fromOffset(0, 33);
	viewport.Size = UDim2.new(1, 0, 0, 176);
	viewport.Parent = holder;
	local viewCamera: Camera = Instance.new('Camera');
	viewCamera.FieldOfView = 40;
	viewCamera.Parent = viewport;
	viewport.CurrentCamera = viewCamera;
	local emptyLabel: TextLabel = bedLabel:Clone();
	emptyLabel.Position = UDim2.fromOffset(0, 186);
	emptyLabel.Size = UDim2.new(1, 0, 0, 20);
	emptyLabel.TextSize = 12;
	emptyLabel.ZIndex = 2;
	emptyLabel.Parent = holder;
	local buttonRow: Frame = Instance.new('Frame');
	buttonRow.BackgroundTransparency = 1;
	buttonRow.Position = UDim2.fromOffset(4, 214);
	buttonRow.Size = UDim2.new(1, -8, 0, 26);
	buttonRow.Parent = holder;
	local rowLayout: UIListLayout = Instance.new('UIListLayout');
	rowLayout.FillDirection = Enum.FillDirection.Horizontal;
	rowLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center;
	rowLayout.Padding = UDim.new(0, 4);
	rowLayout.SortOrder = Enum.SortOrder.LayoutOrder;
	rowLayout.Parent = buttonRow;
	for _: number, offset: number in {32, 209} do
		local divider: Frame = Instance.new('Frame');
		divider.BackgroundColor3 = color.Light(uipallet.Main, 0.04);
		divider.BorderSizePixel = 0;
		divider.Position = UDim2.fromOffset(0, offset);
		divider.Size = UDim2.new(1, 0, 0, 1);
		divider.Parent = holder;
	end;

	local enemyBeds: () -> {BasePart} = function(): {BasePart}
		local beds: {BasePart} = {};
		local team: string = tostring(lplr:GetAttribute('Team'));
		for _: number, bed: Instance in collectionService:GetTagged('bed') do
			if bed:IsA('BasePart') and bed:IsDescendantOf(workspace) and tostring(bed:GetAttribute('TeamId')) ~= team then
				table.insert(beds, bed);
			end;
		end;
		table.sort(beds, function(a: BasePart, b: BasePart): boolean
			return (tonumber(a:GetAttribute('TeamId')) or 0) < (tonumber(b:GetAttribute('TeamId')) or 0);
		end);
		return beds;
	end;

	local targetBed: () -> BasePart? = function(): BasePart?
		local beds: {BasePart} = enemyBeds();
		if BedMode["Value"] == 'Manual' then
			return picked and picked.Parent and picked or beds[1];
		end;
		local eye: CFrame = gameCamera.CFrame;
		local origin: Vector3 = entitylib.isAlive and entitylib.character.RootPart.Position or eye.Position;
		local best: BasePart?, bestScore: number = nil, math.huge;
		for _: number, bed: BasePart in beds do
			local score: number = BedMode["Value"] == 'Crosshair' and -eye.LookVector:Dot((bed.Position - eye.Position).Unit) or (bed.Position - origin).Magnitude;
			if score < bestScore then
				best, bestScore = bed, score;
			end;
		end;
		return best;
	end;

	local scanLayers: (bed: BasePart) -> {{Instance}} = function(bed: BasePart): {{Instance}}
		local depth: {[Vector3]: number} = {};
		local queue: {Vector3} = {};
		local layers: {{Instance}} = {};
		for _: number, cell: Vector3 in {roundPos(bed.Position), roundPos(bed.CFrame * Vector3.new(0, 0, 3))} do
			depth[cell] = 0;
			table.insert(queue, cell);
		end;
		local index: number = 1;
		while queue[index] do
			local cell: Vector3 = queue[index];
			local level: number = depth[cell];
			index += 1;
			if level >= MaxLayers["Value"] then
				continue;
			end;
			for _: number, side: Vector3 in sides do
				local neighbour: Vector3 = cell + side;
				if depth[neighbour] == nil then
					local block: Instance? = getPlacedBlock(neighbour);
					depth[neighbour] = -1;
					if block and block ~= bed and block.Name ~= 'bed' and not block:GetAttribute('NoBreak') then
						depth[neighbour] = level + 1;
						layers[level + 1] = layers[level + 1] or {};
						table.insert(layers[level + 1], block);
						table.insert(queue, neighbour);
					end;
				end;
			end;
		end;
		return layers;
	end;

	local placeCamera: () -> () = function(): ()
		local distance: number = orbit.Radius / math.tan(math.rad(viewCamera.FieldOfView / 2)) * 1.15 * orbit.Zoom;
		viewCamera.CFrame = CFrame.new(orbit.Center) * CFrame.Angles(0, orbit.Yaw, 0) * CFrame.Angles(-orbit.Pitch, 0, 0) * CFrame.new(0, 0, distance);
	end;

	local selectedLayer: () -> number? = function(): number?
		local selected: number? = tonumber(View["Value"]:match('%d+'));
		return selected and selected <= layerCount and selected or nil;
	end;

	local paintButtons: () -> () = function(): ()
		local selected: number? = selectedLayer();
		accent = Color3.fromHSV(vape.GUIColor.Hue, vape.GUIColor.Sat, vape.GUIColor.Value);
		for name: string, button: TextButton in layerButtons do
			local active: boolean = name == (selected and 'Layer '..selected or 'All');
			button.BackgroundColor3 = active and accent or color.Light(uipallet.Main, 0.034);
			button.Label.TextColor3 = active and uipallet.Text or color.Dark(uipallet.Text, 0.16);
		end;
	end;

	local updateView: () -> () = function(): ()
		local selected: number? = selectedLayer();
		local low: Vector3, high: Vector3, shown: number = Vector3.one * math.huge, Vector3.one * -math.huge, 0;
		for level: number, folder: Folder in layerFolders do
			local visible: boolean = not selected or level == selected;
			folder.Parent = visible and viewport or nil;
			for _: number, part: Instance in (visible and folder:GetDescendants() or {}) do
				if part:IsA('BasePart') then
					low, high = low:Min(part.Position - part.Size / 2), high:Max(part.Position + part.Size / 2);
					shown += 1;
				end;
			end;
		end;
		if bedClone and current then
			bedClone.Parent = ShowBed["Enabled"] and viewport or nil;
			low, high = low:Min(current.Position - Vector3.one * 3), high:Max(current.Position + Vector3.one * 3);
		end;
		if low.X ~= math.huge then
			orbit.Center = (low + high) / 2;
			orbit.Radius = math.max((high - low).Magnitude / 2, 6);
		end;
		local teamId: number? = current and tonumber(current:GetAttribute('TeamId'));
		local queue: table? = bedwars.QueueMeta[store.queueType];
		local team: table? = queue and teamId and queue.teams[teamId];
		local bedPart: Instance? = current and current:FindFirstChild('Bed');
		bedLabel.Text = current and (team and team.displayName or 'Team '..(teamId or '?'))..' Bed' or 'No bed';
		bedLabel.TextColor3 = bedPart and bedPart:IsA('BasePart') and bedPart.Color or color.Dark(uipallet.Text, 0.16);
		emptyLabel.Visible = not current or shown == 0;
		emptyLabel.Text = not current and 'No bed found' or selected and 'Layer '..selected..' is empty' or 'No defense';
		paintButtons();
		placeCamera();
	end;

	local detachedClone: (object: Instance) -> Instance? = function(object: Instance): Instance?
		local copy: Instance? = object:Clone();
		for _: number, child: Instance in (copy and {copy, unpack(copy:GetDescendants())} or {}) do
			for _: number, tag: string in child:GetTags() do
				child:RemoveTag(tag);
			end;
		end;
		return copy;
	end;

	local rebuild: (bed: BasePart?, layers: {{Instance}}?) -> () = function(bed: BasePart?, layers: {{Instance}}?): ()
		if vape.ThreadFix then
			setthreadidentity(8);
		end;
		pending = false;
		for _: number, folder: Folder in layerFolders do
			folder:Destroy();
		end;
		table.clear(layerFolders);
		table.clear(tracked);
		if bedClone then
			bedClone:Destroy();
			bedClone = nil;
		end;
		current = bed;
		local found: {{Instance}} = layers or bed and scanLayers(bed) or {};
		if #found ~= layerCount then
			layerCount = #found;
			for _: string, button: TextButton in layerButtons do
				button:Destroy();
			end;
			table.clear(layerButtons);
			for order: number = 1, layerCount + 1 do
				local name: string = order <= layerCount and 'Layer '..order or 'All';
				local button: TextButton = Instance.new('TextButton');
				button.Name = name;
				button.AutoButtonColor = false;
				button.BorderSizePixel = 0;
				button.LayoutOrder = order;
				button.Size = UDim2.new(1 / (layerCount + 1), -4, 1, 0);
				button.Text = '';
				button.Parent = buttonRow;
				Instance.new('UICorner').Parent = button;
				local label: TextLabel = Instance.new('TextLabel');
				label.Name = 'Label';
				label.BackgroundTransparency = 1;
				label.FontFace = uipallet.Font;
				label.Size = UDim2.fromScale(1, 1);
				label.Text = layerCount > 3 and order <= layerCount and tostring(order) or name;
				label.TextSize = 12;
				label.TextStrokeTransparency = 0.7;
				label.ZIndex = 2;
				label.Parent = button;
				button.MouseButton1Click:Connect(function(): ()
					View:SetValue(name);
				end);
				layerButtons[name] = button;
			end;
		end;
		for level: number, blockList: {Instance} in found do
			local folder: Folder = Instance.new('Folder');
			for _: number, block: Instance in blockList do
				tracked[block] = level;
				local copy: Instance? = detachedClone(block);
				if copy then
					copy.Parent = folder;
				end;
			end;
			layerFolders[level] = folder;
		end;
		bedClone = bed and detachedClone(bed);
		updateView();
	end;

	local unchanged: (layers: {{Instance}}) -> boolean = function(layers: {{Instance}}): boolean
		local count: number = 0;
		for level: number, blockList: {Instance} in layers do
			for _: number, block: Instance in blockList do
				if tracked[block] ~= level then
					return false;
				end;
				count += 1;
			end;
		end;
		for _: Instance in tracked do
			count -= 1;
		end;
		return count == 0;
	end;

	local refreshNear: (data: table?) -> () = function(data: table?): ()
		local cell: Vector3? = current and data and data.blockRef and data.blockRef.blockPosition;
		if cell and current and (cell * 3 - current.Position).Magnitude <= nearRange then
			pending = true;
		end;
	end;

	BedDefense = vape:CreateOverlay({
		["Name"] = 'Bed Defense',
		["Icon"] = getcustomasset('velo/assets/new/world.png'),
		["Size"] = UDim2.fromOffset(14, 14),
		["Position"] = UDim2.fromOffset(12, 14),
		["CategorySize"] = 240,
		["Function"] = function(callback: boolean): ()
			if not callback then
				drag.Input, drag.Pinch, pending = nil, nil, false;
				table.clear(drag.Touches);
				rebuild(nil, {});
				return;
			end;
			BedDefense:Clean(vapeEvents.PlaceBlockEvent.Event:Connect(refreshNear));
			BedDefense:Clean(vapeEvents.BreakBlockEvent.Event:Connect(refreshNear));
			BedDefense:Clean(inputService.InputChanged:Connect(function(input: InputObject): ()
				if drag.Pinch and table.find(drag.Touches, input) then
					local spread: number = (drag.Touches[1].Position - drag.Touches[2].Position).Magnitude;
					if spread > 0 then
						orbit.Zoom = math.clamp(orbit.Zoom * drag.Pinch / spread, zoomRange.X, zoomRange.Y);
						drag.Pinch = spread;
						placeCamera();
					end;
				elseif drag.Input and (input == drag.Input or input.UserInputType == Enum.UserInputType.MouseMovement and drag.Input.UserInputType == Enum.UserInputType.MouseButton1) then
					local delta: Vector3 = input.Position - drag.Last;
					drag.Last = input.Position;
					orbit.Yaw -= delta.X * 0.01;
					orbit.Pitch = math.clamp(orbit.Pitch + delta.Y * 0.01, math.rad(-80), math.rad(80));
					placeCamera();
				end;
			end));
			BedDefense:Clean(inputService.InputEnded:Connect(function(input: InputObject): ()
				local touch: number? = table.find(drag.Touches, input);
				if touch then
					table.remove(drag.Touches, touch);
					drag.Pinch = nil;
				end;
				if drag.Input and (input == drag.Input or input.UserInputType == Enum.UserInputType.MouseButton1) then
					drag.Input = nil;
				end;
			end));
			BedDefense:Clean(runService.RenderStepped:Connect(function(deltaTime: number): ()
				if AutoRotate["Enabled"] and not drag.Input and not drag.Pinch and holder.AbsoluteSize.X > 0 and BedDefense.Object.Visible then
					orbit.Yaw += deltaTime * math.rad(RotateSpeed["Value"]);
					placeCamera();
				end;
			end));
			rebuild(targetBed(), nil);
			BedDefense:Clean(task.spawn(function(): ()
				local checked: number = tick();
				repeat
					if Color3.fromHSV(vape.GUIColor.Hue, vape.GUIColor.Sat, vape.GUIColor.Value) ~= accent then
						paintButtons();
					end;
					local bed: BasePart? = targetBed();
					if pending or bed ~= current then
						rebuild(bed, nil);
					elseif bed and tick() - checked > rescanRate then
						checked = tick();
						local layers: {{Instance}} = scanLayers(bed);
						if not unchanged(layers) then
							rebuild(bed, layers);
						end;
					end;
					task.wait(loopRate);
				until not BedDefense.Button["Enabled"];
			end));
		end
	});

	local baseColor: (self: table, hue: number, sat: number, value: number, rainbow: boolean?) -> () = BedDefense.Color;
	BedDefense.Color = function(self: table, hue: number, sat: number, value: number, rainbow: boolean?): ()
		baseColor(self, hue, sat, value, rainbow);
		paintButtons();
	end;

	BedMode = BedDefense:CreateDropdown({
		["Name"] = 'Bed',
		["List"] = {'Nearest', 'Crosshair', 'Manual'},
		["Function"] = function(): ()
			if BedDefense.Button["Enabled"] then
				rebuild(targetBed(), nil);
			end;
		end,
		["Tooltip"] = 'Nearest - closest enemy bed\nCrosshair - enemy bed nearest your aim\nManual - pick the bed with the arrows on the viewer'
	});
	View = BedDefense:CreateDropdown({
		["Name"] = 'View',
		["List"] = {'All', 'Layer 1', 'Layer 2', 'Layer 3', 'Layer 4', 'Layer 5', 'Layer 6', 'Layer 7', 'Layer 8', 'Layer 9', 'Layer 10'},
		["Function"] = function(): ()
			updateView();
		end,
		["Tooltip"] = 'Which defense layer to show (the buttons under the viewer change this too)'
	});
	MaxLayers = BedDefense:CreateSlider({
		["Name"] = 'Max layers',
		["Min"] = 1,
		["Max"] = 10,
		["Default"] = 6,
		["Function"] = function(): ()
			if BedDefense.Button["Enabled"] then
				rebuild(targetBed(), nil);
			end;
		end,
		["Tooltip"] = 'The most layers to scan out from the bed, the viewer shows a button for every layer it finds'
	});
	ShowBed = BedDefense:CreateToggle({
		["Name"] = 'Show bed',
		["Default"] = true,
		["Function"] = function(): ()
			updateView();
		end
	});
	AutoRotate = BedDefense:CreateToggle({
		["Name"] = 'Auto rotate',
		["Default"] = true,
		["Function"] = function(callback: boolean): ()
			RotateSpeed.Object.Visible = callback;
		end
	});
	RotateSpeed = BedDefense:CreateSlider({
		["Name"] = 'Rotate speed',
		["Min"] = 5,
		["Max"] = 90,
		["Default"] = 20,
		["Darker"] = true,
		["Suffix"] = '°/s'
	});
	RotateSpeed.Object.Visible = AutoRotate["Enabled"];
	Transparency = BedDefense:CreateSlider({
		["Name"] = 'Transparency',
		["Min"] = 0,
		["Max"] = 1,
		["Default"] = 0.5,
		["Decimal"] = 10,
		["Function"] = function(value: number): ()
			holder.BackgroundTransparency = value;
		end
	});
	holder.BackgroundTransparency = Transparency["Value"];
	holder.Parent = BedDefense.Children;

	for _: number, step: number in {-1, 1} do
		local arrow: TextButton = Instance.new('TextButton');
		arrow.AnchorPoint = Vector2.new(0.5, 0.5);
		arrow.AutoButtonColor = false;
		arrow.BackgroundColor3 = color.Light(uipallet.Main, 0.034);
		arrow.BorderSizePixel = 0;
		arrow.Position = step < 0 and UDim2.fromOffset(16, 16) or UDim2.new(1, -16, 0, 16);
		arrow.Size = UDim2.fromOffset(22, 22);
		arrow.Text = step < 0 and '<' or '>';
		arrow.FontFace = uipallet.Font;
		arrow.TextSize = 14;
		arrow.TextColor3 = color.Dark(uipallet.Text, 0.16);
		arrow.Parent = holder;
		Instance.new('UICorner').Parent = arrow;
		arrow.MouseEnter:Connect(function(): ()
			arrow.BackgroundColor3 = color.Light(uipallet.Main, 0.1);
			arrow.TextColor3 = uipallet.Text;
		end);
		arrow.MouseLeave:Connect(function(): ()
			arrow.BackgroundColor3 = color.Light(uipallet.Main, 0.034);
			arrow.TextColor3 = color.Dark(uipallet.Text, 0.16);
		end);
		arrow.MouseButton1Click:Connect(function(): ()
			local beds: {BasePart} = enemyBeds();
			if #beds == 0 then
				return;
			end;
			picked = beds[((table.find(beds, current) or 0) - 1 + step) % #beds + 1];
			if BedMode["Value"] ~= 'Manual' then
				BedMode:SetValue('Manual');
			elseif BedDefense.Button["Enabled"] then
				rebuild(picked, nil);
			end;
		end);
	end;

	local capture: TextButton = Instance.new('TextButton');
	capture.BackgroundTransparency = 1;
	capture.Position = viewport.Position;
	capture.Size = viewport.Size;
	capture.Text = '';
	capture.Parent = holder;
	capture.InputBegan:Connect(function(input: InputObject): ()
		if input.UserInputType == Enum.UserInputType.Touch then
			table.insert(drag.Touches, input);
			if #drag.Touches == 2 then
				drag.Input, drag.Pinch = nil, (drag.Touches[1].Position - drag.Touches[2].Position).Magnitude;
				return;
			end;
		end;
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			drag.Input, drag.Last = input, input.Position;
		end;
	end);
	capture.InputChanged:Connect(function(input: InputObject): ()
		if input.UserInputType == Enum.UserInputType.MouseWheel then
			orbit.Zoom = math.clamp(orbit.Zoom * (1 - input.Position.Z * 0.12), zoomRange.X, zoomRange.Y);
			placeCamera();
		end;
	end);
	rebuild(nil, {});
	vape:Clean(holder);
end);

velo.run(function(): ()
	local HitAccuracy: table;
	local HideUnused: table = {["Enabled"] = true};
	local ShowColor: table = {["Enabled"] = true};
	local refreshRate: number = 0.05;
	local chanceLifetime: number = 2;
	local rowHeight: number = 20;
	local sources: {string} = {'ProjectileAura', 'ProjectileAimbot'};
	local rows: {[string]: table} = {};
	local nextRefresh: number = 0;

	local holder: Frame = Instance.new('Frame');
	holder.BackgroundColor3 = Color3.new();
	holder.BackgroundTransparency = 0.5;
	holder.Size = UDim2.fromOffset(190, 32);
	Instance.new('UICorner').Parent = holder;
	for _: number, name: string in {'Waiting', unpack(sources)} do
		local row: Frame = Instance.new('Frame');
		row.BackgroundTransparency = 1;
		row.Name = name;
		row.Position = UDim2.fromOffset(0, 6);
		row.Size = UDim2.new(1, 0, 0, rowHeight);
		row.Parent = holder;
		local title: TextLabel = Instance.new('TextLabel');
		title.BackgroundTransparency = 1;
		title.FontFace = uipallet.Font;
		title.Position = UDim2.fromOffset(10, 0);
		title.Size = UDim2.new(1, -20, 1, 0);
		title.Text = name == 'Waiting' and 'Hit chance' or name;
		title.TextColor3 = Color3.new(1, 1, 1);
		title.TextSize = 14;
		title.TextStrokeTransparency = 0.8;
		title.TextXAlignment = Enum.TextXAlignment.Left;
		title.Parent = row;
		local value: TextLabel = title:Clone();
		value.Text = '--';
		value.TextXAlignment = Enum.TextXAlignment.Right;
		value.Parent = row;
		rows[name] = {["Object"] = row, ["Title"] = title, ["Value"] = value};
	end;

	local refresh: () -> () = function(): ()
		if vape.ThreadFix then
			setthreadidentity(8);
		end;
		local shown: number = 0;
		for _: number, name: string in sources do
			local row: table = rows[name];
			local chance: table? = store.hitchance[name];
			local live: boolean = chance ~= nil and tick() - chance.Clock < chanceLifetime;
			row.Object.Visible = live or not HideUnused["Enabled"];
			if row.Object.Visible then
				row.Object.Position = UDim2.fromOffset(0, 6 + shown * rowHeight);
				row.Value.Text = live and math.round(chance.Value * 100)..'%' or '--';
				row.Value.TextColor3 = live and ShowColor["Enabled"] and Color3.fromHSV(chance.Value * 0.33, 0.75, 1) or Color3.new(1, 1, 1);
				shown += 1;
			end;
		end;
		rows.Waiting.Object.Visible = shown == 0;
		holder.Size = UDim2.fromOffset(190, 12 + math.max(shown, 1) * rowHeight);
	end;

	HitAccuracy = vape:CreateOverlay({
		["Name"] = 'Hit Accuracy',
		["Icon"] = getcustomasset('velo/assets/new/aim.png'),
		["Size"] = UDim2.fromOffset(18, 12),
		["Position"] = UDim2.fromOffset(11, 14),
		["Function"] = function(callback: boolean): ()
			if not callback then
				return;
			end;
			HitAccuracy:Clean(runService.Heartbeat:Connect(function(): ()
				if tick() >= nextRefresh then
					nextRefresh = tick() + refreshRate;
					refresh();
				end;
			end));
		end
	});
	HitAccuracy:CreateFont({
		["Name"] = 'Font',
		["Default"] = 'Gotham',
		["Function"] = function(value: Font): ()
			for _: string, row: table in rows do
				row.Title.FontFace = value;
				row.Value.FontFace = value;
			end;
		end
	});
	HideUnused = HitAccuracy:CreateToggle({
		["Name"] = 'Hide unused',
		["Default"] = true,
		["Function"] = function(): ()
			refresh();
		end,
		["Tooltip"] = 'Leaves out a module until it is actually aiming at someone'
	});
	ShowColor = HitAccuracy:CreateToggle({
		["Name"] = 'Color the number',
		["Default"] = true,
		["Tooltip"] = 'Red through green as the chance climbs'
	});
	HitAccuracy:CreateColorSlider({
		["Name"] = 'Background Color',
		["DefaultValue"] = 0,
		["DefaultOpacity"] = 0.5,
		["Function"] = function(hue: number, sat: number, value: number, opacity: number): ()
			holder.BackgroundColor3 = Color3.fromHSV(hue, sat, value);
			holder.BackgroundTransparency = 1 - opacity;
		end
	});
	holder.Parent = HitAccuracy.Children;
	vape:Clean(HitAccuracy.Children:GetPropertyChangedSignal('AbsolutePosition'):Connect(function(): ()
		if vape.ThreadFix then
			setthreadidentity(8);
		end;
		local rightSide: boolean = HitAccuracy.Children.AbsolutePosition.X > vape.gui.AbsoluteSize.X / 2;
		holder.AnchorPoint = Vector2.new(rightSide and 1 or 0, 0);
		holder.Position = UDim2.fromScale(rightSide and 1 or 0, 0);
	end));
	refresh();
	vape:Clean(holder);
end);

velo.run(function(): ()
	local InventoryOverlay: table;
	local Background: table;
	local ShowHotbar: table;
	local Selected: table;
	local ShowInventory: table;
	local columns: number = 9;
	local tileSize: number = 32;
	local gap: number = 4;
	local padding: number = 4;
	local rowLimits: Vector2 = Vector2.new(3, 8);
	local refreshRate: number = 0.1;
	local cardColumns: number = 7;
	local cardTile: number = 30;
	local cardGap: number = 5;
	local cardLift: number = 4;
	local width: number = columns * tileSize + (columns - 1) * gap + padding * 2;
	local tiles: {table} = {};
	local icons: {[string]: string} = {};
	local layout: table = {["Rows"] = 0, ["Hotbar"] = false};
	local nextRefresh: number, nextCard: number = 0, 0;
	local card: table = {["Row"] = nil, ["Cells"] = {}, ["Lifted"] = {}};

	local orderedItems: (inventory: table, skipBackpack: boolean) -> {table} = function(inventory: table, skipBackpack: boolean): {table}
		local worn: {[Instance]: boolean} = {};
		local items: {table} = {};
		for _: any, armor: any in inventory.armor do
			if type(armor) == 'table' and armor.tool then
				worn[armor.tool] = true;
			end;
		end;
		if skipBackpack and inventory.backpack and inventory.backpack.tool then
			worn[inventory.backpack.tool] = true;
		end;
		for _: number, item: table in inventory.items do
			if item.tool and not worn[item.tool] then
				table.insert(items, item);
			end;
		end;
		table.sort(items, function(a: table, b: table): boolean
			if (a.addedToBackpackTime or 0) ~= (b.addedToBackpackTime or 0) then
				return (a.addedToBackpackTime or 0) < (b.addedToBackpackTime or 0);
			end;
			return a.itemType < b.itemType;
		end);
		return items;
	end;

	local playerNames: () -> {string} = function(): {string}
		local names: {string} = {};
		for _: number, plr: Player in playersService:GetPlayers() do
			if plr ~= lplr then
				table.insert(names, plr.Name);
			end;
		end;
		table.sort(names);
		table.insert(names, 1, 'Self');
		return names;
	end;

	local holder: Frame = Instance.new('Frame');
	holder.BackgroundTransparency = 1;
	holder.Size = UDim2.fromOffset(width, padding * 2 + rowLimits.X * tileSize + (rowLimits.X - 1) * gap);
	local panel: Frame = Instance.new('Frame');
	panel.BackgroundColor3 = uipallet.Main;
	panel.BorderSizePixel = 0;
	panel.Size = UDim2.fromScale(1, 1);
	panel.Parent = holder;
	local panelCorner: UICorner = Instance.new('UICorner');
	panelCorner.CornerRadius = UDim.new(0, 8);
	panelCorner.Parent = panel;

	local refresh: () -> () = function(): ()
		if vape.ThreadFix then
			setthreadidentity(8);
		end;
		if not InventoryOverlay.Object.Visible then
			return;
		end;
		local grid: {[number]: table} = {};
		local hotbar: {[number]: table} = {};
		local last: number = 0;
		local target: Instance? = Selected["Value"] == 'Self' and lplr or playersService:FindFirstChild(Selected["Value"]);
		local slots: table = target == lplr and inventorySlots() or {};
		if #slots > 0 then
			for _: number, slot: table in slots do
				if slot.container == 'hotbar' and slot.index < columns then
					hotbar[slot.index + 1] = slot;
				elseif slot.container == 'inventory' then
					grid[slot.index + 1] = slot;
					last = math.max(last, slot.index + 1);
				end;
			end;
		elseif target and target:IsA('Player') then
			for index: number, item: table in orderedItems(bedwars.getInventory(target), true) do
				if index <= columns then
					hotbar[index] = item;
				else
					grid[index - columns] = item;
					last = index - columns;
				end;
			end;
		end;
		local rows: number = math.clamp(math.ceil(last / columns), rowLimits.X, rowLimits.Y);
		if rows ~= layout.Rows or ShowHotbar["Enabled"] ~= layout.Hotbar or #tiles < (rows + (ShowHotbar["Enabled"] and 1 or 0)) * columns then
			layout.Rows, layout.Hotbar = rows, ShowHotbar["Enabled"];
			local total: number = rows + (layout.Hotbar and 1 or 0);
			for index: number = 1, math.max(total * columns, #tiles) do
				local tile: table? = tiles[index];
				if index <= total * columns and not tile then
					local frame: Frame = Instance.new('Frame');
					frame.BackgroundColor3 = color.Dark(uipallet.Main, 0.04);
					frame.BorderSizePixel = 0;
					frame.Size = UDim2.fromOffset(tileSize, tileSize);
					frame.Parent = panel;
					Instance.new('UICorner').Parent = frame;
					local icon: ImageLabel = Instance.new('ImageLabel');
					icon.AnchorPoint = Vector2.new(0.5, 0.5);
					icon.BackgroundTransparency = 1;
					icon.Position = UDim2.fromScale(0.5, 0.5);
					icon.ScaleType = Enum.ScaleType.Fit;
					icon.Size = UDim2.fromScale(0.8, 0.8);
					icon.Parent = frame;
					local amount: TextLabel = Instance.new('TextLabel');
					amount.AnchorPoint = Vector2.new(1, 1);
					amount.BackgroundTransparency = 1;
					amount.FontFace = uipallet.FontSemiBold;
					amount.Position = UDim2.new(1, -3, 1, -1);
					amount.Size = UDim2.new(1, -3, 0, 12);
					amount.TextColor3 = uipallet.Text;
					amount.TextSize = 11;
					amount.TextStrokeTransparency = 0.5;
					amount.TextXAlignment = Enum.TextXAlignment.Right;
					amount.ZIndex = 2;
					amount.Parent = frame;
					tile = {["Object"] = frame, ["Icon"] = icon, ["Amount"] = amount, ["Type"] = nil, ["Count"] = nil};
					tiles[index] = tile;
				end;
				if tile then
					tile.Object.Visible = index <= total * columns;
					tile.Object.BackgroundTransparency = Background["Enabled"] and 0.7 or 1;
					tile.Object.Position = UDim2.fromOffset(padding + (index - 1) % columns * (tileSize + gap), padding + math.floor((index - 1) / columns) * (tileSize + gap));
				end;
			end;
			holder.Size = UDim2.fromOffset(width, padding * 2 + total * tileSize + (total - 1) * gap);
		end;
		for index: number = 1, (layout.Rows + (layout.Hotbar and 1 or 0)) * columns do
			local tile: table = tiles[index];
			local entry: table? = index <= layout.Rows * columns and grid[index] or hotbar[index - layout.Rows * columns];
			local itemType: string = entry and entry.itemType or '';
			local count: number = entry and (entry.amount or 1) > 1 and entry.amount or 0;
			if tile.Type ~= itemType then
				tile.Type = itemType;
				if itemType ~= '' and not icons[itemType] then
					icons[itemType] = bedwars.getIcon({["itemType"] = itemType}, true);
				end;
				tile.Icon.Image = icons[itemType] or '';
				tile.Icon.Visible = itemType ~= '';
			end;
			if tile.Count ~= count then
				tile.Count = count;
				tile.Amount.Text = count > 0 and tostring(count) or '';
				tile.Amount.Visible = count > 0;
			end;
		end;
	end;

	InventoryOverlay = vape:CreateOverlay({
		["Name"] = 'Inventory Overlay',
		["Icon"] = getcustomasset('velo/assets/new/inventory.png'),
		["Size"] = UDim2.fromOffset(15, 14),
		["Position"] = UDim2.fromOffset(12, 13),
		["CategorySize"] = width,
		["Function"] = function(callback: boolean): ()
			if not callback then
				return;
			end;
			Selected:Change(playerNames());
			InventoryOverlay:Clean(playersService.PlayerAdded:Connect(function(): ()
				Selected:Change(playerNames());
			end));
			InventoryOverlay:Clean(playersService.PlayerRemoving:Connect(function(): ()
				task.defer(function(): ()
					Selected:Change(playerNames());
				end);
			end));
			local overlayStep: () -> () = function(): ()
				if tick() >= nextRefresh then
					nextRefresh = tick() + refreshRate;
					refresh();
				end;
			end;
			InventoryOverlay:Clean(task.spawn(function(): ()
				repeat
					if vape.ThreadFix then
						setthreadidentity(8);
					end;
					overlayStep();
					task.wait();
				until false;
			end));
		end
	});
	Background = InventoryOverlay:CreateToggle({
		["Name"] = 'Render Background',
		["Default"] = true,
		["Function"] = function(callback: boolean): ()
			panel.BackgroundTransparency = callback and 0.3 or 1;
			for _: number, tile: table in tiles do
				tile.Object.BackgroundTransparency = callback and 0.7 or 1;
			end;
		end,
		["Tooltip"] = 'Draw the panel and slot tiles behind the items'
	});
	ShowHotbar = InventoryOverlay:CreateToggle({
		["Name"] = 'Show Hotbar',
		["Function"] = function(): ()
			if InventoryOverlay.Button["Enabled"] then
				refresh();
			end;
		end,
		["Tooltip"] = 'Adds the hotbar as an extra row under the inventory'
	});
	Selected = InventoryOverlay:CreateDropdown({
		["Name"] = 'Inventory',
		["List"] = playerNames(),
		["Function"] = function(): ()
			if InventoryOverlay.Button["Enabled"] then
				refresh();
			end;
		end,
		["Tooltip"] = 'Whose inventory to show. Only your own slot positions reach the client, so other players fill the hotbar then the grid in pickup order'
	});
	holder.Parent = InventoryOverlay.Children;
	vape:Clean(holder);

	local targetOverlay: table? = vape.Categories['Target Info'];
	if not targetOverlay then
		return;
	end;
	local statPalette: table = {["Primary"] = Color3.fromRGB(209, 209, 209), ["Danger"] = Color3.fromRGB(250, 50, 56), ["Input"] = Color3.fromRGB(20, 20, 20)};
	local statHeight: number = 20;
	local stats: {table} = {};
	local fight: table = {["Target"] = nil, ["Combo"] = 0, ["Comparator"] = 0, ["Dealt"] = 0, ["DealtHits"] = 0, ["Taken"] = 0, ["TakenHits"] = 0};
	local statAccent: Color3? = nil;

	local statRow: Frame = Instance.new('Frame');
	statRow.Name = 'Stats';
	statRow.BackgroundTransparency = 1;
	statRow.Size = UDim2.fromOffset(cardColumns * (cardTile + cardGap) - cardGap, statHeight);
	statRow.Visible = false;
	statRow.Parent = targetOverlay.Children;
	local statLayout: UIListLayout = Instance.new('UIListLayout');
	statLayout.FillDirection = Enum.FillDirection.Horizontal;
	statLayout.HorizontalAlignment = Enum.HorizontalAlignment.Right;
	statLayout.Padding = UDim.new(0, 4);
	statLayout.SortOrder = Enum.SortOrder.LayoutOrder;
	statLayout.Parent = statRow;
	vape:Clean(statRow);

	local setStat: (stat: table, value: number) -> () = function(stat: table, value: number): ()
		local shade: Color3 = value > 0 and Color3.fromHSV(vape.GUIColor.Hue, vape.GUIColor.Sat, vape.GUIColor.Value) or (value < 0 and statPalette.Danger or statPalette.Primary);
		stat.Value = value;
		stat.Label.Text = stat.Signed and string.format('%+d', math.clamp(value, -9, 9)) or tostring(math.abs(value));
		if stat.Tint then
			stat.Pill.BackgroundColor3 = value ~= 0 and shade or statPalette.Input;
			return;
		end;
		stat.Label.TextColor3 = shade;
		stat.Tag.TextColor3 = shade;
	end;

	local currentTarget: () -> table? = function(): table?
		local target: table?, longest: number = nil, 0;
		for ent: table, expire: any in targetinfo.Targets do
			local remaining: number = type(expire) == 'number' and (expire > 1e8 and expire - tick() or expire - os.clock()) or 0;
			if remaining > longest then
				target, longest = ent, remaining;
			end;
		end;
		if target and target ~= fight.Target then
			fight.Target, fight.Combo, fight.Comparator, fight.Dealt, fight.DealtHits, fight.Taken, fight.TakenHits = target, 0, 0, 0, 0, 0, 0;
			for _: number, stat: table in stats do
				setStat(stat, 0);
			end;
		end;
		return fight.Target;
	end;

	local clearCard: () -> () = function(): ()
		if card.Row then
			card.Row:Destroy();
			card.Row = nil;
		end;
		table.clear(card.Cells);
		table.clear(card.Lifted);
	end;
	ShowInventory = targetOverlay:CreateToggle({
		["Name"] = 'Show Inventory',
		["Function"] = function(callback: boolean): ()
			if not callback then
				clearCard();
			end;
		end,
		["Tooltip"] = 'Shows the target\'s inventory under the card in tiles like the BedWars hotbar. The item they are holding is lifted like your selected slot, and the armor they are wearing is left out.'
	});
	for index: number, spec: table in {
		{["Name"] = 'Combo Counter', ["Tag"] = 'C', ["Default"] = true, ["Tooltip"] = 'Shows how many hits in a direct row you have landed on, or taken from, the target.'},
		{["Name"] = 'Combo Comparator', ["Tag"] = 'H', ["Signed"] = true, ["Tooltip"] = 'Measures how many hits you have landed compared to the target.'},
		{["Name"] = 'Damage Comparator', ["Default"] = true, ["Signed"] = true, ["Tint"] = true, ["Tooltip"] = 'Measures the strength of the target compared to yourself, from the damage each of you lands per hit.'}
	} do
		local pill: Frame = Instance.new('Frame');
		pill.BackgroundColor3 = statPalette.Input;
		pill.LayoutOrder = index;
		pill.Size = UDim2.fromOffset(spec.Tag and 44 or 28, statHeight);
		pill.Visible = false;
		pill.Parent = statRow;
		local corner: UICorner = Instance.new('UICorner');
		corner.CornerRadius = UDim.new(0, 4);
		corner.Parent = pill;
		local label: TextLabel = Instance.new('TextLabel');
		label.BackgroundTransparency = 1;
		label.FontFace = uipallet.Font;
		label.Position = UDim2.fromOffset(spec.Tag and 20 or 2, 0);
		label.Size = UDim2.fromOffset(spec.Tag and 16 or 18, statHeight);
		label.Text = spec.Signed and '+0' or '0';
		label.TextColor3 = spec.Tint and Color3.new(1, 1, 1) or statPalette.Primary;
		label.TextSize = 14;
		label.TextTransparency = spec.Tint and 0.294 or 0;
		label.TextXAlignment = Enum.TextXAlignment.Right;
		label.Parent = pill;
		local tag: TextLabel = label:Clone();
		tag.Position = UDim2.fromOffset(6, 0);
		tag.Size = UDim2.fromOffset(12, statHeight);
		tag.Text = spec.Tag or '';
		tag.TextSize = 12;
		tag.TextXAlignment = Enum.TextXAlignment.Left;
		tag.Visible = spec.Tag ~= nil;
		tag.Parent = pill;
		local stat: table = {["Pill"] = pill, ["Label"] = label, ["Tag"] = tag, ["Signed"] = spec.Signed == true, ["Tint"] = spec.Tint == true, ["Value"] = 0};
		stat.Toggle = targetOverlay:CreateToggle({
			["Name"] = spec.Name,
			["Default"] = spec.Default,
			["Tooltip"] = spec.Tooltip,
			["Function"] = function(callback: boolean): ()
				pill.Visible = callback;
			end
		});
		table.insert(stats, stat);
	end;
	vape:Clean(clearCard);
	vape:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damageTable: table): ()
		local target: table? = currentTarget();
		if not target or not target.Character then
			return;
		end;
		local landed: boolean = damageTable.fromEntity == lplr.Character and damageTable.entityInstance == target.Character;
		local received: boolean = damageTable.entityInstance == lplr.Character and damageTable.fromEntity == target.Character;
		if not landed and not received then
			return;
		end;
		if landed then
			fight.Combo = fight.Combo >= 0 and fight.Combo + 1 or 0;
			fight.Comparator += 1;
			fight.Dealt += damageTable.damage or 0;
			fight.DealtHits += 1;
		else
			fight.Combo = fight.Combo <= 0 and fight.Combo - 1 or 0;
			fight.Comparator -= 1;
			fight.Taken += damageTable.damage or 0;
			fight.TakenHits += 1;
		end;
		setStat(stats[1], fight.Combo);
		setStat(stats[2], fight.Comparator);
		setStat(stats[3], math.clamp(math.round((fight.DealtHits > 0 and fight.Dealt / fight.DealtHits or 0) - (fight.TakenHits > 0 and fight.Taken / fight.TakenHits or 0)), -9, 9));
	end));
	local cardStep: () -> () = function(): ()
		if tick() < nextCard then
			return;
		end;
		nextCard = tick() + refreshRate;
		if vape.ThreadFix then
			setthreadidentity(8);
		end;
		local target: table? = currentTarget();
		local accent: Color3 = Color3.fromHSV(vape.GUIColor.Hue, vape.GUIColor.Sat, vape.GUIColor.Value);
		if accent ~= statAccent then
			statAccent = accent;
			for _: number, stat: table in stats do
				setStat(stat, stat.Value);
			end;
		end;
		local cardFrame: GuiObject? = nil;
		for _: number, child: Instance in targetOverlay.Children:GetChildren() do
			if child ~= card.Row and child ~= statRow and child:IsA('GuiObject') and child.Visible then
				cardFrame = child;
			end;
		end;
		local statsShown: boolean = false;
		for _: number, stat: table in stats do
			statsShown = statsShown or stat.Toggle["Enabled"];
		end;
		local below: number = cardFrame and cardFrame.Position.Y.Offset + cardFrame.Size.Y.Offset + cardGap or 0;
		statRow.Visible = cardFrame ~= nil and statsShown;
		if cardFrame and statsShown then
			statRow.Position = UDim2.fromOffset(cardFrame.Position.X.Offset, below);
			below += statHeight + cardGap;
		end;
		if not ShowInventory["Enabled"] then
			return;
		end;
		if not card.Row then
			local row: Frame = Instance.new('Frame');
			row.Name = 'Inventory';
			row.BackgroundTransparency = 1;
			row.Visible = false;
			row.Parent = targetOverlay.Children;
			local grid: UIGridLayout = Instance.new('UIGridLayout');
			grid.CellPadding = UDim2.fromOffset(cardGap, cardGap);
			grid.CellSize = UDim2.fromOffset(cardTile, cardTile);
			grid.SortOrder = Enum.SortOrder.LayoutOrder;
			grid.Parent = row;
			card.Row = row;
		end;
		local inventory: table? = target and target.Player and cardFrame and targetOverlay.Object.Visible and bedwars.getInventory(target.Player) or nil;
		local items: {table} = inventory and orderedItems(inventory, false) or {};
		local hand: table? = inventory and inventory.hand;
		for index: number, item: table in items do
			local cell: Frame? = card.Cells[index];
			if not cell then
				cell = Instance.new('Frame');
				cell.Name = 'Slot'..index;
				cell.BackgroundTransparency = 1;
				cell.LayoutOrder = index;
				cell.Parent = card.Row;
				local tile: Frame = Instance.new('Frame');
				tile.Name = 'Tile';
				tile.BackgroundColor3 = Color3.fromRGB(29, 36, 46);
				tile.BorderMode = Enum.BorderMode.Inset;
				tile.Size = UDim2.fromScale(1, 1);
				tile.Parent = cell;
				local icon: ImageLabel = Instance.new('ImageLabel');
				icon.Name = 'Icon';
				icon.AnchorPoint = Vector2.new(0.5, 0);
				icon.BackgroundTransparency = 1;
				icon.Position = UDim2.fromScale(0.5, 0.15);
				icon.Size = UDim2.fromScale(0.8, 0.8);
				icon.Parent = tile;
				local amount: TextLabel = Instance.new('TextLabel');
				amount.Name = 'Amount';
				amount.AnchorPoint = Vector2.new(1, 1);
				amount.BackgroundTransparency = 1;
				amount.FontFace = Font.fromName('RobotoMono', Enum.FontWeight.Bold);
				amount.Position = UDim2.new(1, -2, 1, 0);
				amount.Size = UDim2.new(1, -2, 0, 12);
				amount.TextColor3 = Color3.new(1, 1, 1);
				amount.TextSize = 11;
				amount.TextStrokeTransparency = 0.5;
				amount.TextXAlignment = Enum.TextXAlignment.Right;
				amount.ZIndex = 2;
				amount.Parent = tile;
				card.Cells[index] = cell;
			end;
			local held: boolean = hand ~= nil and item.tool == hand.tool;
			local tile: Frame = cell.Tile;
			cell.Visible = true;
			tile.Icon.Image = bedwars.getIcon(item, true);
			tile.Amount.Text = (item.amount or 1) > 1 and tostring(item.amount) or '';
			tile.BackgroundTransparency = held and 0.2 or 0.4;
			tile.BorderColor3 = held and Color3.new(1, 1, 1) or Color3.fromRGB(114, 126, 172);
			if card.Lifted[cell] ~= held then
				card.Lifted[cell] = held;
				tween:Tween(tile, TweenInfo.new(0.12), {["Position"] = UDim2.fromOffset(0, held and -cardLift or 0)});
			end;
		end;
		for index: number = #items + 1, #card.Cells do
			card.Cells[index].Visible = false;
		end;
		local rows: number = math.ceil(#items / cardColumns);
		card.Row.Size = UDim2.fromOffset(cardColumns * (cardTile + cardGap) - cardGap, math.max(rows * (cardTile + cardGap) - cardGap, 0));
		card.Row.Position = cardFrame and UDim2.fromOffset(cardFrame.Position.X.Offset, below + cardLift) or UDim2.new();
		card.Row.Visible = #items > 0;
	end;
	vape:Clean(task.spawn(function(): ()
		repeat
			if vape.ThreadFix then
				setthreadidentity(8);
			end;
			cardStep();
			task.wait();
		until false;
	end));
end);

velo.run(function(): ()
	local AntiEffect: table = {["Enabled"] = false};
	local Dizzy: table;
	local Fear: table;
	local Vignettes: table;
	local Lasso: table;
	local LassoChance: table;
	local LassoTargeting: table;
	local Suffocate: table;
	local SuffocateMode: table;
	local SuffocateHeight: table;
	local suffocateInterval: number = 0.1;
	local lassoGrace: number = 1;
	local escapeOffsets: {Vector3} = {Vector3.new(0, 3, 0), Vector3.new(3, 0, 0), Vector3.new(-3, 0, 0), Vector3.new(0, 0, 3), Vector3.new(0, 0, -3), Vector3.new(0, -3, 0)};
	local savedVignettes: boolean? = nil;

	local setVignettes: (hidden: boolean) -> () = function(hidden: boolean): ()
		local controller: table = bedwars.VignetteController;
		if hidden and savedVignettes == nil then
			savedVignettes = controller.enableOnScreenEffects;
			controller.enableOnScreenEffects = false;
			controller:destroyAllVignettes();
		elseif not hidden and savedVignettes ~= nil then
			controller.enableOnScreenEffects = savedVignettes;
			savedVignettes = nil;
		end;
	end;

	local watchLasso: (character: Model) -> () = function(character: Model): ()
		AntiEffect:Clean(character.ChildAdded:Connect(function(child: Instance): ()
			if not Lasso["Enabled"] or not child:IsA('Accessory') or not child:FindFirstChild('Rope') or math.random(1, 100) > LassoChance["Value"] then
				return;
			end;
			if LassoTargeting["Enabled"] and not entitylib.EntityPosition({["Range"] = 50, ["Part"] = 'RootPart', ["Players"] = true}) then
				return;
			end;
			local root: BasePart? = character.PrimaryPart;
			if root then
				root.Anchored = true;
				child.Destroying:Once(function(): ()
					task.delay(0.5, function(): ()
						root.Anchored = false;
					end);
				end);
			end;
		end));
	end;

	AntiEffect = vape.Categories.Utility:CreateModule({
		["Name"] = 'AntiEffect',
		["Function"] = function(callback: boolean): ()
			if not callback then
				setVignettes(false);
				return;
			end;
			if Dizzy["Enabled"] then
				runService:UnbindFromRenderStep('dizzy-status');
			end;
			if Fear["Enabled"] then
				runService:UnbindFromRenderStep('werewolf-fear-status');
			end;
			setVignettes(Vignettes["Enabled"]);
			local statusAdded: table = bedwars.SyncEvents.StatusEffectAdded:setPriority(1000):connect(function(event: table): ()
				if event.entityInstance ~= lplr.Character then
					return;
				end;
				if Dizzy["Enabled"] and event.statusEffect == bedwars.StatusEffectMeta.DIZZY then
					runService:UnbindFromRenderStep('dizzy-status');
				elseif Fear["Enabled"] and event.statusEffect == bedwars.StatusEffectMeta.WEREWOLF_FEAR then
					runService:UnbindFromRenderStep('werewolf-fear-status');
				end;
			end);
			AntiEffect:Clean(function(): ()
				statusAdded:Destroy();
			end);
			if entitylib.isAlive then
				watchLasso(entitylib.character.Character);
			end;
			AntiEffect:Clean(entitylib.Events.LocalAdded:Connect(function(ent: table): ()
				task.delay(lassoGrace, function(): ()
					if AntiEffect["Enabled"] and ent.Character.Parent then
						watchLasso(ent.Character);
					end;
				end);
			end));
			AntiEffect:Clean(task.spawn(function(): ()
				repeat
					local root: BasePart? = entitylib.isAlive and entitylib.character.RootPart or nil;
					local head: Vector3 = root and root.Position + Vector3.new(0, SuffocateHeight["Value"], 0) or Vector3.zero;
					local block: Instance? = root and Suffocate["Enabled"] and store.matchState == 1 and getPlacedBlock(head) or nil;
					if root and block and SuffocateMode["Value"] == 'Break' then
						breakBlock(block, {["Effects"] = true, ["Animation"] = 'Normal'});
					elseif root and block then
						local cell: Vector3 = roundPos(head);
						for _: number, offset: Vector3 in escapeOffsets do
							local escape: Vector3 = cell + offset;
							if not getPlacedBlock(escape) and not getPlacedBlock(escape + Vector3.new(0, 3, 0)) then
								root.CFrame = CFrame.new(escape - Vector3.new(0, SuffocateHeight["Value"], 0)) * root.CFrame.Rotation;
								root.AssemblyLinearVelocity = Vector3.zero;
								break;
							end;
						end;
					end;
					task.wait(suffocateInterval);
				until not AntiEffect["Enabled"];
			end));
		end,
		["Tooltip"] = 'Strips the client side of debuffs: dizziness, werewolf fear, vignettes, lasso pulls and getting trapped inside blocks.'
	});
	Dizzy = AntiEffect:CreateToggle({
		["Name"] = 'Dizzy',
		["Default"] = true,
		["Tooltip"] = 'Stops the dizzy toad swinging your walk direction around (the slow itself is server side).'
	});
	Fear = AntiEffect:CreateToggle({
		["Name"] = 'Werewolf fear',
		["Default"] = true,
		["Tooltip"] = 'Stops the werewolf tail walking you away from it.'
	});
	Vignettes = AntiEffect:CreateToggle({
		["Name"] = 'Vignettes',
		["Default"] = true,
		["Function"] = function(callback: boolean): ()
			if AntiEffect["Enabled"] then
				setVignettes(callback);
			end;
		end,
		["Tooltip"] = 'Clears the coloured screen borders (frozen, decay, soaked ...).'
	});
	Lasso = AntiEffect:CreateToggle({
		["Name"] = 'Lasso',
		["Function"] = function(callback: boolean): ()
			if LassoTargeting then
				LassoChance.Object.Visible = callback;
				LassoTargeting.Object.Visible = callback;
			end;
		end,
		["Tooltip"] = 'Anchors you while a lasso rope is attached so it cannot pull you.'
	});
	LassoChance = AntiEffect:CreateSlider({
		["Name"] = 'Lasso chance',
		["Min"] = 0,
		["Max"] = 100,
		["Default"] = 100,
		["Suffix"] = '%',
		["Darker"] = true,
		["Visible"] = false
	});
	LassoTargeting = AntiEffect:CreateToggle({
		["Name"] = 'Lasso only when targeting',
		["Darker"] = true,
		["Visible"] = false,
		["Tooltip"] = 'Only resist when an enemy is within 50 studs.'
	});
	Suffocate = AntiEffect:CreateToggle({
		["Name"] = 'Suffocate',
		["Function"] = function(callback: boolean): ()
			if SuffocateHeight then
				SuffocateMode.Object.Visible = callback;
				SuffocateHeight.Object.Visible = callback;
			end;
		end,
		["Tooltip"] = 'Gets you out of a block someone placed inside you before it suffocates you.'
	});
