velo.run(function(): ()
	local AutoPlay: table = {["Enabled"] = false};
	local Queue: table;
	local RandomQueue: table;
	local Delay: table;
	local Honor: table;
	local HonorDelay: table;
	local Vote: table;
	local VoteOption: table;
	local VoteDelay: table;
	local VoteNotify: table;
	local queueCooldown: number = 5;
	local queuePending: boolean = false;
	local nextQueue: number = 0;
	local honoredTeams: {[any]: boolean} = {};
	local voted: boolean = false;

	local honorPlayers: () -> () = function(): ()
		local team: any = lplr:GetAttribute('Team');
		local players: {Player} = playersService:GetPlayers();
		table.sort(players, function(a: Player, b: Player): boolean
			return a:GetAttribute('Team') == team and b:GetAttribute('Team') ~= team;
		end);
		for _: number, plr: Player in players do
			local teamId: any = plr:GetAttribute('Team');
			local pointsLeft: number = lplr:GetAttribute(teamId == team and 'HonorPointsLeftToGiveToAllies' or 'HonorPointsLeftToGiveToOpponents') or 0;
			if plr ~= lplr and teamId and not honoredTeams[teamId] and pointsLeft > 0 then
				honoredTeams[teamId] = true;
				bedwars.HonorController:honorPlayer(plr.UserId):await();
				task.wait(HonorDelay["Value"]);
			end;
		end;
	end;

	local matchOver: () -> () = function(): ()
		if Honor["Enabled"] then
			AutoPlay:Clean(task.spawn(honorPlayers));
		end;
		if not Queue["Enabled"] or queuePending then
			return;
		end;
		queuePending = true;
		task.delay(Delay["Value"], function(): ()
			queuePending = false;
			local state: table = bedwars.Store:getState();
			if not AutoPlay["Enabled"] or os.clock() < nextQueue or state.Game.customMatch or state.Party.leader.userId ~= lplr.UserId or state.Party.queueState ~= 0 then
				return;
			end;
			nextQueue = os.clock() + queueCooldown;
			local queueType: string = store.queueType;
			if RandomQueue["Enabled"] then
				local modes: {string} = {};
				for mode: string, meta: table in bedwars.QueueMeta do
					if not meta.disabled and not meta.voiceChatOnly and not meta.rankCategory then
						table.insert(modes, mode);
					end;
				end;
				queueType = modes[math.random(1, #modes)];
			end;
			bedwars.QueueController:joinQueue(queueType);
		end);
	end;

	AutoPlay = vape.Categories.Utility:CreateModule({
		["Name"] = 'AutoPlay',
		["Function"] = function(callback: boolean): ()
			if not callback then
				voted = false;
				table.clear(honoredTeams);
				return;
			end;
			AutoPlay:Clean(vapeEvents.EntityDeathEvent.Event:Connect(function(deathTable: table): ()
				if deathTable.finalKill and deathTable.entityInstance == lplr.Character and #bedwars.Store:getState().Party.members <= 0 and store.matchState ~= 2 then
					matchOver();
				end;
			end));
			AutoPlay:Clean(vapeEvents.MatchEndEvent.Event:Connect(matchOver));
			AutoPlay:Clean(task.spawn(function(): ()
				repeat
					if not Vote["Enabled"] or store.matchState ~= 0 then
						voted = false;
					elseif not voted then
						fire('CastPregameVote', 'SendToServer', {["votingOptionIndex"] = VoteOption["Value"] - 1});
						voted = true;
						if VoteNotify["Enabled"] then
							notif('AutoVote', 'Voted for option '..VoteOption["Value"], 4);
						end;
					end;
					task.wait(VoteDelay["Value"]);
				until not AutoPlay["Enabled"];
			end));
		end,
		["Tooltip"] = 'Queues the next match, honors players and votes for maps automatically.'
	});
	Queue = AutoPlay:CreateToggle({
		["Name"] = 'Queue',
		["Default"] = true,
		["Tooltip"] = 'Queue again after the match ends, or after your final death when you are solo.'
	});
	RandomQueue = AutoPlay:CreateToggle({
		["Name"] = 'Random',
		["Tooltip"] = 'Chooses a random mode'
	});
	Delay = AutoPlay:CreateSlider({
		["Name"] = 'Delay',
		["Min"] = 0,
		["Max"] = 10,
		["Decimal"] = 10,
		["Default"] = 0,
		["Suffix"] = function(value: number): string
			return value == 1 and 'second' or 'seconds';
		end,
		["Tooltip"] = 'How long to wait before queueing.'
	});
	Honor = AutoPlay:CreateToggle({
		["Name"] = 'Honor',
		["Function"] = function(callback: boolean): ()
			if HonorDelay then
				HonorDelay.Object.Visible = callback;
			end;
		end,
		["Tooltip"] = 'Honors one player per team (allies first) when your match is over.'
	});
	HonorDelay = AutoPlay:CreateSlider({
		["Name"] = 'Honor delay',
		["Min"] = 0,
		["Max"] = 2,
		["Decimal"] = 100,
		["Default"] = 0.1,
		["Suffix"] = 'seconds',
		["Darker"] = true,
		["Visible"] = false
	});
	Vote = AutoPlay:CreateToggle({
		["Name"] = 'Vote',
		["Function"] = function(callback: boolean): ()
			if VoteNotify then
				VoteOption.Object.Visible = callback;
				VoteDelay.Object.Visible = callback;
				VoteNotify.Object.Visible = callback;
			end;
		end,
		["Tooltip"] = 'Casts your map vote the moment the pregame vote opens.'
	});
	VoteOption = AutoPlay:CreateSlider({
		["Name"] = 'Vote option',
		["Min"] = 1,
		["Max"] = 4,
		["Default"] = 1,
		["Darker"] = true,
		["Visible"] = false,
		["Tooltip"] = 'Which of the voting options to pick, counting from the left.'
	});
	VoteDelay = AutoPlay:CreateSlider({
		["Name"] = 'Vote delay',
		["Min"] = 0.5,
		["Max"] = 10,
		["Default"] = 1,
		["Decimal"] = 10,
		["Suffix"] = 'seconds',
		["Darker"] = true,
		["Visible"] = false
	});
	VoteNotify = AutoPlay:CreateToggle({
		["Name"] = 'Vote notify',
		["Default"] = true,
		["Darker"] = true,
		["Visible"] = false
	});
	AutoPlay:CreateButton({
		["Name"] = 'Leave party',
		["Function"] = function(): ()
			bedwars.PartyController:leaveParty();
		end
	});
	AutoPlay:CreateButton({
		["Name"] = 'Match history',
		["Function"] = function(): ()
			bedwars.Flamework.resolveDependency('@easy-games/game-core:client/controllers/app-controller@AppController'):openApp({["appId"] = 'MatchHistoryApp', ["app"] = bedwars.ModerationApp}, {["player"] = lplr, ["matchHistory"] = {}});
		end
	});
end);

velo.run(function(): ()
	local AutoToxic: table = {["Enabled"] = false};
	local AutoGG: table;
	local GGMessage: table;
	local Respond: table;
	local Responses: table;
	local Triggers: table;
	local events: {table} = {
		{["Key"] = 'Kill', ["Label"] = 'Kill', ["Variable"] = '[killed.player]', ["Default"] = 'vxp on top | [killed.player]'},
		{["Key"] = 'Death', ["Label"] = 'Death', ["Variable"] = '[killer.player]', ["Default"] = 'my gaming chair subscription expired :( | [killer.player]'},
		{["Key"] = 'Bed', ["Label"] = 'Bed', ["Variable"] = '[bed.team]', ["Default"] = 'nice bed lul | [bed.team]'},
		{["Key"] = 'BedDestroyed', ["Label"] = 'Bed destroyed', ["Variable"] = '[breaker.player]', ["Default"] = 'how dare you >:( | [breaker.player]'},
		{["Key"] = 'Win', ["Label"] = 'Win', ["Default"] = 'yall garbage'}
	};
	local insultWords: {string} = {'gay', 'gae', 'gey', 'hack', 'exploit', 'cheat', 'hecker', 'haxker', 'hacer', 'report', 'fat', 'black', 'getalife', 'fatherless', 'disco', 'yt', 'dizcourde', 'retard', 'bad', 'trash', 'nolife', 'loser', 'killyour', 'kys', 'hacktowin', 'bozo', 'kid', 'adopted', 'linlife', 'commitnotalive', 'vape', 'futureclient', 'download', 'youtube', 'die', 'lobby', 'ban', 'wizard', 'wisard', 'witch', 'magic'};
	local defaultResponse: string = 'What are you yapping about <obj>? | Velocity';
	local controls: {[string]: table} = {};
	local lastSaid: {[string]: string} = {};
	local responded: {[Player]: boolean} = {};
	local deathSaid: boolean = false;
	local closePreset: any = nil;

	local say: (text: string, preset: boolean) -> () = function(text: string, preset: boolean): ()
		if not text:match('%S') then
			return;
		end;
		if textChatService.ChatVersion ~= Enum.ChatVersion.TextChatService then
			replicatedStorage.DefaultChatSystemChatEvents.SayMessageRequest:FireServer(text, 'All');
			return;
		end;
		local channel: TextChannel = textChatService.ChatInputBarConfiguration.TargetTextChannel;
		if not preset or textChatService:CanUserChatAsync(lplr.UserId) then
			channel:SendAsync(text);
			return;
		end;
		if not closePreset then
			for _: number, group: table in textChatService:GetPresetsAsync().categoryGroups do
				for _: number, category: table in group.categories do
					for _: number, message: table in category.messages do
						closePreset = message.value == 'So close' and message.presetId or closePreset;
					end;
				end;
			end;
		end;
		if closePreset then
			channel:SendPresetAsync(closePreset);
		end;
	end;

	local announce: (event: table, value: string?) -> () = function(event: table, value: string?): ()
		local control: table = controls[event.Key];
		local message: string = event.Default;
		local list: {string} = control.List.ListEnabled;
		if control.Mode["Value"] == 'Fixed' then
			message = control.Message["Value"]:match('%S') and control.Message["Value"] or event.Default;
		elseif #list > 0 then
			local index: number = math.random(1, #list);
			if #list > 1 and list[index] == lastSaid[event.Key] then
				index = index % #list + 1;
			end;
			message = list[index];
			lastSaid[event.Key] = message;
		end;
		local filled: string = message:gsub('<obj>', function(): string
			return value or '';
		end);
		if event.Variable then
			filled = filled:gsub((event.Variable:gsub('%p', '%%%0')), function(): string
				return value or '';
			end);
		end;
		say(filled, true);
	end;

	local onChat: (plr: Player?, text: string) -> () = function(plr: Player?, text: string): ()
		if not Respond["Enabled"] or not plr or plr == lplr or responded[plr] then
			return;
		end;
		local squashed: string = text:gsub('%W+', ''):lower():gsub('(.)%1+', '%1');
		local triggered: boolean = squashed == 'l';
		for _: number, word: string in insultWords do
			triggered = triggered or squashed:find(word, 1, true) ~= nil;
		end;
		for _: number, word: string in Triggers.ListEnabled do
			triggered = triggered or squashed:find(word:lower(), 1, true) ~= nil;
		end;
		if not triggered then
			return;
		end;
		responded[plr] = true;
		local list: {string} = Responses.ListEnabled;
		local name: string = plr.DisplayName ~= '' and plr.DisplayName or plr.Name;
		local reply: string = (#list > 0 and list[math.random(1, #list)] or defaultResponse):gsub('<obj>', function(): string
			return name;
		end):gsub('<name>', function(): string
			return name;
		end);
		say(reply, true);
	end;

	AutoToxic = vape.Categories.Utility:CreateModule({
		["Name"] = 'AutoToxic',
		["Function"] = function(callback: boolean): ()
			if not callback then
				deathSaid = false;
				table.clear(responded);
				return;
			end;
			AutoToxic:Clean(playersService.PlayerRemoving:Connect(function(plr: Player): ()
				responded[plr] = nil;
			end));
			AutoToxic:Clean(vapeEvents.BedwarsBedBreak.Event:Connect(function(bedTable: table): ()
				if controls.BedDestroyed.Toggle["Enabled"] and bedTable.brokenBedTeam.id == lplr:GetAttribute('Team') then
					announce(events[4], bedTable.player.DisplayName or bedTable.player.Name);
				elseif controls.Bed.Toggle["Enabled"] and bedTable.player.UserId == lplr.UserId then
					local team: table? = bedwars.QueueMeta[store.queueType].teams[tonumber(bedTable.brokenBedTeam.id)];
					announce(events[3], team and team.displayName:lower() or 'white');
				end;
			end));
			AutoToxic:Clean(vapeEvents.EntityDeathEvent.Event:Connect(function(deathTable: table): ()
				if not deathTable.finalKill then
					return;
				end;
				local killer: Player? = playersService:GetPlayerFromCharacter(deathTable.fromEntity);
				local killed: Player? = playersService:GetPlayerFromCharacter(deathTable.entityInstance);
				if not killer or not killed then
					return;
				end;
				if killed == lplr then
					if not deathSaid and killer ~= lplr and controls.Death.Toggle["Enabled"] then
						deathSaid = true;
						announce(events[2], killer.DisplayName or killer.Name);
					end;
				elseif killer == lplr and controls.Kill.Toggle["Enabled"] then
					announce(events[1], killed.DisplayName or killed.Name);
				end;
			end));
			AutoToxic:Clean(vapeEvents.MatchEndEvent.Event:Connect(function(winTable: table): ()
				if AutoGG["Enabled"] then
					say(GGMessage["Value"]:match('%S') and GGMessage["Value"] or 'gg', false);
				end;
				local myTeam: table? = bedwars.Store:getState().Game.myTeam;
				if controls.Win.Toggle["Enabled"] and (myTeam and myTeam.id == winTable.winningTeamId or lplr.Neutral) then
					announce(events[5], nil);
				end;
			end));
			if textChatService.ChatVersion == Enum.ChatVersion.TextChatService then
				AutoToxic:Clean(textChatService.MessageReceived:Connect(function(message: TextChatMessage): ()
					if message.TextSource then
						onChat(playersService:GetPlayerByUserId(message.TextSource.UserId), message.Text);
					end;
				end));
			elseif replicatedStorage:FindFirstChild('DefaultChatSystemChatEvents') then
				AutoToxic:Clean(replicatedStorage.DefaultChatSystemChatEvents.OnMessageDoneFiltering.OnClientEvent:Connect(function(message: table): ()
					onChat(playersService:FindFirstChild(message.FromSpeaker), message.Message);
				end));
			end;
		end,
		["Tooltip"] = 'Says a message after a certain action.\nEach action uses a Fixed message or a Rotating random entry from its list.\nVariables are replaced with the real name:\n[killed.player] - Kill\n[killer.player] - Death\n[bed.team] - Bed\n[breaker.player] - Bed destroyed'
	});
	AutoGG = AutoToxic:CreateToggle({
		["Name"] = 'AutoGG',
		["Default"] = true,
		["Function"] = function(callback: boolean): ()
			if GGMessage then
				GGMessage.Object.Visible = callback;
			end;
		end,
		["Tooltip"] = 'Says a message when the match ends.'
	});
	GGMessage = AutoToxic:CreateTextBox({
		["Name"] = 'GG message',
		["Default"] = 'gg',
		["Placeholder"] = 'gg',
		["Darker"] = true
	});
	for _: number, event: table in events do
		local control: table = {};
		local refreshVisibility: () -> () = function(): ()
			if control.List then
				control.Mode.Object.Visible = control.Toggle["Enabled"];
				control.Message.Object.Visible = control.Toggle["Enabled"] and control.Mode["Value"] == 'Fixed';
				control.List.Object.Visible = control.Toggle["Enabled"] and control.Mode["Value"] == 'Rotating';
			end;
		end;
		control.Toggle = AutoToxic:CreateToggle({
			["Name"] = event.Key..' ',
			["Function"] = refreshVisibility,
			["Tooltip"] = 'Say something on '..event.Label:lower()..(event.Variable and '\n'..event.Variable..' is replaced with the name' or '')
		});
		control.Mode = AutoToxic:CreateDropdown({
			["Name"] = event.Label..' mode',
			["List"] = {'Rotating', 'Fixed'},
			["Function"] = refreshVisibility,
			["Darker"] = true,
			["Visible"] = false,
			["Tooltip"] = 'Rotating - a random entry from the list (the default message when it is empty)\nFixed - the message below'
		});
		control.Message = AutoToxic:CreateTextBox({
			["Name"] = event.Label..' message',
			["Default"] = event.Default,
			["Placeholder"] = 'Type a message',
			["Darker"] = true,
			["Visible"] = false
		});
		control.List = AutoToxic:CreateTextList({
			["Name"] = event.Key,
			["Darker"] = true,
			["Visible"] = false
		});
		controls[event.Key] = control;
	end;
	Respond = AutoToxic:CreateToggle({
		["Name"] = 'Respond',
		["Tooltip"] = 'Answer once to players who insult you in chat.'
	});
	Responses = AutoToxic:CreateTextList({
		["Name"] = 'Responses',
		["Placeholder"] = 'response (<name> is the player)'
	});
	Triggers = AutoToxic:CreateTextList({
		["Name"] = 'Triggers',
		["Placeholder"] = 'phrase (text to respond to)'
	});
end);

velo.run(function(): ()
	local NickHider: table = {["Enabled"] = false};
	local Replacement: table;
	local HideOthers: table;
	local ChatTags: table;
	local Level: table;
	local Kit: table;
	local Device: table;
	local refreshDelay: number = 0.35;
	local scanBudget: number = 0.002;
	local textClasses: {[string]: boolean} = {["TextLabel"] = true, ["TextButton"] = true, ["TextBox"] = true};
	local patterns: {string} = {};
	local plainNames: {string} = {};
	local shortest: number = math.huge;
	local fakeName: string = 'hidden';
	local fakeReplacement: string = 'hidden';
	local writing: Instance? = nil;
	local swapped: {[Instance]: string} = {};
	local watched: {[Instance]: RBXScriptConnection} = {};
	local hiddenKits: {[Instance]: boolean} = {};
	local playerHooks: table? = nil;
	local deviceHook: table? = nil;
	local refreshQueued: boolean = false;
	local refreshing: boolean = false;

	local refresh: () -> () = function(): ()
		if refreshQueued or not NickHider["Enabled"] then
			return;
		end;
		refreshQueued = true;
		task.delay(refreshDelay, function(): ()
			refreshQueued = false;
			if NickHider["Enabled"] then
				refreshing = true;
				NickHider:Toggle();
				NickHider:Toggle();
				refreshing = false;
			end;
		end);
	end;

	local spoofDevice: () -> () = function(): ()
		local controller: table = bedwars.UserInputController;
		deviceHook = {["Original"] = rawget(controller, 'getUserInputType'), ["Previous"] = controller:getUserInputType()};
		controller.getUserInputType = function(): string
			return Device["Value"]:upper();
		end;
		fire('SendUserInputType', 'SendToServer', {["userInputType"] = Device["Value"]:upper()});
	end;

	local restoreDevice: () -> () = function(): ()
		if deviceHook then
			bedwars.UserInputController.getUserInputType = deviceHook.Original;
			fire('SendUserInputType', 'SendToServer', {["userInputType"] = deviceHook.Previous});
			deviceHook = nil;
		end;
	end;

	local replaceText: (object: Instance) -> ();
	replaceText = function(object: Instance): ()
		local text: any = object.Text;
		if writing == object or type(text) ~= 'string' or #text < shortest then
			return;
		end;
		local lowered: string = text:lower();
		local found: boolean = false;
		for _: number, name: string in plainNames do
			found = found or lowered:find(name, 1, true) ~= nil;
		end;
		if not found then
			return;
		end;
		local replaced: string = text;
		for _: number, pattern: string in patterns do
			replaced = replaced:gsub(pattern, fakeReplacement);
		end;
		if replaced == text then
			return;
		end;
		swapped[object] = text;
		object:SetAttribute('NickHiderOriginalText', text);
		writing = object;
		object.Text = replaced;
		writing = nil;
		if not watched[object] then
			watched[object] = object:GetPropertyChangedSignal('Text'):Connect(function(): ()
				replaceText(object);
			end);
			object.Destroying:Once(function(): ()
				swapped[object] = nil;
				watched[object] = nil;
			end);
		end;
	end;

	local inspect: (object: Instance) -> () = function(object: Instance): ()
		if textClasses[object.ClassName] then
			replaceText(object);
		elseif Kit["Enabled"] and object.Name == 'PlayerKitFrame' and hiddenKits[object] == nil then
			task.defer(function(): ()
				local label: Instance? = object.Parent and object.Parent:FindFirstChild('PlayerName', true);
				if NickHider["Enabled"] and label and label.Text:find(fakeName, 1, true) then
					hiddenKits[object] = object.Visible;
					object.Visible = false;
					object.Destroying:Once(function(): ()
						hiddenKits[object] = nil;
					end);
				end;
			end);
		end;
	end;

	local scan: (root: Instance) -> () = function(root: Instance): ()
		if vape.ThreadFix then
			setthreadidentity(8);
		end;
		NickHider:Clean(root.DescendantAdded:Connect(inspect));
		local started: number = os.clock();
		for _: number, object: Instance in root:GetDescendants() do
			inspect(object);
			if os.clock() - started > scanBudget then
				task.wait();
				if vape.ThreadFix then
					setthreadidentity(8);
				end;
				started = os.clock();
			end;
		end;
	end;

	NickHider = vape.Categories.Utility:CreateModule({
		["Name"] = 'NickHider',
		["Function"] = function(callback: boolean): ()
			if not callback then
				if playerHooks then
					for name: string, original: any in playerHooks.Originals do
						playerHooks.Class[name] = original;
					end;
					playerHooks = nil;
				end;
				if not refreshing then
					restoreDevice();
				end;
				if vape.ThreadFix then
					setthreadidentity(8);
				end;
				for _: Instance, connection: RBXScriptConnection in watched do
					connection:Disconnect();
				end;
				table.clear(watched);
				for object: Instance, visible: boolean in hiddenKits do
					if object.Parent then
						object.Visible = visible;
					end;
				end;
				table.clear(hiddenKits);
				for object: Instance, original: string in swapped do
					if object.Parent then
						writing = object;
						object.Text = original;
						object:SetAttribute('NickHiderOriginalText', nil);
					end;
				end;
				writing = nil;
				table.clear(swapped);
				return;
			end;

			table.clear(patterns);
			table.clear(plainNames);
			shortest = math.huge;
			for _: number, plr: Player in playersService:GetPlayers() do
				if plr == lplr or HideOthers["Enabled"] then
					for _: number, name: string in {plr.Name, plr.DisplayName} do
						local lowered: string = name:lower();
						if name ~= '' and not table.find(plainNames, lowered) then
							table.insert(plainNames, lowered);
							shortest = math.min(shortest, #lowered);
						end;
						for _: number, variant: string in {name, lowered, name:upper()} do
							local pattern: string = variant:gsub('%W', '%%%0');
							if variant ~= '' and not table.find(patterns, pattern) then
								table.insert(patterns, pattern);
							end;
						end;
					end;
				end;
			end;
			fakeName = Replacement["Value"] ~= '' and Replacement["Value"] or 'hidden';
			for _: number, pattern: string in patterns do
				fakeName = fakeName:find(pattern) and 'hidden' or fakeName;
			end;
			fakeReplacement = fakeName:gsub('%%', '%%%%');

			local gamePlayer: any = bedwars.GamePlayerUtil.getGamePlayer(lplr);
			local meta: any = gamePlayer and getmetatable(gamePlayer);
			local class: any = type(meta) == 'table' and rawget(meta, '__index');
			if type(class) == 'table' then
				local originals: table = {["getUsername"] = class.getUsername, ["getDisplayName"] = class.getDisplayName, ["getClanTag"] = class.getClanTag, ["getLevel"] = class.getLevel};
				playerHooks = {["Class"] = class, ["Originals"] = originals};
				local concealed: (self: table) -> boolean = function(self: table): boolean
					local plr: Player? = self:getPlayer();
					return plr ~= nil and (plr == lplr or HideOthers["Enabled"]);
				end;
				class.getUsername = function(self: table, ...: any): any
					return concealed(self) and fakeName or originals.getUsername(self, ...);
				end;
				class.getDisplayName = function(self: table, ...: any): any
					return concealed(self) and fakeName or originals.getDisplayName(self, ...);
				end;
				class.getClanTag = function(self: table, ...: any): any
					return self:getPlayer() == lplr and ChatTags["Enabled"] and '' or originals.getClanTag(self, ...);
				end;
				class.getLevel = function(self: table, ...: any): any
					local plr: Player? = self:getPlayer();
					if plr and (HideOthers["Enabled"] or plr == lplr and Level["Enabled"]) then
						return -1;
					end;
					return originals.getLevel(self, ...);
				end;
			end;

			if Device["Value"] ~= 'Off' and not deviceHook then
				spoofDevice();
			end;

			local roots: {Instance} = {coreGui};
			table.insert(roots, lplr:FindFirstChildOfClass('PlayerGui'));
			if gethui then
				table.insert(roots, gethui());
			end;
			if lplr.Character then
				table.insert(roots, lplr.Character);
			end;
			NickHider:Clean(task.spawn(function(): ()
				for _: number, root: Instance in roots do
					scan(root);
				end;
			end));
			NickHider:Clean(lplr.CharacterAdded:Connect(function(character: Model): ()
				NickHider:Clean(task.spawn(scan, character));
			end));
			NickHider:Clean(playersService.PlayerAdded:Connect(function(): ()
				if HideOthers["Enabled"] then
					refresh();
				end;
			end));
			NickHider:Clean(playersService.PlayerRemoving:Connect(function(): ()
				if HideOthers["Enabled"] then
					refresh();
				end;
			end));
		end,
		["Tooltip"] = 'Replaces your username and display name everywhere it shows up on your screen, and can spoof your device.',
		["ExtraText"] = function(): string
			return Replacement["Value"] ~= '' and Replacement["Value"] or 'hidden';
		end
	});
	Replacement = NickHider:CreateTextBox({
		["Name"] = 'Name',
		["Default"] = 'hidden',
		["Function"] = refresh
	});
	HideOthers = NickHider:CreateToggle({
		["Name"] = 'Hide others',
		["Function"] = refresh,
		["Tooltip"] = 'Hides every player\'s username and level.'
	});
	ChatTags = NickHider:CreateToggle({
		["Name"] = 'Hide chat tags',
		["Tooltip"] = 'Hides your clan tag wherever it renders.'
	});
	Level = NickHider:CreateToggle({
		["Name"] = 'Hide level',
		["Function"] = refresh,
		["Tooltip"] = 'Hides your level wherever it renders.'
	});
	Kit = NickHider:CreateToggle({
		["Name"] = 'Hide kit',
		["Function"] = refresh,
		["Tooltip"] = 'Hides your kit icon in the tab list.'
	});
	Device = NickHider:CreateDropdown({
		["Name"] = 'Device',
		["List"] = {'Off', 'Mobile', 'PC', 'Gamepad'},
		["Function"] = function(value: string): ()
			if not NickHider["Enabled"] then
				return;
			end;
			if value == 'Off' then
				restoreDevice();
			elseif deviceHook then
				fire('SendUserInputType', 'SendToServer', {["userInputType"] = value:upper()});
			else
				spoofDevice();
			end;
		end,
		["Tooltip"] = 'Spoofs the device you show up as to the server.'
	});
end);

velo.run(function(): ()
	local StaffDetector: table = {["Enabled"] = false};
	local Mode: table;
	local Clans: table;
	local Profile: table;
	local Users: table;
	local staffGroup: number = 5774246;
	local staffRank: number = 100;
	local spectatorGrace: number = 5;
	local joinWindow: number = 20;
	local friendPages: number = 6;
	local viewerRows: number = 8;
	local blacklistedClans: {string} = {'gg', 'gg2', 'DV', 'DV2'};
	local blacklistedIds: {number} = {1502104539, 3826146717, 4531785383, 1049767300, 4926350670, 653085195, 184655415, 2752307430, 5087196317, 5744061325, 1536265275};
	local safeModules: {string} = {'AutoClicker', 'Reach', 'Sprint', 'HitFix', 'StaffDetector'};
	local categories: {string} = {'Spectate', 'Mod', 'Impossible'};
	local categoryColors: {[string]: string} = {["Spectate"] = 'rgb(236,129,43)', ["Mod"] = 'rgb(250,50,56)', ["Impossible"] = 'rgb(180,90,250)'};
	local leaveTips: {[string]: string} = {
		["Spectate"] = 'Notifies when a flagged spectator leaves',
		["Mod"] = 'Notifies when a detected staff role, blacklisted user or blacklisted clan member leaves',
		["Impossible"] = 'Notifies when a player flagged for an impossible join leaves'
	};
	local leaveNotify: {[string]: table} = {};
	local joinedNames: {[number]: string} = {};
	local rejoined: {[number]: boolean} = {};
	local joinTimes: {[number]: number} = {};
	local spectatorWatch: {[Player]: RBXScriptConnection} = {};
	local entries: {table} = {};
	local window: TextButton? = nil;
	local infoLabel: TextLabel? = nil;
	local expanded: boolean = false;

	local refreshViewer: () -> () = function(): ()
		if not window or not infoLabel then
			return;
		end;
		local counts: {[string]: number} = {["Spectate"] = 0, ["Mod"] = 0, ["Impossible"] = 0};
		for _: number, entry: table in entries do
			counts[entry.Category] += 1;
		end;
		local listed: boolean = expanded and #entries > 0;
		local lines: {string} = {'<b>StaffDetector</b>', '<font size="4"> </font>'};
		for _: number, category: string in categories do
			table.insert(lines, '<font color="'..categoryColors[category]..'">'..category..': '..counts[category]..'</font>');
		end;
		if listed then
			table.insert(lines, '<font size="4"> </font>');
			for index: number = 1, math.min(#entries, viewerRows) do
				table.insert(lines, entries[index].Name..' <font color="'..categoryColors[entries[index].Category]..'">'..entries[index].Reason..'</font>');
			end;
		end;
		infoLabel.Text = table.concat(lines, '\n');
		local bounds: Vector2 = getfontsize(removeTags(infoLabel.Text), infoLabel.TextSize, infoLabel.FontFace);
		local title: Vector2 = getfontsize('StaffDetector', infoLabel.TextSize, Font.new(infoLabel.FontFace.Family, Enum.FontWeight.Bold));
		window.Size = UDim2.fromOffset(math.max(bounds.X, title.X) + 16, bounds.Y + (listed and -8 or 4));
	end;

	local addEntry: (plr: Player, reason: string, category: string) -> () = function(plr: Player, reason: string, category: string): ()
		if plr.Parent == playersService then
			table.insert(entries, 1, {["Name"] = plr.Name, ["UserId"] = plr.UserId, ["Reason"] = reason, ["Category"] = category});
		end;
		refreshViewer();
	end;

	local flagStaff: (plr: Player, reason: string) -> () = function(plr: Player, reason: string): ()
		while not vape.Loaded do
			task.wait();
		end;
		notif('StaffDetector', 'Staff Detected ('..reason..'): '..plr.Name..' ('..plr.UserId..')', 60, 'alert');
		whitelist.customtags[plr.Name] = {{["text"] = 'GAME STAFF', ["color"] = Color3.new(1, 0, 0)}};
		addEntry(plr, reason, reason == 'impossible_join' and 'Impossible' or 'Mod');
		if Mode["Value"] == 'Uninject' then
			task.spawn(function(): ()
				vape:Uninject();
			end);
			starterGui:SetCore('SendNotification', {["Title"] = 'StaffDetector', ["Text"] = 'Staff Detected ('..reason..')\n'..plr.Name..' ('..plr.UserId..')', ["Duration"] = 60});
		elseif Mode["Value"] == 'Requeue' then
			bedwars.QueueController:joinQueue(store.queueType);
		elseif Mode["Value"] == 'Profile' then
			vape.Save = function(): () end;
			if vape.Profile ~= Profile["Value"] then
				vape:Load(true, Profile["Value"]);
			end;
		elseif Mode["Value"] == 'AutoConfig' then
			vape.Save = function(): () end;
			for name: string, module: table in vape.Modules do
				if not table.find(safeModules, name) and module.Category ~= 'Render' then
					if module["Enabled"] then
						module:Toggle();
					end;
					module.Bind:SetBind({});
				end;
			end;
		end;
	end;

	local noteSpectator: (plr: Player, how: string) -> () = function(plr: Player, how: string): ()
		notif('StaffDetector', 'Spectator '..plr.Name..' joined '..how, 20, 'warning');
		addEntry(plr, 'spectator', 'Spectate');
	end;

	local dropWatch: (plr: Player) -> () = function(plr: Player): ()
		local watch: RBXScriptConnection? = spectatorWatch[plr];
		if watch then
			watch:Disconnect();
			spectatorWatch[plr] = nil;
		end;
	end;

	local checkSpectator: (plr: Player) -> boolean = function(plr: Player): boolean
		if plr:GetAttribute('Team') or not plr:GetAttribute('Spectator') or store.matchState ~= 1 or bedwars.Store:getState().Game.customMatch or tick() - (joinTimes[plr.UserId] or 0) > joinWindow then
			return false;
		end;
		dropWatch(plr);
		task.wait(spectatorGrace);
		if not StaffDetector["Enabled"] or plr.Parent ~= playersService or plr:GetAttribute('Team') or not plr:GetAttribute('Spectator') then
			return false;
		end;
		if rejoined[plr.UserId] then
			noteSpectator(plr, 'back after leaving');
			return false;
		end;
		if plr.FollowUserId ~= 0 and joinedNames[plr.FollowUserId] then
			noteSpectator(plr, 'following '..joinedNames[plr.FollowUserId]);
			return false;
		end;
		local fetched: boolean, pages: any = pcall(playersService.GetFriendsAsync, playersService, plr.UserId);
		if not fetched then
			return false;
		end;
		local friend: string?, finished: boolean = nil, pages.IsFinished;
		for _: number = 1, friendPages do
			for _: number, entry: table in pages:GetCurrentPage() do
				friend = friend or joinedNames[entry.Id];
			end;
			if friend or finished then
				break;
			end;
			if not pcall(pages.AdvanceToNextPageAsync, pages) then
				return false;
			end;
			finished = pages.IsFinished;
		end;
		if friend then
			noteSpectator(plr, 'from '..friend);
		elseif finished then
			flagStaff(plr, 'impossible_join');
			return true;
		end;
		return false;
	end;

	local checkPlayer: (plr: Player) -> () = function(plr: Player): ()
		rejoined[plr.UserId] = joinedNames[plr.UserId] ~= nil or nil;
		joinedNames[plr.UserId] = plr.Name;
		local teleported: number? = plr:GetAttribute('LastTeleported');
		joinTimes[plr.UserId] = teleported and tick() - math.min(workspace:GetServerTimeNow() - teleported, 60) or tick();
		if plr == lplr then
			return;
		end;
		if table.find(blacklistedIds, plr.UserId) or table.find(Users.ListEnabled, tostring(plr.UserId)) then
			flagStaff(plr, 'blacklisted_user');
			return;
		end;
		local ranked: boolean, rank: any = pcall(plr.GetRankInGroup, plr, staffGroup);
		if not ranked then
			notif('StaffDetector', rank, 30, 'alert');
		end;
		if (ranked and rank or 0) >= staffRank then
			flagStaff(plr, 'staff_role');
			return;
		end;
		spectatorWatch[plr] = plr:GetAttributeChangedSignal('Spectator'):Connect(function(): ()
			StaffDetector:Clean(task.spawn(checkSpectator, plr));
		end);
		StaffDetector:Clean(spectatorWatch[plr]);
		if checkSpectator(plr) then
			return;
		end;
		if not plr:GetAttribute('ClanTag') then
			plr:GetAttributeChangedSignal('ClanTag'):Wait();
		end;
		local clan: string = plr:GetAttribute('ClanTag');
		if table.find(blacklistedClans, clan) and vape.Loaded and Clans["Enabled"] then
			dropWatch(plr);
			flagStaff(plr, 'blacklisted_clan_'..clan:lower());
		end;
	end;

	StaffDetector = vape.Categories.Utility:CreateModule({
		["Name"] = 'StaffDetector',
		["Function"] = function(callback: boolean): ()
			if not callback then
				table.clear(joinedNames);
				table.clear(rejoined);
				table.clear(joinTimes);
				table.clear(spectatorWatch);
				table.clear(entries);
				refreshViewer();
				return;
			end;
			StaffDetector:Clean(playersService.PlayerAdded:Connect(function(plr: Player): ()
				StaffDetector:Clean(task.spawn(checkPlayer, plr));
			end));
			StaffDetector:Clean(playersService.PlayerRemoving:Connect(function(plr: Player): ()
				dropWatch(plr);
				for index: number = #entries, 1, -1 do
					local entry: table = entries[index];
					if entry.UserId == plr.UserId then
						table.remove(entries, index);
						if leaveNotify[entry.Category]["Enabled"] then
							notif('StaffDetector', entry.Name..' left ('..entry.Reason..')', 10, 'info');
						end;
					end;
				end;
				refreshViewer();
			end));
			for _: number, plr: Player in playersService:GetPlayers() do
				StaffDetector:Clean(task.spawn(checkPlayer, plr));
			end;
		end,
		["Tooltip"] = 'Detects people with a staff rank ingame'
	});
	Mode = StaffDetector:CreateDropdown({
		["Name"] = 'Mode',
		["List"] = {'Uninject', 'Profile', 'Requeue', 'AutoConfig', 'Notify'},
		["Function"] = function(value: string): ()
			if Profile then
				Profile.Object.Visible = value == 'Profile';
			end;
		end
	});
	Clans = StaffDetector:CreateToggle({
		["Name"] = 'Blacklist clans',
		["Default"] = true
	});
	Profile = StaffDetector:CreateTextBox({
		["Name"] = 'Profile',
		["Default"] = 'default',
		["Darker"] = true,
		["Visible"] = false
	});
	Users = StaffDetector:CreateTextList({
		["Name"] = 'Users',
		["Placeholder"] = 'player (userid)'
	});
	for _: number, category: string in categories do
		leaveNotify[category] = StaffDetector:CreateToggle({
			["Name"] = 'Notify '..category..' leave',
			["Tooltip"] = leaveTips[category]
		});
	end;
	StaffDetector:CreateToggle({
		["Name"] = 'Viewer',
		["Function"] = function(callback: boolean): ()
			if callback and not window then
				if vape.ThreadFix then
					setthreadidentity(8);
				end;
				window = Instance.new('TextButton');
				window.Name = 'StaffDetectorViewer';
				window.Position = UDim2.fromOffset(12, 120);
				window.BackgroundColor3 = Color3.new();
				window.BackgroundTransparency = 0.5;
				window.Text = '';
				window.AutoButtonColor = false;
				window.Parent = vape.gui.ScaledGui;
				addBlur(window);
				local corner: UICorner = Instance.new('UICorner');
				corner.CornerRadius = UDim.new(0, 5);
				corner.Parent = window;
				infoLabel = Instance.new('TextLabel');
				infoLabel.Size = UDim2.new(1, -16, 1, -16);
				infoLabel.Position = UDim2.fromOffset(8, 8);
				infoLabel.BackgroundTransparency = 1;
				infoLabel.TextXAlignment = Enum.TextXAlignment.Left;
				infoLabel.TextYAlignment = Enum.TextYAlignment.Top;
				infoLabel.TextSize = 16;
				infoLabel.TextColor3 = Color3.new(1, 1, 1);
				infoLabel.TextStrokeColor3 = Color3.new();
				infoLabel.TextStrokeTransparency = 0.8;
				infoLabel.Font = Enum.Font.Arial;
				infoLabel.RichText = true;
				infoLabel.Parent = window;
				vape:Clean(window);
				vape:Clean(window.MouseButton1Click:Connect(function(): ()
					expanded = not expanded;
					refreshViewer();
				end));
			end;
			if window then
				window.Visible = callback;
				refreshViewer();
			end;
