velo.run(function(): ()
	local MissileTP: table = {["Enabled"] = false};
	local Projectile: table;
	local missileSteerRate: number = 0.1;
	local ravenSteerRate: number = 0.05;
	local ravenFlight: number = 1;
	local ravenDetonate: number = 0.3;

	local steer: (model: Model, ent: table, interval: number, duration: number?) -> () = function(model: Model, ent: table, interval: number, duration: number?): ()
		local root: BasePart = model.PrimaryPart;
		local lift: BodyForce = Instance.new('BodyForce');
		lift.Name = 'AntiGravity';
		lift.Force = Vector3.new(0, root.AssemblyMass * workspace.Gravity, 0);
		lift.Parent = root;
		local started: number, nextStep: number = tick(), 0;
		local follow: RBXScriptConnection;
		follow = runService.Heartbeat:Connect(function(): ()
			if not model.Parent or not ent.RootPart or (duration and tick() - started > duration) then
				follow:Disconnect();
				return;
			end;
			if tick() >= nextStep then
				nextStep = tick() + interval;
				model:SetPrimaryPartCFrame(CFrame.lookAlong(ent.RootPart.Position, gameCamera.CFrame.LookVector));
			end;
		end);
		vape:Clean(follow);
	end;

	MissileTP = vape.Categories.Utility:CreateModule({
		["Name"] = 'MissileTP',
		["Function"] = function(callback: boolean): ()
			if not callback then
				return;
			end;
			MissileTP:Toggle();
			local ent: table? = entitylib.EntityMouse({["Range"] = 1000, ["Players"] = true, ["Part"] = 'RootPart', ["Priority"] = false});
			if not ent then
				return;
			end;
			local hasMissile: boolean = getItem('guided_missile') ~= nil;
			if Projectile["Value"] == 'Missile' or (Projectile["Value"] == 'Auto' and hasMissile) then
				if not hasMissile then
					return;
				end;
				local launched: table? = bedwars.RuntimeLib.await(bedwars.GuidedProjectileController.fireGuidedProjectile:CallServerAsync('guided_missile'));
				if not launched then
					notif('MissileTP', 'Missile on cooldown.', 3);
					return;
				end;
				local model: Model = launched.model;
				if not model.PrimaryPart then
					model:GetPropertyChangedSignal('PrimaryPart'):Wait();
				end;
				steer(model, ent, missileSteerRate, nil);
			elseif getItem('raven') then
				fire('SpawnRaven', 'CallServerAsync'):andThen(function(raven: Model?): ()
					if raven and raven.PrimaryPart then
						steer(raven, ent, ravenSteerRate, ravenFlight);
						task.delay(ravenDetonate, function(): ()
							bedwars.RavenController:detonateRaven();
						end);
					end;
				end);
			end;
		end,
		["Tooltip"] = 'Spawns a guided missile or raven and teleports it to the player\nnearest your mouse.'
	});
	Projectile = MissileTP:CreateDropdown({
		["Name"] = 'Projectile',
		["List"] = {'Auto', 'Missile', 'Raven'},
		["Default"] = 'Missile',
		["Tooltip"] = 'Missile - your guided missile\nRaven - your raven\nAuto - missile when you have one, otherwise your raven.'
	});
end);

