				if tick() < nextPickup or not entitylib.isAlive then
					return;
				end;
				nextPickup = tick() + pickupInterval;
				for drop: Instance in picking do
					if not drop.Parent then
						picking[drop] = nil;
					end;
				end;
				local origin: Vector3 = entitylib.character.RootPart.Position;
				for _: number, drop: BasePart in drops do
					if picking[drop] or tick() - (drop:GetAttribute('ClientDropTime') or 0) < dropGrace then
						continue;
