						continue;
					end;
					picking[drop] = true;
					fire('PickupItemDrop', 'CallServerAsync', {["itemDrop"] = drop}):andThen(function(success: any): ()
						picking[drop] = nil;
						if not success then
							return;
						end;
						bedwars.AudioManager:playAudio(bedwars.SoundList.PICKUP_ITEM_DROP);
						local meta: table? = bedwars.ItemMeta[drop.Name];
						if meta and meta.pickUpOverlaySound then
							bedwars.AudioManager:playAudio(meta.pickUpOverlaySound, {["position"] = drop.Position, ["volumeMultiplier"] = 0.9});
						end;
					end);
				end;
			end));
