	local fetchTries: number = 3;
	local hoverOption: number = 0;
	local defenderClass: number = 2;
	local statWeights: {[string]: number} = {["Win"] = 1, ["Combat"] = 0.5, ["Rank"] = 2, ["Kit"] = 1, ["KitPlays"] = 0.2, ["Experience"] = 0.15, ["Streak"] = 0.25, ["FinalKills"] = 0.5, ["BedBreaks"] = 0.5, ["Level"] = 0.2, ["Device"] = 0.4, ["Recent"] = 0.5};
	local roleThreat: {[string]: number} = {["Juggernaut"] = 1, ["Breaker"] = 0.8, ["Defender"] = 0.6, ["Cycler"] = 0.5, ["Support"] = 0.4};
	local kitRoles: {[string]: {string}} = {
		["Defender"] = {'black_market_trader', 'slime_tamer', 'hannah', 'fisherman', 'farmer_cletus', 'spirit_gardener'},
		["Cycler"] = {'fisherman', 'metal_detector', 'beekeeper', 'cowgirl', 'farmer_cletus', 'steam_engineer', 'spirit_gardener', 'davey', 'miner'},
		["Breaker"] = {'davey', 'oil_man', 'santa', 'dino_tamer', 'smoke', 'yeti', 'glacial_skater', 'elk_master', 'mimic', 'shielder', 'airbender'},
		["Support"] = {'baker', 'soul_broker', 'oasis', 'melody', 'hatter'},
		["Juggernaut"] = {'frost_hammer_kit', 'axolotl', 'summoner', 'bigman', 'pinata', 'tinker', 'blood_assassin', 'miner', 'aery', 'nazar', 'barbarian', 'ice_queen', 'block_kicker', 'seahorse', 'void_knight'}
	};
	local deviceThreat: {[string]: number} = {["PC"] = 1, ["GAMEPAD"] = 0.5, ["MOBILE"] = 0};
	local ignoredKits: {[string]: boolean} = {["none"] = true, ["random"] = true, [""] = true};
	local regionCountries: {[string]: string} = {
		["NA"] = 'AG AI AR AW BB BL BM BO BQ BR BS BV BZ CA CL CO CR CU CW DM DO EC EU FK GD GF GL GP GS GT GY HN HT JM KN KY LC MF MQ MS MX NI PA PE PM PR PY SR SV SX TC TT US UY VC VE VG VI',
		["EU"] = 'AD AL AO AQ AT AX BA BE BF BG BI BJ BW BY CD CF CG CH CI CM CV CZ DE DJ DK DZ EE EG EH ER ES ET FI FO FR GA GB GG GH GI GM GN GQ GR GW HR HU IE IM IO IS IT JE KE KM LI LR LS LT LU LV LY MA MC MD ME MG MK ML MR MT MU MW MZ NA NE NG NL NO PL PT RE RO RS RU RW SC SD SE SH SI SJ SK SL SM SN SO SS ST SZ TD TF TG TN TZ UA UG VA XK YT ZA ZM ZW',
		["AS"] = 'AE AM AZ BD BH BN BT CN CY GE HK ID IL IN IQ IR JO JP KG KH KP KR KW KZ LA LB LK MM MN MO MV MY NP OM PH PK PS QA SG SY TH TJ TL TM TR TW UZ VN YE',
		["OCEANIA"] = 'AU CC CK CX FJ FM GU HM KI MH MP NC NF NR NU NZ PF PG PN PW SB TK TO TV UM VU WF WS'
	};
	local regionOf: {[string]: string} = {["NA"] = 'NA', ["EU"] = 'EU', ["AS"] = 'AS', ["ASIA"] = 'AS', ["OCEANIA"] = 'OCEANIA', ["USA"] = 'NA', ["AMERICA"] = 'NA', ["UK"] = 'EU', ["EUROPE"] = 'EU', ["OCE"] = 'OCEANIA', ["AUS"] = 'OCEANIA', ["AUSTRALIA"] = 'OCEANIA'};
	for region: string, codes: string in regionCountries do
		for code: string in codes:gmatch('%a+') do
			regionOf[code] = regionOf[code] or region;
		end;
	end;
	local kitThreat: {[string]: number} = {};
	for role: string, kits: {string} in kitRoles do
		for _: number, kit: string in kits do
			kitThreat[kit] = math.max(kitThreat[kit] or 0, roleThreat[role]);
		end;
	end;
	for kit: string, meta: table in bedwars.BedwarsKitMeta do
		if meta.kitClass == defenderClass then
