		AutoMatchDodge:Clean(task.spawn(function(): ()
			-- CallServer rethrows server-side handler errors; catsix treats a failed fetch as "no data, retry in 5s".
			local fetched: boolean, data: any = pcall(fire, 'RequestProfileData', 'CallServer', plr);
			local ranked: boolean, ranks: any = pcall(fire, 'FetchRanks', 'CallServer', {plr.UserId});
			if entry.Tries ~= attempt then
				return;
			end;
			entry.Pending, entry.Retry = false, os.clock() + 5;
			if not fetched or type(data) ~= 'table' or type(data.queues) ~= 'table' then
				return;
			end;
			ranks = ranked and ranks or nil;
			local rows: {table} = {};
			for _: number, match: table in data.matchHistory or {} do
				for _: number, row: table in (not match.matchCancelled and match.players or {}) do
					if row.playerInfo and row.playerInfo.userId == data.userId then
						table.insert(rows, {["Queue"] = match.queueType, ["Outcome"] = row.generic and row.generic.matchOutcome, ["Kit"] = row.bedwars and row.bedwars.kit});
						break;
					end;
				end;
			end;
			entry.Data, entry.Rows, entry.Done = data, rows, true;
			entry.Rank = type(ranks) == 'table' and type(ranks[1]) == 'table' and ranks[1].rankDivision or nil;
		end));
		return entry;
	end;

	local matchContext: () -> table = function(): table
		local teleportData: any = teleportService:GetLocalPlayerTeleportData();
		local match: table? = type(teleportData) == 'table' and (teleportData.match or teleportData.customMatch) or nil;
		local queue: string = match and match.queueType or store.queueType;
		local meta: table? = bedwars.QueueMeta[queue];
		return {
			["Queue"] = queue,
			["Baseline"] = 1 / math.max(meta and meta.teams and #meta.teams or 2, 2),
			["Ranked"] = meta ~= nil and meta.rankCategory ~= nil,
			["Draft"] = bedwars.Store:getState().Draft
		};
	end;

	local skillScore: (plr: Player, entry: table, context: table) -> number = function(plr: Player, entry: table, context: table): number
		local data: table? = entry.Data;
		if not data then
			return 0;
		end;
		local baseline: number = context.Baseline;
		local stats: table = data.queues[context.Queue] or {};
		local logit: (wins: number, losses: number) -> number = function(wins: number, losses: number): number
			local rate: number = (wins + baseline * priorMatches) / (wins + losses + priorMatches);
			return math.log(rate * (1 - baseline) / ((1 - rate) * baseline));
		end;
		local recentWins: number, recentLosses: number = 0, 0;
		for _: number, row: table in entry.Rows do
			if row.Queue == context.Queue then
				recentWins += row.Outcome == 'win' and 1 or 0;
				recentLosses += row.Outcome == 'loss' and 1 or 0;
			end;
		end;

