				kit, confidence = pick.kit, 1;
			elseif context.Ranked then
				local banned: {[string]: boolean} = {};
				for _: any, bans: {string} in context.Draft.sharedData.kitBans or {} do
					for _: number, bannedKit: string in bans do
						banned[bannedKit] = true;
					end;
				end;
