				for _: number, row: table in entry.Rows do
					if row.Kit then
						plays[row.Kit] = (plays[row.Kit] or 0) + 1;
					end;
				end;
				local best: number, total: number = 0, 0;
				for candidate: string, count: number in plays do
					if not ignoredKits[candidate] then
						total += count;
						if not banned[candidate] and count > best then
							kit, best = candidate, count;
						end;
					end;
				end;
				confidence = best / (total + priorMatches);
			end;
		end;

		local matches: number = (stats.matches or 0) + priorMatches;
		local parts: {[string]: number} = {
			["Win"] = logit(stats.wins or 0, stats.losses or 0),
			["Combat"] = math.log(((stats.kills or 0) + priorMatches) / ((stats.deaths or 0) + priorMatches)),
			["Rank"] = (entry.Rank or 0) / topDivision,
			["Kit"] = (kit and kitThreat[kit] or 0) * confidence,
			["KitPlays"] = math.log(1 + (kit and data.favoriteKitData and data.favoriteKitData[kit] or 0)) * confidence,
			["Experience"] = math.log(1 + (data.globalStats and data.globalStats.matches or 0)),
			["Streak"] = math.log(1 + (stats.currentWinStreak or 0)),
			["FinalKills"] = math.log(1 + (stats.finalKills or 0) / matches),
			["BedBreaks"] = math.log(1 + (stats.bedBreaks or 0) / matches),
			["Level"] = math.log(1 + (data.level or 0)),
			["Device"] = deviceThreat[plr:GetAttribute('UserInputType') or data.platform] or 0,
			["Recent"] = logit(recentWins, recentLosses)
		};
		local score: number = 0;
		for name: string, value: number in parts do
			score += value * statWeights[name];
		end;
		return score;
	end;

	local dodgeReason: () -> string? = function(): string?
		local context: table = matchContext();
		if RankCheck["Enabled"] and not context.Ranked then
			return nil;
		end;
		if SkillCheck["Enabled"] then
			local mine: table = fetchProfile(lplr);
			local stronger: number = 0;
			for _: number, ent: table in entitylib.List do
				local plr: Player? = ent.Player;
				if plr and plr:GetAttribute('Team') ~= lplr:GetAttribute('Team') and plr:IsDescendantOf(playersService) then
					local theirs: table = fetchProfile(plr);
					if mine.Done and theirs.Done and skillScore(lplr, mine, context) <= skillScore(plr, theirs, context) then
						stronger += 1;
					end;
				end;
			end;
			if stronger > 1 then
				return 'Dodging because multiple opponents are "better" than you';
			end;
		end;
		if PlayerCheck["Enabled"] then
			local whitelisted: {[string]: boolean} = {};
			for _: number, name: string in Teammates.ListEnabled do
				whitelisted[name:lower()] = true;
			end;
			local myTeam: any = lplr:GetAttribute('Team');
			local allies: number, enemies: {[any]: number}, pending: boolean = 1, {}, false;
			for _: number, plr: Player in playersService:GetPlayers() do
				local team: any = plr:GetAttribute('Team');
				if plr == lplr or plr:GetAttribute('Spectator') then
					continue;
				elseif whitelisted[plr.Name:lower()] or (myTeam and team == myTeam) then
					allies += 1;
				elseif not team then
					pending = true;
				elseif myTeam then
					enemies[team] = (enemies[team] or 0) + 1;
				end;
			end;
			local state: table = bedwars.Store:getState();
			local meta: table? = bedwars.QueueMeta[store.queueType];
			local present: number, expected: number, largest: number = allies, 0, 0;
			for _: any, count: number in enemies do
				present += count;
				largest = math.max(largest, count);
			end;
			for _: any, team: table in state.Game.teams or {} do
				for _: any in team.members or {} do
					expected += 1;
				end;
			end;
			local drafting: boolean = meta ~= nil and meta.drafting ~= nil and meta.drafting.enabled == true;
			local ready: boolean = present >= expected and (not drafting or state.Draft.sharedData.matchDraftPhase >= 3);
			if myTeam and not pending and ready and allies < largest then
				return 'Dodging because you have fewer players ('..allies..') than the enemy team ('..largest..')';
			end;
		end;
		return nil;
	end;

	local regionVerdict: (code: string) -> boolean = function(code: string): boolean
		local normalize: (text: string) -> string? = function(text: string): string?
			local word: string? = text:upper():gsub('<[^>]*>', ''):gsub('REGION:', ''):match('%a+');
			return word and regionOf[word];
		end;
		local region: string? = normalize(code);
		local selected: {[string]: boolean} = {};
		local anySelected: boolean = false;
		for _: number, entry: string in Regions.ListEnabled do
			local name: string? = normalize(entry);
			if name then
				selected[name], anySelected = true, true;
			end;
		end;
		if not anySelected then
			notif('RegionLock', 'No valid region is turned on, loading every region', 8, 'warning');
		elseif not region then
			notif('RegionLock', 'Unknown region '..code..', loading anyway', 8, 'warning');
		elseif not selected[region] then
			notif('RegionLock', 'Dodging '..code..' ('..region..'), it is not in your regions', 12, 'info');
			return false;
		end;
		return true;
	end;

	AutoMatchDodge = vape.Categories.Utility:CreateModule({
		["Name"] = 'AutoMatchDodge',
		["Function"] = function(callback: boolean): ()
			writefile(flagPath, tostring(callback));
			if not callback then
				table.clear(profiles);
				hold.Release();
				return;
			end;
			if not hold.Held then
				return;
			end;
			hold.Claimed = true;
			local claimed: number = os.clock();
			local loadAt: number = hold.Started + Timeout["Value"];
			local regionDone: boolean = false;
			local checking: boolean = true;
			local nextCheck: number = 0;
			local watcher: RBXScriptConnection;
			watcher = runService.Heartbeat:Connect(function(): ()
				local now: number = os.clock();
				if not hold.Held then
					watcher:Disconnect();
					return;
				end;
				if now < nextCheck then
					return;
				end;
				nextCheck = now + checkInterval;
				local regionOnly: boolean = Mode["Value"] == 'Region only';
				if not regionDone and (RegionLock["Enabled"] or regionOnly) then
					local display: Instance? = lplr.PlayerGui:FindFirstChild('ServerRegionDisplay');
					local label: Instance? = display and display:FindFirstChild('ServerRegionText');
					local code: string? = label and label.Text:gsub('<[^>]*>', ''):gsub('REGION:%s*', ''):match('%S+');
					if code then
						regionDone = true;
						hold.Block = not regionVerdict(code) and 'RegionLock' or nil;
					elseif now - claimed > regionTimeout then
						regionDone = true;
						notif('RegionLock', 'Could not read the server region, loading anyway', 8, 'warning');
					end;
				end;
				if regionOnly then
					if regionDone and not hold.Block then
						watcher:Disconnect();
						hold.Release();
					end;
					return;
				end;
				if Mode["Value"] ~= 'Auto' or not checking then
					return;
				end;
				local reason: string? = dodgeReason();
				if reason then
					notif('AutoMatchDodge', reason, 12, 'info');
					checking = false;
				elseif now > loadAt and not hold.Block then
					watcher:Disconnect();
					task.spawn(hold.Release);
				end;
			end);
			AutoMatchDodge:Clean(watcher);
		end,
		["ExtraText"] = function(): string
			return hold.Dodging and 'Dodging' or 'Game loaded';
		end,
		["Tooltip"] = 'Holds you in the loading screen so you can dodge the match. Carries over into the next match.'
	});
	Mode = AutoMatchDodge:CreateDropdown({
		["Name"] = 'Mode',
		["List"] = {'Auto', 'Manual', 'Region only'},
		["Function"] = function(value: string): ()
			for _: number, option: table? in {Timeout, SkillCheck, RankCheck, PlayerCheck} do
				if option then
					option.Object.Visible = value == 'Auto';
				end;
			end;
			if Regions and RegionLock then
				Regions.Object.Visible = RegionLock["Enabled"] or value == 'Region only';
			end;
		end,
		["Tooltip"] = 'Auto loads after the timeout unless a check dodges, Manual waits for Load, Region only loads as soon as the server region is accepted'
	});
	AutoMatchDodge:CreateButton({
		["Name"] = 'Load',
		["Function"] = hold.Release,
		["Tooltip"] = 'Loads this match now'
	});
	Timeout = AutoMatchDodge:CreateSlider({
		["Name"] = 'Load timeout',
		["Min"] = 1,
		["Max"] = 90,
		["Default"] = 45,
		["Darker"] = true,
		["Suffix"] = function(value: number): string
			return value <= 1 and 'sec' or 'secs';
		end,
		["Tooltip"] = 'Loads into the game after this long'
	});
	SkillCheck = AutoMatchDodge:CreateToggle({
		["Name"] = 'Skill check',
		["Default"] = true,
		["Darker"] = true,
		["Tooltip"] = 'Dodges when more than one opponent looks "better" than you (not 100% accurate)'
	});
	RankCheck = AutoMatchDodge:CreateToggle({
		["Name"] = 'Rank check',
		["Default"] = true,
		["Darker"] = true,
		["Tooltip"] = 'Only dodges in ranked queues, any other match just loads'
	});
	PlayerCheck = AutoMatchDodge:CreateToggle({
		["Name"] = 'Player check',
		["Darker"] = true,
		["Function"] = function(callback: boolean): ()
			if Teammates then
				Teammates.Object.Visible = callback;
			end;
		end,
		["Tooltip"] = 'Dodges when your team has fewer players than the biggest enemy team'
	});
	Teammates = AutoMatchDodge:CreateTextList({
		["Name"] = 'Players Whitelist',
		["Darker"] = true,
		["Visible"] = false,
		["Tooltip"] = 'Players that will always be on your team if they are in the server'
	});
	RegionLock = AutoMatchDodge:CreateToggle({
		["Name"] = 'Region lock',
		["Function"] = function(callback: boolean): ()
			if Regions then
				Regions.Object.Visible = callback or Mode["Value"] == 'Region only';
			end;
			if not callback and hold.Block == 'RegionLock' then
				hold.Block = nil;
			end;
		end,
		["Tooltip"] = 'Dodges servers outside your selected regions'
	});
	Regions = AutoMatchDodge:CreateTextList({
		["Name"] = 'Regions',
		["Placeholder"] = 'NA / EU / AS / OCEANIA',
		["Default"] = {'NA', 'EU', 'AS', 'OCEANIA'},
		["Darker"] = true,
		["Visible"] = false,
		["Function"] = function(): ()
			for _: number, list: {string} in (Regions and {Regions.List, Regions.ListEnabled} or {}) do
				for index: number, entry: string in list do
					list[index] = entry:gsub('%s+', ''):upper();
				end;
			end;
		end,
		["Tooltip"] = 'Turn off the regions you do not want. SG-03 counts as AS, AU/NZ as OCEANIA, US-CA as NA. Leaving every region on accepts anything'
	});
end);

velo.run(function(): ()
	local AutoPearl: table = {["Enabled"] = false};
	local VoidSave: table;
	local Aggro: table;
	local LegitSwitch: table;
	local SwitchBack: table;
	local LandCheck: table;
	local PearlCheck: table;
	local BackDelay: table;
	local LimitItem: table;
	local DistanceLimit: table;
	local MinHealth: table;
	local Cooldown: table;

	local fallVelocity: number = -98;
	local voidDepth: number = 60;
	local groundDepth: number = 300;
	local searchRadii: {number} = {0, 6, 12, 18, 24, 30, 36};
	local voidTolerance: number = 5;
	local aggroTolerance: number = 4;
	local followMinimum: number = 12;
	local flightStep: number = 0.05;
	local maxFlight: number = 4;
	local landTimeout: number = 10;
	local pearlBox: Vector3 = Vector3.new(3, 1, 3);
	local inFlight: Instance?;
	local nextThrow: number = 0;
	local session: table? = nil;

	local landingOf: (origin: Vector3, velocity: Vector3, gravity: number) -> Vector3? = function(origin: Vector3, velocity: Vector3, gravity: number): Vector3?
		local last: Vector3 = origin;
		for step: number = 1, math.round(maxFlight / flightStep) do
			local t: number = step * flightStep;
			local point: Vector3 = origin + velocity * t + Vector3.new(0, -0.5 * gravity * t * t, 0);
			local hit: RaycastResult? = workspace:Blockcast(CFrame.new(last), pearlBox, point - last, store.airRay);
			if hit then
				return last + (point - last).Unit * hit.Distance;
			end;
			last = point;
		end;
		return nil;
	end;

	local launchTo: (from: Vector3, spot: Vector3, tolerance: number) -> Vector3? = function(from: Vector3, spot: Vector3, tolerance: number): Vector3?
		local meta: table = bedwars.ProjectileMeta.telepearl;
		local speed: number, gravity: number = meta.launchVelocity, meta.gravitationalAcceleration or config.Gravity;
		local offset: Vector3 = spot - from;
		local flat: Vector3 = offset * Vector3.new(1, 0, 1);
		local candidates: {Vector3} = {};
		if flat.Magnitude >= 1 then
			local discriminant: number = speed ^ 4 - gravity * (gravity * flat.Magnitude ^ 2 + 2 * offset.Y * speed ^ 2);
			for _: number, sign: number in (discriminant >= 0 and {-1, 1} or {}) do
				local angle: number = math.atan((speed ^ 2 + sign * math.sqrt(discriminant)) / (gravity * flat.Magnitude));
				table.insert(candidates, flat.Unit * (math.cos(angle) * speed) + Vector3.new(0, math.sin(angle) * speed, 0));
			end;
		end;
		for _: number, velocity: Vector3 in candidates do
			local landing: Vector3? = landingOf(from, velocity, gravity);
			if landing and (landing - spot).Magnitude <= tolerance then
				return velocity;
			end;
		end;
		return nil;
	end;

	local voidThrow: (from: Vector3, anchor: Vector3) -> Vector3? = function(from: Vector3, anchor: Vector3): Vector3?
		local meta: table = bedwars.ProjectileMeta.telepearl;
		local gravity: number = meta.gravitationalAcceleration or config.Gravity;
		for _: number, radius: number in searchRadii do
			for slice: number = 0, radius > 0 and 7 or 0 do
				local direction: Vector3 = Vector3.new(math.cos(slice * math.pi / 4), 0, math.sin(slice * math.pi / 4));
				local ground: RaycastResult? = workspace:Raycast(Vector3.new(from.X, anchor.Y + 3, from.Z) + direction * radius, Vector3.new(0, -groundDepth, 0), store.airRay);
				if not ground then
					continue;
				end;
				local aim: Vector3?, _: any, flight: number? = trajectory.SolveTrajectory(from, meta.launchVelocity, gravity, ground.Position, Vector3.zero, workspace.Gravity, 0, nil, nil, false, ground.Position, nil, nil, true);
				if aim and flight then
					local velocity: Vector3 = aim - from;
					local clear: boolean, hit: RaycastResult? = trajectory.IsTrajectoryClear(from, velocity, gravity, flight, store.airRay);
					if clear or (hit and (hit.Position - ground.Position).Magnitude < voidTolerance) then
						return velocity;
					end;
				end;
			end;
		end;
		return nil;
	end;

	local holdingPearl: () -> boolean = function(): boolean
		return store.hand.tool ~= nil and store.hand.tool.Name == 'telepearl';
	end;

	local switchBack: (previous: Instance) -> () = function(previous: Instance): ()
		task.wait(BackDelay:GetRandomValue());
		switchItem(previous);
		local previousSlot: number? = hotbarSlotOf(previous);
		if LegitSwitch["Enabled"] and previousSlot then
			hotbarSwitch(previousSlot);
		end;
	end;

	local launch: (item: table, position: Vector3, velocity: Vector3) -> (Instance?, any) = function(item: table, position: Vector3, velocity: Vector3): (Instance?, any)
		local shotId: string = bedwars.IdUtil.generateId(8);
		local shot: table = ballistics.shotData('telepearl');
		local projectile: Instance? = bedwars.ProjectileController:createLocalProjectile(bedwars.ProjectileMeta.telepearl, 'telepearl', 'telepearl', position, shotId, velocity, shot);
		return projectile, fire('ProjectileFire', 'CallServerAsync', item.tool, 'telepearl', 'telepearl', position, position, velocity, shotId, shot, workspace:GetServerTimeNow() - config.ShotLatency);
	end;

	local voidPearl: (anchor: Vector3, item: table) -> () = function(anchor: Vector3, item: table): ()
		if PearlCheck["Enabled"] then
			for _: number, projectile: Instance in store.selfProjectiles do
				if projectile.Name == 'telepearl' then
					return;
				end;
			end;
		end;
		if not voidThrow(entitylib.character.RootPart.Position, anchor) then
			return;
		end;
		local slot: number? = hotbarSlotOf(item.tool);
		local previous: Instance? = store.hand.tool;
		switchItem(item.tool, 0);
		if LegitSwitch["Enabled"] and slot then
			hotbarSwitch(slot);
		end;
		task.wait(math.max(0.04, store.ping.total or 0));
		if not entitylib.isAlive then
			return;
		end;
		local position: Vector3 = entitylib.character.RootPart.Position;
		local velocity: Vector3? = voidThrow(position, anchor);
		local projectile: Instance? = nil;
		if velocity then
			local request: any;
			projectile, request = launch(item, position, velocity);
			request:andThen(function(result: any): ()
				if type(result) == 'table' and result.accepted and result.model then
					result.model.Parent = replicatedStorage;
				end;
			end);
		end;
		if SwitchBack["Enabled"] and LandCheck["Enabled"] and projectile then
			local timeout: number = tick() + landTimeout;
			repeat
				task.wait();
			until not AutoPearl["Enabled"] or tick() >= timeout or not projectile.Parent;
		end;
		if SwitchBack["Enabled"] and previous then
			switchBack(previous);
		end;
	end;

	local aggroPearl: (spot: Vector3, item: table) -> () = function(spot: Vector3, item: table): ()
		if not entitylib.isAlive or not launchTo(entitylib.character.RootPart.Position, spot, aggroTolerance) then
			return;
		end;
		local slot: number? = hotbarSlotOf(item.tool);
		local previous: Instance? = store.hand.tool;
		local previousThrow: number = nextThrow;
		local reserved: number = tick() + Cooldown["Value"];
		nextThrow = reserved;
		switchItem(item.tool);
		if LegitSwitch["Enabled"] and slot then
			hotbarSwitch(slot);
		end;
		local position: Vector3 = entitylib.character.RootPart.Position;
		local velocity: Vector3? = entitylib.isAlive and launchTo(position, spot, aggroTolerance) or nil;
		local landed: boolean = false;
		if velocity then
			local projectile: Instance?, request: any = launch(item, position, velocity);
			inFlight = projectile;
			local tracked: Instance?, waiting: boolean = projectile, projectile == nil;
			request:andThen(function(result: any): ()
				waiting = false;
				if type(result) == 'table' and result.accepted then
					if projectile == nil and typeof(result.model) == 'Instance' then
						tracked, inFlight = result.model, result.model;
					elseif result.model then
						result.model.Parent = replicatedStorage;
					end;
					return;
				end;
				if nextThrow == reserved then
					nextThrow = previousThrow;
				end;
				if inFlight == projectile then
					inFlight = nil;
				end;
			end);
			task.spawn(function(): ()
				local timeout: number = tick() + landTimeout;
				repeat
					task.wait();
				until not AutoPearl["Enabled"] or tick() >= timeout or (not waiting and (not tracked or not tracked.Parent));
				landed = true;
			end);
		else
			if nextThrow == reserved then
				nextThrow = previousThrow;
			end;
			landed = true;
		end;
		if SwitchBack["Enabled"] and LandCheck["Enabled"] then
			repeat
				task.wait();
			until landed or not AutoPearl["Enabled"];
		end;
		if SwitchBack["Enabled"] and previous then
			switchBack(previous);
		end;
	end;

	local follow: (origin: Vector3, launchVelocity: Vector3) -> () = function(origin: Vector3, launchVelocity: Vector3): ()
		if not entitylib.isAlive or not store.airRay then
			return;
		end;
		local spot: Vector3? = landingOf(origin, launchVelocity, bedwars.ProjectileMeta.telepearl.gravitationalAcceleration or config.Gravity);
		if not spot or not AutoPearl["Enabled"] or not Aggro["Enabled"] or not entitylib.isAlive then
			return;
		end;
		local position: Vector3 = entitylib.character.RootPart.Position;
		local gap: number = (spot - position).Magnitude;
		if gap > DistanceLimit["Value"] or gap < followMinimum or gap < (origin - position).Magnitude then
			return;
		end;
		if tick() < nextThrow or (PearlCheck["Enabled"] and inFlight and inFlight.Parent) then
			return;
		end;
		if (MinHealth["Value"] > 0 and entitylib.character.Health < MinHealth["Value"]) or (LimitItem["Enabled"] and not holdingPearl()) then
			return;
		end;
		local item: table? = getItem('telepearl');
		if item then
			aggroPearl(spot, item);
		end;
	end;

	local onLaunch: (event: table) -> () = function(event: table): ()
		if event.projectileType ~= 'telepearl' or not entitylib.isAlive then
			return;
		end;
		if event.shooter == entitylib.character.Character then
			if typeof(event.projectile) == 'Instance' and event.projectile:IsA('PVInstance') then
				inFlight = event.projectile;
			end;
			return;
		end;
		if not Aggro["Enabled"] or typeof(event.origin) ~= 'Vector3' or typeof(event.launchVelocity) ~= 'Vector3' then
			return;
		end;
		for _: number, ent: table in entitylib.List do
			if ent.Character == event.shooter then
				if ent.Targetable then
					task.spawn(follow, event.origin, event.launchVelocity);
				end;
				break;
			end;
		end;
	end;

	AutoPearl = vape.Categories.Utility:CreateModule({
		["Name"] = 'AutoPearl',
		["Function"] = function(callback: boolean): ()
			if not callback then
				inFlight, session = nil, nil;
				return;
			end;
			local launches: table = bedwars.SyncEvents.ProjectileLaunched:connect(onLaunch);
			AutoPearl:Clean(function(): ()
				launches:Destroy();
			end);
			local current: table = {};
			session = current;
			local thrown: boolean = false;
			local anchor: Vector3? = nil;
			repeat
				task.wait();
				if VoidSave["Enabled"] and entitylib.isAlive and (not LimitItem["Enabled"] or holdingPearl()) then
					local root: BasePart = entitylib.character.RootPart;
					if entitylib.character.Humanoid.FloorMaterial ~= Enum.Material.Air then
						anchor = root.Position;
					end;
					if anchor and root.AssemblyLinearVelocity.Y <= fallVelocity and not workspace:Raycast(root.Position, Vector3.new(0, -voidDepth, 0), store.airRay) then
						if not thrown then
							thrown = true;
							local item: table? = getItem('telepearl');
							if item then
								voidPearl(anchor, item);
							end;
						end;
					else
						thrown = false;
					end;
				end;
			until not AutoPearl["Enabled"] or session ~= current;
		end,
		["Tooltip"] = 'Pearls you back to ground when falling into the void, and can follow enemy pearls to where they land.'
	});
	VoidSave = AutoPearl:CreateToggle({
		["Name"] = 'Void save',
		["Default"] = true,
		["Tooltip"] = 'Throws a pearl onto nearby ground after falling toward the void'
	});
	Aggro = AutoPearl:CreateToggle({
		["Name"] = 'Aggro',
		["Function"] = function(callback: boolean): ()
			for _: number, option: table? in {DistanceLimit, MinHealth, Cooldown} do
				if option then
					option.Object.Visible = callback;
				end;
			end;
		end,
		["Tooltip"] = 'Predicts where an enemy pearl lands the moment it is thrown and pearls you to the same spot.\nPearls into the void, closer to you than the thrower, or out of reach are ignored'
	});
	DistanceLimit = AutoPearl:CreateSlider({
		["Name"] = 'Distance limit',
		["Min"] = 10,
		["Max"] = 200,
		["Default"] = 150,
		["Suffix"] = 'studs',
		["Darker"] = true,
		["Visible"] = false,
		["Tooltip"] = 'How far away an enemy pearl can land before it is ignored'
	});
	MinHealth = AutoPearl:CreateSlider({
		["Name"] = 'Min health',
		["Min"] = 0,
		["Max"] = 100,
		["Default"] = 0,
		["Darker"] = true,
		["Visible"] = false,
		["Tooltip"] = 'Never follows a pearl below this health, 0 disables the check'
	});
	Cooldown = AutoPearl:CreateSlider({
		["Name"] = 'Cooldown',
		["Min"] = 0,
		["Max"] = 5,
		["Default"] = 1,
		["Decimal"] = 10,
		["Suffix"] = 'seconds',
		["Darker"] = true,
		["Visible"] = false,
		["Tooltip"] = 'Minimum gap between two followed pearls'
	});
	LegitSwitch = AutoPearl:CreateToggle({
		["Name"] = 'Legit Switch',
		["Default"] = true,
		["Tooltip"] = 'Shows the hotbar switch clientside'
	});
	SwitchBack = AutoPearl:CreateToggle({
		["Name"] = 'Switch back',
		["Default"] = true,
		["Function"] = function(callback: boolean): ()
			for _: number, option: table? in {BackDelay, LandCheck} do
				if option then
					option.Object.Visible = callback;
				end;
			end;
		end,
		["Tooltip"] = 'Switches back to what you held before the pearl'
	});
	LandCheck = AutoPearl:CreateToggle({
		["Name"] = 'Only after landed',
		["Darker"] = true,
		["Tooltip"] = 'Only switches back once your pearl landed'
	});
	BackDelay = AutoPearl:CreateTwoSlider({
		["Name"] = 'Switch Back Delay',
		["Min"] = 0,
		["Max"] = 2,
		["DefaultMin"] = 0.1,
		["DefaultMax"] = 0.2,
		["Darker"] = true
	});
	PearlCheck = AutoPearl:CreateToggle({
		["Name"] = 'Pearl check',
		["Default"] = true,
		["Tooltip"] = 'Does not throw while one of your pearls is still in the air'
	});
	LimitItem = AutoPearl:CreateToggle({
		["Name"] = 'Limit to item',
		["Tooltip"] = 'Only throws while holding a pearl'
	});
end);

velo.run(function(): ()
	local Scaffold: table = {["Enabled"] = false};
	local Expand: table;
	local Tower: table;
	local Downwards: table;
	local Diagonal: table;
	local LimitItem: table;
	local MouseDown: table;
	local FillColor: table;
	local OutlineColor: table;
	local HudPosition: table;
	local BlockUp: table;
	local ReturnSlot: table;
	local Center: table;
	local Blacklist: table;

	local bridgeInterval: number = 0.03;
	local towerVelocity: number = 38;
	local towerMinHealth: number = 8;
	local towerGate: number = 0.15;
	local towerRepeat: number = 0.5;
	local towerCooldown: number = 0.2;
	local towerGrace: number = 0.25;
	local proximityReach: Vector3 = Vector3.new(21, 21, 21);
	local raise: Vector3 = Vector3.new(0, 3, 0);
	local anchorFaces: {Vector3} = {Vector3.new(0, -3, 0), Vector3.new(3, 0, 0), Vector3.new(-3, 0, 0), Vector3.new(0, 0, 3), Vector3.new(0, 0, -3)};
	local neighbours: {Vector3} = {};
	for x: number = -3, 3, 3 do
		for y: number = -3, 3, 3 do
			for z: number = -3, 3, 3 do
				if x ~= 0 or y ~= 0 or z ~= 0 then
					table.insert(neighbours, Vector3.new(x, y, z));
				end;
			end;
		end;
	end;
	local clickGui: Frame = vape.gui.ScaledGui.ClickGui;
	local lastCell: Vector3 = Vector3.zero;
	local nextBridge: number = 0;
	local preview: Part?;
	local previewTween: Tween?;
	local previewCell: Vector3?;
	local hud: table?;
	local tower: table = {["Started"] = false, ["Held"] = false, ["LastPlace"] = 0, ["Cooldown"] = 0};

	local scaffoldBlock: () -> (string?, number) = function(): (string?, number)
		if store.hand.toolType == 'block' and store.hand.tool then
			return store.hand.tool.Name, store.hand.amount or 0;
		end;
		if LimitItem["Enabled"] then
			return nil, 0;
		end;
		local wool: string?, amount: number? = getWool();
		if wool then
			return wool, amount or 0;
		end;
		for _: number, item: table in store.inventory.inventory.items do
			if bedwars.ItemMeta[item.itemType].block then
				return item.itemType, item.amount or 0;
			end;
		end;
		return nil, 0;
	end;

	local towerBlock: () -> (string?, number?) = function(): (string?, number?)
		local blacklisted: (itemType: string) -> boolean = function(itemType: string): boolean
			return table.find(Blacklist.ListEnabled, itemType) ~= nil or (itemType:find('wool') ~= nil and table.find(Blacklist.ListEnabled, 'wool') ~= nil);
		end;
		local hand: table = store.hand;
		if hand.toolType == 'block' and hand.tool and (hand.amount or 0) > 0 and not blacklisted(hand.tool.Name) then
			return hand.tool.Name, nil;
		end;
		if LimitItem["Enabled"] then
			return nil, nil;
		end;
		local best: string?, bestSlot: number?, bestRank: number, bestHealth: number = nil, nil, math.huge, math.huge;
		for _: number, item: table in store.inventory.inventory.items do
			local block: table? = bedwars.ItemMeta[item.itemType] and bedwars.ItemMeta[item.itemType].block;
			if block and (block.health or 0) >= towerMinHealth and (item.amount or 0) > 0 and not blacklisted(item.itemType) then
				local slot: number? = hotbarSlotOf(item.tool);
				local rank: number = (slot and 0 or 2) + (item.itemType:find('wool') and 0 or 1);
				if rank < bestRank or (rank == bestRank and block.health < bestHealth) then
					best, bestSlot, bestRank, bestHealth = item.itemType, slot, rank, block.health;
				end;
			end;
		end;
		return best, bestSlot;
	end;

	local supportFor: (position: Vector3, cell: Vector3) -> Vector3? = function(position: Vector3, cell: Vector3): Vector3?
		for _: number, offset: Vector3 in neighbours do
			if getPlacedBlock(cell + offset) then
				return cell;
			end;
		end;
		local best: Vector3?, bestDistance: number = nil, 60;
		local from: Vector3 = bedwars.BlockController:getBlockPosition(position - proximityReach);
		local to: Vector3 = bedwars.BlockController:getBlockPosition(position + proximityReach);
		for _: number, block: Vector3 in getBlocksInPoints(from, to) do
			local reach: Vector3 = block + (position - block).Unit * 100;
			local corner: Vector3 = Vector3.new(math.clamp(reach.X, block.X - 3, block.X + 3), math.clamp(reach.Y, block.Y - 3, block.Y + 3), math.clamp(reach.Z, block.Z - 3, block.Z + 3));
			if (position - corner).Magnitude < bestDistance then
				best, bestDistance = corner, (position - corner).Magnitude;
			end;
		end;
		return best;
	end;

	local hudOffset: () -> UDim2 = function(): UDim2
		local x: string?, y: string? = HudPosition["Value"]:match('^(%-?%d+),(%-?%d+)$');
		return UDim2.new(0.5, tonumber(x) or 0, 0.5, tonumber(y) or 60);
	end;

	local updateHud: (block: string?, count: number) -> () = function(block: string?, count: number): ()
		if vape.ThreadFix then
			setthreadidentity(8);
		end;
		local now: number = os.clock();
		local delta: number = math.max(now - hud.Clock, 0.001);
		if block ~= hud.Block then
			hud.Block, hud.Peak, hud.Last = block, 0, count;
			hud.Icon.Image = block and bedwars.getIcon({["itemType"] = block}, true) or '';
		end;
		hud.Speed += (math.max(hud.Last - count, 0) / delta - hud.Speed) * math.min(delta * 0.5, 1);
		hud.Peak, hud.Last, hud.Clock = math.max(hud.Peak, count), count, now;
		local accent: Color3 = Color3.fromHSV(vape.GUIColor.Hue, vape.GUIColor.Sat, vape.GUIColor.Value);
		hud.Badge.BackgroundColor3, hud.Trail.BackgroundColor3, hud.Fill.BackgroundColor3 = accent, accent, accent;
		local ratio: number = hud.Peak > 0 and count / hud.Peak or 0;
		if ratio ~= hud.Ratio then
			local draining: boolean = ratio < hud.Ratio;
			hud.Ratio = ratio;
			for _: number, running: Tween in hud.Tweens do
				running:Cancel();
			end;
			hud.Tweens = {
				tweenService:Create(hud.Fill, TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {["Size"] = UDim2.fromScale(ratio, 1)}),
				tweenService:Create(hud.Trail, TweenInfo.new(draining and 0.45 or 0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out, 0, false, draining and 0.2 or 0), {["Size"] = UDim2.fromScale(ratio, 1)})
			};
			for _: number, running: Tween in hud.Tweens do
				running:Play();
			end;
		end;
		hud.Count.Text = '<font color="#'..accent:ToHex()..'">'..count..'</font> '..(count == 1 and 'block' or 'blocks');
		hud.Rate.Text = string.format('%.1f b/s', hud.Speed);
		local width: number = 228 + math.ceil(math.max(hud.Count.TextBounds.X, hud.Rate.TextBounds.X));
		if hud.Frame.Size.X.Offset ~= width then
			hud.Frame.Size = UDim2.fromOffset(width, 44);
		end;
	end;

	local refreshHud: () -> () = function(): ()
		if not hud then
			return;
		end;
		if vape.ThreadFix then
			setthreadidentity(8);
		end;
		hud.Frame.Visible = Scaffold["Enabled"] or clickGui.Visible;
		if hud.Frame.Visible and not Scaffold["Enabled"] then
			local block: string?, count: number = scaffoldBlock();
			updateHud(block, count);
		end;
	end;

	local destroyHud: () -> () = function(): ()
		if hud then
			hud.Connection:Disconnect();
			hud.Frame:Destroy();
			hud = nil;
		end;
	end;

	local buildHud: () -> () = function(): ()
		if vape.ThreadFix then
			setthreadidentity(8);
		end;
		local make: (className: string, parent: Instance, props: {[string]: any}, rounded: boolean?) -> any = function(className: string, parent: Instance, props: {[string]: any}, rounded: boolean?): any
			local object: any = Instance.new(className);
			for property: string, value: any in props do
				object[property] = value;
			end;
			if rounded then
				Instance.new('UICorner', object).CornerRadius = UDim.new(1, 0);
			end;
			object.Parent = parent;
			return object;
		end;
		local frame: Frame = make('Frame', vape.gui, {["Size"] = UDim2.fromOffset(300, 44), ["Position"] = hudOffset(), ["AnchorPoint"] = Vector2.new(0.5, 0), ["BackgroundColor3"] = Color3.fromRGB(22, 22, 26), ["BackgroundTransparency"] = 0.45, ["BorderSizePixel"] = 0}, true);
		local badge: Frame = make('Frame', frame, {["Size"] = UDim2.fromOffset(32, 32), ["Position"] = UDim2.new(0, 6, 0.5, 0), ["AnchorPoint"] = Vector2.new(0, 0.5), ["BackgroundTransparency"] = 0.7, ["BorderSizePixel"] = 0}, true);
		local track: Frame = make('Frame', frame, {["Size"] = UDim2.fromOffset(150, 4), ["Position"] = UDim2.new(0, 48, 0.5, 0), ["AnchorPoint"] = Vector2.new(0, 0.5), ["BackgroundColor3"] = Color3.new(1, 1, 1), ["BackgroundTransparency"] = 0.85, ["BorderSizePixel"] = 0}, true);
		hud = {
			["Frame"] = frame,
			["Badge"] = badge,
			["Icon"] = make('ImageLabel', badge, {["Size"] = UDim2.fromOffset(22, 22), ["Position"] = UDim2.fromScale(0.5, 0.5), ["AnchorPoint"] = Vector2.new(0.5, 0.5), ["BackgroundTransparency"] = 1}),
			["Trail"] = make('Frame', track, {["Size"] = UDim2.fromScale(0, 1), ["BackgroundTransparency"] = 0.6, ["BorderSizePixel"] = 0}, true),
			["Fill"] = make('Frame', track, {["Size"] = UDim2.fromScale(0, 1), ["ZIndex"] = 2, ["BorderSizePixel"] = 0}, true),
			["Count"] = make('TextLabel', frame, {["Size"] = UDim2.fromOffset(100, 22), ["Position"] = UDim2.fromOffset(214, 9), ["BackgroundTransparency"] = 1, ["Text"] = '0 blocks', ["TextColor3"] = Color3.new(1, 1, 1), ["TextSize"] = 16, ["TextXAlignment"] = Enum.TextXAlignment.Left, ["RichText"] = true, ["FontFace"] = uipallet.Font}),
			["Rate"] = make('TextLabel', frame, {["Size"] = UDim2.fromOffset(100, 15), ["Position"] = UDim2.fromOffset(214, 25), ["BackgroundTransparency"] = 1, ["Text"] = '0.0 b/s', ["TextColor3"] = Color3.fromRGB(150, 150, 158), ["TextSize"] = 12, ["TextXAlignment"] = Enum.TextXAlignment.Left, ["FontFace"] = uipallet.Font}),
			["Tweens"] = {},
			["Ratio"] = 0,
			["Peak"] = 0,
			["Last"] = 0,
			["Speed"] = 0,
			["Clock"] = os.clock(),
			["Connection"] = clickGui:GetPropertyChangedSignal('Visible'):Connect(refreshHud)
		};
		frame.InputBegan:Connect(function(input: InputObject): ()
			if vape.ThreadFix then
				setthreadidentity(8);
			end;
			if not clickGui.Visible or (input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch) then
				return;
			end;
			local start: Vector3 = input.Position;
			local origin: UDim2 = frame.Position;
			local moveType: Enum.UserInputType = input.UserInputType == Enum.UserInputType.Touch and Enum.UserInputType.Touch or Enum.UserInputType.MouseMovement;
			local moving: RBXScriptConnection = inputService.InputChanged:Connect(function(change: InputObject): ()
				if change.UserInputType == moveType then
					if vape.ThreadFix then
						setthreadidentity(8);
					end;
					local viewport: Vector2 = gameCamera.ViewportSize;
					local limitX: number = (viewport.X - frame.AbsoluteSize.X) / 2;
					frame.Position = UDim2.new(0.5, math.clamp(origin.X.Offset + change.Position.X - start.X, -limitX, limitX), 0.5, math.clamp(origin.Y.Offset + change.Position.Y - start.Y, -viewport.Y / 2, viewport.Y / 2 - frame.AbsoluteSize.Y));
				end;
			end);
			local released: RBXScriptConnection;
			released = input.Changed:Connect(function(): ()
				if input.UserInputState == Enum.UserInputState.End then
					moving:Disconnect();
					released:Disconnect();
					HudPosition:SetValue(math.round(frame.Position.X.Offset)..','..math.round(frame.Position.Y.Offset));
				end;
			end);
		end);
		refreshHud();
	end;
	vape:Clean(destroyHud);

	local warnOnce: (text: string) -> () = function(text: string): ()
		if tower.Warned ~= text then
			tower.Warned = text;
			notif('AutoBlockUp', text, 3, 'warning');
		end;
	end;

	local suppressJump: (enable: boolean) -> () = function(enable: boolean): ()
		if enable then
			if tower.Humanoid or vape.MovementOwner or not entitylib.isAlive then
				return;
			end;
			vape.MovementOwner, tower.Owned = 'AutoBlockUp', true;
			tower.Humanoid = entitylib.character.Humanoid;
			tower.JumpHeight = tower.Humanoid.JumpHeight;
			tower.Humanoid.JumpHeight = 0;
			return;
		end;
		if tower.Humanoid and tower.JumpHeight and tower.Humanoid.JumpHeight == 0 then
			tower.Humanoid.JumpHeight = tower.JumpHeight;
		end;
		if tower.Owned and vape.MovementOwner == 'AutoBlockUp' then
			vape.MovementOwner = nil;
		end;
		tower.Humanoid, tower.JumpHeight, tower.Owned = nil, nil, false;
	end;

	local stopTower: () -> () = function(): ()
		if ReturnSlot["Enabled"] and tower.Previous and tower.Equipped == store.inventory.hotbarSlot and entitylib.isAlive then
			task.spawn(hotbarSwitch, tower.Previous);
		end;
		suppressJump(false);
		tower.Started, tower.Warned, tower.Previous, tower.Equipped, tower.LostAt = false, nil, nil, nil, nil;
		tower.Cooldown = os.clock() + towerCooldown;
	end;

	local towerTarget: () -> (Vector3?, string?, string?) = function(): (Vector3?, string?, string?)
		if not entitylib.isAlive then
			return nil, nil, nil;
		end;
		local position: Vector3 = entitylib.character.RootPart.Position;
		local feet: number = position.Y - entitylib.character.HipHeight;
		local target: Vector3 = roundPos(Vector3.new(position.X, feet - 1.5, position.Z));
		for _: number = 1, 3 do
			if target.Y - 1.5 > feet + 3 or not getPlacedBlock(target) then
				break;
			end;
			target += raise;
		end;
		if target.Y - 1.5 > feet + 3 or getPlacedBlock(target + raise) or getPlacedBlock(target + raise * 2) then
			return nil, nil, nil;
		end;
		local anchored: boolean = false;
		for _: number, face: Vector3 in anchorFaces do
			anchored = anchored or getPlacedBlock(target + face) ~= nil;
		end;
		if not anchored then
			return nil, nil, nil;
		end;
		local itemType: string? = towerBlock();
		if not itemType then
			return nil, nil, 'No blocks to place';
		end;
		if lplr:GetAttribute('DenyBlockPlace') then
			return nil, nil, "Can't place blocks here";
		end;
		local map: table? = bedwars.MapController;
		if map then
			local cell: Vector3 = bedwars.BlockController:getBlockPosition(target);
			-- MapController lookups can throw while the map data is still loading; catsix counts a failed lookup as allowed.
			local checkedDeny: boolean, denied: any = pcall(map.isInDenyRegion, map, cell);
			local checkedBounds: boolean, outside: any = pcall(map.isOutOfBounds, map, cell);
			if (checkedDeny and denied) or (checkedBounds and outside) then
				return nil, nil, "Can't place blocks here";
			end;
		end;
		return target, itemType, nil;
	end;

	local towerStep: () -> () = function(): ()
		if not entitylib.isAlive then
			suppressJump(false);
			tower.Started, tower.Warned, tower.Previous, tower.Equipped, tower.LostAt = false, nil, nil, nil, nil;
			return;
		end;
		local owner: string? = vape.MovementOwner;
		local jumpMode: boolean = BlockUp["Value"] == 'Holding jump';
		if (owner and owner ~= 'AutoBlockUp') or (jumpMode and not tower.Held) then
			if tower.Started or tower.Owned then
				stopTower();
			end;
			return;
		end;
		if not tower.Started then
			if os.clock() < tower.Cooldown or (jumpMode and not towerTarget()) then
				return;
			end;
			tower.Started = true;
			local itemType: string?, slot: number? = towerBlock();
			if not itemType then
				warnOnce('No blocks to place');
			elseif slot and slot ~= store.inventory.hotbarSlot then
				tower.Previous, tower.Equipped = store.inventory.hotbarSlot, slot;
				task.spawn(hotbarSwitch, slot);
			end;
			if jumpMode then
				suppressJump(true);
			end;
		end;
		local root: BasePart = entitylib.character.RootPart;
		local humanoid: Humanoid = entitylib.character.Humanoid;
		if Center["Enabled"] and humanoid.MoveDirection.Magnitude < 0.1 and humanoid.FloorMaterial ~= Enum.Material.Air and isnetworkowner(root) then
			local middle: Vector3 = roundPos(root.Position);
			if math.abs(middle.X - root.Position.X) > 0.05 or math.abs(middle.Z - root.Position.Z) > 0.05 then
				root.CFrame = CFrame.new(middle.X, root.Position.Y, middle.Z) * root.CFrame.Rotation;
			end;
		end;
		local now: number = workspace:GetServerTimeNow();
		local placeDelay: number = 1 / math.max(math.min(bedwars.DefaultPlaceCPS or math.huge, bedwars.SharedConstants.BLOCK_PLACE_CPS), 1);
		if now - math.max(tower.LastPlace, bedwars.BlockCpsController.lastPlaceTimestamp) < placeDelay or not canPlace() then
			return;
		end;
		local target: Vector3?, itemType: string?, reason: string? = towerTarget();
		if jumpMode then
			if target then
				tower.LostAt = nil;
				suppressJump(true);
			else
				tower.LostAt = tower.LostAt or os.clock();
				if os.clock() - tower.LostAt >= towerGrace then
					suppressJump(false);
				end;
			end;
		elseif reason then
			warnOnce(reason);
		end;
		if not target or target.Y - 1.5 > root.Position.Y - entitylib.character.HipHeight + towerGate or (target == tower.LastTarget and now - tower.LastPlace < towerRepeat) then
			return;
		end;
		tower.Warned = nil;
		tower.LastPlace, tower.LastTarget = now, target;
		task.spawn(placeBlock, target, itemType);
	end;

	local bridgeStep: () -> () = function(): ()
		if vape.MovementOwner then
			return;
		end;
		local held: string?, amount: number = scaffoldBlock();
		local itemType: string? = held;
		if (MouseDown["Enabled"] and not inputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)) or BlockUp["Value"] == 'When enabled' then
			itemType = nil;
		end;
		if hud then
			updateHud(held, amount);
		end;
		if not itemType then
			return;
		end;
		local root: BasePart = entitylib.character.RootPart;
		local humanoid: Humanoid = entitylib.character.Humanoid;
		if Tower["Enabled"] and inputService:IsKeyDown(Enum.KeyCode.Space) and not inputService:GetFocusedTextBox() then
			root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, towerVelocity, root.AssemblyLinearVelocity.Z);
		end;
		local drop: number = entitylib.character.HipHeight + (Downwards["Enabled"] and inputService:IsKeyDown(Enum.KeyCode.LeftShift) and 4.5 or 1.5);
		for step: number = Expand["Value"], 1, -1 do
			local cell: Vector3 = roundPos(root.Position - Vector3.new(0, drop, 0) + humanoid.MoveDirection * (step * 3));
			if Diagonal["Enabled"] and math.abs(math.round(math.deg(math.atan2(-humanoid.MoveDirection.X, -humanoid.MoveDirection.Z)) / 45) * 45) % 90 == 45 then
				local delta: Vector3 = lastCell - cell;
				if ((delta.X == 0 and delta.Z ~= 0) or (delta.X ~= 0 and delta.Z == 0)) and ((lastCell - root.Position) * Vector3.new(1, 0, 1)).Magnitude < 2.5 then
					cell = lastCell;
				end;
			end;
			if preview then
				local shown: Vector3 = bedwars.BlockController:getBlockPosition(cell) * 3;
				if previewCell ~= shown then
					if previewTween then
						previewTween:Cancel();
						previewTween = nil;
					end;
					if preview.Parent == gameCamera then
						previewTween = tweenService:Create(preview, TweenInfo.new(0.1, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {["CFrame"] = CFrame.new(shown)});
						previewTween:Play();
					else
						preview.CFrame = CFrame.new(shown);
						preview.Parent = gameCamera;
					end;
					previewCell = shown;
				end;
			end;
			local block: Instance?, blockCell: Vector3? = getPlacedBlock(cell);
			local spot: Vector3? = not block and supportFor(cell, blockCell * 3) or nil;
			if spot then
				task.delay(0, placeBlock, spot, itemType);
			end;
			lastCell = cell;
		end;
	end;

	local setHeld: (down: boolean) -> () = function(down: boolean): ()
		tower.Held = down;
		if down and BlockUp["Value"] == 'Holding jump' and towerTarget() then
			suppressJump(true);
		end;
	end;

	Scaffold = vape.Categories.Utility:CreateModule({
		["Name"] = 'Scaffold',
		["Function"] = function(callback: boolean): ()
			if vape.ThreadFix then
				setthreadidentity(8);
			end;
			refreshHud();
			if not callback then
				stopTower();
				if previewTween then
					previewTween:Cancel();
					previewTween = nil;
				end;
				if preview then
					preview.Parent = nil;
				end;
				previewCell = nil;
				return;
			end;
			if not vape.Loaded and BlockUp["Value"] == 'When enabled' then
				task.defer(function(): ()
					if Scaffold["Enabled"] then
						Scaffold:Toggle();
					end;
				end);
				return;
			end;
			if hud then
				hud.Block, hud.Speed = nil, 0;
			end;
			tower.Started, tower.Warned, tower.Previous, tower.Equipped, tower.LostAt, tower.LastPlace, tower.Cooldown = false, nil, nil, nil, nil, 0, 0;
			setHeld(not inputService:GetFocusedTextBox() and inputService:IsKeyDown(Enum.KeyCode.Space));
			Scaffold:Clean(inputService.InputBegan:Connect(function(input: InputObject): ()
				if not inputService:GetFocusedTextBox() and (input.KeyCode == Enum.KeyCode.Space or input.KeyCode == Enum.KeyCode.ButtonA) then
					setHeld(true);
				end;
			end));
			Scaffold:Clean(inputService.InputEnded:Connect(function(input: InputObject): ()
				if input.KeyCode == Enum.KeyCode.Space or input.KeyCode == Enum.KeyCode.ButtonA then
					setHeld(false);
				end;
			end));
			local touchGui: Instance? = inputService.TouchEnabled and lplr.PlayerGui:FindFirstChild('TouchGui') or nil;
			local jumpButton: Instance? = touchGui and touchGui:FindFirstChild('JumpButton', true);
			if jumpButton then
				Scaffold:Clean(jumpButton:GetPropertyChangedSignal('ImageRectOffset'):Connect(function(): ()
					setHeld(jumpButton.ImageRectOffset.X == 146);
				end));
			end;
			Scaffold:Clean(runService.Heartbeat:Connect(function(): ()
				if vape.ThreadFix then
					setthreadidentity(8);
				end;
				if BlockUp["Value"] ~= 'Off' then
					towerStep();
				end;
				local now: number = os.clock();
				if now < nextBridge or not entitylib.isAlive then
					return;
				end;
				nextBridge = now + bridgeInterval;
				bridgeStep();
			end));
		end,
		["Tooltip"] = 'Helps you bridge and scaffold walk, and can tower straight up under you.'
	});
	Expand = Scaffold:CreateSlider({
		["Name"] = 'Expand',
		["Min"] = 1,
		["Max"] = 6
	});
	Tower = Scaffold:CreateToggle({
		["Name"] = 'Tower',
		["Default"] = true,
		["Tooltip"] = 'Boosts you upward while holding jump'
	});
	Downwards = Scaffold:CreateToggle({
		["Name"] = 'Downwards',
		["Default"] = true
	});
	Diagonal = Scaffold:CreateToggle({
		["Name"] = 'Diagonal',
		["Default"] = true
	});
	LimitItem = Scaffold:CreateToggle({
		["Name"] = 'Limit to items',
		["Tooltip"] = 'Only places the block in your hand, never switches or digs through your inventory'
	});
	MouseDown = Scaffold:CreateToggle({
		["Name"] = 'Require mouse down'
	});
	BlockUp = Scaffold:CreateDropdown({
		["Name"] = 'Block up',
		["List"] = {'Off', 'Holding jump', 'When enabled'},
		["Function"] = function(value: string): ()
			if tower.Started then
				stopTower();
			end;
			for _: number, option: table? in {ReturnSlot, Center} do
				if option then
					option.Object.Visible = value ~= 'Off';
				end;
			end;
		end,
		["Tooltip"] = 'Equips blocks and towers under you as fast as the game allows.\nHolding jump: builds while you hold jump and there is room, cancelling that jump.\nWhen enabled: towers whenever Scaffold is on instead of bridging (best with a hold bind)'
	});
	ReturnSlot = Scaffold:CreateToggle({
		["Name"] = 'Return to last slot',
		["Default"] = true,
		["Darker"] = true,
		["Visible"] = false,
		["Tooltip"] = 'Switches back to what you were holding when towering stops'
	});
	Center = Scaffold:CreateToggle({
		["Name"] = 'Center',
		["Default"] = true,
		["Darker"] = true,
		["Visible"] = false,
		["Tooltip"] = 'Keeps you in the middle of your block while standing still so the tower stays one block wide'
	});
	Blacklist = Scaffold:CreateTextList({
		["Name"] = 'Blacklist',
		["Default"] = {'ballista', 'cannon', 'siege_tnt', 'tnt'},
		["Tooltip"] = 'Block types Block up will never place'
	});
	Scaffold:CreateToggle({
		["Name"] = 'Visual',
		["Function"] = function(callback: boolean): ()
			if vape.ThreadFix then
				setthreadidentity(8);
			end;
			for _: number, option: table? in {FillColor, OutlineColor} do
				if option then
					option.Object.Visible = callback;
				end;
			end;
			if previewTween then
				previewTween:Cancel();
				previewTween = nil;
			end;
			if preview then
				preview:Destroy();
				preview, previewCell = nil, nil;
			end;
			if not callback then
				return;
			end;
			local part: Part = Instance.new('Part');
			part.Size = Vector3.new(3, 3, 3);
			part.Anchored = true;
			part.CanCollide = false;
			part.CanQuery = false;
			part.CanTouch = false;
			part.CastShadow = false;
			part.Transparency = 1;
			local selection: SelectionBox = Instance.new('SelectionBox');
			selection.Adornee = part;
			selection.LineThickness = 0.04;
			selection.Color3 = Color3.fromHSV(OutlineColor["Hue"], OutlineColor["Sat"], OutlineColor["Value"]);
			selection.Transparency = 1 - OutlineColor["Opacity"];
			selection.SurfaceColor3 = Color3.fromHSV(FillColor["Hue"], FillColor["Sat"], FillColor["Value"]);
			selection.SurfaceTransparency = 1 - FillColor["Opacity"];
			selection.Parent = part;
			bedwars.QueryUtil:setQueryIgnored(part, true);
			preview = part;
		end,
		["Tooltip"] = 'Outlines the block about to be placed'
	});
	FillColor = Scaffold:CreateColorSlider({
		["Name"] = 'Fill Color',
		["DefaultSat"] = 0,
		["DefaultOpacity"] = 0.4,
		["Darker"] = true,
		["Visible"] = false,
		["Function"] = function(hue: number, sat: number, val: number, opacity: number): ()
			if preview then
				if vape.ThreadFix then
					setthreadidentity(8);
				end;
				preview.SelectionBox.SurfaceColor3 = Color3.fromHSV(hue, sat, val);
				preview.SelectionBox.SurfaceTransparency = 1 - opacity;
			end;
		end
	});
	OutlineColor = Scaffold:CreateColorSlider({
		["Name"] = 'Outline Color',
		["DefaultValue"] = 0,
		["Darker"] = true,
		["Visible"] = false,
		["Function"] = function(hue: number, sat: number, val: number, opacity: number): ()
			if preview then
				if vape.ThreadFix then
					setthreadidentity(8);
				end;
				preview.SelectionBox.Color3 = Color3.fromHSV(hue, sat, val);
				preview.SelectionBox.Transparency = 1 - opacity;
			end;
		end
	});
	Scaffold:CreateToggle({
		["Name"] = 'Block Count',
		["Function"] = function(callback: boolean): ()
			if vape.ThreadFix then
				setthreadidentity(8);
			end;
			destroyHud();
			if callback then
				buildHud();
			end;
		end,
		["Tooltip"] = 'Shows your block count and placement rate. Open the menu and drag it to move it'
	});
	HudPosition = Scaffold:CreateTextBox({
		["Name"] = 'HUD Position',
		["Default"] = '0,60',
		["Visible"] = false,
		["Function"] = function(): ()
			if hud then
				if vape.ThreadFix then
					setthreadidentity(8);
				end;
				hud.Frame.Position = hudOffset();
			end;
		end
	});
end);

velo.run(function(): ()
	local Nuker: table = {["Enabled"] = false};
	local AutoBreak: table = {["Enabled"] = true};
	local Mode: table = {["Value"] = 'Health'};
	local ClosestBreak: table = {["Enabled"] = false};
	local Range: table = {["Value"] = 30};
	local BreakSpeed: table = {["Value"] = 0.25};
	local UpdateRate: table = {["Value"] = 60};
	local Custom: table = {["ListEnabled"] = {}};
	local Bed: table = {["Enabled"] = true};
	local Tesla: table = {["Enabled"] = true};
	local Hive: table = {["Enabled"] = true};
	local LuckyBlock: table = {["Enabled"] = true};
	local IronOre: table = {["Enabled"] = true};
	local Effect: table = {["Enabled"] = true};
	local CustomHealth: table = {["Enabled"] = true};
	local Animation: table = {["Value"] = 'No Animation'};
	local SelfBreak: table = {["Enabled"] = false};
	local Wallcheck: table = {["Enabled"] = true};
	local ViewAngle: table = {["Value"] = 60};
	local AutoTool: table = {["Enabled"] = false};
	local SwitchDelay: table = {};
	local LimitItem: table = {["Enabled"] = false};
	local PlayerCheck: table = {["Enabled"] = false};
	local FastBreak: table = {["Enabled"] = false};
	local FastSpeed: table = {["Value"] = 0.25};
	local BedCheck: table = {["Enabled"] = false};
	local HiveCheck: table = {["Enabled"] = false};
	local UseBlacklist: table = {["Enabled"] = false};
	local Blacklist: table = {["ListEnabled"] = {}};
	local BedAssist: table = {["Enabled"] = false};
	local AssistCurve: table = {["Value"] = 'Simple'};
	local AssistAim: table = {["Value"] = 'Camera'};
	local AssistSpeed: table = {["Value"] = 7};
	local AssistRange: table = {["Value"] = 18};
	local AssistAngle: table = {["Value"] = 60};
	local AssistShake: table = {["Value"] = 3};
	local AssistLimit: table = {["Enabled"] = true};
	local AutoMine: table = {["Enabled"] = true};
	local MineBed: table = {["Enabled"] = true};
	local PhaseMine: table = {["Enabled"] = false};

	local legitCooldown: number = 0.3;
	local pathLength: number = 30;
	local healthbarLifetime: number = 5;
	local assistSearchInterval: number = 0.15;
	local assistDepthRadius: number = 18;
	local assistSearchBudget: number = 512;
	local aimOffsets: {Vector3} = {Vector3.zero, Vector3.xAxis * 1.35, -Vector3.xAxis * 1.35, Vector3.yAxis * 1.35, -Vector3.yAxis * 1.35, Vector3.zAxis * 1.35, -Vector3.zAxis * 1.35};
	local cellSides: {Vector3} = {Vector3.xAxis, -Vector3.xAxis, Vector3.yAxis, -Vector3.yAxis, Vector3.zAxis, -Vector3.zAxis};
	local pathColors: {[string]: Color3} = {["Target"] = Color3.new(1, 0.2, 0.2), ["Hit"] = Color3.new(0.2, 0.2, 1), ["Path"] = Color3.new(0.2, 1, 0.2)};

	local customBlocks: {Instance} = {};
	local blacklistNames: {string} = {};
	local pathParts: {BasePart} = {};
	local activeBlock: Instance? = nil;
	local pathShown: boolean = false;
	local nextBreak: number = 0;
	local fastActive: boolean = false;
	local healthbar: table = {};
	local phased: {[Model]: table} = {};
	local assist: table = {["Search"] = 0, ["Started"] = 0};
	local session: table = {};
	local assistParams: RaycastParams = RaycastParams.new();
	assistParams.FilterType = Enum.RaycastFilterType.Exclude;
	local shield: (block: Instance) -> boolean = function(block: Instance): boolean
		return (block:GetAttribute('BedShieldEndTime') or 0) > workspace:GetServerTimeNow();
	end;
	local ownTeamNoBreak: (block: Instance) -> boolean = function(block: Instance): boolean
		return block:GetAttribute('Team'..(lplr:GetAttribute('Team') or -1)..'NoBreak') ~= nil;
	end;
	local holdingBreaker: () -> boolean = function(): boolean
		local meta: table? = store.hand.tool and bedwars.ItemMeta[store.hand.tool.Name];
		return meta ~= nil and meta.breakBlock ~= nil;
	end;

	local showPath: (position: Vector3?, path: {[Vector3]: Vector3}?, target: Vector3?) -> () = function(position: Vector3?, path: {[Vector3]: Vector3}?, target: Vector3?): ()
		if not position and not pathShown then
			return;
		end;
		pathShown = position ~= nil;
		local node: Vector3? = position;
		for _: number, part: BasePart in pathParts do
			part.Position = node or Vector3.zero;
			if node then
				part.BoxHandleAdornment.Color3 = node == target and pathColors.Target or node == position and pathColors.Hit or pathColors.Path;
			end;
			node = node and path and path[node];
		end;
	end;

	local clearHealthbar: () -> () = function(): ()
		if healthbar.Anchor then
			healthbar.Anchor:Destroy();
		end;
		table.clear(healthbar);
	end;

	local drawHealthbar: (_: table, blockRef: table, health: number, maxHealth: number?, change: number, block: Instance) -> () = function(_: table, blockRef: table, health: number, maxHealth: number?, change: number, block: Instance): ()
		if block:GetAttribute('NoHealthbar') or not maxHealth then
			return;
		end;
		if healthbar.Cell ~= blockRef.blockPosition then
			clearHealthbar();
			local anchor: Attachment = Instance.new('Attachment');
			anchor.WorldPosition = bedwars.BlockController:getWorldPosition(blockRef.blockPosition);
			anchor.Parent = workspace.Terrain;
			local gui: BillboardGui = Instance.new('BillboardGui');
			gui.Size = UDim2.fromOffset(249, 102);
			gui.StudsOffset = Vector3.new(0, 2.5, 0);
			gui.MaxDistance = 40;
			gui.AlwaysOnTop = true;
			gui.Adornee = anchor;
			gui.Parent = anchor;
			local frame: Frame = Instance.new('Frame');
			frame.Size = UDim2.fromOffset(160, 50);
			frame.Position = UDim2.fromOffset(44, 32);
			frame.BackgroundColor3 = Color3.new();
			frame.BackgroundTransparency = 0.5;
			frame.Parent = gui;
			Instance.new('UICorner', frame).CornerRadius = UDim.new(0, 5);
			addBlur(frame);
			local meta: table? = bedwars.ItemMeta[block.Name];
			for _: number, shade: table in {{["Offset"] = 13, ["Color"] = Color3.new()}, {["Offset"] = 12, ["Color"] = color.Dark(uipallet.Text, 0.16)}} do
				local title: TextLabel = Instance.new('TextLabel');
				title.Size = UDim2.fromOffset(145, 14);
				title.Position = UDim2.fromOffset(shade.Offset, shade.Offset - 1);
				title.BackgroundTransparency = 1;
				title.Text = meta and meta.displayName or block.Name;
				title.TextXAlignment = Enum.TextXAlignment.Left;
				title.TextYAlignment = Enum.TextYAlignment.Top;
				title.TextColor3 = shade.Color;
				title.TextScaled = true;
				title.Font = Enum.Font.Arial;
				title.Parent = frame;
			end;
			local bar: Frame = Instance.new('Frame');
			bar.Size = UDim2.fromOffset(138, 4);
			bar.Position = UDim2.fromOffset(12, 32);
			bar.BackgroundColor3 = uipallet.Main;
			bar.Parent = frame;
			Instance.new('UICorner', bar).CornerRadius = UDim.new(1, 0);
			local start: number = math.clamp(health / maxHealth, 0, 1);
			local fill: Frame = Instance.new('Frame');
			fill.Size = UDim2.fromScale(start, 1);
			fill.BackgroundColor3 = Color3.fromHSV(math.clamp(start / 2.5, 0, 1), 0.89, 0.75);
			fill.Parent = bar;
			Instance.new('UICorner', fill).CornerRadius = UDim.new(1, 0);
			local token: table = {};
			healthbar.Anchor, healthbar.Fill, healthbar.Cell, healthbar.Token = anchor, fill, blockRef.blockPosition, token;
			task.delay(healthbarLifetime, function(): ()
				if healthbar.Token == token then
					clearHealthbar();
				end;
			end);
		end;
		local percent: number = math.clamp((health - change) / maxHealth, 0, 1);
		tweenService:Create(healthbar.Fill, TweenInfo.new(0.3), {["Size"] = UDim2.fromScale(percent, 1), ["BackgroundColor3"] = Color3.fromHSV(math.clamp(percent / 2.5, 0, 1), 0.89, 0.75)}):Play();
	end;

	local fastAllowed: (block: Instance?) -> boolean = function(block: Instance?): boolean
		if not block or (BedCheck["Enabled"] and block.Name == 'bed') or (HiveCheck["Enabled"] and block.Name == 'beehive') then
			return false;
		end;
		for _: number, name: string in (UseBlacklist["Enabled"] and blacklistNames or {}) do
			if block.Name:find(name, 1, true) then
				return false;
			end;
		end;
		return true;
	end;

	local phaseCharacter: (character: Model) -> () = function(character: Model): ()
		if phased[character] then
			return;
		end;
		local entry: table = {["Parts"] = {}, ["Connections"] = {}};
		phased[character] = entry;
		local ignore: (part: Instance) -> () = function(part: Instance): ()
			if part:IsA('BasePart') then
				table.insert(entry.Parts, part);
				bedwars.QueryUtil:setQueryIgnored(part, true);
			end;
		end;
		for _: number, part: Instance in character:GetDescendants() do
			ignore(part);
		end;
		table.insert(entry.Connections, character.ChildAdded:Connect(ignore));
		table.insert(entry.Connections, character.Destroying:Connect(function(): ()
			for _: number, connection: RBXScriptConnection in entry.Connections do
				connection:Disconnect();
			end;
			phased[character] = nil;
		end));
	end;
	local unphase: () -> () = function(): ()
		for _: Model, entry: table in phased do
			for _: number, connection: RBXScriptConnection in entry.Connections do
				connection:Disconnect();
			end;
			for _: number, part: BasePart in entry.Parts do
				if part.Parent then
					bedwars.QueryUtil:setQueryIgnored(part, false);
				end;
			end;
		end;
		table.clear(phased);
	end;
	local phaseEveryone: () -> () = function(): ()
		for _: number, ent: table in entitylib.List do
			if ent.Player and ent.Player ~= lplr and ent.Character then
				phaseCharacter(ent.Character);
			end;
		end;
	end;

	local containedCells: (block: Instance) -> {Vector3} = function(block: Instance): {Vector3}
		local handler: table? = bedwars.BlockController:getHandlerRegistry():getHandler(block.Name);
		return handler and handler:getContainedPositions(block) or {bedwars.BlockController:getBlockPosition(block.Position)};
	end;

	local pickBlock: (entry: table, origin: Vector3, mouseRay: Ray, mouseHit: Instance?, playerParams: RaycastParams) -> Instance? = function(entry: table, origin: Vector3, mouseRay: Ray, mouseHit: Instance?, playerParams: RaycastParams): Instance?
		local chosen: Instance?, best: number = nil, math.huge;
		for _: number, block: Instance in entry.List do
			local distance: number = math.huge;
			for _: number, cell: Vector3 in containedCells(block) do
				if bedwars.BlockController:isBlockBreakable({["blockPosition"] = cell}, lplr) then
					distance = math.min(distance, (cell * 3 - origin).Magnitude);
				end;
			end;
			if distance >= Range["Value"] or shield(block) or (not SelfBreak["Enabled"] and block:GetAttribute('PlacedByUserId') == lplr.UserId) then
				continue;
			end;
			if entry.TeamCheck then
				local placer: Player? = playersService:GetPlayerByUserId(block:GetAttribute('PlacedByUserId') or 0);
				if placer and placer:GetAttribute('Team') == lplr:GetAttribute('Team') then
					continue;
				end;
			end;
			if block ~= activeBlock and Wallcheck["Enabled"] and not ClosestBreak["Enabled"] and ViewAngle["Value"] < 180 then
				local offset: Vector3 = block.Position - gameCamera.CFrame.Position;
				if offset.Magnitude > 0 and math.deg(math.acos(math.clamp(offset.Unit:Dot(gameCamera.CFrame.LookVector), -1, 1))) > ViewAngle["Value"] then
					continue;
				end;
			end;
			if (LimitItem["Enabled"] and not holdingBreaker()) or (PlayerCheck["Enabled"] and workspace:Raycast(entitylib.character.Head.Position, block.Position - entitylib.character.Head.Position, playerParams)) then
				continue;
			end;
			if block == activeBlock then
				return block;
			end;
			local score: number = distance;
			if ClosestBreak["Enabled"] and block ~= mouseHit then
				local offset: Vector3 = block.Position - mouseRay.Origin;
				local along: number = offset:Dot(mouseRay.Direction);
				score = along > 0 and (offset - mouseRay.Direction * along).Magnitude or offset.Magnitude;
			end;
			if score < best then
				chosen, best = block, score;
			end;
		end;
		return chosen;
	end;

	local aimAt: (block: Instance, position: Vector3, direction: Vector3) -> Vector3? = function(block: Instance, position: Vector3, direction: Vector3): Vector3?
		local eye: Vector3 = gameCamera.CFrame.Position;
		for _: number, offset: Vector3 in aimOffsets do
			if block.Name == 'bed' and (offset == Vector3.zero or getPlacedBlock(position + offset.Unit * 3)) then
				continue;
			end;
			local delta: Vector3 = position + offset - eye;
			if delta.Magnitude <= 0.001 or delta.Unit:Dot(direction) < math.cos(math.rad(AssistAngle["Value"])) then
				continue;
			end;
			local hit: RaycastResult? = bedwars.QueryUtil:raycast(eye, delta.Unit * (delta.Magnitude + 3), assistParams);
			if not hit or (hit.Instance ~= block and not hit.Instance:IsDescendantOf(block)) then
				continue;
			end;
			if block.Name == 'bed' then
				local nearest: Vector3?, gap: number = nil, math.huge;
				for _: number, cell: Vector3 in containedCells(block) do
					local separation: number = (cell * 3 - (hit.Position - hit.Normal * 0.1)).Magnitude;
					if separation < gap then
						nearest, gap = cell * 3, separation;
					end;
				end;
				if nearest ~= position then
					continue;
				end;
			end;
			return hit.Position;
		end;
		return nil;
	end;

	local assistRoute: (bed: Instance, direction: Vector3, reach: number) -> (Instance?, Vector3?, number, number, number) = function(bed: Instance, direction: Vector3, reach: number): (Instance?, Vector3?, number, number, number)
		local blockStore: table = bedwars.BlockController:getStore();
		local cells: {Vector3} = containedCells(bed);
		local origin: Vector3 = entitylib.character.RootPart.Position;
		local queue: {table}, costs: {[Vector3]: number}, depths: {[Vector3]: number}, visited: {[Vector3]: boolean} = {}, {}, {}, {};
		local chosen: Instance?, chosenPosition: Vector3? = nil, nil;
		local cost: number, depth: number, spread: number, gap: number = math.huge, math.huge, math.huge, math.huge;
		for _: number, cell: Vector3 in cells do
			if blockStore:getBlockAt(cell) == bed then
				costs[cell], depths[cell] = 0, 0;
				table.insert(queue, {["Cell"] = cell, ["Cost"] = 0, ["Depth"] = 0});
			end;
		end;
		for _: number = 1, assistSearchBudget do
			local index: number?, node: table? = nil, nil;
			for slot: number, entry: table in queue do
				if not node or entry.Cost < node.Cost or (entry.Cost == node.Cost and entry.Depth < node.Depth) then
					index, node = slot, entry;
				end;
			end;
			if not node or node.Cost > cost then
				break;
			end;
			table.remove(queue, index);
			if visited[node.Cell] then
				continue;
			end;
			visited[node.Cell] = true;
			local current: Instance? = blockStore:getBlockAt(node.Cell);
			local position: Vector3 = node.Cell * 3;
			local distance: number = (origin - position).Magnitude;
			local nodeSpread: number = math.huge;
			for _: number, cell: Vector3 in cells do
				nodeSpread = math.min(nodeSpread, (node.Cell - cell).Magnitude);
			end;
			if current and distance <= reach and aimAt(current, position, direction) and (node.Cost < cost or node.Depth < depth or (node.Depth == depth and (nodeSpread < spread or (nodeSpread == spread and ((current == assist.Target and chosen ~= assist.Target) or ((current == assist.Target) == (chosen == assist.Target) and distance < gap)))))) then
				chosen, chosenPosition, cost, depth, spread, gap = current, position, node.Cost, node.Depth, nodeSpread, distance;
			end;
			for _: number, side: Vector3 in cellSides do
				local nextCell: Vector3 = node.Cell + side;
				local nextBlock: Instance? = not visited[nextCell] and (nextCell * 3 - bed.Position).Magnitude <= assistDepthRadius and blockStore:getBlockAt(nextCell) or nil;
				local meta: table? = nextBlock and bedwars.ItemMeta[nextBlock.Name];
				if meta and meta.block and not nextBlock:GetAttribute('NoBreak') and not ownTeamNoBreak(nextBlock) and bedwars.BlockController:isBlockBreakable({["blockPosition"] = nextCell}, lplr) then
					local data: Instance? = blockStore:getBlockData(nextCell);
					local health: number? = data and data:GetAttribute(bedwars.BlockBreaker.blockHealthbar:getHealthKey(nextBlock)) or nextBlock:GetAttribute('Health') or meta.block.health;
					local damage: number = bedwars.BlockController:calculateBlockDamage(lplr, {["blockPosition"] = nextCell});
					if damage > 0 then
						local hits: number = node.Cost + math.max(math.ceil((health or 10) / damage), 1);
						if hits < (costs[nextCell] or math.huge) or (hits == costs[nextCell] and node.Depth + 1 < depths[nextCell]) then
							costs[nextCell], depths[nextCell] = hits, node.Depth + 1;
							table.insert(queue, {["Cell"] = nextCell, ["Cost"] = hits, ["Depth"] = node.Depth + 1});
						end;
					end;
				end;
			end;
		end;
		return chosen, chosenPosition, cost, depth, gap;
	end;

	Nuker = vape.Categories.World:CreateModule({
		["Name"] = 'Nuker',
		["Function"] = function(callback: boolean): ()
			if not callback then
				return;
			end;
			activeBlock, nextBreak, fastActive, pathShown = nil, 0, false, false;
			session = {};
			assist.Target, assist.Bed, assist.Position, assist.Search, assist.Started = nil, nil, nil, 0, 0;
			for _: number = 1, pathLength do
				local part: Part = Instance.new('Part');
				part.Anchored = true;
				part.CanQuery = false;
				part.CanCollide = false;
				part.Transparency = 1;
				part.Parent = gameCamera;
				local highlight: BoxHandleAdornment = Instance.new('BoxHandleAdornment');
				highlight.Size = Vector3.one;
				highlight.AlwaysOnTop = true;
				highlight.ZIndex = 1;
				highlight.Transparency = 0.5;
				highlight.Adornee = part;
				highlight.Parent = part;
				table.insert(pathParts, part);
				Nuker:Clean(part);
			end;
			customBlocks = collection('block', Nuker, function(list: table, block: Instance, tag: string): ()
				if table.find(Custom.ListEnabled, block.Name) then
					table.insert(list, block);
				end;
			end);
			local beds: {Instance} = collection('bed', Nuker);
			local targets: {table} = {
				{["List"] = beds, ["Option"] = Bed, ["Route"] = true},
				{["List"] = collection('beehive', Nuker), ["Option"] = Hive, ["TeamCheck"] = true},
				{["List"] = collection('tesla-trap', Nuker), ["Option"] = Tesla, ["TeamCheck"] = true},
				{["List"] = collection('iron_ore_mesh_block', Nuker), ["Option"] = IronOre},
				{["List"] = collection('LuckyBlock', Nuker), ["Option"] = LuckyBlock},
				{["List"] = customBlocks}
			};
			local mouseParams: RaycastParams = RaycastParams.new();
			mouseParams.FilterType = Enum.RaycastFilterType.Exclude;
			local playerParams: RaycastParams = RaycastParams.new();
			playerParams.FilterType = Enum.RaycastFilterType.Include;
			local assistMaid: table = rawget(getmetatable(bedwars.BlockBreaker.maid), 'new')();
			local random: Random = Random.new();

			Nuker:Clean(function(): ()
				session.Cancelled = true;
				if store.breakTool and store.breakTool.session == session then
					store.breakTool = nil;
				end;
				assistMaid:DoCleaning();
				table.clear(pathParts);
				activeBlock, pathShown = nil, false;
				clearHealthbar();
				if fastActive then
					bedwars.BlockBreaker:setCooldown(legitCooldown);
				end;
				unphase();
			end);

			blockHitHooks.Nuker = function(breaker: table, _: table, mouseRay: any): ()
				if not FastBreak["Enabled"] then
					return;
				end;
				local info: table? = breaker.clientManager:getBlockSelector():getMouseInfo(1, {["ray"] = mouseRay});
				if fastAllowed(info and info.target and info.target.blockInstance) then
					fastActive = true;
					breaker:setCooldown(FastSpeed["Value"]);
				end;
			end;
			Nuker:Clean(function(): ()
				blockHitHooks.Nuker = nil;
			end);

			local previousHit: (...any) -> ...any = bedwars.BlockBreaker.hitBlock;
			local pending: table? = nil;
			local assistHit: (...any) -> ...any;
			assistHit = function(breaker: table, maid: table, mouseRay: any, ...: any): ...any
				if not BedAssist["Enabled"] or not MineBed["Enabled"] then
					return previousHit(breaker, maid, mouseRay, ...);
				end;
				local info: table? = breaker.clientManager:getBlockSelector():getMouseInfo(1, {["ray"] = mouseRay, ["range"] = math.min(AssistRange["Value"], breaker:getRange())});
				local selected: table? = info and info.target;
				if not selected or selected.blockInstance.Name ~= 'bed' then
					return previousHit(breaker, maid, mouseRay, ...);
				end;
				local block: Instance = selected.blockInstance;
				local timeout: number = math.max(1, lplr:GetNetworkPing() * 4 + 0.5);
				if (pending and tick() - pending.Sent < timeout) or not entitylib.isAlive or store.matchState ~= 1 or lplr:GetAttribute('DenyBlockBreak') or tick() - breaker.lastHitTime < breaker:getCooldown() or not bedwars.BlockController:isBlockBreakable(selected.blockRef, lplr) or ownTeamNoBreak(block) or shield(block) then
					return nil;
				end;
				local data: Instance? = bedwars.BlockController:getStore():getBlockData(selected.blockRef.blockPosition);
				local healthKey: string = breaker.blockHealthbar:getHealthKey(block);
				local before: number = data and data:GetAttribute(healthKey) or block:GetAttribute('Health');
				local request: table = {["Sent"] = tick()};
				pending = request;
				breaker.lastHitTime = tick();
				store.lastHit = breaker.lastHitTime;
				for _: string, hook: (...any) -> () in blockHitHooks do
					hook(breaker, maid, mouseRay, ...);
				end;
				local track: AnimationTrack? = bedwars.AnimationUtil:playAnimation(lplr, bedwars.BlockController:getAnimationController():getAssetId(1));
				if track then
					maid:GiveTask(function(): ()
						track:Stop();
						track:Destroy();
					end);
				end;
				breaker.onBreak:Fire();
				bedwars.ClientDamageBlock:Get('DamageBlock'):CallServerAsync({
					["blockRef"] = selected.blockRef,
					["hitPosition"] = selected.hitPosition,
					["hitNormal"] = selected.hitNormal
				}):andThen(function(result: any): ()
					if pending == request then
						pending = nil;
					end;
					if not Nuker["Enabled"] or not BedAssist["Enabled"] then
						return;
					end;
					if result == 'destroyed' then
						breaker.blockHealthbar:destroy();
						breaker.breakTextureHandler:removeTexture(selected.blockRef);
						if bedwars.BlockController:getStore():getBlockAt(selected.blockRef.blockPosition) == block then
							bedwars.BlockController:destroyBlock(selected.blockRef);
						end;
						breaker.breakEffect:playBreak(block.Name, selected.blockRef.blockPosition, lplr);
					elseif result == 'damaged' then
						local after: number = data and data:GetAttribute(healthKey) or block:GetAttribute('Health');
						breaker:updateHealthbar(selected.blockRef, before, block:GetAttribute('MaxHealth'), math.max(before - after, 0), block);
						breaker.breakEffect:playHit(block.Name, selected.blockRef.blockPosition, lplr);
					end;
					assist.Search = 0;
				end):catch(function(): ()
					if pending == request then
						pending = nil;
					end;
					if Nuker["Enabled"] and BedAssist["Enabled"] then
						assist.Search = 0;
					end;
				end);
				return nil;
			end;
			bedwars.BlockBreaker.hitBlock = assistHit;
			Nuker:Clean(function(): ()
				if bedwars.BlockBreaker.hitBlock == assistHit then
					bedwars.BlockBreaker.hitBlock = previousHit;
				end;
			end);

			if PhaseMine["Enabled"] then
				phaseEveryone();
			end;
			Nuker:Clean(entitylib.Events.EntityAdded:Connect(function(ent: table): ()
				if ent.Player and PhaseMine["Enabled"] then
					task.delay(1, function(): ()
						if Nuker["Enabled"] and PhaseMine["Enabled"] and ent.Character then
							phaseCharacter(ent.Character);
						end;
					end);
				end;
			end));

			Nuker:Clean(runService.Heartbeat:Connect(function(): ()
				if fastActive and (not FastBreak["Enabled"] or tick() - (store.lastHit or 0) > legitCooldown) then
					fastActive = false;
					bedwars.BlockBreaker:setCooldown(legitCooldown);
				end;
			end));

			Nuker:Clean(runService.PostSimulation:Connect(function(delta: number): ()
				if not BedAssist["Enabled"] or not entitylib.isAlive or store.matchState ~= 1 or lplr:GetAttribute('Spectator') or lplr:GetAttribute('DenyBlockBreak') or inputService:GetFocusedTextBox() or guiService.MenuIsOpen or bedwars.AppController:isLayerOpen(bedwars.UILayers.MAIN) or (AssistLimit["Enabled"] and not holdingBreaker()) then
					assist.Target, assist.Bed, assist.Position, assist.Search = nil, nil, nil, 0;
					return;
				end;
				local reach: number = math.min(AssistRange["Value"], bedwars.BlockBreaker:getRange());
				local mouse: Vector2 = inputService.MouseEnabled and inputService:GetMouseLocation() or gameCamera.ViewportSize / 2;
				local mouseRay: Ray = gameCamera:ViewportPointToRay(mouse.X, mouse.Y);
				local origin: Vector3 = entitylib.character.RootPart.Position;
				assistParams.FilterDescendantsInstances = {lplr.Character, gameCamera};
				if tick() >= assist.Search or (assist.Target and not assist.Target.Parent) then
					local chosen: Instance?, chosenBed: Instance?, chosenPosition: Vector3? = nil, nil, nil;
					local cost: number, depth: number, gap: number = math.huge, math.huge, math.huge;
					for _: number, bed: Instance in beds do
						if not bed.Parent or ownTeamNoBreak(bed) or shield(bed) or (bed.Position - origin).Magnitude > AssistRange["Value"] + 3 or not bedwars.BlockController:isBlockBreakable({["blockPosition"] = bedwars.BlockController:getBlockPosition(bed.Position)}, lplr) then
							continue;
						end;
						local block: Instance?, position: Vector3?, routeCost: number, routeDepth: number, routeGap: number = assistRoute(bed, mouseRay.Direction, reach);
						if block and (routeCost < cost or (routeCost == cost and (routeDepth < depth or (routeDepth == depth and routeGap < gap)))) then
							chosen, chosenBed, chosenPosition, cost, depth, gap = block, bed, position, routeCost, routeDepth, routeGap;
						end;
					end;
					if chosen ~= assist.Target then
						assist.Started = tick();
					end;
					assist.Target, assist.Bed, assist.Position, assist.Search = chosen, chosenBed, chosenPosition, tick() + assistSearchInterval;
				end;
				local target: Instance? = assist.Target;
				if not target or not target.Parent or not assist.Bed.Parent or ownTeamNoBreak(assist.Bed) or shield(assist.Bed) or (target == assist.Bed and not MineBed["Enabled"]) or (origin - assist.Position).Magnitude > reach then
					return;
				end;
				local aimPoint: Vector3? = aimAt(target, assist.Position, mouseRay.Direction);
				if not aimPoint then
					return;
				end;
				local speed: number = AssistSpeed["Value"];
				if AssistCurve["Value"] == 'Adaptive' then
					local progress: number = math.clamp((tick() - assist.Started) * speed * 0.5, 0, 1);
					speed *= progress < 0.5 and 4 * progress ^ 3 or 1 - (-2 * progress + 2) ^ 3 / 2;
				end;
				local alpha: number = 1 - math.exp(-speed * delta);
				local aim: Vector3 = aimPoint + Vector3.new(random:NextNumber(-1, 1), random:NextNumber(-1, 1), random:NextNumber(-1, 1)) * AssistShake["Value"] * 0.005;
				if AssistAim["Value"] == 'Mouse' then
					local screen: Vector3, visible: boolean = gameCamera:WorldToViewportPoint(aim);
					if visible then
						local move: Vector2 = (Vector2.new(screen.X, screen.Y) - mouse) * alpha;
						mousemoverel(move.X, move.Y);
					end;
				else
					local direction: Vector3 = (aim - mouseRay.Origin).Unit;
					local axis: Vector3 = mouseRay.Direction:Cross(direction);
					if axis.Magnitude > 0.0001 then
						local turn: CFrame = CFrame.fromAxisAngle(axis.Unit, math.acos(math.clamp(mouseRay.Direction:Dot(direction), -1, 1)) * alpha);
						gameCamera.CFrame = CFrame.new(gameCamera.CFrame.Position) * turn * gameCamera.CFrame.Rotation;
					end;
				end;
				if AutoMine["Enabled"] and not inputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) and tick() - bedwars.BlockBreaker.lastHitTime >= bedwars.BlockBreaker:getCooldown() then
					local ray: Ray = gameCamera:ViewportPointToRay(mouse.X, mouse.Y);
					local info: table? = bedwars.BlockBreaker.clientManager:getBlockSelector():getMouseInfo(1, {["ray"] = ray, ["range"] = reach});
					if info and info.target and info.target.blockInstance == target then
						assistMaid:DoCleaning();
