velo.run(function(): ()
	local FastConsume: table = {["Enabled"] = false};
	local Multiplier: table;
	local normalSpeed: number = 40;
	local serverTolerance: number = 0.2;

	FastConsume = vape.Categories.Inventory:CreateModule({
		["Name"] = 'FastConsume',
		["Function"] = function(callback: boolean): ()
			if not callback then
				return;
			end;
			local clickHold: table = bedwars.ClickHold;
			local oldStartClick: (...any) -> ...any = clickHold.startClick;
			local oldShowProgress: (...any) -> ...any = clickHold.showProgress;
			clickHold.startClick = function(self: table): ()
				self.startedClickTime = tick();
				local duration: number = math.max(self.durationSeconds * (Multiplier["Value"] / normalSpeed), self.durationSeconds - serverTolerance);
				local handle: any = self:showProgress(duration);
				local started: number = self.startedClickTime;
				bedwars.RuntimeLib.Promise.defer(function(): ()
					task.wait(duration);
					if handle ~= self.handle or started ~= self.startedClickTime or not self.closeOnComplete then
						return;
					end;
					self:hideProgress();
					if self.onComplete then
						self.onComplete();
					end;
					if self.onPartialComplete then
						self.onPartialComplete(1);
					end;
					self.startedClickTime = -1;
				end);
			end;
			clickHold.showProgress = function(self: table, duration: number): any
				local roact: table = debug.getupvalue(oldShowProgress, 1);
				local handle: any = roact.mount(roact.createElement('ScreenGui', {}, {
					roact.createElement('Frame', {
						[roact.Ref] = self.wrapperRef,
						["Size"] = UDim2.new(),
						["Position"] = UDim2.fromScale(0.5, 0.55),
						["AnchorPoint"] = Vector2.new(0.5, 0),
						["BackgroundColor3"] = Color3.fromRGB(0, 0, 0),
						["BackgroundTransparency"] = 0.8
					}, {
						roact.createElement('Frame', {
							[roact.Ref] = self.progressRef,
							["Size"] = UDim2.fromScale(0, 1),
							["BackgroundColor3"] = Color3.new(1, 1, 1),
							["BackgroundTransparency"] = 0.5
						})
					})
				}), lplr:FindFirstChild('PlayerGui'));
				self.handle = handle;
				local grow: Tween = tweenService:Create(self.wrapperRef:getValue(), TweenInfo.new(0.1), {["Size"] = UDim2.fromScale(0.11, 0.005)});
				local fill: Tween = tweenService:Create(self.progressRef:getValue(), TweenInfo.new(duration, Enum.EasingStyle.Linear), {["Size"] = UDim2.fromScale(1, 1)});
				grow:Play();
				fill:Play();
				table.insert(self.tweens, fill);
				table.insert(self.tweens, grow);
				return handle;
			end;
			FastConsume:Clean(function(): ()
				clickHold.startClick = oldStartClick;
				clickHold.showProgress = oldShowProgress;
			end);
		end,
		["Tooltip"] = 'Use/Consume items quicker.'
	});
	Multiplier = FastConsume:CreateSlider({
		["Name"] = 'Multiplier',
		["Min"] = 0,
		["Max"] = 100,
		["Tooltip"] = '40 is normal speed, lower is faster\nThe server throws away anything finished more than about 0.25s early, so it never goes past 0.2s faster'
	});
end);

velo.run(function(): ()
	local FastDrop: table = {["Enabled"] = false};
	local idlePoll: number = 0.1;

	FastDrop = vape.Categories.Inventory:CreateModule({
		["Name"] = 'FastDrop',
		["Function"] = function(callback: boolean): ()
			if not callback then
				return;
			end;
			repeat
				if entitylib.isAlive and not store.inventory.opened and (inputService:IsKeyDown(Enum.KeyCode.H) or inputService:IsKeyDown(Enum.KeyCode.Backspace)) and inputService:GetFocusedTextBox() == nil then
					task.spawn(bedwars.ItemDropController.dropItemInHand);
					task.wait();
				else
					task.wait(idlePoll);
				end;
			until not FastDrop["Enabled"];
		end,
		["Tooltip"] = 'Drops items fast while you hold H or Backspace.'
	});
end);

