		optionApi.Save = function(self: table, data: table): ()
			local saved: {table} = {};
			for _: number, layout: table in self.Hotbars do
				table.insert(saved, layout.Hotbar);
			end;
			data.HotbarList = {["Selected"] = self.Selected, ["Hotbars"] = saved};
		end;

		optionApi.Load = function(self: table, data: table): ()
			for _: number, layout: table in self.Hotbars do
				layout.Object:Destroy();
			end;
			table.clear(self.Hotbars);
			for _: number, hotbar: table in data.Hotbars do
				self:AddHotbar(hotbar);
