	local resolveItem: (itemType: string) -> string = function(itemType: string): string
		local best: {string}? = bestOf[itemType];
		if best then
			local tool: table? = store.tools[best[1]];
			return tool and tool.itemType or best[2];
		end;
		if itemType == 'wood_bow' then
			local bow: table? = getBow();
			return bow and bow.itemType or itemType;
		end;
		if itemType == 'wool_white' then
			local items: {table} = table.clone(store.inventory.inventory.items);
			table.sort(items, function(a: table, b: table): boolean
				return a.amount < b.amount;
			end);
			for _: number, item: table in items do
				local block: table? = bedwars.ItemMeta[item.itemType] and bedwars.ItemMeta[item.itemType].block;
				if block and not block.seeThrough then
					return item.itemType;
				end;
			end;
		end;
		return itemType;
	end;

	local sortHotbar: () -> () = function(): ()
		local layout: table? = List.Hotbars[List.Selected];
		local wanted: {[string]: string} = {};
		for slot: string, itemType: string in (layout and layout.Hotbar or {}) do
			wanted[slot] = resolveItem(itemType);
		end;
		local placed: {[number]: boolean} = {};
		for slot: number = 1, 9 do
			local held: table? = store.inventory.hotbar[slot];
			if wanted[tostring(slot)] and held and held.item and held.item.itemType == wanted[tostring(slot)] then
				placed[slot - 1] = true;
			end;
		end;
		for slot: number = 1, 9 do
			local itemType: string? = wanted[tostring(slot)];
			if not itemType or placed[slot - 1] then
				continue;
			end;
			local source: table? = nil;
			for _: number, entry: table in inventorySlots() do
				if entry.itemType == itemType and entry.container ~= 'armor' and not (entry.container == 'hotbar' and placed[entry.index]) then
					source = entry;
					break;
				end;
			end;
			if source and moveSlot({
				["operation"] = 'swap_hotbar',
				["slot"] = {["container"] = source.container, ["index"] = source.index},
				["target"] = {["container"] = 'hotbar', ["index"] = slot - 1}
			}) then
				local deadline: number = os.clock() + settleTime;
				repeat
					task.wait();
					local held: table? = store.inventory.hotbar[slot];
				until held and held.item and held.item.itemType == itemType or os.clock() > deadline;
			end;
		end;
		if Clear["Enabled"] then
			local keep: {[string]: boolean} = {};
			for _: string, itemType: string in wanted do
				keep[itemType] = true;
			end;
			for _: number, entry: table in table.clone(inventorySlots()) do
				if entry.container == 'hotbar' and not keep[entry.itemType] then
					moveSlot({["operation"] = 'quick_move', ["slot"] = {["container"] = 'hotbar', ["index"] = entry.index}});
				end;
			end;
		end;
	end;

	local runSort: () -> () = function(): ()
		if sorting then
			return;
		end;
		sorting = true;
		pcall(sortHotbar);
		sorting = false;
	end;

	AutoHotbar = vape.Categories.Inventory:CreateModule({
		["Name"] = 'AutoHotbar',
		["Function"] = function(callback: boolean): ()
			if not callback then
				return;
			end;
			task.spawn(runSort);
			if Mode["Value"] == 'On Key' then
				AutoHotbar:Toggle();
				return;
			end;
			AutoHotbar:Clean(vapeEvents.InventoryAmountChanged.Event:Connect(runSort));
		end,
		["Tooltip"] = 'Automatically arranges hotbar to your liking.'
	});
	Mode = AutoHotbar:CreateDropdown({
		["Name"] = 'Activation',
		["List"] = {'Toggle', 'On Key'},
		["Function"] = function(): ()
			if AutoHotbar["Enabled"] then
				AutoHotbar:Toggle();
				AutoHotbar:Toggle();
			end;
		end
	});
	Clear = AutoHotbar:CreateToggle({["Name"] = 'Clear Hotbar'});
	List = AutoHotbar:CreateHotbarList({});
end);

velo.run(function(): ()
	local AutoPChest: table = {["Enabled"] = false};
	local Items: table;
	local OnEnemy: table;
	local EnemyRange: table;
	local BankSplit: table;
	local EnemyBaseOnly: table;
	local Minimum: table;
	local ChestRange: table;
	local Delay: table;
	local scanRate: number = 0.1;
	local nextScan: number = 0;
	local nextDeposit: number = 0;

	local partOf: (object: Instance) -> BasePart? = function(object: Instance): BasePart?
		if object:IsA('Model') then
			return object.PrimaryPart or object:FindFirstChildWhichIsA('BasePart', true);
		end;
		return object:IsA('BasePart') and object or nil;
	end;

	AutoPChest = vape.Categories.Inventory:CreateModule({
		["Name"] = 'AutoPChest',
		["Function"] = function(callback: boolean): ()
			if not callback then
				return;
			end;
			nextDeposit = 0;
			AutoPChest:Clean(runService.Heartbeat:Connect(function(): ()
				local now: number = tick();
				if now < nextScan then
					return;
				end;
				nextScan = now + scanRate;
				if store.matchState == 0 or not entitylib.isAlive or now < nextDeposit or #Items.ListEnabled == 0 then
					return;
				end;
				local origin: Vector3 = entitylib.character.RootPart.Position;
				local atChest: boolean = false;
				for _: number, chest: Instance in collectionService:GetTagged('personal-chest') do
					local part: BasePart? = partOf(chest);
					if part and (part.Position - origin).Magnitude <= ChestRange["Value"] then
						atChest = true;
						break;
					end;
				end;
				if not atChest then
					return;
				end;
				local threatened: boolean = false;
				for _: number, ent: table in (OnEnemy["Enabled"] and entitylib.List or {}) do
					if ent.Player and ent.Targetable and ent.Health > 0 and ent.RootPart and (ent.RootPart.Position - origin).Magnitude <= EnemyRange["Value"] then
						threatened = true;
						break;
					end;
				end;
				local splitting: boolean = false;
				if not threatened and BankSplit["Enabled"] then
					splitting = not EnemyBaseOnly["Enabled"];
					local closest: number = math.huge;
					for _: number, crate: Instance in (splitting and {} or collectionService:GetTagged('team-crate')) do
						local part: BasePart? = partOf(crate);
						if part and (part.Position - origin).Magnitude < closest then
							closest = (part.Position - origin).Magnitude;
							splitting = crate:GetAttribute('Team') ~= lplr:GetAttribute('Team');
						end;
					end;
				end;
				if not threatened and not splitting then
					return;
				end;
				nextDeposit = now + Delay["Value"];
				local inventories: Instance? = replicatedStorage:FindFirstChild('Inventories');
				local personal: Instance? = inventories and inventories:FindFirstChild(lplr.Name..'_personal');
				if not personal then
					return;
				end;
				local giveItem: any = bedwars.Client:GetNamespace('Inventory'):Get('ChestGiveItem');
				local minimum: number = threatened and 1 or Minimum["Value"];
				for _: number, itemType: string in Items.ListEnabled do
					local item: table? = getItem(itemType);
					if item and (item.amount or 1) >= minimum then
						task.spawn(giveItem.CallServer, giveItem, personal, item.tool);
					end;
				end;
			end));
		end,
		["Tooltip"] = 'Banks your loot in your personal chest when an enemy gets close, or banks the split whenever you stand at one.'
	});
	Items = AutoPChest:CreateTextList({
		["Name"] = 'Items',
		["Default"] = {'diamond', 'emerald'},
		["Tooltip"] = 'What gets banked, add iron or gold if you want those safe too'
	});
	OnEnemy = AutoPChest:CreateToggle({
		["Name"] = 'Enemy nearby',
		["Default"] = true,
		["Tooltip"] = 'Bank everything listed when an enemy gets close'
	});
	EnemyRange = AutoPChest:CreateSlider({
		["Name"] = 'Enemy range',
		["Min"] = 1,
		["Max"] = 60,
		["Default"] = 25,
		["Darker"] = true,
		["Suffix"] = function(value: number): string
			return value <= 1 and 'stud' or 'studs';
		end
	});
	BankSplit = AutoPChest:CreateToggle({
		["Name"] = 'Bank split',
		["Tooltip"] = 'Bank the split the moment you are stood at a personal chest'
	});
	EnemyBaseOnly = AutoPChest:CreateToggle({
		["Name"] = 'Enemy base only',
		["Default"] = true,
		["Darker"] = true,
		["Tooltip"] = 'Only bank the split at a chest that is closer to their generator than yours'
	});
	Minimum = AutoPChest:CreateSlider({
		["Name"] = 'Minimum',
		["Min"] = 1,
		["Max"] = 64,
		["Default"] = 1,
		["Darker"] = true,
		["Tooltip"] = 'Split banking leaves a stack alone until you are holding this many'
	});
	ChestRange = AutoPChest:CreateSlider({
		["Name"] = 'Chest range',
		["Min"] = 1,
		["Max"] = 20,
		["Default"] = 18,
		["Suffix"] = function(value: number): string
			return value <= 1 and 'stud' or 'studs';
		end,
		["Tooltip"] = 'How close to your personal chest you have to be, the server stops taking items at about 20'
	});
	Delay = AutoPChest:CreateSlider({
		["Name"] = 'Delay',
		["Min"] = 0,
		["Max"] = 5,
		["Decimal"] = 10,
		["Default"] = 0.5,
		["Suffix"] = 'seconds'
	});
end);

velo.run(function(): ()
	local blockStore: table = bedwars.BlockController:getStore();
	local solidTags: {string} = {'BedwarsItemShop', 'TeamUpgradeShopkeeper'};
	local solidParams: OverlapParams = OverlapParams.new();
	solidParams.FilterType = Enum.RaycastFilterType.Include;
	local mapFolder: Instance? = workspace:FindFirstChild('Map');

	local refreshSolids: () -> () = function(): ()
		local solids: {Instance} = {mapFolder or workspace.Terrain};
		for _: number, tag: string in solidTags do
			for _: number, object: Instance in collectionService:GetTagged(tag) do
				table.insert(solids, object);
			end;
		end;
		solidParams.FilterDescendantsInstances = solids;
	end;
	refreshSolids();
	for _: number, tag: string in solidTags do
		vape:Clean(collectionService:GetInstanceAddedSignal(tag):Connect(function(): ()
			refreshSolids();
			if navigation.World then
				navigation.World:Touch();
			end;
		end));
	end;

	navigation:SetWorld(navigation.newWorld({
		["GetBlocks"] = function(): table
			return blockStore:getAllBlockPositions();
		end,
		["GetBlock"] = function(x: number, y: number, z: number): Instance?
			return blockStore:getBlockAt(Vector3.new(x, y, z));
		end,
		["IsSolid"] = function(x: number, y: number, z: number): boolean
			if not mapFolder then
				mapFolder = workspace:FindFirstChild('Map');
				refreshSolids();
			end;
			return #workspace:GetPartBoundsInBox(CFrame.new(x * 3, y * 3, z * 3), navigation.CellBounds, solidParams) > 0;
		end
	}));

	local oldSetBlock: (self: table, position: Vector3, block: any) -> any = blockStore.setBlock;
	blockStore.setBlock = function(self: table, position: Vector3, block: any): any
		if navigation.World then
			navigation.World:Invalidate(position.X, position.Y, position.Z);
		end;
		return oldSetBlock(self, position, block);
	end;

	vape:Clean(function(): ()
		blockStore.setBlock = oldSetBlock;
		navigation:SetWorld(nil);
	end);
end);

velo.run(function(): ()
	local Clutch: table = {["Enabled"] = false};
	local OnVoid: table;
	local FallDamage: table;
	local Accuracy: table = {};
	local Allowance: table;
	local FallCheck: table;
	local FallBlocks: table;
	local PlaceSpeed: table;
	local SilentAim: table;
	local ResetAngle: table;
	local ReturnSlot: table;
	local MoveDelay: table;
	local FailDelay: table;
	local Staircase: table;
	local LimitBlocks: table;
	local MaxBlocks: table;
	local Blacklist: table;
	local HeldOnly: table;
	local Whitelist: table;

	local maxDrop: number = 512;
	local columnDepth: number = 3;
	local catchReach: number = 14;
	local bridgeReach: number = 14;
	local catchWindow: number = 0.4;
	local catchAttempts: number = 2;
	local knockbackWindow: number = 0.2;
	local settleTime: number = 0.5;
	local ticksPerSecond: number = 60;
	local warnGap: number = 5;

	local counter: TextLabel?;
	local placed: number, nextPlace: number, lastDanger: number = 0, 0, 0;
	local engaged: boolean = false;
	local catchCell: Vector3?, catchUntil: number, catchSeen: boolean, catchTries: number = nil, 0, false, 0;
	local impulse: Vector3, impulseUntil: number = Vector3.zero, 0;
	local groundY: number? = nil;

	local pickBlock: () -> (string?, number, table?) = function(): (string?, number, table?)
		local allowed: (itemType: string) -> boolean = function(itemType: string): boolean
			return #Whitelist["ListEnabled"] == 0 or Blacklist["Enabled"] ~= (table.find(Whitelist["ListEnabled"], itemType) ~= nil);
		end;
		if store.hand.toolType == 'block' and allowed(store.hand.tool.Name) then
			return store.hand.tool.Name, store.hand.amount, nil;
		end;
		if not HeldOnly["Enabled"] then
			for _: number, item: table in store.inventory.inventory.items do
				local meta: table? = bedwars.ItemMeta[item.itemType];
				if meta and meta.block and allowed(item.itemType) then
					return item.itemType, item.amount, item;
				end;
			end;
		end;
		return nil, 0, nil;
	end;

	local dangerAt: (position: Vector3) -> boolean = function(position: Vector3): boolean
		if not (OnVoid["Enabled"] or FallCheck["Enabled"]) then
			return false;
		end;
		local floor: RaycastResult? = bedwars.QueryUtil:raycast(position, Vector3.new(0, -maxDrop, 0), store.airRay);
		if not floor then
			return OnVoid["Enabled"];
		end;
		return FallCheck["Enabled"] and (position.Y - floor.Position.Y) / 3 > FallBlocks["Value"];
	end;

	local choosePlacement: () -> (Vector3?, boolean) = function(): (Vector3?, boolean)
		local root: BasePart = entitylib.character.RootPart;
		local humanoid: Humanoid = entitylib.character.Humanoid;
		local motion: table = {
			["Position"] = root.Position,
			["Velocity"] = tick() < impulseUntil and root.AssemblyLinearVelocity + impulse or root.AssemblyLinearVelocity,
			["Grounded"] = humanoid.FloorMaterial ~= Enum.Material.Air
		};
		if motion.Grounded and humanoid.MoveDirection == Vector3.zero and (motion.Velocity * Vector3.new(1, 0, 1)).Magnitude < 0.5 then
			return nil, false;
		end;
		if not motion.Grounded and catchTries < catchAttempts and (FallDamage["Enabled"] or FallCheck["Enabled"] or OnVoid["Enabled"]) then
			local result: table = navigation:FindClutch(motion, {
				["Channel"] = 'clutch',
				["Reach"] = catchReach,
				["BlocksAvailable"] = LimitBlocks["Enabled"] and math.max(MaxBlocks["Value"] - placed, 0) or nil,
				["DamageAllowance"] = FallDamage["Enabled"] and math.min(Allowance["Value"], math.max(entitylib.character.Health - 1, 0)) or 1000,
				["Agent"] = {["SafeMargin"] = Accuracy["Value"] / 100},
				["Clutch"] = {["MaxFall"] = FallCheck["Enabled"] and FallBlocks["Value"] * 3 or math.huge, ["Void"] = OnVoid["Enabled"]}
			});
			if result.Success then
				return result.BridgePath[1].Position, true;
			elseif result.Reason == 'Safe' then
				return nil, false;
			end;
		end;

		local feet: Vector3 = motion.Position - Vector3.new(0, entitylib.character.HipHeight + 1.5, 0);
		local level: number = groundY or roundPos(feet).Y;
		if feet.Y < level - 1.5 then
			return nil, false;
		end;
		local voidCell: table? = navigation:SolveVoid(motion, {["Channel"] = 'clutch', ["Reach"] = bridgeReach});
		if voidCell and dangerAt(voidCell.Position) then
			return voidCell.Position, false;
		end;
		local under: Vector3 = Vector3.new(math.round(feet.X / 3) * 3, level, math.round(feet.Z / 3) * 3);
		local columns: {Vector3} = {under};
		if humanoid.MoveDirection.Magnitude > 0 then
			table.insert(columns, roundPos(under + humanoid.MoveDirection * 3));
			if Staircase["Enabled"] then
				table.insert(columns, roundPos(under + humanoid.MoveDirection * 3 + Vector3.new(0, 3, 0)));
			end;
		end;
		for _: number, column: Vector3 in columns do
			for depth: number = 0, columnDepth do
				local cell: Vector3 = column - Vector3.new(0, depth * 3, 0);
				if getPlacedBlock(cell) then
					break;
				end;
				if dangerAt(cell) and navigation:SolvePlacement(motion, navigation.WorldToGrid(cell), {["Channel"] = 'clutch', ["Reach"] = bridgeReach}).Valid then
					return cell, false;
				end;
			end;
		end;
		return nil, false;
	end;

	local step: (lastSlot: {number?}) -> () = function(lastSlot: {number?}): ()
		if not entitylib.isAlive then
			catchCell, catchSeen, catchTries, engaged = nil, false, 0, false;
			return;
		end;
		local root: BasePart = entitylib.character.RootPart;
		local grounded: boolean = entitylib.character.Humanoid.FloorMaterial ~= Enum.Material.Air;
		if grounded then
			groundY = roundPos(root.Position - Vector3.new(0, entitylib.character.HipHeight + 1.5, 0)).Y;
			placed, catchTries = 0, 0;
		end;

		if catchCell then
			local feet: Vector3 = root.Position - Vector3.new(0, entitylib.character.HipHeight + 1.5, 0);
			local velocity: Vector3 = tick() < impulseUntil and root.AssemblyLinearVelocity + impulse or root.AssemblyLinearVelocity;
			local gravity: number = workspace.Gravity;
			local fallTime: number = (velocity.Y + math.sqrt(velocity.Y * velocity.Y + 2 * gravity * math.max(feet.Y - (catchCell.Y + 1.5), 0))) / gravity;
			local landing: Vector3 = Vector3.new(math.round((feet.X + velocity.X * fallTime) / 3) * 3, catchCell.Y, math.round((feet.Z + velocity.Z * fallTime) / 3) * 3);
			if grounded or feet.Y < catchCell.Y or (landing - catchCell).Magnitude > 3 then
				catchCell, catchSeen = nil, false;
			elseif getPlacedBlock(catchCell) then
				catchSeen = true;
			elseif catchSeen or tick() > catchUntil then
				catchCell, catchSeen = nil, false;
			end;
		end;

		local position: Vector3?, catching: boolean = nil, false;
		if not catchCell then
			position, catching = choosePlacement();
		end;

		if position or counter then
			local itemType: string?, amount: number, item: table? = pickBlock();
			if counter then
				if vape.ThreadFix then
					setthreadidentity(8);
				end;
				counter.Text = amount..' <font color="rgb(170, 170, 170)">(Clutch)</font>';
				counter.TextColor3 = Color3.fromHSV(amount / 128 / 2.8, 0.86, 1);
			end;
			if position and itemType and (not LimitBlocks["Enabled"] or placed < MaxBlocks["Value"]) then
				if not engaged then
					engaged = true;
					lastSlot[1] = store.inventory.hotbarSlot;
					task.wait(MoveDelay:GetRandomValue() / ticksPerSecond);
					if vape.ThreadFix then
						setthreadidentity(8);
					end;
					position = nil;
					if entitylib.isAlive then
						position, catching = choosePlacement();
					end;
				end;
				local serverNow: number = workspace:GetServerTimeNow();
				local interval: number = 1 / bedwars.SharedConstants.BLOCK_PLACE_CPS;
				if position and serverNow >= nextPlace then
					local slot: number? = item and hotbarSlotOf(item.tool);
					if slot then
						task.spawn(hotbarSwitch, slot);
					end;
					nextPlace = serverNow + math.max(1 / PlaceSpeed["Value"], interval);
					local restore: CFrame? = nil;
					if not SilentAim["Enabled"] then
						restore = gameCamera.CFrame;
						if vape.ThreadFix then
							setthreadidentity(8);
						end;
						gameCamera.CFrame = CFrame.lookAt(restore.Position, position);
					end;
					local success: any = placeBlock(position, itemType);
					if restore then
						task.delay(ResetAngle:GetRandomValue() / ticksPerSecond, function(): ()
							if vape.ThreadFix then
								setthreadidentity(8);
							end;
							gameCamera.CFrame = CFrame.lookAt(gameCamera.CFrame.Position, gameCamera.CFrame.Position + restore.LookVector);
						end);
					end;
					if success then
						placed += 1;
						if catching then
							catchCell, catchSeen = position, false;
							catchTries += 1;
							catchUntil = tick() + catchWindow + math.clamp(store.ping.total, 0, 0.3);
						end;
					else
						nextPlace = serverNow + math.max(FailDelay["Value"] / 1000, interval);
					end;
				end;
			end;
		end;

		if position then
			lastDanger = tick();
		elseif engaged and tick() - lastDanger > settleTime then
			engaged, placed = false, 0;
			if ReturnSlot["Enabled"] and lastSlot[1] then
				hotbarSwitch(lastSlot[1]);
			end;
			lastSlot[1] = nil;
		end;
	end;

	Clutch = vape.Categories.Utility:CreateModule({
		["Name"] = 'Clutch',
		["Function"] = function(callback: boolean): ()
			if counter then
				if vape.ThreadFix then
					setthreadidentity(8);
				end;
				counter.Visible = callback;
			end;
			if not callback then
				engaged, placed, catchCell, catchSeen, catchTries, impulseUntil, groundY = false, 0, nil, false, 0, 0, nil;
				return;
			end;

			Clutch:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damage: table): ()
				local multiplier: table? = damage.knockbackMultiplier;
				if damage.entityInstance ~= lplr.Character or not entitylib.isAlive or not damage.fromPosition or (multiplier and multiplier.disabled) then
					return;
				end;
				local direction: Vector3 = bedwars.KnockbackUtil.getDirection(entitylib.character.RootPart.Position, damage.fromPosition);
				if direction.Magnitude > 0 then
					impulse = bedwars.KnockbackUtil.calculateKnockbackVelocity(direction, 1, multiplier);
					impulseUntil = tick() + knockbackWindow;
				end;
			end));

			local lastSlot: {number?} = {};
			local warnedAt: number = 0;
			repeat
				if vape.ThreadFix then
					setthreadidentity(8);
				end;
				local ran: boolean, failure: any = pcall(step, lastSlot);
				if not ran and tick() > warnedAt then
					warnedAt = tick() + warnGap;
					warn('[Velocity] clutch step failed: '..tostring(failure));
				end;
				task.wait();
			until not Clutch["Enabled"];
		end,
		["Tooltip"] = 'Places blocks under you to save you from falling into the void or taking fall damage.'
	});
	OnVoid = Clutch:CreateToggle({
		["Name"] = 'On void',
		["Tooltip"] = 'Clutches when there is nothing at all beneath you.'
	});
	FallDamage = Clutch:CreateToggle({
		["Name"] = 'On fall damage',
		["Default"] = true,
		["Function"] = function(callback: boolean): ()
			if Accuracy.Object then
				Accuracy.Object.Visible = callback;
			end;
		end,
		["Tooltip"] = 'Catches you as low as possible while still landing without damage.'
	});
	Accuracy = Clutch:CreateSlider({
		["Name"] = 'Accuracy',
		["Min"] = 50,
		["Max"] = 100,
		["Default"] = 100,
		["Darker"] = true,
		["Suffix"] = '%',
		["Tooltip"] = 'How close it cuts the real limit; lower catches you higher with room to spare.'
	});
	Allowance = Clutch:CreateSlider({
		["Name"] = 'Damage allowance',
		["Min"] = 0,
		["Max"] = 100,
		["Default"] = 0,
		["Suffix"] = 'hp',
		["Tooltip"] = 'Fall damage you accept so it can catch you even lower.'
	});
	FallCheck = Clutch:CreateToggle({
		["Name"] = 'On more than x blocks',
		["Default"] = true
	});
	FallBlocks = Clutch:CreateSlider({
		["Name"] = 'Blocks',
		["Min"] = 1,
		["Max"] = 30,
		["Default"] = 3,
		["Suffix"] = function(value: number): string
			return value <= 1 and 'block' or 'blocks';
		end
	});
	PlaceSpeed = Clutch:CreateSlider({
		["Name"] = 'Speed',
		["Min"] = 1,
		["Max"] = 40,
		["Default"] = 20,
		["Suffix"] = 'bps',
		["Tooltip"] = 'Blocks placed per second.'
	});
	SilentAim = Clutch:CreateToggle({
		["Name"] = 'Silent aim',
		["Default"] = true,
		["Tooltip"] = 'Places without turning your camera to the block.'
	});
	ResetAngle = Clutch:CreateTwoSlider({
		["Name"] = 'Reset angle delay',
		["Min"] = 0,
		["Max"] = 20,
		["DefaultMin"] = 3,
		["DefaultMax"] = 6,
		["Tooltip"] = 'Ticks before your camera turns back.'
	});
	ReturnSlot = Clutch:CreateToggle({
		["Name"] = 'Return to last slot',
		["Tooltip"] = 'Switches back to what you were holding once you are safe.'
	});
	MoveDelay = Clutch:CreateTwoSlider({
		["Name"] = 'Clutch move delay',
		["Min"] = 0,
		["Max"] = 20,
		["DefaultMin"] = 2,
		["DefaultMax"] = 5,
		["Tooltip"] = 'Ticks of reaction time before the first block goes down.'
	});
	FailDelay = Clutch:CreateSlider({
		["Name"] = 'Fail delay',
		["Min"] = 0,
		["Max"] = 1000,
		["Default"] = 0,
		["Suffix"] = 'ms'
	});
	Staircase = Clutch:CreateToggle({
		["Name"] = 'Allow staircase up',
		["Tooltip"] = 'Also places ahead and above you so you can climb back up.'
	});
	Clutch:CreateToggle({
		["Name"] = 'Show block count',
		["Function"] = function(callback: boolean): ()
			if vape.ThreadFix then
				setthreadidentity(8);
			end;
			if not callback then
				if counter then
					counter:Destroy();
					counter = nil;
				end;
				return;
			end;
			local label: TextLabel = Instance.new('TextLabel');
			label.Size = UDim2.fromOffset(100, 20);
			label.Position = UDim2.new(0.5, 6, 0.5, 80);
			label.AnchorPoint = Vector2.new(0.5, 0);
			label.BackgroundTransparency = 1;
			label.Text = '0';
			label.TextColor3 = Color3.new(0, 1, 0);
			label.TextSize = 18;
			label.RichText = true;
			label.Font = Enum.Font.Arial;
			label.Visible = Clutch["Enabled"];
			label.Parent = vape.gui;
			counter = label;
		end
	});
	LimitBlocks = Clutch:CreateToggle({
		["Name"] = 'Limit blocks',
		["Default"] = true,
		["Tooltip"] = 'Caps how many blocks a single clutch may use.'
	});
	MaxBlocks = Clutch:CreateSlider({
		["Name"] = 'Max blocks',
		["Min"] = 1,
		["Max"] = 32,
		["Default"] = 5
	});
	Blacklist = Clutch:CreateToggle({
		["Name"] = 'Blacklist',
		["Tooltip"] = 'Treat the list as blocks to avoid instead of blocks to use.'
	});
	HeldOnly = Clutch:CreateToggle({
		["Name"] = 'Held whitelist',
		["Tooltip"] = 'Only clutch with the block already in your hand.'
	});
	Whitelist = Clutch:CreateTextList({
		["Name"] = 'Whitelist',
		["Tooltip"] = 'Block types the clutch may use.'
	});
	vape:Clean(function(): ()
		if counter then
			counter:Destroy();
		end;
	end);
end);

velo.run(function(): ()
	local LegitAutoPlay: table = {["Enabled"] = false};
	local Reaction: table;
	local TurnSpeed: table;
	local ClickRate: table;
	local RetreatHealth: table;
	local Style: table;
	local BreakBeds: table;
	local CoverBed: table;
	local HuntPlayers: table;
	local EmptyBeds: table;
	local Debug: table;

	local flat: Vector3 = Vector3.new(1, 0, 1);
	local up: Vector3 = Vector3.new(0, 1, 0);
	local profile: table = {
		["Timing"] = {["Observe"] = 0.2, ["Think"] = 0.3, ["Command"] = 0.12, ["GoalTimeout"] = 45, ["SwitchDelay"] = 0.14},
		["Memory"] = {["Sight"] = 120, ["Remember"] = 8, ["Visible"] = 0.6, ["Hit"] = 3, ["FailureLife"] = 40, ["FailureWeight"] = 25, ["Shortfall"] = 30, ["Learn"] = 30, ["LearnGap"] = 1.5},
		["Decide"] = {["Commit"] = 18, ["SwitchMargin"] = 8, ["TravelWeight"] = 1.1, ["RiskWeight"] = 45, ["Detour"] = 1.25},
		["Walk"] = {
			["Waypoint"] = 1.6, ["WaypointHeight"] = 2.6, ["DropHeight"] = 7, ["DropOvershoot"] = 3,
			["ProbeShrink"] = Vector3.new(0.4, 0.4, 0.4), ["ProbeReach"] = 3.4, ["StepHeight"] = 3.4,
			["SteerAngles"] = {35, -35, 70, -70, 110, -110}, ["SteerHold"] = 1.2, ["SteerReach"] = 4,
			["TunnelDelay"] = 0.55, ["TunnelReach"] = 9, ["WeaveWidth"] = 0.9, ["WeaveRate"] = 0.33, ["WeaveMinimum"] = 9,
			["PauseGap"] = {7, 16}, ["PauseLength"] = {0.15, 0.4}, ["PauseClear"] = 40, ["HopGap"] = {9, 22}, ["HopDistance"] = 14,
			["StartDelay"] = {0.1, 0.28}, ["JumpRange"] = 3.4, ["JumpRise"] = 1.2, ["JumpCooldown"] = 0.5,
			["Lookahead"] = 3, ["LookaheadClear"] = 1.2, ["StuckTime"] = 1.4, ["StuckDistance"] = 0.6,
			["RouteRetry"] = 0.8, ["RouteFaults"] = 3, ["SafeDrop"] = 6, ["IdleDrift"] = 5
		},
		["Build"] = {
			["Reserve"] = 6, ["Floor"] = 16, ["Target"] = 40, ["Margin"] = 1.45, ["BridgeCap"] = 40,
			["CoverReach"] = 12, ["CoverRadius"] = 7, ["CoverTimeout"] = 14, ["CoverPatience"] = 2,
			["BreakReach"] = 11, ["BreakRadius"] = 6, ["BreakInterval"] = 0.24, ["BreakStall"] = 5,
			["CoverItems"] = {'stone_brick', 'wood_plank_oak'}, ["CellProbe"] = Vector3.new(2.4, 2.4, 2.4),
			["Faces"] = {Vector3.new(1, 0, 0), Vector3.new(-1, 0, 0), Vector3.new(0, 0, 1), Vector3.new(0, 0, -1), Vector3.new(0, 1, 0)}
		},
		["Fight"] = {
			["MeleeReach"] = 11.4, ["StrikeRange"] = 8.5, ["StrikeCone"] = 28, ["Range"] = 32, ["Disengage"] = 44, ["Close"] = 3.6,
			["StrafeMin"] = 0.45, ["StrafeMax"] = 1.1, ["Retaliate"] = 45, ["DefendRange"] = 32, ["Defend"] = 85,
			["UnknownDamage"] = 24, ["UnknownArmor"] = 0.2, ["BareDamage"] = 12, ["RetreatDistance"] = 30
		},
		["Value"] = {["Bed"] = 100, ["Fight"] = 55, ["Hunt"] = 85, ["Cover"] = 70, ["Farm"] = 28, ["Wait"] = 5},
		["Economy"] = {
			["LootRadius"] = 45, ["LootTimeout"] = 14, ["Pickup"] = 2.2, ["DropSearch"] = 16,
			["Loot"] = {["iron"] = 30, ["diamond"] = 58, ["emerald"] = 72},
			["PurchaseGap"] = 0.35, ["PurchaseLimit"] = 8, ["PurchaseTimeout"] = 2, ["CollectWait"] = 16, ["Collect"] = 4,
			["ShopRadius"] = 3.8, ["ShopReach"] = 4.8, ["BaseRadius"] = 80,
			["Swords"] = {'wood_sword', 'stone_sword', 'iron_sword', 'diamond_sword', 'emerald_sword'},
			["Armors"] = {'leather_chestplate', 'iron_chestplate', 'diamond_chestplate', 'emerald_chestplate'},
			["Tools"] = {'wood_pickaxe', 'wood_axe', 'shears'},
			["TeamUpgrades"] = {'ARMOR', 'DAMAGE', 'TEAM_GENERATOR'},
			["GearPlan"] = {{0, 'stone_sword'}, {50, 'leather_chestplate'}, {100, 'iron_chestplate'}, {150, 'iron_sword'}},
			["Urgency"] = {["parity"] = 90, ["now"] = 62, ["armor"] = 55, ["soon"] = 38, ["cover"] = 36, ["upgrade"] = 30, ["nice"] = 14}
		},
		["Phases"] = {
			["OPENING"] = {["bed"] = 0.8, ["cover"] = 1.5, ["fight"] = 0.8, ["farm"] = 1.4},
			["EARLY"] = {["bed"] = 1.1, ["cover"] = 1.2, ["fight"] = 0.9, ["farm"] = 1.2},
			["MIDGAME"] = {["bed"] = 1.2, ["cover"] = 0.9, ["fight"] = 1, ["farm"] = 1},
			["ENDGAME"] = {["bed"] = 1.1, ["cover"] = 0.5, ["fight"] = 1.2, ["farm"] = 0.7},
			["FINAL"] = {["bed"] = 1, ["cover"] = 0.2, ["fight"] = 1.4, ["farm"] = 0.4}
		},
		["Styles"] = {
			["Balanced"] = {["bed"] = 1, ["cover"] = 1, ["fight"] = 1},
			["Aggressive"] = {["bed"] = 1.25, ["cover"] = 0.7, ["fight"] = 1.2},
			["Defensive"] = {["bed"] = 0.8, ["cover"] = 1.35, ["fight"] = 0.9}
		}
	};

	local agent: table? = nil;
	local senses: table? = nil;
	local mind: table = {};
	local world: table = {};
	local walker: table = {};
	local fight: table = {};
	local goalKinds: {[string]: table} = {};

	local log: (text: string) -> () = function(text: string): ()
		if Debug["Enabled"] then
			warn('[velocity] legitautoplay '..text);
		end;
	end;

	local jitter: (base: number, spread: number) -> number = function(base: number, spread: number): number
		return base * (1 + (math.random() * 2 - 1) * spread);
	end;

	local between: (range: {number}) -> number = function(range: {number}): number
		return range[1] + math.random() * (range[2] - range[1]);
	end;

	local alive: () -> boolean = function(): boolean
		local character: Model? = lplr.Character;
		return entitylib.isAlive and character ~= nil and (character:GetAttribute('Health') or 0) > 0;
	end;

	local known: (record: table, now: number) -> boolean = function(record: table, now: number): boolean
		return record.alive and record.position ~= nil and now - record.seenAt <= profile.Memory.Remember;
	end;

	local odds: (record: table) -> number = function(record: table): number
		local me: table = world.self;
		local theirDamage: number = record.gearAt and math.max(record.sword, profile.Fight.BareDamage) or profile.Fight.UnknownDamage;
		local theirArmor: number = record.gearAt and record.armor or profile.Fight.UnknownArmor;
		local hitsToKillMe: number = me.health / math.max(theirDamage * (1 - me.armor), 1);
		local hitsToKillThem: number = (record.health or 100) / math.max(math.max(me.sword, profile.Fight.BareDamage) * (1 - theirArmor), 1);
		return hitsToKillMe / (hitsToKillMe + hitsToKillThem);
	end;

	local danger: (position: Vector3, radius: number, now: number, except: table?) -> number = function(position: Vector3, radius: number, now: number, except: table?): number
		local total: number = 0;
		for _: string, record: table in world.enemies do
			if record ~= except and known(record, now) then
				local distance: number = (record.position - position).Magnitude;
				if distance < radius then
					total += (1 - distance / radius) * (1.4 - odds(record));
				end;
			end;
		end;
		return total;
	end;

	local nearestEnemy: (now: number) -> (table?, number) = function(now: number): (table?, number)
		local best: table?, gap: number = nil, math.huge;
		for _: string, record: table in world.enemies do
			if known(record, now) and (record.position - world.self.position).Magnitude < gap then
				best, gap = record, (record.position - world.self.position).Magnitude;
			end;
		end;
		return best, gap;
	end;

	local mark: (reason: string) -> () = function(reason: string): ()
		if not mind.dirty then
			mind.readyAt = math.max(mind.readyAt, os.clock() + jitter(Reaction["Value"] / 1000, 0.3));
		end;
		mind.dirty = mind.dirty or reason;
		mind.nextObserve = 0;
	end;

	local itemPower: (itemType: string) -> number = function(itemType: string): number
		local meta: table? = bedwars.ItemMeta[itemType];
		return meta and (meta.sword and meta.sword.damage or meta.armor and meta.armor.damageReductionMultiplier) or 0;
	end;

	local quote: (itemType: string, team: boolean?) -> table? = function(itemType: string, team: boolean?): table?
		if team then
			local meta: table? = bedwars.TeamUpgradeMeta and bedwars.TeamUpgradeMeta[itemType];
			if not meta or meta.disabledInQueue and table.find(meta.disabledInQueue, store.queueType) then
				return nil;
			end;
			local owned: table = bedwars.Store:getState().Bedwars.teamUpgrades[lplr:GetAttribute('Team')] or {};
			local tierIndex: number = (owned[itemType] or 0) + 1;
			local tier: table? = meta.tiers[tierIndex];
			if not tier or tier.availableOnlyInQueue and not table.find(tier.availableOnlyInQueue, store.queueType) then
				return nil;
			end;
			return {["item"] = itemType, ["upgrade"] = true, ["currency"] = 'diamond', ["price"] = tier.cost, ["cost"] = tier.cost, ["tier"] = tierIndex};
		end;
		local shopItem: table? = bedwars.Shop and bedwars.Shop.getShopItem(itemType, lplr);
		if not shopItem or (shopItem.price or 0) <= 0 or shopItem.disabled or shopItem.lockedByForge or shopItem.ignoredByKit and table.find(shopItem.ignoredByKit, store.equippedKit) then
			return nil;
		end;
		local needs: table? = shopItem.require and shopItem.require.teamUpgrade;
		if needs and (bedwars.Store:getState().Bedwars.teamUpgrades[needs.upgradeId] or -1) < needs.lowestTierIndex then
			return nil;
		end;
		return {["item"] = itemType, ["currency"] = shopItem.currency, ["price"] = shopItem.price, ["cost"] = shopItem.price, ["amount"] = shopItem.amount, ["tiered"] = shopItem.tiered};
	end;

	local nextTier: (chain: {string}, current: number, field: string) -> string? = function(chain: {string}, current: number, field: string): string?
		for _: number, itemType: string in chain do
			local meta: table? = bedwars.ItemMeta[itemType];
			if meta and meta[field] and itemPower(itemType) > current and quote(itemType) then
				return itemType;
			end;
		end;
		return nil;
	end;

	local planned: (field: string) -> number = function(field: string): number
		local best: number = 0;
		for _: number, step: table in profile.Economy.GearPlan do
			local meta: table? = bedwars.ItemMeta[step[2]];
			if world.match.elapsed >= step[1] and meta and meta[field] then
				best = math.max(best, itemPower(step[2]));
			end;
		end;
		return best;
	end;

	local openFaces: (bed: BasePart) -> {Vector3} = function(bed: BasePart): {Vector3}
		local handler: table? = bedwars.BlockController:getHandlerRegistry():getHandler(bed.Name);
		local cells: {Vector3} = handler and handler:getContainedPositions(bed) or {bedwars.BlockController:getBlockPosition(bed.Position)};
		local taken: {[Vector3]: boolean} = {};
		local open: {Vector3} = {};
		for _: number, cell: Vector3 in cells do
			taken[cell] = true;
		end;
		for _: number, cell: Vector3 in cells do
			for _: number, face: Vector3 in profile.Build.Faces do
				local grid: Vector3 = cell + face;
				if not taken[grid] then
					taken[grid] = true;
					if not getPlacedBlock(grid * 3) and #workspace:GetPartBoundsInBox(CFrame.new(grid * 3), profile.Build.CellProbe, senses.Overlap) == 0 then
						table.insert(open, grid * 3);
					end;
				end;
			end;
		end;
		return open;
	end;

	local observe: (now: number) -> () = function(now: number): ()
		local me: table, match: table = world.self, world.match;
		local character: Model = lplr.Character;
		me.position = entitylib.character.RootPart.Position;
		me.team = tostring(lplr:GetAttribute('Team'));
		me.health = character:GetAttribute('Health') or 0;
		me.maxHealth = math.max(character:GetAttribute('MaxHealth') or 100, 1);
		me.ratio = math.clamp(me.health / me.maxHealth, 0, 1);
		me.speed = getSpeed();
		local wool: string?, woolAmount: number? = getWool();
		me.blocks = wool and woolAmount or 0;
		local sword: number, armorSlots: table = senses.Gear(store.inventory.inventory);
		me.sword, me.armorSlots, me.armor = sword, armorSlots, 0;
		for _: any, reduction: number in armorSlots do
			me.armor += reduction;
		end;
		me.armor = math.clamp(me.armor, 0, 0.9);
		table.clear(me.resources);
		for _: number, item: table in store.inventory.inventory.items do
			me.resources[item.itemType] = (me.resources[item.itemType] or 0) + item.amount;
		end;

		table.clear(world.teams);
		for _: number, bed: table in senses.Beds() do
			world.teams[bed.team] = {["id"] = bed.team, ["bed"] = bed, ["members"] = 0, ["alive"] = 0};
			world.homes[bed.team] = bed.position;
		end;
		for _: number, member: table in senses.Roster() do
			local team: table = world.teams[member.team] or {["id"] = member.team, ["members"] = 0, ["alive"] = 0};
			world.teams[member.team] = team;
			team.members += 1;
			team.alive += member.alive and 1 or 0;
			if member.enemy then
				local record: table = world.enemies[member.id] or {["id"] = member.id, ["player"] = member.player, ["name"] = member.player.Name, ["seenAt"] = -math.huge, ["hitAt"] = -math.huge, ["sword"] = 0, ["armor"] = 0};
				world.enemies[member.id] = record;
				record.team, record.alive, record.present = member.team, member.alive, now;
				record.root = member.alive and member.root or nil;
				if member.alive then
					record.health, record.maxHealth, record.protected = member.health, math.max(member.maxHealth, 1), member.protected;
					local eye: Vector3 = entitylib.character.Head and entitylib.character.Head.Position or me.position + up * 2;
					local target: Vector3 = member.position + up * 1.5;
					if (member.position - me.position).Magnitude <= profile.Memory.Sight and not workspace:Raycast(eye, target - eye, senses.Params) then
						record.position, record.velocity, record.seenAt = member.position, member.velocity, now;
						if member.gearKnown then
							record.sword, record.armor, record.ranged, record.gearAt = member.sword, member.armor, member.ranged, now;
						end;
					end;
				end;
			end;
		end;
		for id: string, record: table in world.enemies do
			if now - record.present > 2 then
				world.enemies[id] = nil;
			end;
		end;

		local own: table? = world.teams[me.team];
		match.ownBed = own ~= nil and own.bed ~= nil;
		match.enemyBeds, match.enemyTeams, match.enemyPlayers = 0, 0, 0;
		for id: string, team: table in world.teams do
			if id ~= me.team and (team.members > 0 or EmptyBeds["Enabled"] and team.bed ~= nil) then
				match.enemyTeams += 1;
				match.enemyPlayers += math.max(team.alive, team.members == 0 and 1 or 0);
				match.enemyBeds += team.bed and not team.bed.locked and 1 or 0;
			end;
		end;
		local started: number? = bedwars.Store:getState().Game.startTime;
		match.elapsed = started and started > 0 and math.max(workspace:GetServerTimeNow() - started, 0) or os.clock() - mind.began;
		if match.enemyTeams == 0 or match.enemyBeds == 0 or match.enemyPlayers <= 1 then
			match.phase = 'FINAL';
		elseif match.enemyTeams <= 2 or not match.ownBed then
			match.phase = 'ENDGAME';
		elseif match.elapsed > 360 or me.sword >= itemPower('iron_sword') and me.armor >= 0.3 then
			match.phase = 'MIDGAME';
		elseif match.elapsed > 75 then
			match.phase = 'EARLY';
		else
			match.phase = 'OPENING';
		end;
	end;

	local turnToward: (position: Vector3, delta: number) -> number = function(position: Vector3, delta: number): number
		local root: BasePart = entitylib.character.RootPart;
		local wanted: Vector3 = (position - root.Position) * flat;
		local facing: Vector3 = root.CFrame.LookVector * flat;
		if wanted.Magnitude < 0.1 then
			return 0;
		end;
		local errorAngle: number = math.deg(math.acos(math.clamp(facing.Unit:Dot(wanted.Unit), -1, 1)));
		if errorAngle < 0.5 then
			return errorAngle;
		end;
		local fraction: number = math.min(TurnSpeed["Value"] * delta / errorAngle, 1);
		local turned: Vector3 = facing.Unit:Lerp(wanted.Unit, fraction);
		if turned.Magnitude > 0.01 then
			root.CFrame = CFrame.lookAt(root.Position, root.Position + turned.Unit);
		end;
		return errorAngle * (1 - fraction);
	end;

	local holdAim: (active: boolean) -> () = function(active: boolean): ()
		if entitylib.isAlive then
			entitylib.character.Humanoid.AutoRotate = not active;
		end;
	end;

	walker.note = function(status: string, detail: string?): ()
		if walker.status ~= status then
			walker.status = status;
			log('walk '..status..(detail and ' '..detail or ''));
		end;
	end;

	walker.halt = function(): ()
		walker.idleSince = walker.idleSince or os.clock();
		if entitylib.isAlive then
			entitylib.character.Humanoid:MoveTo(entitylib.character.RootPart.Position);
		end;
		walker.commanded = nil;
	end;

	walker.jump = function(now: number): boolean
		local humanoid: Humanoid = entitylib.character.Humanoid;
		if now - walker.jumpedAt < profile.Walk.JumpCooldown or humanoid.FloorMaterial == Enum.Material.Air then
			return false;
		end;
		walker.jumpedAt = now;
		humanoid:ChangeState(Enum.HumanoidStateType.Jumping);
		return true;
	end;

	walker.floor = function(position: Vector3): boolean
		local hit: RaycastResult? = workspace:Raycast(position + Vector3.new(0, 2, 0), Vector3.new(0, -(profile.Walk.SafeDrop + 3), 0), senses.Params);
		return hit ~= nil and hit.Normal.Y > 0.5;
	end;

	walker.learn = function(direction: Vector3, now: number): ()
		if now - (walker.learnedAt or -math.huge) < profile.Memory.LearnGap then
			return;
		end;
		walker.learnedAt = now;
		local root: BasePart = entitylib.character.RootPart;
		local grid: Vector3 = navigation.WorldToGrid(root.Position + direction * 3 - Vector3.new(0, entitylib.character.HipHeight - 1.5, 0));
		agent.Memory:Route(grid, 'collision', now);
		if navigation.World and navigation.World.Learn then
			navigation.World:Learn(grid.X, grid.Y, grid.Z, profile.Memory.Learn);
			navigation.World:Learn(grid.X, grid.Y + 1, grid.Z, profile.Memory.Learn);
		end;
		agent:Invalidate('Blocked ahead');
		walker.note('blocked', 'learned '..tostring(grid));
	end;

	walker.steer = function(target: Vector3, now: number): Vector3
		local root: BasePart = entitylib.character.RootPart;
		local offset: Vector3 = (target - root.Position) * flat;
		if offset.Magnitude < 0.6 then
			walker.blockedAt = nil;
			return target;
		end;
		local box: Vector3 = Vector3.new(root.Size.X, entitylib.character.HipHeight + root.Size.Y / 2, root.Size.X) - profile.Walk.ProbeShrink;
		local probe: (direction: Vector3, distance: number, lift: number) -> RaycastResult? = function(direction: Vector3, distance: number, lift: number): RaycastResult?
			return workspace:Blockcast(CFrame.new(root.Position + Vector3.new(0, lift, 0)), box, direction * distance, senses.Params);
		end;
		local direction: Vector3 = offset.Unit;
		local reach: number = math.min(profile.Walk.ProbeReach, offset.Magnitude);
		local hit: RaycastResult? = probe(direction, reach, 0);
		if not hit then
			walker.blockedAt = nil;
			return target;
		end;
		walker.blockedAt = walker.blockedAt or now;
		if not probe(direction, reach, profile.Walk.StepHeight) then
			walker.jump(now);
			return target;
		end;
		if now - walker.blockedAt >= profile.Walk.TunnelDelay and walker.tunnels then
			local wall: Instance? = getPlacedBlock(hit.Position - hit.Normal * 1.2);
			if wall and wall.Name ~= 'bed' and (wall.Position - root.Position).Magnitude <= profile.Walk.TunnelReach then
				if now >= mind.nextBreak then
					mind.nextBreak = now + jitter(0.3, 0.3);
					task.spawn(breakBlock, wall, {["Effects"] = true, ["Animation"] = 'Normal', ["AutoTool"] = true});
				end;
				walker.note('tunneling', wall.Name);
				return target;
			end;
		end;
		local side: number = walker.deflect and now < walker.deflect.Until and walker.deflect.Sign or 0;
		local angles: {number} = {};
		for pass: number = 1, 2 do
			for _: number, degrees: number in profile.Walk.SteerAngles do
				if (pass == 1) == (side == 0 or math.sign(degrees) == side) then
					table.insert(angles, degrees);
				end;
			end;
		end;
		for _: number, degrees: number in angles do
			local turned: Vector3 = CFrame.Angles(0, math.rad(degrees), 0):VectorToWorldSpace(direction);
			local point: Vector3 = root.Position + turned * profile.Walk.SteerReach;
			if not probe(turned, profile.Walk.SteerReach, 0) and senses.Ground(point) then
				walker.deflect = {["Sign"] = math.sign(degrees), ["Until"] = now + profile.Walk.SteerHold};
				if now - walker.blockedAt > profile.Walk.SteerHold then
					walker.learn(direction, now);
				end;
				return point;
			end;
		end;
		walker.learn(direction, now);
		return root.Position;
	end;

	walker.command = function(position: Vector3, now: number, trusted: boolean?): ()
		local root: BasePart = entitylib.character.RootPart;
		position = walker.steer(position, now);
		if not trusted then
			local offset: Vector3 = (position - root.Position) * flat;
			local safe: Vector3? = offset.Magnitude < 0.5 and position or nil;
			for step: number = 1, offset.Magnitude >= 0.5 and math.ceil(offset.Magnitude / 2) or 0 do
				local sample: Vector3 = root.Position + offset.Unit * math.min(step * 2, offset.Magnitude);
				if not walker.floor(sample) then
					break;
				end;
				safe = sample;
			end;
			if not safe then
				walker.halt();
				return;
			end;
			position = safe;
		end;
		local offset: Vector3 = (position - root.Position) * flat;
		if offset.Magnitude >= profile.Walk.WeaveMinimum and walker.weaving then
			local across: Vector3 = Vector3.new(-offset.Unit.Z, 0, offset.Unit.X);
			local swayed: Vector3 = position + across * math.noise(now * profile.Walk.WeaveRate, walker.seed, 0) * 2 * profile.Walk.WeaveWidth;
			if senses.Ground(swayed) and senses.Ground(root.Position + across * 3) and senses.Ground(root.Position - across * 3) then
				position = swayed;
			end;
		end;
		if not walker.commanded or now - walker.commandedAt >= profile.Timing.Command or (position - walker.commanded).Magnitude > 2 then
			walker.commanded, walker.commandedAt = position, now;
			entitylib.character.Humanoid:MoveTo(position);
		end;
	end;

	walker.sprint = function(): ()
		local controller: table? = bedwars.SprintController;
		if controller and not controller.sprinting then
			pcall(controller.startSprinting, controller);
		end;
	end;

	walker.cancel = function(): ()
		if walker.request then
			walker.request.Cancelled = true;
		end;
		walker.request, walker.requestKey, walker.key, walker.target = nil, nil, nil, nil;
		walker.faults, walker.retryAt = 0, 0;
		walker.progress, walker.progressAt = nil, 0;
		if agent then
			agent:Invalidate();
		end;
	end;

	walker.fault = function(key: string, reason: string, now: number): ()
		walker.faults += 1;
		walker.retryAt = now + math.min(walker.faults, 4) * profile.Walk.RouteRetry;
		log('route fault '..key..': '..reason);
	end;

	walker.ask = function(key: string, position: Vector3, threats: {Vector3}?, now: number): ()
		local request: table = {["Cancelled"] = false};
		local from: Vector3 = entitylib.character.RootPart.Position;
		local me: table = world.self;
		walker.request, walker.requestKey = request, key;
		task.spawn(function(): ()
			local success: boolean, plan: any, result: any = pcall(agent.Draft, agent, from, position, {
				["Channel"] = 'legitautoplay',
				["Mode"] = 'Legit',
				["BlocksAvailable"] = math.max(me.blocks - profile.Build.Reserve, 0),
				["BlocksBudget"] = profile.Build.BridgeCap,
				["Debug"] = Debug["Enabled"],
				["Label"] = true,
				["Agent"] = {["WalkSpeed"] = me.speed or getSpeed(), ["MaxDrop"] = profile.Walk.SafeDrop},
				["Traversal"] = {["Mover"] = 'Jump', ["MaxAirTime"] = 1.75, ["Margin"] = 1, ["Rise"] = 1, ["Instant"] = false},
				["Search"] = {["MaxSteps"] = 25000, ["WalkSteps"] = 8000, ["Fallback"] = false, ["Smooth"] = false, ["Bridge"] = true, ["Tower"] = false, ["JumpGap"] = false}
			}, threats, key, request);
			if walker.request ~= request then
				return;
			end;
			walker.request, walker.requestKey = nil, nil;
			local at: number = os.clock();
			if not success or not plan then
				walker.fault(key, success and result and result.Reason or tostring(plan), at);
				return;
			end;
			if not alive() then
				return;
			end;
			local root: BasePart = entitylib.character.RootPart;
			local carried: number = world.self.blocks;
			local pending: number = plan:Pending();
			if plan.Result.Partial and plan.Kind ~= 'Retreat' then
				mind.shortfall = {["key"] = key, ["blocks"] = math.min(math.max(math.max(pending, mind.estimates[key] or 0), carried + 16) + profile.Build.Reserve, profile.Build.Target), ["at"] = at};
				walker.fault(key, 'route does not reach the goal with '..carried..' blocks', at);
				agent:Invalidate('Partial route');
				return;
			end;
			if pending > carried then
				mind.shortfall = {["key"] = key, ["blocks"] = math.min(pending + profile.Build.Reserve, profile.Build.Target), ["at"] = at};
				walker.fault(key, 'needs '..pending..' blocks, carrying '..carried, at);
				return;
			end;
			agent:Adopt(plan, {["position"] = root.Position, ["velocity"] = root.AssemblyLinearVelocity, ["airborne"] = entitylib.character.Humanoid.FloorMaterial == Enum.Material.Air}, at);
			walker.key, walker.target, walker.faults = key, position, 0;
			walker.progress, walker.progressAt = root.Position, at;
		end);
	end;

	local placeAt: (position: Vector3, itemType: string?, now: number) -> boolean = function(position: Vector3, itemType: string?, now: number): boolean
		local block: string? = itemType or getWool();
		local serverNow: number = workspace:GetServerTimeNow();
		local key: string = tostring(position);
		if not block or not canPlace() or serverNow < mind.nextPlace or (mind.placed[key] or 0) > now then
			return false;
		end;
		local held: table? = getItem(block);
		if not held or not held.tool then
			return false;
		end;
		if store.hand.tool ~= held.tool then
			local slot: number? = hotbarSlotOf(held.tool);
			if slot and store.inventory.hotbarSlot ~= slot then
				mind.nextPlace = serverNow + jitter(profile.Timing.SwitchDelay, 0.3);
				bedwars.Store:dispatch({["type"] = 'InventorySelectHotbarSlot', ["slot"] = slot});
			end;
			return false;
		end;
		mind.nextPlace = serverNow + jitter(1 / (bedwars.SharedConstants.BLOCK_PLACE_CPS or 12), 0.18);
		mind.placed[key] = now + 0.8;
		task.spawn(placeBlock, position, block);
		return true;
	end;

	walker.follow = function(plan: table, now: number): string
		local root: BasePart = entitylib.character.RootPart;
		local humanoid: Humanoid = entitylib.character.Humanoid;
		local position: Vector3 = root.Position;
		local points: table = plan.Waypoints;
		while plan.Cursor <= #points do
			local point: table = points[plan.Cursor];
			local height: number = point.Type == 'Drop' and profile.Walk.DropHeight or profile.Walk.WaypointHeight;
			if ((point.Position - position) * flat).Magnitude > profile.Walk.Waypoint or math.abs(point.Position.Y - position.Y) > height or (point.Blocks and not plan:Placed(point)) then
				break;
			end;
			plan.Cursor += 1;
			walker.progress, walker.progressAt = position, now;
		end;
		local point: table? = points[plan.Cursor];
		if not point then
			return 'end';
		end;

		local missing: number, nearest: number, placedOne: boolean = 0, math.huge, false;
		for _: number, block: table in point.Blocks or {} do
			if not plan:Solid(block.Grid) then
				local distance: number = (block.Position - position).Magnitude;
				missing += 1;
				nearest = math.min(nearest, distance);
				if not placedOne and distance <= profile.Build.CoverReach + 4 then
					placedOne = placeAt(block.Position, nil, now);
				end;
			end;
		end;
		if missing > 0 then
			walker.note('building', 'waypoint '..plan.Cursor..'/'..#points..' needs '..missing..', nearest '..string.format('%.1f', nearest)..' away, wool '..world.self.blocks);
			walker.halt();
			walker.progressAt = now;
			return 'building';
		end;
		if now < walker.pauseUntil then
			walker.halt();
			return 'moving';
		end;

		local aim: Vector3 = point.Position;
		for index: number = plan.Cursor + 1, math.min(plan.Cursor + profile.Walk.Lookahead, #points) do
			local previous: table, candidate: table = points[index - 1], points[index];
			if candidate.Type ~= 'Walk' or candidate.Blocks or candidate.AirTime or previous.Blocks or math.abs(candidate.Position.Y - position.Y) > profile.Walk.LookaheadClear then
				break;
			end;
			local offset: Vector3 = candidate.Position - position;
			local samples: number = math.ceil(offset.Magnitude / 3);
			local clear: boolean = true;
			for step: number = 1, samples do
				clear = clear and senses.Ground(position + offset * (step / samples));
			end;
			if not clear then
				break;
			end;
			aim = candidate.Position;
		end;
		if point.Type == 'Drop' then
			local heading: Vector3 = ((points[plan.Cursor + 1] or point).Position - position) * flat;
			if heading.Magnitude > 0.1 then
				aim = point.Position + heading.Unit * profile.Walk.DropOvershoot;
			end;
		end;
		if walker.idleSince and now - walker.idleSince > 1 then
			walker.idleSince = nil;
			walker.pauseUntil = now + between(profile.Walk.StartDelay);
			return 'moving';
		end;
		walker.idleSince = nil;
		walker.sprint();
		walker.command(aim, now, true);
		walker.note('moving');

		local remaining: number = ((points[#points].Position - position) * flat).Magnitude;
		local quiet: boolean = danger(position, profile.Walk.PauseClear, now, nil) == 0;
		local open: boolean = remaining > profile.Walk.HopDistance and plan:Pending() == 0 and humanoid.FloorMaterial ~= Enum.Material.Air;
		walker.weaving = quiet and plan:Pending() == 0;
		if now >= walker.nextPause then
			walker.nextPause = now + jitter((profile.Walk.PauseGap[1] + profile.Walk.PauseGap[2]) / 2, 0.4);
			if quiet and open then
				walker.pauseUntil = now + between(profile.Walk.PauseLength);
			end;
		end;
		if now >= walker.nextHop then
			walker.nextHop = now + between(profile.Walk.HopGap);
			if open and not senses.Surface(position).narrow and senses.Ground(aim) then
				walker.jump(now);
			end;
		end;
		if point.Position.Y - position.Y > profile.Walk.JumpRise and ((point.Position - position) * flat).Magnitude <= profile.Walk.JumpRange then
			walker.jump(now);
		end;

		if not walker.progress or (position - walker.progress).Magnitude >= profile.Walk.StuckDistance then
			walker.progress, walker.progressAt = position, now;
		elseif now - walker.progressAt > profile.Walk.StuckTime then
			walker.progressAt = now;
			if walker.jump(now) then
				return 'moving';
			end;
			local grid: Vector3 = point.Grid or navigation.WorldToGrid(point.Position);
			agent.Memory:Route(grid, 'collision', now);
			if navigation.World then
				local here: Vector3 = navigation.WorldToGrid(position - Vector3.new(0, humanoid.HipHeight - 1.5, 0));
				for x: number = -1, 1 do
					for y: number = -1, 1 do
						for z: number = -1, 1 do
							navigation.World:Invalidate(grid.X + x, grid.Y + y, grid.Z + z);
							navigation.World:Invalidate(here.X + x, here.Y + y, here.Z + z);
						end;
					end;
				end;
			end;
			agent:Invalidate('Stuck against the route');
			walker.note('stuck', 'at waypoint '..plan.Cursor..'/'..#points..' '..point.Type..' '..tostring(point.Position));
			return 'stuck';
		end;
		return 'moving';
	end;

	walker.travel = function(key: string, position: Vector3, radius: number, now: number, vertical: number?, threats: {Vector3}?): string
		local offset: Vector3 = position - entitylib.character.RootPart.Position;
		if (offset * flat).Magnitude <= radius and math.abs(offset.Y) <= (vertical or 6) then
			return 'arrived';
		end;
		local plan: table? = agent:Current();
		local owned: boolean = plan ~= nil and not plan.Expired and walker.key == key;
		if owned and plan:Stale() then
			agent:Invalidate('Route support changed');
			owned = false;
		end;
		if owned and walker.target and (position - walker.target).Magnitude > math.clamp(offset.Magnitude * 0.25, 5, 30) then
			owned = false;
		end;
		if not owned then
			if walker.request and walker.requestKey ~= key then
				walker.request.Cancelled = true;
				walker.request, walker.requestKey = nil, nil;
			end;
			if not walker.request and now >= walker.retryAt then
				walker.ask(key, position, threats, now);
			end;
			if not plan or plan.Expired or walker.key ~= key then
				walker.halt();
				return walker.faults >= profile.Walk.RouteFaults and 'failed' or 'routing';
			end;
		end;
		if plan.Cursor > #plan.Waypoints then
			walker.key = nil;
			return 'end';
		end;
		return walker.follow(plan, now);
	end;

	fight.reset = function(): ()
		fight.side, fight.sideUntil, fight.nextJump = 1, 0, 0;
	end;

	fight.engage = function(record: table, now: number, delta: number): ()
		local root: BasePart = entitylib.character.RootPart;
		local targetRoot: BasePart? = record.root;
		if not targetRoot or not targetRoot.Parent then
			holdAim(false);
			return;
		end;
		local position: Vector3 = targetRoot.Position;
		local distance: number = ((position - root.Position) * flat).Magnitude;
		holdAim(true);
		local errorAngle: number = turnToward(position, delta);
		if distance > profile.Fight.Close + 1.5 then
			local lead: Vector3 = position + (record.velocity or Vector3.zero) * flat * math.min(distance / math.max(world.self.speed or 20, 8), 0.4);
			walker.sprint();
			walker.command(lead, now);
		else
			if now >= fight.sideUntil then
				fight.side = -fight.side;
				fight.sideUntil = now + jitter((profile.Fight.StrafeMin + profile.Fight.StrafeMax) / 2, 0.45);
			end;
			local radial: Vector3 = (root.Position - position) * flat;
			local outward: Vector3 = radial.Magnitude > 0.1 and radial.Unit or root.CFrame.LookVector * flat;
			local tangent: Vector3 = Vector3.new(-outward.Z, 0, outward.X) * fight.side;
			local point: Vector3 = root.Position + tangent * 3 - outward * math.clamp(distance - (profile.Fight.Close + 0.8), -2, 4);
			if not senses.Ground(point) or senses.Surface(point).nearVoid then
				fight.side = -fight.side;
				fight.sideUntil = now + jitter(0.6, 0.3);
				point = root.Position - tangent * 3;
			end;
			walker.command(point, now);
		end;
		if now >= fight.nextJump and distance <= profile.Fight.StrikeRange and math.random() < 0.02 then
			fight.nextJump = now + jitter(1.6, 0.5);
			walker.jump(now);
		end;
		if distance <= math.min(profile.Fight.StrikeRange, profile.Fight.MeleeReach - 2) and errorAngle <= profile.Fight.StrikeCone and now >= mind.nextSwing then
			mind.nextSwing = now + jitter(1 / ClickRate["Value"], 0.25);
			senses.Attack({["target"] = targetRoot, ["player"] = record.player, ["owner"] = record.team});
		end;
	end;

	local finishGoal: (goal: table, now: number, success: boolean, reason: string) -> () = function(goal: table, now: number, success: boolean, reason: string): ()
		log(goal.Kind..' '..goal.Label..' '..(success and 'done' or 'dropped')..': '..reason);
		if not success then
			local failed: table? = mind.failures[goal.Key];
			mind.failures[goal.Key] = {["count"] = (failed and failed.count or 0) + 1, ["at"] = now};
		end;
		mind.goal = nil;
		mind.dirty = mind.dirty or 'Goal ended';
		walker.cancel();
		fight.reset();
		holdAim(false);
	end;

	local closestSite: (list: {table}, accept: (site: table) -> boolean) -> table? = function(list: {table}, accept: (site: table) -> boolean): table?
		local best: table?, gap: number = nil, math.huge;
		for _: number, site: table in list do
			local distance: number = (site.position - world.self.position).Magnitude;
			if site.target.Parent and distance < gap and accept(site) then
				best, gap = site, distance;
			end;
		end;
		return best;
	end;

	local wishlist: () -> {table} = function(): {table}
		local me: table = world.self;
		local economy: table = profile.Economy;
		local list: {table} = {};
		if me.blocks < profile.Build.Floor then
			table.insert(list, {["item"] = 'wool_white', ["urgency"] = 'now', ["blocks"] = profile.Build.Target - me.blocks});
		end;
		local short: table? = mind.shortfall;
		if short and os.clock() - short.at < profile.Memory.Shortfall and me.blocks < short.blocks then
			table.insert(list, {["item"] = 'wool_white', ["urgency"] = 'now', ["blocks"] = short.blocks - me.blocks});
		end;
		local blade: string? = nextTier(economy.Swords, me.sword, 'sword');
		if blade then
			local behind: boolean = planned('sword') > me.sword;
			for _: string, record: table in world.enemies do
				behind = behind or (record.gearAt ~= nil and (record.sword or 0) > me.sword);
			end;
			table.insert(list, {["item"] = blade, ["urgency"] = behind and 'parity' or 'nice'});
		end;
		local chest: table? = bedwars.ItemMeta[economy.Armors[1]];
		local plate: number = chest and me.armorSlots[chest.armor.slot] or 0;
		local vest: string? = chest and nextTier(economy.Armors, plate, 'armor') or nil;
		if vest then
			local exposed: boolean = planned('armor') > plate;
			for _: string, record: table in world.enemies do
				exposed = exposed or (record.gearAt ~= nil and (record.armor or 0) > me.armor + 0.05);
			end;
			table.insert(list, {["item"] = vest, ["urgency"] = exposed and 'armor' or 'soon'});
		end;
		if world.match.phase ~= 'OPENING' then
			for _: number, tool: string in economy.Tools do
				if not getItem(tool) and quote(tool) then
					table.insert(list, {["item"] = tool, ["urgency"] = 'soon'});
				end;
			end;
		end;
		local open: number = mind.coverOpen or 0;
		if CoverBed["Enabled"] and open >= profile.Build.CoverPatience and me.blocks < open + profile.Build.Reserve then
			table.insert(list, {["item"] = 'wool_white', ["urgency"] = 'cover', ["blocks"] = open + profile.Build.Reserve - me.blocks});
		end;
		if world.match.phase ~= 'OPENING' then
			for _: number, upgrade: string in economy.TeamUpgrades do
				table.insert(list, {["item"] = upgrade, ["urgency"] = upgrade == 'ARMOR' and 'armor' or 'upgrade', ["team"] = true});
			end;
		end;
		table.sort(list, function(a: table, b: table): boolean
			return economy.Urgency[a.urgency] > economy.Urgency[b.urgency];
		end);
		return list;
	end;

	goalKinds.SHOP = {
		["Propose"] = function(list: {table}, now: number): ()
			local me: table = world.self;
			local sites: table = senses.Sites();
			local base: Vector3? = world.homes[me.team];
			mind.missing = nil;
			for _: number, want: table in wishlist() do
				local deal: table? = quote(want.item, want.team);
				if deal and (mind.bought[want.item] or -math.huge) + 1.5 < now then
					if want.blocks and deal.amount then
						deal.cost = deal.price * math.max(math.ceil(want.blocks / deal.amount), 1);
					end;
					local value: number = profile.Economy.Urgency[want.urgency];
					if (me.resources[deal.currency] or 0) >= deal.cost then
						local site: table? = closestSite(deal.upgrade and sites.Upgrades or sites.Shops, function(candidate: table): boolean
							if deal.upgrade then
								return base ~= nil and (candidate.position - base).Magnitude <= profile.Economy.BaseRadius;
							end;
							return candidate.owner == me.team or danger(candidate.position, 25, now, nil) < 0.4;
						end);
						if site then
							table.insert(list, {["Kind"] = 'SHOP', ["Key"] = 'shop:'..site.id, ["Label"] = want.item, ["Position"] = site.position, ["Site"] = site, ["Value"] = value, ["Risk"] = danger(site.position, 25, now, nil), ["Reason"] = want.urgency..': '..deal.price..' '..deal.currency..' on hand'});
							return;
						end;
					elseif not mind.missing and value >= profile.Economy.Urgency.soon then
						mind.missing = {["currency"] = deal.currency, ["need"] = deal.cost, ["value"] = value, ["item"] = want.item};
					end;
				end;
			end;
		end,
		["Run"] = function(goal: table, now: number, delta: number): ()
			if goal.Phase == 'APPROACH' then
				local status: string = walker.travel(goal.Key, goal.Position, profile.Economy.ShopRadius, now, 3);
				local close: boolean = (entitylib.character.RootPart.Position - goal.Position).Magnitude <= profile.Economy.ShopReach;
				if status == 'arrived' or status == 'end' and close then
					goal.Phase, goal.Bought, goal.NextBuy, goal.Rejected = 'BUY', 0, now + jitter(Reaction["Value"] / 1000, 0.3), {};
					walker.cancel();
					walker.halt();
				elseif status == 'end' or status == 'failed' then
					finishGoal(goal, now, false, status == 'end' and 'route ended short of the shop' or 'no route to the shop');
				end;
				return;
			end;
			local pending: table? = goal.Pending;
			if pending then
				if pending.done then
					goal.Pending = nil;
					if pending.success then
						goal.Bought += 1;
						mind.bought[pending.item] = now;
						goal.NextBuy = now + jitter(profile.Economy.PurchaseGap, 0.4);
					else
						goal.Rejected[pending.item] = true;
					end;
				elseif now - pending.started > profile.Economy.PurchaseTimeout then
					goal.Rejected[pending.item] = true;
					goal.Pending = nil;
				end;
				return;
			end;
			if now < goal.NextBuy then
				return;
			end;
			if goal.Bought >= profile.Economy.PurchaseLimit then
				finishGoal(goal, now, true, 'bought '..goal.Bought..' items');
				return;
			end;
			for _: number, want: table in wishlist() do
				local deal: table? = quote(want.item, want.team);
				if deal and not goal.Rejected[want.item] and (world.self.resources[deal.currency] or 0) >= deal.price and (deal.upgrade == true) == (goal.Site.shopId == nil) then
					local order: table = {["started"] = now, ["item"] = want.item};
					goal.Pending = order;
					senses.Buy({["target"] = goal.Site.target, ["position"] = goal.Site.position, ["shopId"] = goal.Site.shopId}, deal, function(success: boolean): ()
						order.done, order.success = true, success;
						if success and not deal.upgrade then
							bedwars.AudioManager:playAudio(bedwars.SoundList.BEDWARS_PURCHASE_ITEM);
							bedwars.Store:dispatch({["type"] = 'BedwarsAddItemPurchased', ["itemType"] = deal.item});
							if deal.tiered and bedwars.BedwarsShopController then
								bedwars.BedwarsShopController.alreadyPurchasedMap[deal.item] = true;
							end;
						end;
						mark('Purchase');
					end);
					return;
				end;
			end;
			finishGoal(goal, now, goal.Bought > 0, 'nothing more to buy here');
		end
	};

	goalKinds.FARM = {
		["Propose"] = function(list: {table}, now: number): ()
			local me: table = world.self;
			local need: table? = mind.missing;
			local currency: string = need and need.currency or 'iron';
			local site: table? = closestSite(senses.Sites().Generators, function(candidate: table): boolean
				if candidate.resource ~= currency then
					return false;
				end;
				if candidate.resource ~= 'iron' then
					return danger(candidate.position, 30, now, nil) < 0.5;
				end;
				local owner: table? = candidate.owner and world.teams[candidate.owner];
				return candidate.owner == me.team or owner ~= nil and (owner.members == 0 or not owner.bed);
			end);
			if site then
				table.insert(list, {
					["Kind"] = 'FARM', ["Key"] = 'farm:'..site.id, ["Label"] = site.id, ["Position"] = site.position, ["Site"] = site, ["Currency"] = currency,
					["Need"] = need and need.need or (me.resources[currency] or 0) + 24,
					["Value"] = (need and need.value * 0.8 or profile.Value.Farm) * profile.Phases[world.match.phase].farm,
					["Risk"] = danger(site.position, 25, now, nil),
					["Reason"] = need and need.need..' '..currency..' for '..need.item or 'income'
				});
			end;
		end,
		["Run"] = function(goal: table, now: number, delta: number): ()
			local held: table? = getItem(goal.Currency);
			local amount: number = held and held.amount or 0;
			if amount >= goal.Need then
				finishGoal(goal, now, true, 'collected '..amount..' '..goal.Currency);
				return;
			end;
			if goal.Phase == 'APPROACH' then
				local status: string = walker.travel(goal.Key, goal.Site.position, profile.Economy.Collect, now);
				if status == 'arrived' or status == 'end' then
					goal.Phase, goal.CollectAt = 'COLLECT', now;
					walker.cancel();
					walker.halt();
				elseif status == 'failed' then
					finishGoal(goal, now, false, 'no route to the generator');
				end;
				return;
			end;
			local here: Vector3 = entitylib.character.RootPart.Position;
			if ((goal.Site.position - here) * flat).Magnitude > profile.Economy.DropSearch + profile.Economy.Collect then
				goal.Phase = 'APPROACH';
				return;
			end;
			if goal.Drop and not goal.Drop.Parent then
				goal.Drop = nil;
			end;
			if not goal.Drop and now >= (goal.DropAt or 0) then
				goal.DropAt = now + 0.25;
				local gap: number = math.huge;
				for _: number, drop: Instance in collectionService:GetTagged('ItemDrop') do
					if drop.Name == goal.Currency and drop:IsA('BasePart') and (drop.Position - goal.Site.position).Magnitude <= profile.Economy.DropSearch and (drop.Position - here).Magnitude < gap and walker.floor(drop.Position) then
						goal.Drop, gap = drop, (drop.Position - here).Magnitude;
					end;
				end;
			end;
			if goal.Drop then
				walker.command(goal.Drop.Position, now);
			elseif now >= (goal.DriftAt or 0) then
				goal.DriftAt = now + jitter(profile.Walk.IdleDrift, 0.6);
				local angle: number = math.random() * math.pi * 2;
				walker.command(goal.Site.position + Vector3.new(math.cos(angle), 0, math.sin(angle)) * 2, now);
			end;
			if now - goal.CollectAt > profile.Economy.CollectWait + goal.Need / 4 then
				finishGoal(goal, now, false, 'generator wait expired');
			end;
		end
	};

	goalKinds.COVER = {
		["Propose"] = function(list: {table}, now: number): ()
			local own: table? = world.teams[world.self.team];
			mind.coverOpen = 0;
			if not CoverBed["Enabled"] or not own or not own.bed or not own.bed.part.Parent then
				return;
			end;
			local open: {Vector3} = openFaces(own.bed.part);
			mind.coverOpen = #open;
			if #open >= profile.Build.CoverPatience and world.self.blocks >= math.min(#open, 6) then
				table.insert(list, {
					["Kind"] = 'COVER', ["Key"] = 'cover', ["Label"] = 'bed', ["Position"] = own.bed.position, ["Bed"] = own.bed,
					["Value"] = profile.Value.Cover * profile.Phases[world.match.phase].cover * profile.Styles[Style["Value"]].cover * math.min(#open / 5, 1),
					["Risk"] = danger(own.bed.position, 20, now, nil),
					["Reason"] = #open..' open faces'
				});
			end;
		end,
		["Run"] = function(goal: table, now: number, delta: number): ()
			local bed: BasePart = goal.Bed.part;
			local root: BasePart = entitylib.character.RootPart;
			if not bed.Parent then
				finishGoal(goal, now, false, 'bed is gone');
				return;
			end;
			if goal.Phase == 'APPROACH' then
				local status: string = walker.travel(goal.Key, goal.Position, profile.Build.CoverRadius, now);
				if status == 'arrived' or status == 'end' and (bed.Position - root.Position).Magnitude <= profile.Build.CoverReach then
					goal.Phase, goal.CoverAt = 'COVER', now;
					walker.cancel();
					walker.halt();
				elseif status == 'failed' or status == 'end' then
					finishGoal(goal, now, false, 'cannot reach the bed');
				end;
				return;
			end;
			local open: {Vector3} = openFaces(bed);
			mind.coverOpen = #open;
			if #open == 0 then
				finishGoal(goal, now, true, 'bed is covered');
				return;
			elseif now - goal.CoverAt > profile.Build.CoverTimeout then
				finishGoal(goal, now, false, 'cover took too long');
				return;
			end;
			local block: string? = nil;
			for _: number, itemType: string in profile.Build.CoverItems do
				block = block or (getItem(itemType) and itemType or nil);
			end;
			block = block or getWool();
			if not block then
				finishGoal(goal, now, false, 'out of cover blocks');
				return;
			end;
			local closest: Vector3?, gap: number = nil, math.huge;
			for _: number, face: Vector3 in open do
				local offset: Vector3 = face - root.Position;
				if offset.Magnitude <= profile.Build.CoverReach and ((offset * flat).Magnitude > 2.4 or math.abs(offset.Y) > 4) then
					turnToward(face, delta);
					placeAt(face, block, now);
					return;
				end;
				if offset.Magnitude < gap then
					closest, gap = face, offset.Magnitude;
				end;
			end;
			if closest then
				walker.travel('cover:reach', closest, 4, now);
			end;
		end
	};

	goalKinds.LOOT = {
		["Propose"] = function(list: {table}, now: number): ()
			local me: table = world.self;
			local best: table?, rank: number = nil, -math.huge;
			for _: number, drop: Instance in collectionService:GetTagged('ItemDrop') do
				local worth: number? = profile.Economy.Loot[drop.Name];
				if worth and drop:IsA('BasePart') and drop.Parent then
					local offset: Vector3 = drop.Position - me.position;
					local distance: number = (offset * flat).Magnitude;
					if distance <= profile.Economy.LootRadius and math.abs(offset.Y) <= 14 and walker.floor(drop.Position) then
						local amount: number = drop:GetAttribute('Amount') or 1;
						local value: number = worth * (0.7 + 0.15 * math.min(amount, 6));
						local risk: number = danger(drop.Position, 20, now, nil);
						if value - distance * 0.4 - risk * profile.Decide.RiskWeight > rank then
							best, rank = {["Part"] = drop, ["Value"] = value, ["Risk"] = risk, ["Amount"] = amount}, value - distance * 0.4 - risk * profile.Decide.RiskWeight;
						end;
					end;
				end;
			end;
			if best then
				table.insert(list, {
					["Kind"] = 'LOOT', ["Key"] = 'loot:'..tostring(best.Part:GetAttribute('Id') or best.Part.Position), ["Label"] = best.Part.Name,
					["Position"] = best.Part.Position, ["Part"] = best.Part, ["Value"] = best.Value, ["Risk"] = best.Risk, ["Reason"] = best.Amount..' on the ground'
				});
			end;
		end,
		["Run"] = function(goal: table, now: number, delta: number): ()
			if not goal.Part.Parent then
				finishGoal(goal, now, true, 'picked up');
				return;
			elseif now - goal.StartedAt > profile.Economy.LootTimeout then
				finishGoal(goal, now, false, 'could not reach it');
				return;
			end;
			local status: string = walker.travel(goal.Key, goal.Part.Position, profile.Economy.Pickup, now, 6);
			if status == 'arrived' or status == 'end' then
				walker.command(goal.Part.Position, now);
			elseif status == 'failed' then
				finishGoal(goal, now, false, 'no route to it');
			end;
		end
	};

	goalKinds.RAID = {
		["Propose"] = function(list: {table}, now: number): ()
			if not BreakBeds["Enabled"] then
				return;
			end;
			local me: table = world.self;
			local targets: {table}, positions: {Vector3} = {}, {};
			for id: string, team: table in world.teams do
				if id ~= me.team and team.bed and not team.bed.locked and team.bed.part.Parent and (team.members > 0 or EmptyBeds["Enabled"]) then
					table.insert(targets, team);
					table.insert(positions, team.bed.position);
				end;
			end;
			if #targets == 0 then
				return;
			end;
			local costs: table = navigation.World and navigation:GetBlockCosts(me.position, positions, {["Mode"] = 'Legit'}) or {};
			local cheapest: number = math.huge;
			for index: number, team: table in targets do
				local blocks: number = costs[index] or 0;
				local key: string = 'raid:'..tostring(team.id or team.bed.team);
				mind.estimates[key] = blocks;
				cheapest = math.min(cheapest, blocks);
				if blocks <= 0 or blocks * profile.Build.Margin + profile.Build.Reserve <= me.blocks then
					local defence: number = danger(team.bed.position, 28, now, nil);
					local early: number = me.sword < itemPower('stone_sword') and world.match.elapsed < 40 and 0.5 or 1;
					table.insert(list, {
						["Kind"] = 'RAID', ["Key"] = key, ["Label"] = 'team '..tostring(team.bed.team), ["Position"] = team.bed.position, ["Bed"] = team.bed,
						["Value"] = profile.Value.Bed * profile.Phases[world.match.phase].bed * profile.Styles[Style["Value"]].bed * early,
						["Risk"] = defence,
						["Reason"] = math.floor(blocks)..' blocks, '..string.format('%.1f', defence)..' defence'
					});
				end;
			end;
			if cheapest < math.huge and cheapest * profile.Build.Margin + profile.Build.Reserve > me.blocks then
				mind.shortfall = {["key"] = 'raid', ["blocks"] = math.min(math.ceil(cheapest * profile.Build.Margin) + profile.Build.Reserve, profile.Build.Target), ["at"] = now};
			end;
		end,
		["Run"] = function(goal: table, now: number, delta: number): ()
			local bed: BasePart = goal.Bed.part;
			if not bed.Parent then
				finishGoal(goal, now, true, 'bed destroyed');
				return;
			end;
			local root: BasePart = entitylib.character.RootPart;
			local distance: number = (bed.Position - root.Position).Magnitude;
			if goal.Phase == 'APPROACH' then
				local status: string = walker.travel(goal.Key, goal.Position, profile.Build.BreakRadius, now, 8);
				if status == 'arrived' or distance <= profile.Build.BreakReach and senses.Ground(root.Position) then
					goal.Phase, goal.BreakAt = 'BREAK', now;
					walker.cancel();
					walker.halt();
				elseif status == 'end' or status == 'failed' then
					finishGoal(goal, now, false, status == 'end' and 'route ended short of the bed' or 'no route to the bed');
				end;
				return;
			end;
			if distance > profile.Build.BreakReach + 3 then
				goal.Phase = 'APPROACH';
				return;
			end;
			turnToward(bed.Position, delta);
			if now >= mind.nextBreak and (bed:GetAttribute('BedShieldEndTime') or 0) <= workspace:GetServerTimeNow() then
				mind.nextBreak = now + jitter(profile.Build.BreakInterval, 0.3);
				task.spawn(breakBlock, bed, {["Effects"] = true, ["Animation"] = 'Normal', ["AutoTool"] = true});
			end;
			if now - goal.BreakAt > profile.Build.BreakStall + 20 then
				finishGoal(goal, now, false, 'bed will not break');
			end;
		end
	};

	goalKinds.FIGHT = {
		["Propose"] = function(list: {table}, now: number): ()
			local me: table = world.self;
			local own: table? = world.teams[me.team];
			local home: Vector3? = own and own.bed and own.bed.position or world.homes[me.team];
			for _: string, record: table in world.enemies do
				if known(record, now) and not record.protected then
					local chance: number = odds(record);
					local retaliating: boolean = now - record.hitAt <= profile.Memory.Hit;
					local intruder: boolean = home ~= nil and (record.position - home).Magnitude <= profile.Fight.DefendRange;
					if (record.position - me.position).Magnitude <= profile.Fight.Range or retaliating or intruder then
						local value: number = profile.Value.Fight * profile.Phases[world.match.phase].fight * profile.Styles[Style["Value"]].fight * (0.4 + chance);
						value += retaliating and profile.Fight.Retaliate or 0;
						value = intruder and math.max(value, profile.Fight.Defend * (0.5 + chance * 0.5)) or value;
						value *= (chance < 0.35 and not retaliating) and 0.25 or 1;
						table.insert(list, {
							["Kind"] = 'FIGHT', ["Key"] = 'fight:'..record.id, ["Label"] = record.name, ["Position"] = record.position, ["Record"] = record,
							["Value"] = value, ["Risk"] = 0,
							["Reason"] = 'odds '..string.format('%.2f', chance)..(retaliating and ' retaliating' or '')..(intruder and ' intruder' or '')
						});
					end;
				end;
			end;
		end,
		["Run"] = function(goal: table, now: number, delta: number): ()
			local record: table = goal.Record;
			if not record.alive or record.protected then
				finishGoal(goal, now, true, 'target is down');
				return;
			end;
			if not record.root or now - record.seenAt > profile.Memory.Visible then
				if not known(record, now) then
					finishGoal(goal, now, false, 'lost sight of the target');
					return;
				end;
				holdAim(false);
				local status: string = walker.travel(goal.Key, record.position, 4, now);
				if status == 'arrived' or status == 'failed' or status == 'end' then
					record.seenAt = -math.huge;
				end;
				return;
			end;
			if (record.position - world.self.position).Magnitude > profile.Fight.Disengage and now - record.hitAt > profile.Memory.Hit then
				finishGoal(goal, now, false, 'target got away');
				return;
			end;
			fight.engage(record, now, delta);
		end
	};

	goalKinds.RETREAT = {
		["Propose"] = function(list: {table}, now: number): ()
			local me: table = world.self;
			if me.ratio >= RetreatHealth["Value"] / 100 then
				return;
			end;
			local record: table?, distance: number = nearestEnemy(now);
			if record and distance <= profile.Fight.RetreatDistance + 10 or now - mind.hitAt <= profile.Memory.Hit then
				table.insert(list, {
					["Kind"] = 'RETREAT', ["Key"] = 'retreat', ["Label"] = 'safe ground', ["Position"] = me.position,
					["Value"] = 150 * (1 - me.ratio / math.max(RetreatHealth["Value"] / 100, 0.01)) + 60, ["Risk"] = 0,
					["Reason"] = 'health '..math.floor(me.ratio * 100)..'%'
				});
			end;
		end,
		["Run"] = function(goal: table, now: number, delta: number): ()
			local me: table = world.self;
			local record: table?, distance: number = nearestEnemy(now);
			local threatened: boolean = record ~= nil and distance <= profile.Fight.RetreatDistance and odds(record) < 0.5;
			for _: string, enemy: table in world.enemies do
				threatened = threatened or (enemy.alive and now - enemy.hitAt <= profile.Memory.Hit);
			end;
			if me.ratio >= math.min(RetreatHealth["Value"] / 100 + 0.25, 0.9) and not threatened then
				finishGoal(goal, now, true, 'recovered');
				return;
			end;
			holdAim(false);
			local own: table? = world.teams[me.team];
			local home: Vector3? = own and own.bed and own.bed.position or world.homes[me.team];
			if home and ((home - me.position) * flat).Magnitude > 8 and danger(home, 20, now, nil) < 0.6 and walker.faults < profile.Walk.RouteFaults then
				walker.travel('retreat:home', home, 8, now);
				return;
			end;
			if record and distance <= profile.Fight.RetreatDistance then
				local away: Vector3 = (me.position - record.position) * flat;
				local point: Vector3 = away.Magnitude > 0.1 and me.position + away.Unit * 14 or me.position;
				if away.Magnitude > 0.1 and senses.Ground(point) then
					walker.command(point, now);
					return;
				end;
			end;
			walker.halt();
		end
	};

	goalKinds.HUNT = {
		["Propose"] = function(list: {table}, now: number): ()
			if not HuntPlayers["Enabled"] or world.match.enemyBeds > 0 and world.match.phase ~= 'FINAL' then
				return;
			end;
			for _: string, record: table in world.enemies do
				local position: Vector3? = known(record, now) and record.position or world.homes[record.team];
				if record.alive and not record.protected and position then
					table.insert(list, {
						["Kind"] = 'HUNT', ["Key"] = 'hunt:'..record.id, ["Label"] = record.name, ["Position"] = position, ["Record"] = record,
						["Value"] = profile.Value.Hunt * profile.Phases[world.match.phase].fight,
						["Risk"] = danger(position, 20, now, record),
						["Reason"] = known(record, now) and 'last seen' or 'checking their island'
					});
				end;
			end;
		end,
		["Run"] = function(goal: table, now: number, delta: number): ()
			local record: table = goal.Record;
			if not record.alive then
				finishGoal(goal, now, true, 'target is down');
				return;
			end;
			if record.root and now - record.seenAt <= profile.Memory.Visible and (record.position - world.self.position).Magnitude <= profile.Fight.Range then
				fight.engage(record, now, delta);
				return;
			end;
			holdAim(false);
			local position: Vector3? = known(record, now) and record.position or world.homes[record.team];
			if not position then
				finishGoal(goal, now, false, 'nowhere to look');
				return;
			end;
			goal.Position = position;
			local status: string = walker.travel(goal.Key, position, 6, now);
			if status == 'failed' then
				finishGoal(goal, now, false, 'no route to the target');
			elseif status == 'arrived' and not known(record, now) then
				finishGoal(goal, now, false, 'they are not here');
			end;
		end
	};

	goalKinds.WAIT = {
		["Propose"] = function(list: {table}, now: number): ()
			local own: table? = world.teams[world.self.team];
			table.insert(list, {
				["Kind"] = 'WAIT', ["Key"] = 'wait', ["Label"] = 'base',
				["Position"] = own and own.bed and own.bed.position or world.homes[world.self.team] or world.self.position,
				["Value"] = profile.Value.Wait, ["Risk"] = 0, ["Reason"] = 'nothing better to do'
			});
		end,
		["Run"] = function(goal: table, now: number, delta: number): ()
			local status: string = walker.travel(goal.Key, goal.Position, 9, now);
			if (status == 'arrived' or status == 'end') and now >= (goal.DriftAt or 0) then
				goal.DriftAt = now + jitter(profile.Walk.IdleDrift, 0.6);
				local angle: number = math.random() * math.pi * 2;
				walker.command(entitylib.character.RootPart.Position + Vector3.new(math.cos(angle), 0, math.sin(angle)) * 2.5, now);
			elseif status == 'failed' then
				finishGoal(goal, now, false, 'no route to the base');
			end;
		end
	};
	local proposalOrder: {string} = {'SHOP', 'FARM', 'COVER', 'LOOT', 'RAID', 'FIGHT', 'RETREAT', 'HUNT', 'WAIT'};

	local think: (now: number) -> () = function(now: number): ()
		mind.dirty = false;
		mind.nextThink = now + profile.Timing.Think;
		local candidates: {table} = {};
		for _: number, kind: string in proposalOrder do
			goalKinds[kind].Propose(candidates, now);
		end;
		local current: table? = mind.goal;
		local best: table?, stay: table? = nil, nil;
		for _: number, candidate: table in candidates do
			local failed: table? = mind.failures[candidate.Key];
			local penalty: number = failed and profile.Memory.FailureWeight * failed.count * math.max(1 - (now - failed.at) / profile.Memory.FailureLife, 0) or 0;
			local travel: number = ((candidate.Position - world.self.position) * flat).Magnitude * profile.Decide.Detour / math.max(world.self.speed or 20, 8);
			candidate.Score = candidate.Value - travel * profile.Decide.TravelWeight - candidate.Risk * profile.Decide.RiskWeight - penalty + (current and current.Key == candidate.Key and profile.Decide.Commit or 0);
			stay = current and candidate.Key == current.Key and candidate or stay;
			best = (not best or candidate.Score > best.Score) and candidate or best;
		end;
		if not best then
			return;
		end;
		if current and stay then
			for key: string, value: any in stay do
				current[key] = value;
			end;
			if best.Key == current.Key or best.Score < stay.Score + profile.Decide.SwitchMargin then
				return;
			end;
		end;
		best.StartedAt, best.Phase = now, 'APPROACH';
		walker.tunnels = best.Kind == 'RAID' or best.Kind == 'HUNT';
		if current then
			walker.cancel();
			fight.reset();
		end;
		holdAim(false);
		mind.goal = best;
		log('goal '..best.Kind..' '..best.Label..' ('..string.format('%.0f', best.Score)..'): '..best.Reason);
	end;

	local resetState: () -> () = function(): ()
		mind = {
			["goal"] = nil, ["failures"] = {}, ["nextObserve"] = 0, ["nextThink"] = 0, ["readyAt"] = 0, ["nextPlace"] = 0,
			["nextBreak"] = 0, ["nextSwing"] = 0, ["placed"] = {}, ["bought"] = {}, ["estimates"] = {}, ["dirty"] = false,
			["began"] = os.clock(), ["hitAt"] = -math.huge, ["active"] = false
		};
		world = {
			["self"] = {["resources"] = {}, ["armorSlots"] = {}, ["ratio"] = 1, ["blocks"] = 0, ["sword"] = 0, ["armor"] = 0},
			["teams"] = {}, ["enemies"] = {}, ["homes"] = {},
			["match"] = {["elapsed"] = 0, ["phase"] = 'OPENING', ["enemyBeds"] = 0, ["enemyTeams"] = 0, ["enemyPlayers"] = 0, ["ownBed"] = true}
		};
		walker.request, walker.requestKey, walker.key, walker.target, walker.retryAt, walker.faults = nil, nil, nil, nil, 0, 0;
		walker.seed, walker.blockedAt, walker.deflect, walker.tunnels = math.random() * 100, nil, nil, false;
		walker.nextPause, walker.pauseUntil, walker.nextHop, walker.idleSince, walker.weaving = 0, 0, 0, nil, true;
		walker.commanded, walker.commandedAt, walker.jumpedAt, walker.progress, walker.progressAt = nil, 0, 0, nil, 0;
		fight.reset();
	end;

	local errorLimit: number = 3;

	local standDown: () -> () = function(): ()
		walker.cancel();
		fight.reset();
		holdAim(false);
		mind.goal = nil;
	end;

	local step: (now: number, delta: number) -> () = function(now: number, delta: number): ()
		local playing: boolean = alive() and store.matchState == 1 and isnetworkowner(entitylib.character.RootPart);
		if not playing then
			if mind.active then
				mind.active = false;
				standDown();
			end;
			return;
		end;
		if not mind.active then
			mind.active = true;
			mark('Resumed control');
		end;
		senses.Filter();
		if now >= mind.nextObserve then
			mind.nextObserve = now + profile.Timing.Observe;
			observe(now);
		end;
		if now >= mind.readyAt and (mind.dirty or now >= mind.nextThink) then
			think(now);
		end;
		local goal: table? = mind.goal;
		if not goal then
			walker.halt();
			return;
		end;
		if now - goal.StartedAt > profile.Timing.GoalTimeout and goal.Kind ~= 'WAIT' and goal.Kind ~= 'FIGHT' then
			finishGoal(goal, now, false, 'timed out');
			return;
		end;
		goalKinds[goal.Kind].Run(goal, now, delta);
	end;

	LegitAutoPlay = vape.Categories.Utility:CreateModule({
		["Name"] = 'LegitAutoPlay',
		["Function"] = function(callback: boolean): ()
			if not callback then
				holdAim(false);
				if entitylib.isAlive then
					walker.halt();
				end;
				if agent then
					agent:Destroy();
				end;
				if mind then
					mind.goal = nil;
				end;
				agent, senses = nil, nil;
				return;
			end;
			local pathModel: Model = Instance.new('Model');
			pathModel.Name = 'legitPathModel';
			pathModel.Parent = workspace.Terrain;
			LegitAutoPlay:Clean(pathModel);
			agent = navigation.newAgent({
				["Config"] = {["BlockReserve"] = profile.Build.Reserve},
				["Context"] = {
					["Player"] = lplr,
					["Players"] = playersService,
					["Collection"] = collectionService,
					["Entity"] = entitylib,
					["Store"] = store,
					["bedwars"] = setmetatable({
						["Handler"] = {
							["Get"] = function(self: table, name: string): table
								return {["Fire"] = function(_: table, method: string?, ...: any): any
									return fire(name, method, ...);
								end};
							end
						},
						["breakBlock"] = function(block: Instance): ()
							breakBlock(block, {["Effects"] = true, ["Animation"] = 'Normal', ["AutoTool"] = true});
						end,
						["placeBlock"] = placeBlock
					}, {__index = bedwars}),
					["PathModel"] = pathModel,
					["PlacedBlock"] = getPlacedBlock,
					["Wool"] = getWool,
					["Item"] = getItem,
					["Hotbar"] = hotbarSlotOf,
					["CanPlace"] = canPlace,
					["CanSwing"] = canSwing,
					["Projectiles"] = function(filter: {string}?): {table}
						local tuples: {table} = {};
						for _: number, entry: table in getProjectiles(filter) do
							table.insert(tuples, {entry.Item, entry.Ammo, entry.Projectile, entry.Source});
						end;
						return tuples;
					end,
					["FireProjectile"] = ballistics.fire,
					["BreakEnabled"] = function(): boolean
						return BreakBeds["Enabled"];
					end,
					["DebugEnabled"] = function(): boolean
						return Debug["Enabled"];
					end
				}
			});
			senses = agent.Interface;
			resetState();

			LegitAutoPlay:Clean(vapeEvents.BedwarsBedBreak.Event:Connect(function(): ()
				senses.Mark('beds');
				mark('Bed destroyed');
			end));
			LegitAutoPlay:Clean(vapeEvents.EntityDeathEvent.Event:Connect(function(death: table): ()
				if death.entityInstance == lplr.Character then
					walker.cancel();
					fight.reset();
					mind.goal = nil;
					return;
				end;
				local killed: Player? = death.entityInstance and playersService:GetPlayerFromCharacter(death.entityInstance);
				local record: table? = killed and world.enemies[tostring(killed.UserId)];
				if record then
					record.alive, record.root, record.seenAt = false, nil, -math.huge;
					mark('Enemy died');
				end;
			end));
			LegitAutoPlay:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damage: table): ()
				if damage.entityInstance ~= lplr.Character then
					return;
				end;
				local attacker: Player? = damage.fromEntity and playersService:GetPlayerFromCharacter(damage.fromEntity);
				local record: table? = attacker and world.enemies[tostring(attacker.UserId)];
				mind.hitAt = os.clock();
				if record then
					record.hitAt = os.clock();
				end;
				mark('Under attack');
			end));
			LegitAutoPlay:Clean(vapeEvents.InventoryAmountChanged.Event:Connect(function(): ()
				mark('Inventory changed');
			end));
			LegitAutoPlay:Clean(vapeEvents.PlaceBlockEvent.Event:Connect(function(placement: table): ()
				if placement.player ~= lplr then
					senses.Obstacle(placement.blockRef.blockPosition * 3);
				end;
			end));
			LegitAutoPlay:Clean(entitylib.Events.LocalAdded:Connect(function(): ()
				mark('Respawned');
			end));

			LegitAutoPlay:Clean(runService.Heartbeat:Connect(function(delta: number): ()
				local ran: boolean, problem: any = xpcall(step, debug.traceback, os.clock(), delta);
				if ran then
					return;
				end;
				warn('[Velocity] legitautoplay step failed: '..tostring(problem));
				mind.errors = (mind.errors or 0) + 1;
				if mind.errors >= errorLimit then
					mind.errors = 0;
					standDown();
				end;
			end));
		end,
		["Tooltip"] = 'Plays the match like a person: walks with the humanoid, turns and clicks at human rates, and weighs shopping, farming, covering your bed, raiding beds and fighting as the match changes.'
	});
	Reaction = LegitAutoPlay:CreateSlider({
		["Name"] = 'Reaction time',
		["Min"] = 100,
		["Max"] = 600,
		["Default"] = 240,
		["Suffix"] = 'ms',
		["Tooltip"] = 'How long it takes to react after something changes, like being hit or a bed breaking.'
	});
	TurnSpeed = LegitAutoPlay:CreateSlider({
		["Name"] = 'Turn speed',
		["Min"] = 120,
		["Max"] = 1080,
		["Default"] = 520,
		["Suffix"] = 'deg/s',
		["Tooltip"] = 'Fastest it turns to face a target; it never snaps.'
	});
	ClickRate = LegitAutoPlay:CreateSlider({
		["Name"] = 'Click rate',
		["Min"] = 4,
		["Max"] = 14,
		["Default"] = 9,
		["Decimal"] = 10,
		["Suffix"] = 'cps',
		["Tooltip"] = 'Average sword swings per second; each click is randomised around it.'
	});
	RetreatHealth = LegitAutoPlay:CreateSlider({
		["Name"] = 'Retreat health',
		["Min"] = 5,
		["Max"] = 90,
		["Default"] = 35,
		["Suffix"] = '%',
		["Tooltip"] = 'Health where it stops fighting and falls back to your bed when enemies are close.'
	});
	Style = LegitAutoPlay:CreateDropdown({
		["Name"] = 'Style',
		["List"] = {'Balanced', 'Aggressive', 'Defensive'},
		["Tooltip"] = 'Balanced - weighs everything evenly\nAggressive - goes for beds and fights sooner\nDefensive - covers and defends your bed more'
	});
	BreakBeds = LegitAutoPlay:CreateToggle({
		["Name"] = 'Break beds',
		["Default"] = true,
		["Tooltip"] = 'Go after enemy beds; off, it only farms, shops and fights.'
	});
	CoverBed = LegitAutoPlay:CreateToggle({
		["Name"] = 'Cover bed',
		["Default"] = true,
		["Tooltip"] = 'Wall off the open sides of your own bed with the best blocks you carry.'
	});
	HuntPlayers = LegitAutoPlay:CreateToggle({
		["Name"] = 'Hunt players',
		["Default"] = true,
		["Tooltip"] = 'Once every enemy bed is gone it searches for the remaining players.'
	});
	EmptyBeds = LegitAutoPlay:CreateToggle({
		["Name"] = 'Empty beds',
		["Tooltip"] = 'Also go after beds whose team has no players (custom matches, training rooms).'
	});
	Debug = LegitAutoPlay:CreateToggle({
		["Name"] = 'Debug',
		["Tooltip"] = 'Warn on every goal change with its score and reason.'
	});
end);

velo.run(function(): ()
	local AutoCounterTNT: table = {["Enabled"] = false};
	local Range: table;
	local LimitToItem: table;
	local AutoSwitch: table = {};
	local scanGap: number, placeGap: number, rememberFor: number = 0.1, 0.12, 3;

	AutoCounterTNT = vape.Categories.Utility:CreateModule({
		["Name"] = 'AutoCounterTNT',
		["Function"] = function(callback: boolean): ()
			if not callback then
				return;
			end;
			local tnts: {BasePart} = {};
			local countered: {[Vector3]: number} = {};
			AutoCounterTNT:Clean(workspace.ChildAdded:Connect(function(child: Instance): ()
				if child.Name ~= 'tnt' or not child:IsA('BasePart') then
					return;
				end;
				table.insert(tnts, child);
				child.Destroying:Once(function(): ()
					local index: number? = table.find(tnts, child);
					if index then
						table.remove(tnts, index);
					end;
				end);
			end));
			repeat
				for spot: Vector3, expiry: number in countered do
					if expiry <= tick() then
						countered[spot] = nil;
					end;
				end;
				if entitylib.isAlive then
					local tool: Instance?;
					if LimitToItem["Enabled"] then
						tool = store.hand.tool and store.hand.tool.Name == 'tnt' and store.hand.tool or nil;
					else
						local held: table? = getItem('tnt');
						tool = held and held.tool or nil;
					end;
					if tool then
						local origin: Vector3 = entitylib.character.RootPart.Position;
						for _: number, tnt: BasePart in tnts do
							local spot: Vector3 = Vector3.new(math.round(tnt.Position.X), math.round(tnt.Position.Y), math.round(tnt.Position.Z));
							if tnt.AssemblyLinearVelocity.Y >= 0 and not countered[spot] and (origin - tnt.Position).Magnitude <= Range["Value"] then
								if not LimitToItem["Enabled"] and AutoSwitch["Enabled"] then
									local slot: number? = hotbarSlotOf(tool);
									switchItem(tool);
									hotbarSwitch(slot);
								end;
								countered[spot] = tick() + rememberFor;
								task.spawn(placeBlock, tnt.Position, tool.Name);
								task.wait(placeGap);
							end;
						end;
					end;
				end;
				task.wait(scanGap);
			until not AutoCounterTNT["Enabled"];
		end,
		["Tooltip"] = "Automatically places tnt on opponent's tnt"
	});
	Range = AutoCounterTNT:CreateSlider({
		["Name"] = 'Range',
		["Min"] = 1,
		["Max"] = 60,
		["Default"] = 30
	});
	LimitToItem = AutoCounterTNT:CreateToggle({
		["Name"] = 'Limit to item',
		["Function"] = function(callback: boolean): ()
			if AutoSwitch.Object then
				AutoSwitch.Object.Visible = not callback;
			end;
		end,
		["Tooltip"] = 'Only counter while you are holding tnt'
	});
	AutoSwitch = AutoCounterTNT:CreateToggle({
		["Name"] = 'Auto Switch',
		["Default"] = true,
		["Function"] = function(callback: boolean): ()
			LimitToItem.Object.Visible = not callback;
		end,
		["Tooltip"] = 'Switches to tnt before countering'
	});
end);

velo.run(function(): ()
	local AutoHalloween: table = {["Enabled"] = false};
