	local sceneStyle: {[string]: string} = {["halloween_obby"] = 'none', ["skeleton_boss"] = 'bow', ["halloween_2025_stage_2"] = 'both', ["halloween_2024_stage_3"] = 'both'};
	local tuning: {[string]: {[string]: any}} = {
