velo.run(function(): ()
	local checkRate: number = 0.1;
	local banners: {[string]: string} = {["Fire"] = 'damage_banner', ["Defense"] = 'defense_banner', ["Heal"] = 'heal_banner'};
	local spots: {Vector3} = {Vector3.new(3, 3, 0), Vector3.new(-3, 3, 0), Vector3.new(0, 3, 3), Vector3.new(0, 3, -3), Vector3.new(0, 3, 0)};
	local Banner: table;
	local Trigger: table;
	local Range: table;
	local Cooldown: table;
	local LegitSwitch: table;
	local SwitchDelay: table;
