			local oldLaunch: (...any) -> ...any = bedwars.CannonHandController.launchSelf;
			bedwars.CannonController.startAiming = function(self: table, cannon: BasePart?, ...: any): ...any
				local results: table = table.pack(oldAim(self, cannon, ...));
