		["Options"] = function(autoKit: table): {table}
			local meta: table? = bedwars.BedwarsKitMeta.battery;
			Drink = autoKit:CreateToggle({["Name"] = meta and meta.name or 'Battery', ["Default"] = true, ["Tooltip"] = 'Drinks every charged battery you stand next to'});
