			FullCharge = autoKit:CreateToggle({["Name"] = 'Lumen Full charge', ["Default"] = true, ["Tooltip"] = 'Holds to max charge (an upgraded lumen only fires the multi beam at full charge)'});
			Delay = autoKit:CreateSlider({["Name"] = 'Lumen Delay', ["Min"] = 0, ["Max"] = 2, ["Default"] = 0.1, ["Decimal"] = 100, ["Suffix"] = 's'});
			return {Range, FullCharge, Delay};
		end,
		["Start"] = function(autoKit: table): ()
			local charger: table = bedwars.SwordChargeController;
			local balance: table = bedwars.LumenBalance or {["MIN_CHARGE_TIME"] = 0.65, ["MAX_CHARGE_TIME"] = 1.25};
			local started: number?, holdFor: number = nil, 0;
			local nextCheck: number, cooldown: number = 0, 0;
			autoKit:Clean(function(): ()
				if started then
					charger:stopCharging(swordType);
				end;
			end);
