			Charge = autoKit:CreateToggle({["Name"] = 'Sigrid Charge attack', ["Tooltip"] = 'Charges whoever is in range while riding the elk'});
			Range = autoKit:CreateSlider({["Name"] = 'Sigrid Range', ["Min"] = 1, ["Max"] = 80, ["Default"] = 40, ["Suffix"] = 'studs'});
