			SwapAura = autoKit:CreateToggle({["Name"] = 'Silas Swap aura', ["Default"] = true, ["Tooltip"] = 'Damage aura near enemies, healing aura near hurt allies'});
			PressAttack = autoKit:CreateToggle({["Name"] = 'Silas Press the attack', ["Default"] = true, ["Tooltip"] = 'Uses the shield ability when an enemy gets close'});
			return {Range, SwapAura, PressAttack};
		end,
		["Start"] = function(autoKit: table): ()
			local aura: string = '';
			local nextCheck: number = 0;
			autoKit:Clean(bedwars.Client:Get('UpdateRebellionAura'):Connect(function(data: table): ()
				if data.player == lplr then
					aura = data.newAura;
				end;
			end));
			autoKit:Clean(runService.Heartbeat:Connect(function(): ()
				if tick() < nextCheck or not entitylib.isAlive then
					return;
				end;
				nextCheck = tick() + checkRate;
				local origin: Vector3 = entitylib.character.RootPart.Position;
				local enemy: table? = entitylib.EntityPosition({["Origin"] = origin, ["Range"] = Range["Value"], ["Part"] = 'RootPart', ["Players"] = true, ["Priority"] = false});
				if PressAttack["Enabled"] and enemy and bedwars.AbilityController:canUseAbility('rebellion_shield', quiet) then
					bedwars.AbilityController:useAbility('rebellion_shield');
				end;
				if not SwapAura["Enabled"] or aura == '' then
					return;
				end;
				local wanted: string? = enemy and 'damage' or nil;
				for _: number, ent: table in (wanted and {} or entitylib.List) do
