						wanted = 'healing';
						break;
					end;
				end;
				if wanted and wanted ~= aura and bedwars.AbilityController:canUseAbility('rebellion_aura_swap', quiet) then
					bedwars.AbilityController:useAbility('rebellion_aura_swap');
				end;
			end));
		end
	};
end);

velo.run(function(): ()
	local checkRate: number = 0.1;
	local expiryMargin: number = 1;
	local quiet: table = {["disableBlockedAbilityAlert"] = true};
	local TargetMode: table;
	local Range: table;
	local AimWolf: table;
	local Detonate: table;
	local DetonateAt: table;
	local Health: table;
	kitSpecs.Skoll = {
		["Kits"] = {'void_hunter'},
		["Options"] = function(autoKit: table): {table}
			local modes: {string} = {'Distance', 'Health'};
			for _: number, name: string in sortNames do
				if not table.find(modes, name) then
					table.insert(modes, name);
				end;
			end;
			TargetMode = autoKit:CreateDropdown({["Name"] = 'Skoll Target mode', ["List"] = modes});
			Range = autoKit:CreateSlider({["Name"] = 'Skoll Range', ["Min"] = 1, ["Max"] = 100, ["Default"] = 50, ["Suffix"] = 'studs', ["Tooltip"] = 'Fenrir travels 39 studs a second and lives 3 seconds'});
			AimWolf = autoKit:CreateToggle({["Name"] = 'Skoll Aim wolf', ["Default"] = true, ["Tooltip"] = 'Throws Fenrir straight at your target instead of where the camera points'});
			Detonate = autoKit:CreateToggle({["Name"] = 'Skoll Auto detonate', ["Default"] = true, ["Tooltip"] = 'Sets the mark off, which costs you the damage buff on them'});
			DetonateAt = autoKit:CreateDropdown({["Name"] = 'Skoll Detonate at', ["List"] = {'Low health', 'Instantly', 'Before it expires'}, ["Tooltip"] = 'Low health finishes them off; Before it expires keeps the buff until the mark runs out'});
			Health = autoKit:CreateSlider({["Name"] = 'Skoll Health', ["Min"] = 1, ["Max"] = 100, ["Default"] = 30, ["Suffix"] = '%', ["Tooltip"] = 'Low health threshold for detonating'});
			return {TargetMode, Range, AimWolf, Detonate, DetonateAt, Health};
		end,
		["Start"] = function(autoKit: table): ()
			local marked: {[Instance]: number} = {};
			local pickTarget: () -> table? = function(): table?
				local targets: table = autoKit.Options.Targets;
				return entitylib.EntityPosition({
					["Range"] = Range["Value"],
					["Part"] = 'RootPart',
					["Players"] = targets.Players["Enabled"],
					["NPCs"] = targets.NPCs["Enabled"],
					["Wallcheck"] = targets.Walls["Enabled"] or nil,
					["Sort"] = sortMethods[TargetMode["Value"]]
				});
			end;
			local controller: table = bedwars.VoidHunterKitController;
			local original: (...any) -> ...any = controller.onAbilityUsed;
			local hooked: (...any) -> ...any = function(self: table, character: Model, data: table?, ...: any): ...any
				local ent: table? = AimWolf["Enabled"] and data and data.ability == 'void_hunter_mark' and character == lplr.Character and character.PrimaryPart and pickTarget() or nil;
				local delta: Vector3 = ent and ent.RootPart.Position - character.PrimaryPart.Position or Vector3.zero;
				if delta.Magnitude > 0 then
					fire('VoidHunter_MarkAbilityRequest', 'SendToServer', {["originPosition"] = character.PrimaryPart.Position, ["direction"] = delta.Unit});
					return;
				end;
				return original(self, character, data, ...);
			end;
			controller.onAbilityUsed = hooked;
			autoKit:Clean(function(): ()
				if controller.onAbilityUsed == hooked then
					controller.onAbilityUsed = original;
				end;
				table.clear(marked);
			end);
			autoKit:Clean(bedwars.Client:Get('VoidHunter_TargetMarked'):Connect(function(data: table): ()
				if data.userPlayer == lplr and data.targetEntityInstance then
					marked[data.targetEntityInstance] = tick() + bedwars.VoidHunterBalance.MARK_DURATION;
				end;
			end));
			autoKit:Clean(bedwars.Client:Get('VoidHunter_TargetMarkRemoved'):Connect(function(data: table): ()
				if data.userPlayer == lplr and data.targetEntityInstance then
					marked[data.targetEntityInstance] = nil;
				end;
			end));
			local nextCheck: number = 0;
			autoKit:Clean(runService.Heartbeat:Connect(function(): ()
				if tick() < nextCheck or not entitylib.isAlive then
					return;
				end;
				nextCheck = tick() + checkRate;
				local health: number?, expires: number?;
				for victim: Instance, expiry: number in marked do
					local humanoid: Humanoid? = victim.Parent and tick() < expiry and victim:FindFirstChildWhichIsA('Humanoid') or nil;
					if humanoid and humanoid.MaxHealth > 0 then
						health = (humanoid.Health + math.max(victim:GetAttribute('TotalShield') or 0, 0)) / humanoid.MaxHealth * 100;
						expires = expiry;
						break;
					end;
				end;
				local mode: string = DetonateAt["Value"];
				local detonate: boolean = Detonate["Enabled"] and (mode == 'Instantly' or (health ~= nil and (mode == 'Low health' and health <= Health["Value"] or mode == 'Before it expires' and tick() >= expires - expiryMargin)));
				if detonate and bedwars.AbilityController:canUseAbility('void_hunter_detonate', quiet) then
					bedwars.AbilityController:useAbility('void_hunter_detonate');
					table.clear(marked);
				elseif pickTarget() and bedwars.AbilityController:canUseAbility('void_hunter_mark', quiet) then
					bedwars.AbilityController:useAbility('void_hunter_mark');
				end;
			end));
		end
	};
end);

