			Delay = autoKit:CreateSlider({["Name"] = 'Star Collector Delay', ["Min"] = 0, ["Max"] = 1, ["Default"] = 0.2, ["Decimal"] = 100, ["Suffix"] = 's'});
			return {Streamer, Animation, Range, Delay};
