				cooldowns[star] = nil;
			end));
			autoKit:Clean(proximityPrompts.PromptShown:Connect(function(prompt: ProximityPrompt): ()
				if Streamer["Enabled"] and prompt.Name == 'stars_ProximityPrompt' then
