				local pool: {string} = hunting and {trapperUtil.getSelectedTrap(lplr), table.unpack(constants.TrapperTraps)} or Traps.ListEnabled;
				for _: number, item: string in pool do
					local trapperTrap: boolean = trapperUtil.isTrapperTrap(item);
					if (trapperTrap and stocked(item)) or (not hunting and not trapperTrap and getItem(item)) then
						return item;
					end;
				end;
				return nil;
			end;

			local place: (point: Vector3, item: string) -> boolean = function(point: Vector3, item: string): boolean
				local hit: RaycastResult? = cast(point + Vector3.new(0, 3, 0), Vector3.new(0, -groundProbe, 0));
				if not hit or hit.Normal.Y <= 0.99 then
					return false;
				end;
				local position: Vector3 = roundPos(hit.Position + Vector3.new(0, 0.15, 0));
				local origin: Vector3 = entitylib.character.RootPart.Position + Vector3.new(0, 1, 0);
				if tick() < (recent[position] or 0) or getPlacedBlock(position) or (position - origin).Magnitude > math.min(PlaceRange["Value"], balance.ThrowRange) then
					return false;
				end;
				if trapperUtil.isTrapperTrap(item) then
					if controller.currentAim or not stocked(item) or not trapperUtil.canThrowTrap(origin, position, cast, Vector3.yAxis) then
						return false;
					end;
					if trapperUtil.getSelectedTrap(lplr) ~= item then
						if tick() >= nextSwitch and bedwars.AbilityController:canUseAbility('trapper_switch', quiet) then
							nextSwitch = tick() + math.max(balance.SwitchCooldown, switchFloor);
							bedwars.AbilityController:useAbility('trapper_switch', nil, {["trapType"] = item});
						end;
						return false;
					end;
					local payload: table = {["trapType"] = item, ["target"] = position, ["normal"] = Vector3.yAxis};
					ownAim = {["character"] = lplr.Character, ["trapType"] = item, ["source"] = 'binding', ["released"] = true, ["payload"] = payload};
					controller.currentAim = ownAim;
					-- The ability runs game code while our fake aim is installed; the aim has to be cancelled before any error propagates.
					local ran: boolean, thrown: any = pcall(function(): boolean
						if not bedwars.AbilityController:canUseAbility('trapper_throw', quiet) then
							return false;
						end;
						bedwars.AbilityController:useAbility('trapper_throw', nil, payload);
						return true;
					end);
					if controller.currentAim == ownAim then
						controller:cancelAim();
					end;
					if not ran then
						error(thrown);
					end;
					if not thrown then
						return false;
					end;
				else
					if not getPlacedBlock(position - Vector3.new(0, 3, 0)) or not canPlace() then
						return false;
					end;
					local previous: number? = SwitchBack["Enabled"] and store.hand.tool and hotbarSlotOf(store.hand.tool) or nil;
					placeBlock(position, item);
					if previous then
						hotbarSwitch(previous);
					end;
				end;
				recent[position] = tick() + reuseDelay;
				if Notify["Enabled"] then
					notif('AutoTrap', 'Placed '..item, 3);
				end;
				return true;
			end;

			local throwPoints: (hunting: boolean, item: string, enemies: {table}) -> {Vector3} = function(hunting: boolean, item: string, enemies: {table}): {Vector3}
				local points: {Vector3} = {};
				local origin: Vector3 = entitylib.character.RootPart.Position;
				if hunting then
					for _: number, ent: table in enemies do
						local travel: number = trapperUtil.trapThrowDuration(origin + Vector3.new(0, 1, 0), ent.RootPart.Position) + balance.SettleTime + constants.TrapperTrapMeta[item].setupTime + store.ping.total;
						local lead: Vector3 = ent.RootPart.AssemblyLinearVelocity * Vector3.new(1, 0, 1) * travel;
						lead = lead.Magnitude > leadCap and lead.Unit * leadCap or lead;
						for _: number, share: number in {1, 0.5, 0} do
							table.insert(points, ent.RootPart.Position + lead * share - Vector3.new(0, ent.HipHeight - 1.5, 0));
						end;
					end;
					return points;
				end;
				local ownBed: string = 'Team'..(lplr:GetAttribute('Team') or -1)..'NoBreak';
				local bed: BasePart?, closest: number = nil, Range["Value"];
				for _: number, candidate: BasePart in collectionService:GetTagged('bed') do
					local distance: number = (origin - candidate.Position).Magnitude;
					local mine: boolean = candidate:GetAttribute(ownBed) and true or false;
					if mine == (Target["Value"] == 'Your bed') and distance < closest then
						bed, closest = candidate, distance;
					end;
				end;
				local edge: number = Radius["Value"] * 3;
				for x: number = -edge, edge, 3 do
					for z: number = -edge, edge, 3 do
						if bed and (math.abs(x) == edge or math.abs(z) == edge) then
							table.insert(points, bed.Position + Vector3.new(x, 0, z));
						end;
					end;
				end;
				return points;
			end;

			autoKit:Clean(function(): ()
				if ownAim and controller.currentAim == ownAim then
					controller:cancelAim();
				end;
			end);
			autoKit:Clean(runService.Heartbeat:Connect(function(): ()
				if tick() < nextCheck then
					return;
				end;
				nextCheck = tick() + checkRate;
				for position: Vector3, expiry: number in recent do
					if tick() >= expiry then
						recent[position] = nil;
					end;
				end;
				if not entitylib.isAlive or (KitCheck["Enabled"] and not hasKit('trapper')) then
					return;
				end;
				local targets: table = autoKit.Options.Targets;
				local armed: boolean = Detonate["Enabled"] and trapperUtil.getArmedTrapCount(lplr, 'explosive_trap') > 0;
				local enemies: {table} = entitylib.AllPosition({
					["Range"] = armed and math.huge or PlaceRange["Value"] + huntPadding,
					["Part"] = 'RootPart',
					["Players"] = targets.Players["Enabled"],
					["NPCs"] = targets.NPCs["Enabled"],
					["Wallcheck"] = (IgnoreWalls["Enabled"] or targets.Walls["Enabled"]) or nil,
					["Sort"] = sortMethods.Distance,
					["Priority"] = false
				});
				if armed and tick() >= nextDetonate and controller:canUseAbilities() and bedwars.AbilityController:canUseAbility('trapper_detonate', quiet) then
					for _: number, trap: Instance in placedTraps do
						if trap.Name == 'explosive_trap' and trap:GetAttribute('PlacedByUserId') == lplr.UserId and trap:GetAttribute('SnapTrapState') == activeState then
							local center: Vector3 = trapperUtil.trapSurfacePosition(trap.Position, trap:GetAttribute('TrapperSurfaceNormal') or Vector3.yAxis);
							for _: number, ent: table in enemies do
								local later: Vector3 = ent.RootPart.Position + ent.RootPart.AssemblyLinearVelocity * balance.ExplosionDelay;
								if (ent.RootPart.Position - center).Magnitude <= balance.ExplosionRadius and (later - center).Magnitude <= balance.ExplosionRadius then
									nextDetonate = tick() + math.max(balance.DetonateCooldown, balance.ExplosionDelay);
									bedwars.AbilityController:useAbility('trapper_detonate');
									break;
								end;
							end;
						end;
						if tick() < nextDetonate then
							break;
						end;
					end;
				end;
				local hunting: boolean = Mode["Value"] == 'Enemies';
				local item: string? = tick() >= nextThrow and chooseTrap(hunting) or nil;
				if not item then
					return;
				end;
				local ignore: {Instance} = {gameCamera, entitylib.character.Character};
				for _: number, ent: table in entitylib.List do
					table.insert(ignore, ent.Character);
				end;
				for _: number, object: Instance in collectionService:GetTagged('DontBlockAbilityRaycast') do
					table.insert(ignore, object);
				end;
				sight.FilterDescendantsInstances = ignore;
				for _: number, point: Vector3 in throwPoints(hunting, item, enemies) do
					if place(point, item) then
						ringCount = hunting and 0 or ringCount + 1;
						local pause: boolean = hunting or ringCount >= Amount["Value"];
						nextThrow = tick() + math.max(balance.ThrowCooldown, pause and Delay["Value"] or 0);
						ringCount = pause and 0 or ringCount;
						break;
					end;
				end;
			end));
		end
	};
end);

velo.run(function(): ()
	local checkRate: number = 0.1;
	local voidDepth: number = 200;
	local groundDrop: number = 80;
	local fallbackCooldown: number = 8;
	local scanLift: number = 40;
	local aimLift: Vector3 = Vector3.new(0, 0.5, 0);
	local FallSpeed: table;
	local Search: table;
	local LegitSwitch: table;
	local SwitchBack: table;
	local BackDelay: table;
	local LimitItem: table;
	kitSpecs.Triton = {
		["Kits"] = {'harpoon'},
		["Options"] = function(autoKit: table): {table}
			FallSpeed = autoKit:CreateSlider({["Name"] = 'Triton Fall speed', ["Min"] = 10, ["Max"] = 200, ["Default"] = 60, ["Suffix"] = 'studs/s', ["Tooltip"] = 'How fast you must be falling before it throws'});
			Search = autoKit:CreateSlider({["Name"] = 'Triton Search range', ["Min"] = 4, ["Max"] = 60, ["Default"] = 40, ["Suffix"] = 'studs', ["Tooltip"] = 'How far out it looks for ground to land on'});
			LegitSwitch = autoKit:CreateToggle({["Name"] = 'Triton Legit Switch', ["Default"] = true, ["Tooltip"] = 'Shows the switch on your hotbar'});
			SwitchBack = autoKit:CreateToggle({["Name"] = 'Triton Switch back', ["Default"] = true, ["Tooltip"] = 'Returns to your last item after throwing'});
			BackDelay = autoKit:CreateTwoSlider({["Name"] = 'Triton Switch Back Delay', ["Min"] = 0, ["Max"] = 2, ["DefaultMin"] = 0.1, ["DefaultMax"] = 0.2, ["Decimal"] = 100});
			LimitItem = autoKit:CreateToggle({["Name"] = 'Triton Limit to item', ["Tooltip"] = 'Only throws while you already hold the trident'});
			return {FallSpeed, Search, LegitSwitch, SwitchBack, BackDelay, LimitItem};
		end,
		["Start"] = function(autoKit: table): ()
			local nextCheck: number, nextFire: number = 0, 0;
			local busy: boolean = false;
			local lastGround: Vector3?;
			local ground: RaycastParams = RaycastParams.new();
			ground.RespectCanCollide = true;
			ground.FilterType = Enum.RaycastFilterType.Include;
			local landingNear: (center: Vector3) -> Vector3? = function(center: Vector3): Vector3?
				for step: number = 1, Search["Value"] do
					for _: number, axis: Vector3 in {Vector3.xAxis, Vector3.zAxis, -Vector3.xAxis, -Vector3.zAxis} do
						local hit: RaycastResult? = workspace:Raycast(center + Vector3.new(0, 3, 0) + axis * step, Vector3.new(0, -groundDrop, 0), ground);
						if hit then
							return hit.Position;
						end;
					end;
				end;
				return nil;
			end;
			autoKit:Clean(runService.Heartbeat:Connect(function(): ()
				if busy or tick() < math.max(nextCheck, nextFire) or not entitylib.isAlive or not store.map or (LimitItem["Enabled"] and not (store.hand.tool and store.hand.tool.Name == 'harpoon')) then
					return;
				end;
				if vape.ThreadFix then
					setthreadidentity(8);
				end;
				nextCheck = tick() + checkRate;
				local root: BasePart = entitylib.character.RootPart;
				ground.FilterDescendantsInstances = {store.map};
				ground.CollisionGroup = root.CollisionGroup;
				if entitylib.character.Humanoid.FloorMaterial ~= Enum.Material.Air then
					lastGround = root.Position;
				end;
				local harpoon: table? = getItem('harpoon');
				if not harpoon or root.AssemblyLinearVelocity.Y >= -FallSpeed["Value"] or workspace:Raycast(root.Position, Vector3.new(0, -voidDepth, 0), ground) then
					return;
				end;
				local spot: Vector3? = landingNear(root.Position + Vector3.new(0, scanLift, 0)) or lastGround and landingNear(lastGround + Vector3.new(0, 5, 0));
				local meta: table = bedwars.ProjectileMeta.harpoon_projectile;
				local source: table? = bedwars.ItemMeta.harpoon.projectileSource;
				local offset: table = bedwars.BowConstantsTable;
				local shootPosition: Vector3? = spot and (CFrame.new(root.Position, spot) * CFrame.new(-offset.RelX, -offset.RelY, -offset.RelZ)).Position;
				local aim: Vector3? = shootPosition and prediction.SolveTrajectory(shootPosition, meta.launchVelocity, meta.gravitationalAcceleration or config.Gravity, spot + aimLift, Vector3.zero, workspace.Gravity, 0);
				if not aim then
					return;
				end;
				busy = true;
				local previous: Instance? = store.hand.tool;
				switchItem(harpoon.tool);
				if LegitSwitch["Enabled"] then
					hotbarSwitch(hotbarSlotOf(harpoon.tool));
				end;
				nextFire = tick() + (source and source.fireDelaySec or fallbackCooldown);
				fire('ProjectileFire', 'CallServerAsync', harpoon.tool, nil, source and source.projectileType('harpoon') or 'harpoon_projectile', shootPosition, root.Position, CFrame.lookAt(shootPosition, aim).LookVector * meta.launchVelocity, bedwars.IdUtil.generateId(8), ballistics.shotData('harpoon'), workspace:GetServerTimeNow() - config.ShotLatency):andThen(function(result: any): ()
					if type(result) == 'table' and result.accepted and result.model then
						result.model.Parent = replicatedStorage;
					end;
				end);
				busy = false;
				if SwitchBack["Enabled"] and previous then
					task.delay(BackDelay:GetRandomValue(), function(): ()
						switchItem(previous);
						if LegitSwitch["Enabled"] then
							hotbarSwitch(hotbarSlotOf(previous));
						end;
					end);
				end;
			end));
		end
	};
end);

