	end;

	local collectNear: (autoKit: table, tag: string, master: table, callback: (object: Instance) -> ()) -> () = function(autoKit: table, tag: string, master: table, callback: (object: Instance) -> ()): ()
		local objects: {Instance} = collection(tag, autoKit);
