velo.run(function(): ()
	local checkRate: number = 0.1;
	local fallDepth: number = 12;
	local quiet: table = {["disableBlockedAbilityAlert"] = true};
	local teammates: {string} = {'None'};
	local owlBalance: Instance? = replicatedStorage.TS.balance:FindFirstChild('owl-balance-file');
	local attachRange: number = owlBalance and require(owlBalance).OwlBalance.OWL_ATTACH_MAX_RANGE or 60;
	local Heal: table;
	local Health: table;
	local Lift: table;
	local AutoOwl: table;
	local Teammate: table;
	local FovCheck: table;
	local Fov: table;
	local RangeCircle: table;
	local CircleColor: table;
	local CircleTransparency: table;
	local CircleThickness: table;
	local CircleFilled: table;
	local mapBottom: number = math.huge;
	local footingOwner: Model?, footingY: number = nil, -math.huge;

	local addTeammate: (plr: Player) -> () = function(plr: Player): ()
		if plr ~= lplr and plr:GetAttribute('Team') == lplr:GetAttribute('Team') and not table.find(teammates, plr.Name) then
			table.insert(teammates, plr.Name);
			if Teammate then
				Teammate:Change(teammates);
			end;
		end;
	end;
	local watchTeam: (plr: Player) -> () = function(plr: Player): ()
		vape:Clean(plr:GetAttributeChangedSignal('Team'):Connect(function(): ()
			addTeammate(plr);
		end));
		addTeammate(plr);
	end;
	for _: number, plr: Player in playersService:GetPlayers() do
		watchTeam(plr);
	end;
	vape:Clean(playersService.PlayerAdded:Connect(watchTeam));

	local mouseOrigin: () -> Vector2 = function(): Vector2
		return inputService.TouchEnabled and gameCamera.ViewportSize / 2 or inputService:GetMouseLocation();
	end;

	local pickTeammate: () -> Player? = function(): Player?
		local chosen: Player? = playersService:FindFirstChild(Teammate["Value"]);
		if not FovCheck["Enabled"] then
			return chosen;
		end;
		if not entitylib.isAlive then
			return nil;
		end;
		local origin: Vector2, best: Player?, bestDistance: number = mouseOrigin(), nil, Fov["Value"];
		for _: number, plr: Player in (chosen and {chosen} or playersService:GetPlayers()) do
			local root: BasePart? = plr.Character and plr.Character:FindFirstChild('HumanoidRootPart');
			if plr == lplr or not root or plr:GetAttribute('Team') ~= lplr:GetAttribute('Team') or plr:GetAttribute('IsOwlTarget') or (root.Position - entitylib.character.RootPart.Position).Magnitude > attachRange then
				continue;
			end;
			local point: Vector3, visible: boolean = gameCamera:WorldToViewportPoint(root.Position);
			local distance: number = (Vector2.new(point.X, point.Y) - origin).Magnitude;
			if visible and distance <= bestDistance then
				best, bestDistance = plr, distance;
			end;
		end;
		return best;
	end;

	local ready: (ability: string) -> boolean = function(ability: string): boolean
		return bedwars.AbilityController:getEnabledAbility(ability) ~= nil and bedwars.AbilityController:canUseAbility(ability, quiet);
	end;

	kitSpecs.Whisper = {
		["Kits"] = {'owl'},
		["Options"] = function(autoKit: table): {table}
			Heal = autoKit:CreateToggle({["Name"] = 'Whisper Heal', ["Default"] = true});
			Health = autoKit:CreateSlider({["Name"] = 'Whisper Health', ["Min"] = 1, ["Max"] = 100, ["Default"] = 99, ["Suffix"] = '%', ["Tooltip"] = 'Heals the owl target at or below this health'});
			Lift = autoKit:CreateToggle({["Name"] = 'Whisper Fly', ["Default"] = true, ["Tooltip"] = 'Lifts the owl target once they drop well below their last footing, so normal jumps and bridging never trigger it'});
			AutoOwl = autoKit:CreateToggle({["Name"] = 'Whisper Auto owl', ["Tooltip"] = 'Sends the owl to your chosen teammate as soon as it is ready'});
			Teammate = autoKit:CreateDropdown({["Name"] = 'Whisper Teammate', ["List"] = teammates, ["Tooltip"] = 'Who the owl is summoned onto'});
			FovCheck = autoKit:CreateToggle({["Name"] = 'Whisper FOV check', ["Tooltip"] = 'Only picks a teammate near your mouse, inside owl range and without an owl\nWith Teammate on None it picks whoever is closest to your mouse'});
			Fov = autoKit:CreateSlider({["Name"] = 'Whisper FOV', ["Min"] = 1, ["Max"] = 1000, ["Default"] = 150});
			RangeCircle = autoKit:CreateToggle({["Name"] = 'Whisper Range Circle'});
			CircleColor = autoKit:CreateColorSlider({["Name"] = 'Whisper Circle Color'});
			CircleTransparency = autoKit:CreateSlider({["Name"] = 'Whisper Transparency', ["Min"] = 0, ["Max"] = 1, ["Default"] = 0.5, ["Decimal"] = 10});
			CircleThickness = autoKit:CreateSlider({["Name"] = 'Whisper Thickness', ["Min"] = 1, ["Max"] = 10, ["Default"] = 1, ["Decimal"] = 10, ["Tooltip"] = 'Outline width, ignored while the circle is filled'});
			CircleFilled = autoKit:CreateToggle({["Name"] = 'Whisper Circle Filled'});
			return {Heal, Health, Lift, AutoOwl, Teammate, FovCheck, Fov, RangeCircle, CircleColor, CircleTransparency, CircleThickness, CircleFilled};
		end,
		["Start"] = function(autoKit: table): ()
			local controller: table = bedwars.OwlKitController;
			local ownHandler: any = rawget(controller, 'onAbilityUsed');
			local original: (...any) -> ...any = controller.onAbilityUsed;
			local hook: (...any) -> ...any = function(self: table, character: Model, data: table?, ...: any): ...any
				if AutoOwl["Enabled"] and data and data.ability == 'SUMMON_OWL' and character == lplr.Character then
					local target: Player? = pickTeammate();
					if target and target ~= lplr then
						fire('SummonOwl', 'CallServer', target);
						return nil;
					end;
				end;
				return original(self, character, data, ...);
			end;
			controller.onAbilityUsed = hook;
			autoKit:Clean(function(): ()
				if controller.onAbilityUsed == hook then
					controller.onAbilityUsed = ownHandler;
				end;
			end);

			if Drawing then
				local circle: any = Drawing.new('Circle');
				circle.NumSides = 100;
				autoKit:Clean(function(): ()
					circle:Remove();
				end);
				autoKit:Clean(runService.RenderStepped:Connect(function(): ()
					circle.Visible = AutoOwl["Enabled"] and FovCheck["Enabled"] and RangeCircle["Enabled"];
					if circle.Visible then
						circle.Position = mouseOrigin();
						circle.Radius = Fov["Value"];
						circle.Color = Color3.fromHSV(CircleColor["Hue"], CircleColor["Sat"], CircleColor["Value"]);
						circle.Transparency = 1 - CircleTransparency["Value"];
						circle.Thickness = CircleThickness["Value"];
						circle.Filled = CircleFilled["Enabled"];
					end;
				end));
			end;

			local nextCheck: number = 0;
			autoKit:Clean(runService.Heartbeat:Connect(function(): ()
				if tick() < nextCheck or store.matchState == 0 then
					return;
				end;
				nextCheck = tick() + checkRate;
				if AutoOwl["Enabled"] and not bedwars.OwlAbilityController.target and bedwars.AbilityController:canUseAbility('SUMMON_OWL', quiet) and pickTeammate() then
					bedwars.AbilityController:useAbility('SUMMON_OWL');
				end;
				local attached: Instance? = bedwars.OwlAbilityController.target;
				local character: Model? = attached and (attached:IsA('Player') and attached.Character or attached:IsA('Model') and attached) or nil;
				if not character then
					return;
				end;
				local root: BasePart? = character.PrimaryPart;
				if root then
					if footingOwner ~= character then
						if mapBottom == math.huge then
							for _: number, block: BasePart in store.blocks do
								mapBottom = math.min(mapBottom, block.Position.Y - block.Size.Y / 2);
							end;
						end;
						footingOwner, footingY = character, (mapBottom == math.huge and -math.huge or mapBottom) + fallDepth;
					end;
					if math.abs(root.AssemblyLinearVelocity.Y) < 2 then
						footingY = root.Position.Y;
					end;
