						bedwars.AbilityController:useAbility('OWL_LIFT');
					end;
				end;
				local health: number?, maxHealth: number? = character:GetAttribute('Health'), character:GetAttribute('MaxHealth');
				local hurt: boolean = Health["Value"] >= 100 or (health ~= nil and maxHealth ~= nil and maxHealth > 0 and health / maxHealth <= Health["Value"] / 100);
				if Heal["Enabled"] and hurt and ready('OWL_HEAL') then
					bedwars.AbilityController:useAbility('OWL_HEAL');
				end;
			end));
		end
	};
end);

