			TargetMode = autoKit:CreateDropdown({["Name"] = 'Zeno Target Mode', ["List"] = sortNames, ["Default"] = 'Distance'});
			LimitItem = autoKit:CreateToggle({["Name"] = 'Zeno Limit to item', ["Default"] = true, ["Tooltip"] = 'Only casts while you hold a staff instead of switching to one'});
			AfkCheck = autoKit:CreateToggle({["Name"] = 'Zeno AFK check', ["Tooltip"] = 'Stops casting after 30 seconds without input'});
			Strike = autoKit:CreateToggle({["Name"] = 'Zeno Lightning Strike', ["Default"] = true});
			Storm = autoKit:CreateToggle({["Name"] = 'Zeno Lightning Storm'});
			Shockwave = autoKit:CreateToggle({["Name"] = 'Zeno Shockwave', ["Tooltip"] = 'Casts shockwave when a target is close'});
			ShockwaveRange = autoKit:CreateSlider({["Name"] = 'Zeno Shockwave Range', ["Min"] = 1, ["Max"] = 12, ["Default"] = 12, ["Decimal"] = 5, ["Suffix"] = 'studs'});
			Range = autoKit:CreateSlider({["Name"] = 'Zeno Range', ["Min"] = 1, ["Max"] = 60, ["Default"] = 35, ["Decimal"] = 5, ["Suffix"] = 'studs'});
			Delay = autoKit:CreateSlider({["Name"] = 'Zeno Delay', ["Min"] = 0, ["Max"] = 10, ["Default"] = 0.5, ["Decimal"] = 5, ["Suffix"] = 's'});
			return {TargetMode, LimitItem, AfkCheck, Strike, Storm, Shockwave, ShockwaveRange, Range, Delay};
		end,
		["Start"] = function(autoKit: table): ()
			local retryAt: {[string]: number} = {};
