			return along(direction), ownRoot();
		end},
		["Xurot Wing Flap"] = {["Controller"] = 'VoidDragonController', ["Method"] = 'flapWings', ["Push"] = lift(40)}
	};

	local boostOptions: (autoKit: table, label: string, tooltip: string) -> {table} = function(autoKit: table, label: string, tooltip: string): {table}
		local boost: table = boosts[label];
		boost.Toggle = autoKit:CreateToggle({["Name"] = label..' boost', ["Tooltip"] = tooltip});
		boost.Multiplier = autoKit:CreateSlider({["Name"] = label..' multiplier', ["Min"] = 1, ["Max"] = 5, ["Default"] = 2, ["Decimal"] = 10, ["Suffix"] = 'x'});
		return {boost.Toggle, boost.Multiplier};
	end;

	local hookBoost: (autoKit: table, label: string) -> () = function(autoKit: table, label: string): ()
		local boost: table = boosts[label];
		local controller: table? = bedwars[boost.Controller];
		local original: any = controller and controller[boost.Method];
		if type(original) ~= 'function' then
			return;
		end;
		local own: any = rawget(controller, boost.Method);
		local hook: (...any) -> ...any = function(self: table, ...: any): ...any
			local primed: boolean = boost.Ready == nil or bedwars.AbilityController:canUseAbility(boost.Ready, quiet);
			local results: table = table.pack(original(self, ...));
			if primed and boost.Toggle["Enabled"] then
				local push: Vector3?, root: BasePart? = boost.Push(...);
				if push and root then
					root:ApplyImpulse(push * root.AssemblyMass * (boost.Multiplier["Value"] - 1));
				end;
			end;
			return table.unpack(results, 1, results.n);
		end;
		controller[boost.Method] = hook;
		autoKit:Clean(function(): ()
			if controller[boost.Method] == hook then
				controller[boost.Method] = own;
			end;
		end);
	end;

	kitSpecs.JadeHammer = {
		["Kits"] = {'jade'},
		["Options"] = function(autoKit: table): {table}
			return boostOptions(autoKit, 'Jade Hammer', 'Extends how far the Jade Hammer jump launches you');
		end,
		["Start"] = function(autoKit: table): ()
			hookBoost(autoKit, 'Jade Hammer');
		end
	};

	kitSpecs.RegentDash = {
		["Kits"] = {'regent'},
		["Options"] = function(autoKit: table): {table}
			return boostOptions(autoKit, 'Regent Dash', 'Extends how far the void axe dash launches you');
		end,
		["Start"] = function(autoKit: table): ()
			hookBoost(autoKit, 'Regent Dash');
		end
	};

	kitSpecs.Yamini = {
		["Kits"] = {'cat'},
		["Options"] = function(autoKit: table): {table}
			local created: {table} = boostOptions(autoKit, 'Yamini Pounce', 'Extends how far the pounce launches you');
			for _: number, option: table in boostOptions(autoKit, 'Yamini Wall Kick', 'Extends how high dropping off a climbed wall throws you') do
				table.insert(created, option);
			end;
			return created;
		end,
		["Start"] = function(autoKit: table): ()
			hookBoost(autoKit, 'Yamini Pounce');
			hookBoost(autoKit, 'Yamini Wall Kick');
		end
	};

	local InstantCharge: table;
	kitSpecs.Yuzi = {
		["Kits"] = {'dasher'},
		["Options"] = function(autoKit: table): {table}
			local created: {table} = boostOptions(autoKit, 'Yuzi Dash', 'Extends how far the dao dash launches you');
			InstantCharge = autoKit:CreateToggle({["Name"] = 'Yuzi Instant charge', ["Tooltip"] = 'Your dao is fully charged the moment charging starts, so you can dash right away'});
			table.insert(created, InstantCharge);
			return created;
		end,
		["Start"] = function(autoKit: table): ()
			hookBoost(autoKit, 'Yuzi Dash');
			local dao: table? = bedwars.DaoController;
			local original: any = dao and dao.enterChargingState;
			if type(original) ~= 'function' then
				return;
			end;
			local own: any = rawget(dao, 'enterChargingState');
			local hook: (...any) -> ...any = function(self: table, ...: any): ...any
				local results: table = table.pack(original(self, ...));
				if InstantCharge["Enabled"] and self.chargingMaid then
					self.beginChargeTime = time() - 60;
				end;
				return table.unpack(results, 1, results.n);
			end;
			dao.enterChargingState = hook;
			autoKit:Clean(function(): ()
				if dao.enterChargingState == hook then
					dao.enterChargingState = own;
				end;
			end);
		end
	};

	local checkRate: number = 0.05;
	local wingSpeed: number = 2;
	local formBreathRate: number = 0.1;
	local formBreathRange: number = 30;
	local Range: table;
	local Delay: table;
	local Wings: table;
	kitSpecs.Xurot = {
		["Kits"] = {'void_dragon'},
		["Options"] = function(autoKit: table): {table}
			Range = autoKit:CreateSlider({["Name"] = 'Xurot Range', ["Min"] = 1, ["Max"] = 200, ["Default"] = 120, ["Suffix"] = 'studs', ["Tooltip"] = 'Breathes on enemies in this range while you are a dragon'});
			Delay = autoKit:CreateSlider({["Name"] = 'Xurot Delay', ["Min"] = 0.1, ["Max"] = 3, ["Default"] = 0.5, ["Decimal"] = 10, ["Suffix"] = 's'});
			Wings = autoKit:CreateToggle({["Name"] = 'Xurot Wing Boost', ["Default"] = true, ["Tooltip"] = 'catsix AutoKit Xurot: each wing flap gives a speed boost, and dragon breath hits players within 30 studs', ["Function"] = function(): ()
				if autoKit["Enabled"] then
					autoKit:Toggle();
					autoKit:Toggle();
				end;
			end});
			local created: {table} = boostOptions(autoKit, 'Xurot Wing Flap', 'Extends how high each wing flap throws you');
			table.insert(created, 1, Range);
			table.insert(created, 2, Delay);
			table.insert(created, 3, Wings);
			return created;
		end,
		["Start"] = function(autoKit: table): ()
			if Wings["Enabled"] then
				local controller: table = bedwars.VoidDragonController;
				local original: (...any) -> ...any = controller.flapWings;
				local flap: table = boosts['Xurot Wing Flap'];
				local flapped: boolean = false;
				local hook: (...any) -> ...any = function(self: table, ...: any): ...any
					if not flapped and fire('DragonFlap', 'CallServer', {["player"] = lplr}) ~= false then
						self.SpeedMaid:GiveTask(bedwars.SprintController:getMovementStatusModifier():addModifier({["blockSprint"] = true, ["constantSpeedMultiplier"] = wingSpeed}));
						self.SpeedMaid:GiveTask(function(): ()
							flapped = false;
						end);
						flapped = true;
					end;
					if flap.Toggle["Enabled"] then
						local push: Vector3?, root: BasePart? = flap.Push();
						if push and root then
							root:ApplyImpulse(push * root.AssemblyMass * (flap.Multiplier["Value"] - 1));
						end;
					end;
					return nil;
				end;
				controller.flapWings = hook;
				autoKit:Clean(function(): ()
					if controller.flapWings == hook then
						controller.flapWings = original;
					end;
				end);
				local nextFormBreath: number = 0;
				autoKit:Clean(runService.Heartbeat:Connect(function(): ()
					if tick() < nextFormBreath or store.matchState == 0 then
						return;
					end;
					nextFormBreath = tick() + formBreathRate;
					local target: table? = controller.inDragonForm and entitylib.EntityPosition({["Range"] = formBreathRange, ["Part"] = 'RootPart', ["Players"] = true, ["Priority"] = false}) or nil;
					if target then
						fire('DragonBreath', 'SendToServer', {["player"] = lplr, ["targetPoint"] = target.RootPart.Position});
					end;
				end));
			else
				hookBoost(autoKit, 'Xurot Wing Flap');
			end;
			local dragon: boolean = false;
			local ours: (event: any) -> boolean = function(event: any): boolean
				return type(event) ~= 'table' or event.player == nil or event.player == lplr;
			end;
			autoKit:Clean(bedwars.Client:Get('VoidDragonAction'):Connect(function(event: any): ()
				if ours(event) and type(event) == 'table' then
					dragon = event.action == 'transform' or (dragon and event.action ~= 'dragon_deactive');
				end;
			end));
			autoKit:Clean(bedwars.Client:Get('VoidDragonDeactive'):Connect(function(event: any): ()
				if ours(event) then
					dragon = false;
				end;
			end));
			autoKit:Clean(lplr.CharacterAdded:Connect(function(): ()
				dragon = false;
			end));
			local nextCheck: number, nextBreath: number = 0, 0;
			autoKit:Clean(runService.Heartbeat:Connect(function(): ()
				if not dragon or tick() < math.max(nextCheck, nextBreath) or not entitylib.isAlive then
					return;
				end;
				nextCheck = tick() + checkRate;
				local target: table? = entitylib.EntityPosition({
					["Origin"] = entitylib.character.RootPart.Position,
					["Range"] = Range["Value"],
					["Part"] = 'RootPart',
					["Players"] = true,
					["Wallcheck"] = true,
					["Priority"] = false
				});
				if target then
					nextBreath = tick() + Delay["Value"];
					fire('DragonBreath', 'SendToServer', {["player"] = lplr, ["targetPoint"] = target.RootPart.Position});
				end;
			end));
		end
	};

	local original: number?;
	local Reach: table;
	local ReachRange: table;
	local applyReach: () -> () = function(): ()
		local balance: table = bedwars.SummonerKitBalance;
		original = original or balance.SPELL_CAST_RANGE;
		balance.SPELL_CAST_RANGE = Reach["Enabled"] and math.max(ReachRange["Value"], original) or original;
	end;
	kitSpecs.KaidaReach = {
		["Kits"] = {'summoner'},
		["Options"] = function(autoKit: table): {table}
			Reach = autoKit:CreateToggle({["Name"] = 'Kaida Reach', ["Tooltip"] = 'Lifts the cap on where the summon circle can land', ["Function"] = function(): ()
				if original then
					applyReach();
				end;
			end});
			ReachRange = autoKit:CreateSlider({["Name"] = 'Kaida Reach range', ["Min"] = 45, ["Max"] = 120, ["Default"] = 75, ["Suffix"] = 'studs', ["Function"] = function(): ()
				if original then
					applyReach();
				end;
			end});
			return {Reach, ReachRange};
		end,
		["Start"] = function(autoKit: table): ()
			applyReach();
			autoKit:Clean(function(): ()
				bedwars.SummonerKitBalance.SPELL_CAST_RANGE = original;
				original = nil;
			end);
		end
	};
end);

velo.run(function(): ()
	local AutoKit: table = {["Enabled"] = false};
	local ShowAll: table = {["Enabled"] = false};
	local Notify: table = {["Enabled"] = false};
	local specNames: {string} = {};
	for name: string in kitSpecs do
		table.insert(specNames, name);
	end;
	table.sort(specNames);

	local appliesNow: (spec: table) -> boolean = function(spec: table): boolean
		for _: number, kit: string in spec.Kits or {} do
			if hasKit(kit) then
				return true;
			end;
		end;
		return spec.Kits == nil;
	end;

	local startSpec: (name: string) -> boolean = function(name: string): boolean
		return xpcall(kitSpecs[name].Start, function(message: any): ()
			velo.report('AutoKit '..name, message);
		end, AutoKit);
	end;

	local refreshOptions: () -> () = function(): ()
		for _: number, name: string in specNames do
			local spec: table = kitSpecs[name];
			local shown: boolean = ShowAll["Enabled"] or appliesNow(spec);
			for _: number, option: table in spec.Objects or {} do
				option.Object.Visible = shown;
			end;
		end;
	end;

	AutoKit = vape.Categories.Utility:CreateModule({
		["Name"] = 'AutoKit',
		["Function"] = function(callback: boolean): ()
			if not callback then
				return;
			end;
			local started: {string} = {};
			local deferred: {string} = {};
			for _: number, name: string in specNames do
				local spec: table = kitSpecs[name];
				if spec.Objects and (appliesNow(spec) or spec.AnyKit) then
					if spec.MatchOnly and store.matchState == 0 then
						table.insert(deferred, name);
					elseif startSpec(name) and spec.Kits and appliesNow(spec) then
						table.insert(started, name);
					end;
				end;
			end;
			if #deferred > 0 then
				AutoKit:Clean(vapeEvents.MatchStarted.Event:Once(function(): ()
					if vape.ThreadFix then
						setthreadidentity(8);
					end;
					for _: number, name: string in deferred do
						startSpec(name);
					end;
				end));
			end;
			if Notify["Enabled"] and #started > 0 then
				local kitNames: {string} = {};
				for _: number, kit: string in store.equippedKits do
					local meta: table? = bedwars.BedwarsKitMeta[kit];
					table.insert(kitNames, meta and meta.name or kit);
				end;
				notif('AutoKit', 'Running for '..table.concat(kitNames, ' & ')..': '..table.concat(started, ', '), 8, 'info');
			end;
			AutoKit:Clean(vapeEvents.KitChanged.Event:Connect(function(): ()
				task.defer(function(): ()
					if AutoKit["Enabled"] then
						AutoKit:Toggle();
						AutoKit:Toggle();
					end;
				end);
			end));
		end,
		["Tooltip"] = 'Automates every supported kit. Only the options of the kit you are playing are shown.'
	});
	AutoKit:CreateTargets({
		["Players"] = true,
		["NPCs"] = true
	});
	AutoKit:CreateToggle({
		["Name"] = 'Legit Range',
		["Tooltip"] = 'Kits with a range keep it within what a legit player could reach.'
	});
	ShowAll = AutoKit:CreateToggle({
		["Name"] = 'Show all kits',
		["Function"] = refreshOptions,
		["Tooltip"] = 'Show the options of kits you are not playing.'
	});
	Notify = AutoKit:CreateToggle({
		["Name"] = 'Notify',
		["Tooltip"] = 'Notify which kit automations started.'
	});
	for _: number, name: string in specNames do
		local built: boolean, objects: any = xpcall(kitSpecs[name].Options, function(message: any): ()
			velo.report('AutoKit '..name, message);
		end, AutoKit);
		kitSpecs[name].Objects = built and objects or nil;
	end;
	refreshOptions();
	vape:Clean(vapeEvents.KitChanged.Event:Connect(refreshOptions));
end);
